// ═══════════════════════════════════════════════════════════════════════════
// PRISM_CALCULATOR_LEARNING_ENGINE v1.0.0
// Bayesian parameter learning specific to machining operations
// ═══════════════════════════════════════════════════════════════════════════

const PRISM_CALCULATOR_LEARNING_ENGINE = {
    version: '1.0.0',
    authority: 'PRISM_CALCULATOR_LEARNING_ENGINE',
    
    learningData: {
        speedFeedOutcomes: [],
        userAdjustments: [],
        toolLifeObservations: [],
        surfaceFinishResults: [],
        chatterIncidents: []
    },
    
    posteriors: {
        speed_multiplier: { mean: 1.0, variance: 0.1, observations: 0 },
        feed_multiplier: { mean: 1.0, variance: 0.1, observations: 0 },
        doc_multiplier: { mean: 1.0, variance: 0.1, observations: 0 },
        woc_multiplier: { mean: 1.0, variance: 0.1, observations: 0 },
        tool_life_factor: { mean: 1.0, variance: 0.15, observations: 0 }
    },
    
    materialLearning: {},
    toolLearning: {},
    machineLearning: {},
    
    initialize: function() {
        this._loadPersistedData();
        console.log('[CALCULATOR_LEARNING] Initialized');
        return this;
    },
    
    recordOutcome: function(params) {
        const { material, tool, machine, recommended, actual, outcome, metrics = {} } = params;
        const timestamp = Date.now();
        const accepted = this._isAccepted(recommended, actual);
        
        const record = {
            id: 'outcome_' + timestamp + '_' + Math.random().toString(36).substr(2, 9),
            timestamp, material: this._normalize(material), tool: this._normalize(tool),
            machine: this._normalize(machine), recommended, actual, outcome, metrics, accepted,
            adjustmentFactors: this._calculateFactors(recommended, actual)
        };
        
        this.learningData.speedFeedOutcomes.push(record);
        this._updateBayesianPosteriors(record);
        if (material) this._updateMaterialLearning(record);
        if (tool) this._updateToolLearning(record);
        if (machine) this._updateMachineLearning(record);
        
        if (metrics.toolLife) {
            this.learningData.toolLifeObservations.push({
                timestamp, params: actual, predicted: recommended.predictedToolLife, actual: metrics.toolLife
            });
        }
        
        if (this.learningData.speedFeedOutcomes.length % 10 === 0) this._persistData();
        if (typeof PRISM_EVENT_BUS !== 'undefined') PRISM_EVENT_BUS.publish('calculator:learning:outcome', record);
        return record;
    },
    
    processFeedback: function(feedback) {
        const { outcomeId, rating, feedbackType, comments = '' } = feedback;
        const record = { id: 'feedback_' + Date.now(), timestamp: Date.now(), outcomeId, rating, feedbackType, comments };
        if (!this.learningData.userFeedback) this.learningData.userFeedback = [];
        this.learningData.userFeedback.push(record);
        
        switch (feedbackType) {
            case 'too_aggressive':
                this._adjustPosterior('speed_multiplier', -0.05);
                this._adjustPosterior('feed_multiplier', -0.05);
                break;
            case 'too_conservative':
                this._adjustPosterior('speed_multiplier', 0.05);
                this._adjustPosterior('feed_multiplier', 0.05);
                break;
            case 'chatter':
                this._adjustPosterior('doc_multiplier', -0.1);
                this._adjustPosterior('woc_multiplier', -0.1);
                break;
            case 'poor_finish':
                this._adjustPosterior('feed_multiplier', -0.05);
                break;
        }
        return record;
    },
    
    adjustRecommendation: function(baseRec, context = {}) {
        const { material, tool, machine } = context;
        let speedMult = this.posteriors.speed_multiplier.mean;
        let feedMult = this.posteriors.feed_multiplier.mean;
        let docMult = this.posteriors.doc_multiplier.mean;
        let wocMult = this.posteriors.woc_multiplier.mean;
        
        const matKey = this._normalize(material);
        if (this.materialLearning[matKey]) {
            speedMult *= this.materialLearning[matKey].speedFactor || 1.0;
            feedMult *= this.materialLearning[matKey].feedFactor || 1.0;
        }
        
        const toolKey = this._normalize(tool);
        if (this.toolLearning[toolKey]) {
            speedMult *= this.toolLearning[toolKey].speedFactor || 1.0;
            feedMult *= this.toolLearning[toolKey].feedFactor || 1.0;
        }
        
        const confidence = this._calculateConfidence();
        return {
            speed: Math.round(baseRec.speed * speedMult),
            feed: Math.round(baseRec.feed * feedMult * 1000) / 1000,
            doc: Math.round(baseRec.doc * docMult * 1000) / 1000,
            woc: Math.round(baseRec.woc * wocMult * 1000) / 1000,
            base: baseRec,
            multipliers: { speedMult, feedMult, docMult, wocMult },
            confidence,
            learningApplied: true,
            observationCount: this.posteriors.speed_multiplier.observations
        };
    },
    
    thompsonSample: function(param = 'speed_multiplier') {
        const p = this.posteriors[param];
        if (!p) return 1.0;
        const u1 = Math.random(), u2 = Math.random();
        const z = Math.sqrt(-2 * Math.log(u1)) * Math.cos(2 * Math.PI * u2);
        return Math.max(0.5, Math.min(1.5, p.mean + Math.sqrt(p.variance) * z));
    },
    
    getStatistics: function() {
        const outcomes = this.learningData.speedFeedOutcomes;
        const successCount = outcomes.filter(o => o.outcome === 'success').length;
        const acceptedCount = outcomes.filter(o => o.accepted).length;
        return {
            totalOutcomes: outcomes.length,
            successRate: outcomes.length > 0 ? (successCount / outcomes.length * 100).toFixed(1) + '%' : 'N/A',
            acceptanceRate: outcomes.length > 0 ? (acceptedCount / outcomes.length * 100).toFixed(1) + '%' : 'N/A',
            toolLifeObservations: this.learningData.toolLifeObservations.length,
            materialsLearned: Object.keys(this.materialLearning).length,
            posteriors: {
                speed: { multiplier: this.posteriors.speed_multiplier.mean.toFixed(3) },
                feed: { multiplier: this.posteriors.feed_multiplier.mean.toFixed(3) }
            }
        };
    },
    
    exportLearningData: function() {
        return { version: this.version, exported: new Date().toISOString(), posteriors: this.posteriors,
            materialLearning: this.materialLearning, toolLearning: this.toolLearning };
    },
    
    importLearningData: function(data) {
        if (data.posteriors) this.posteriors = data.posteriors;
        if (data.materialLearning) this.materialLearning = data.materialLearning;
        if (data.toolLearning) this.toolLearning = data.toolLearning;
    },
    
    _isAccepted: function(rec, act) {
        if (!rec || !act) return false;
        return Math.abs(rec.speed - act.speed) / rec.speed < 0.1 && Math.abs(rec.feed - act.feed) / rec.feed < 0.1;
    },
    
    _calculateFactors: function(rec, act) {
        if (!rec || !act) return {};
        return { speed: act.speed / (rec.speed || 1), feed: act.feed / (rec.feed || 1),
            doc: act.doc / (rec.doc || 1), woc: act.woc / (rec.woc || 1) };
    },
    
    _updateBayesianPosteriors: function(record) {
        const f = record.adjustmentFactors;
        const w = record.outcome === 'success' ? 1.0 : record.outcome === 'modified' ? 0.5 : 0.2;
        if (f.speed) this._updatePosterior('speed_multiplier', f.speed, w);
        if (f.feed) this._updatePosterior('feed_multiplier', f.feed, w);
        if (f.doc) this._updatePosterior('doc_multiplier', f.doc, w);
    },
    
    _updatePosterior: function(param, obs, weight = 1.0) {
        const p = this.posteriors[param];
        if (!p) return;
        const n = p.observations + weight;
        const priorPrec = 1 / p.variance, obsPrec = weight / 0.1;
        const newPrec = priorPrec + obsPrec;
        p.mean = Math.max(0.5, Math.min(1.5, (priorPrec * p.mean + obsPrec * obs) / newPrec));
        p.variance = Math.max(0.001, 1 / newPrec);
        p.observations = n;
    },
    
    _adjustPosterior: function(param, delta) {
        const p = this.posteriors[param];
        if (p) { p.mean = Math.max(0.5, Math.min(1.5, p.mean + delta)); p.variance *= 0.95; }
    },
    
    _updateMaterialLearning: function(record) {
        const key = record.material;
        if (!this.materialLearning[key]) this.materialLearning[key] = { speedFactor: 1.0, feedFactor: 1.0, observations: 0 };
        const m = this.materialLearning[key], n = m.observations + 1, f = record.adjustmentFactors;
        if (f.speed) m.speedFactor = (m.speedFactor * m.observations + f.speed) / n;
        if (f.feed) m.feedFactor = (m.feedFactor * m.observations + f.feed) / n;
        m.observations = n;
    },
    
    _updateToolLearning: function(record) {
        const key = record.tool;
        if (!this.toolLearning[key]) this.toolLearning[key] = { speedFactor: 1.0, feedFactor: 1.0, observations: 0 };
        const t = this.toolLearning[key], n = t.observations + 1, f = record.adjustmentFactors;
        if (f.speed) t.speedFactor = (t.speedFactor * t.observations + f.speed) / n;
        if (f.feed) t.feedFactor = (t.feedFactor * t.observations + f.feed) / n;
        t.observations = n;
    },
    
    _updateMachineLearning: function(record) {
        const key = record.machine;
        if (!this.machineLearning[key]) this.machineLearning[key] = { rigidityFactor: 1.0, feedFactor: 1.0, observations: 0 };
        const m = this.machineLearning[key], n = m.observations + 1, f = record.adjustmentFactors;
        if (f.speed) m.rigidityFactor = (m.rigidityFactor * m.observations + f.speed) / n;
        m.observations = n;
    },
    
    _calculateConfidence: function() {
        const avgVar = (this.posteriors.speed_multiplier.variance + this.posteriors.feed_multiplier.variance) / 2;
        return Math.max(0, Math.min(1, 1 - Math.sqrt(avgVar)));
    },
    
    _normalize: function(input) {
        if (!input) return 'unknown';
        if (typeof input === 'string') return input.toLowerCase().replace(/\s+/g, '_');
        return (input.name || input.id || 'unknown').toLowerCase().replace(/\s+/g, '_');
    },
    
    _loadPersistedData: function() {
        try {
            const stored = localStorage.getItem('prism_calculator_learning');
            if (stored) this.importLearningData(JSON.parse(stored));
        } catch (e) { /* No data */ }
    },
    
    _persistData: function() {
        try { localStorage.setItem('prism_calculator_learning', JSON.stringify(this.exportLearningData())); }
        catch (e) { /* Storage unavailable */ }
    },
    
    runSelfTests: function() {
        console.log('[CALCULATOR_LEARNING] Running self-tests...');
        const results = { passed: 0, failed: 0, tests: [] };
        
        try {
            this.initialize();
            results.passed++; results.tests.push({ name: 'Initialize', status: 'PASS' });
        } catch (e) { results.failed++; results.tests.push({ name: 'Initialize', status: 'FAIL', error: e.message }); }
        
        try {
            const outcome = this.recordOutcome({
                material: 'steel_1018', tool: 'endmill',
                recommended: { speed: 5000, feed: 0.02, doc: 0.5, woc: 0.25 },
                actual: { speed: 4800, feed: 0.018, doc: 0.5, woc: 0.25 },
                outcome: 'success', metrics: { toolLife: 45 }
            });
            if (outcome.id) { results.passed++; results.tests.push({ name: 'Record Outcome', status: 'PASS' }); }
            else throw new Error('No ID');
        } catch (e) { results.failed++; results.tests.push({ name: 'Record Outcome', status: 'FAIL', error: e.message }); }
        
        try {
            const adj = this.adjustRecommendation({ speed: 5000, feed: 0.02, doc: 0.5, woc: 0.25 }, { material: 'steel' });
            if (adj.speed && adj.confidence !== undefined) { results.passed++; results.tests.push({ name: 'Adjust Recommendation', status: 'PASS' }); }
            else throw new Error('Invalid');
        } catch (e) { results.failed++; results.tests.push({ name: 'Adjust Recommendation', status: 'FAIL', error: e.message }); }
        
        try {
            const sample = this.thompsonSample('speed_multiplier');
            if (sample >= 0.5 && sample <= 1.5) { results.passed++; results.tests.push({ name: 'Thompson Sampling', status: 'PASS' }); }
            else throw new Error('Out of bounds: ' + sample);
        } catch (e) { results.failed++; results.tests.push({ name: 'Thompson Sampling', status: 'FAIL', error: e.message }); }
        
        console.log('[CALCULATOR_LEARNING] Tests: ' + results.passed + '/' + (results.passed + results.failed) + ' passed');
        return results;
    }
};

if (typeof PRISM_GATEWAY !== 'undefined') {
    PRISM_GATEWAY.register('calculator.learning.outcome', 'PRISM_CALCULATOR_LEARNING_ENGINE.recordOutcome');
    PRISM_GATEWAY.register('calculator.learning.feedback', 'PRISM_CALCULATOR_LEARNING_ENGINE.processFeedback');
    PRISM_GATEWAY.register('calculator.learning.adjust', 'PRISM_CALCULATOR_LEARNING_ENGINE.adjustRecommendation');
    PRISM_GATEWAY.register('calculator.learning.stats', 'PRISM_CALCULATOR_LEARNING_ENGINE.getStatistics');
}

console.log('[PRISM_CALCULATOR_LEARNING_ENGINE] Loaded v1.0.0');


// ═══════════════════════════════════════════════════════════════════════════
// PRISM_CALCULATOR_OPTIMIZER v1.0.0
// PSO Multi-objective optimization for speed/feed
// ═══════════════════════════════════════════════════════════════════════════

const PRISM_CALCULATOR_OPTIMIZER = {
    version: '1.0.0',
    authority: 'PRISM_CALCULATOR_OPTIMIZER',
    
    config: { swarmSize: 30, maxIterations: 100, w: 0.7, c1: 1.5, c2: 1.5, wDecay: 0.99, velClamp: 0.2 },
    
    optimize: function(params) {
        const { material, tool, machine, constraints = {}, objective = 'balanced', returnParetoFront = false } = params;
        const bounds = this._calculateBounds(material, tool, machine, constraints);
        const weights = this._getWeights(objective);
        const swarm = this._initSwarm(bounds);
        
        let globalBest = null, globalBestFitness = -Infinity, paretoFront = [];
        let w = this.config.w;
        
        for (let iter = 0; iter < this.config.maxIterations; iter++) {
            for (const p of swarm) {
                const fitness = this._evaluate(p.position, material, tool, machine, weights);
                p.fitness = fitness.combined; p.objectives = fitness.objectives;
                if (fitness.combined > p.bestFitness) { p.bestFitness = fitness.combined; p.bestPosition = [...p.position]; }
                if (fitness.combined > globalBestFitness) { globalBestFitness = fitness.combined; globalBest = { position: [...p.position], fitness: fitness.combined, objectives: fitness.objectives }; }
                if (returnParetoFront) this._updatePareto(paretoFront, p);
            }
            
            for (const p of swarm) {
                for (let d = 0; d < p.velocity.length; d++) {
                    p.velocity[d] = w * p.velocity[d] + this.config.c1 * Math.random() * (p.bestPosition[d] - p.position[d]) + this.config.c2 * Math.random() * (globalBest.position[d] - p.position[d]);
                    const range = bounds[d].max - bounds[d].min, maxVel = range * this.config.velClamp;
                    p.velocity[d] = Math.max(-maxVel, Math.min(maxVel, p.velocity[d]));
                    p.position[d] = Math.max(bounds[d].min, Math.min(bounds[d].max, p.position[d] + p.velocity[d]));
                }
            }
            w *= this.config.wDecay;
        }
        
        const optimized = this._toParams(globalBest.position, bounds);
        const result = { optimized, metrics: this._metrics(optimized, tool), objectives: globalBest.objectives, fitness: globalBestFitness, goal: objective };
        if (returnParetoFront) result.paretoFront = paretoFront.map(p => ({ params: this._toParams(p.position, bounds), objectives: p.objectives }));
        return result;
    },
    
    multiObjectiveOptimize: function(params) { return this.optimize({ ...params, returnParetoFront: true }); },
    
    quickOptimize: function(params) {
        const saved = { ...this.config };
        this.config.swarmSize = 15; this.config.maxIterations = 30;
        const result = this.optimize(params);
        this.config = saved;
        return result;
    },
    
    _calculateBounds: function(material, tool, machine, constraints) {
        let speedMin = 100, speedMax = 15000, feedMin = 0.001, feedMax = 0.5, docMin = 0.01, docMax = 10, wocMin = 0.01, wocMax = 50;
        if (tool) {
            const d = tool.diameter || 12;
            speedMax = Math.min(speedMax, 300 * 1000 / (Math.PI * d));
            wocMax = Math.min(wocMax, d * 0.8); docMax = Math.min(docMax, d * 2);
        }
        if (machine?.maxRPM) speedMax = Math.min(speedMax, machine.maxRPM);
        if (constraints.speedMin) speedMin = Math.max(speedMin, constraints.speedMin);
        if (constraints.speedMax) speedMax = Math.min(speedMax, constraints.speedMax);
        return [{ name: 'speed', min: speedMin, max: speedMax }, { name: 'feed', min: feedMin, max: feedMax }, { name: 'doc', min: docMin, max: docMax }, { name: 'woc', min: wocMin, max: wocMax }];
    },
    
    _getWeights: function(obj) {
        const presets = { mrr: { MRR: 0.8, TL: 0.1, SF: 0.05, COST: 0.05 }, tool_life: { MRR: 0.1, TL: 0.7, SF: 0.1, COST: 0.1 },
            finish: { MRR: 0.1, TL: 0.1, SF: 0.7, COST: 0.1 }, balanced: { MRR: 0.4, TL: 0.3, SF: 0.2, COST: 0.1 } };
        return presets[obj] || presets.balanced;
    },
    
    _initSwarm: function(bounds) {
        const swarm = [];
        for (let i = 0; i < this.config.swarmSize; i++) {
            const pos = bounds.map(b => b.min + Math.random() * (b.max - b.min));
            const vel = bounds.map(b => (Math.random() - 0.5) * (b.max - b.min) * 0.1);
            swarm.push({ position: pos, velocity: vel, bestPosition: [...pos], bestFitness: -Infinity, fitness: 0, objectives: {} });
        }
        return swarm;
    },
    
    _evaluate: function(pos, material, tool, machine, weights) {
        const [speed, feed, doc, woc] = pos;
        const flutes = tool?.flutes || 4, diameter = tool?.diameter || 12;
        const feedrate = speed * feed * flutes, mrr = feedrate * doc * woc / 1000;
        const Vc = speed * Math.PI * diameter / 1000;
        const matN = material?.taylorN || 0.25, matC = material?.taylorC || 200;
        const toolLife = matC / Math.pow(Vc, 1/matN);
        const cr = tool?.cornerRadius || 0.4, Ra = Math.max(0.2, (feed * feed * 1e6) / (32 * cr) * (1 + Vc/500));
        const toolCost = tool?.cost || 50, machCost = machine?.hourlyRate || 75;
        const costPerVol = mrr > 0 ? ((toolLife > 0 ? toolCost / toolLife : toolCost) + machCost / 60) / mrr : 999;
        
        const objectives = { MRR: Math.min(1, mrr / 100), TL: Math.min(1, toolLife / 120), SF: Math.max(0, 1 - Ra / 10), COST: Math.max(0, 1 - costPerVol / 5) };
        const combined = weights.MRR * objectives.MRR + weights.TL * objectives.TL + weights.SF * objectives.SF + weights.COST * objectives.COST;
        return { combined, objectives, raw: { mrr, toolLife, Ra, costPerVol } };
    },
    
    _updatePareto: function(front, particle) {
        const dominated = front.some(p => this._dominates(p.objectives, particle.objectives));
        if (dominated) return;
        for (let i = front.length - 1; i >= 0; i--) if (this._dominates(particle.objectives, front[i].objectives)) front.splice(i, 1);
        front.push({ position: [...particle.position], objectives: { ...particle.objectives } });
        if (front.length > 50) { front.sort((a, b) => b.objectives.MRR - a.objectives.MRR); front.splice(50); }
    },
    
    _dominates: function(o1, o2) {
        let better = false;
        for (const k of Object.keys(o1)) { if (o1[k] > o2[k]) better = true; if (o1[k] < o2[k]) return false; }
        return better;
    },
    
    _toParams: function(pos, bounds) {
        return { speed: Math.round(pos[0]), feed: Math.round(pos[1] * 10000) / 10000, doc: Math.round(pos[2] * 1000) / 1000, woc: Math.round(pos[3] * 1000) / 1000 };
    },
    
    _metrics: function(params, tool) {
        const flutes = tool?.flutes || 4, diameter = tool?.diameter || 12;
        const feedrate = params.speed * params.feed * flutes, mrr = feedrate * params.doc * params.woc / 1000;
        return { feedrate: Math.round(feedrate), mrr: Math.round(mrr * 100) / 100, surfaceSpeed: Math.round(params.speed * Math.PI * diameter / 1000 * 10) / 10 };
    },
    
    runSelfTests: function() {
        console.log('[CALCULATOR_OPTIMIZER] Running self-tests...');
        const results = { passed: 0, failed: 0, tests: [] };
        
        try {
            const r = this.optimize({ material: { taylorN: 0.25, taylorC: 200 }, tool: { diameter: 12, flutes: 4 }, machine: { maxRPM: 10000 }, objective: 'balanced' });
            if (r.optimized.speed > 0) { results.passed++; results.tests.push({ name: 'Optimize', status: 'PASS' }); }
            else throw new Error('Invalid');
        } catch (e) { results.failed++; results.tests.push({ name: 'Optimize', status: 'FAIL', error: e.message }); }
        
        try {
            const r = this.multiObjectiveOptimize({ material: { taylorN: 0.25 }, tool: { diameter: 12 } });
            if (r.paretoFront && r.paretoFront.length > 0) { results.passed++; results.tests.push({ name: 'Multi-objective', status: 'PASS' }); }
            else throw new Error('No Pareto');
        } catch (e) { results.failed++; results.tests.push({ name: 'Multi-objective', status: 'FAIL', error: e.message }); }
        
        console.log('[CALCULATOR_OPTIMIZER] Tests: ' + results.passed + '/' + (results.passed + results.failed) + ' passed');
        return results;
    }
};

if (typeof PRISM_GATEWAY !== 'undefined') {
    PRISM_GATEWAY.register('calculator.optimize', 'PRISM_CALCULATOR_OPTIMIZER.optimize');
    PRISM_GATEWAY.register('calculator.optimize.multi', 'PRISM_CALCULATOR_OPTIMIZER.multiObjectiveOptimize');
    PRISM_GATEWAY.register('calculator.optimize.quick', 'PRISM_CALCULATOR_OPTIMIZER.quickOptimize');
}

console.log('[PRISM_CALCULATOR_OPTIMIZER] Loaded v1.0.0');


// ═══════════════════════════════════════════════════════════════════════════
// PRISM_CALCULATOR_RECOMMENDATION_ENGINE v1.0.0
// Material recognition and tool recommendations
// ═══════════════════════════════════════════════════════════════════════════

const PRISM_CALCULATOR_RECOMMENDATION_ENGINE = {
    version: '1.0.0',
    authority: 'PRISM_CALCULATOR_RECOMMENDATION_ENGINE',
    
    getRecommendation: function(params) {
        const { material, tool, operation, machine, requirements = {} } = params;
        const matInfo = this._identifyMaterial(material);
        const toolRec = tool ? this._validateTool(tool, matInfo, operation) : this._recommendTool(matInfo, operation);
        const cuttingParams = this._getCuttingParams(matInfo, toolRec, operation, machine);
        
        let adjusted = cuttingParams;
        if (typeof PRISM_CALCULATOR_LEARNING_ENGINE !== 'undefined') {
            adjusted = PRISM_CALCULATOR_LEARNING_ENGINE.adjustRecommendation(cuttingParams, { material: matInfo, tool: toolRec, machine });
        }
        
        return { material: matInfo, tool: toolRec, operation, parameters: adjusted,
            confidence: this._calcConfidence(matInfo, toolRec, adjusted),
            warnings: this._getWarnings(matInfo, toolRec, adjusted, machine) };
    },
    
    recognizeMaterial: function(input) { return this._identifyMaterial(input); },
    
    recommendTools: function(material, operation, count = 3) {
        const matInfo = this._identifyMaterial(material);
        const tools = [], strategies = ['productivity', 'finish', 'cost'];
        for (const s of strategies) {
            const t = this._recommendTool(matInfo, operation, { priority: s });
            if (t && !tools.find(x => x.type === t.type && x.diameter === t.diameter)) tools.push({ ...t, strategy: s });
            if (tools.length >= count) break;
        }
        return tools;
    },
    
    _identifyMaterial: function(input) {
        if (!input) return this._defaultMaterial();
        if (input.id && input.machinabilityIndex) return input;
        if (typeof input === 'string') return this._parseMaterial(input);
        if (input.hardness) return this._inferMaterial(input);
        return this._defaultMaterial();
    },
    
    _parseMaterial: function(str) {
        const lower = str.toLowerCase();
        const patterns = [
            { p: /aluminum|al\s*\d|6061|7075/, cat: 'aluminum', sfm: 800, mi: 500 },
            { p: /1018|1020|1045|a36|carbon.*steel/, cat: 'carbon_steel', sfm: 100, mi: 100 },
            { p: /304|316|stainless/, cat: 'stainless', sfm: 80, mi: 45 },
            { p: /4140|4340|alloy.*steel/, cat: 'alloy_steel', sfm: 80, mi: 65 },
            { p: /titanium|ti-?6/, cat: 'titanium', sfm: 60, mi: 25 },
            { p: /inconel|hastelloy/, cat: 'superalloy', sfm: 30, mi: 15 },
            { p: /brass|bronze|copper/, cat: 'copper', sfm: 400, mi: 300 },
            { p: /cast.*iron|ductile/, cat: 'cast_iron', sfm: 100, mi: 80 },
            { p: /plastic|nylon|delrin|peek/, cat: 'plastic', sfm: 500, mi: 400 }
        ];
        for (const { p, cat, sfm, mi } of patterns) {
            if (p.test(lower)) return { id: 'parsed_' + cat, name: str, category: cat, machinabilityIndex: mi, recommendedSFM: { carbide: sfm }, source: 'parsed' };
        }
        return this._defaultMaterial();
    },
    
    _inferMaterial: function(props) {
        const h = props.hardness || props.HRC || 30;
        let cat = 'steel', mi = 100, sfm = 100;
        if (h < 20) { cat = 'aluminum'; mi = 500; sfm = 800; }
        else if (h < 35) { cat = 'steel'; mi = 100; sfm = 100; }
        else if (h < 50) { cat = 'tool_steel'; mi = 60; sfm = 60; }
        else { cat = 'hardened_steel'; mi = 30; sfm = 40; }
        return { id: 'inferred_' + cat, name: 'Inferred ' + cat, category: cat, hardness: h, machinabilityIndex: mi, recommendedSFM: { carbide: sfm }, source: 'inferred' };
    },
    
    _defaultMaterial: function() {
        return { id: 'default_steel', name: 'General Steel', category: 'carbon_steel', hardness: 200, machinabilityIndex: 100, recommendedSFM: { carbide: 100 }, source: 'default' };
    },
    
    _recommendTool: function(material, operation, req = {}) {
        const cat = material.category || 'steel';
        let type = 'endmill', diameter = 12, flutes = 4, coating = 'AlTiN';
        if (operation === 'roughing') { diameter = 16; flutes = cat === 'aluminum' ? 3 : 4; }
        else if (operation === 'finishing') { diameter = 6; flutes = cat === 'aluminum' ? 3 : 5; }
        else if (operation === 'slotting') { diameter = 10; flutes = cat === 'aluminum' ? 2 : 4; coating = 'TiAlN'; }
        else if (operation === 'drilling') { type = 'drill'; flutes = 2; coating = 'TiN'; }
        return { type, diameter, flutes, coating, cornerRadius: diameter < 12 ? 0.2 : 0.4, material: 'carbide' };
    },
    
    _validateTool: function(tool, material, operation) {
        const warnings = [];
        if (material.category === 'aluminum' && tool.flutes > 3) warnings.push('Fewer flutes recommended for aluminum');
        if (operation === 'finishing' && tool.diameter > 16) warnings.push('Smaller diameter recommended for finishing');
        return { ...tool, validationWarnings: warnings, suitability: warnings.length === 0 ? 'optimal' : 'acceptable' };
    },
    
    _getCuttingParams: function(material, tool, operation, machine) {
        const sfm = material.recommendedSFM?.carbide || 100, mi = material.machinabilityIndex || 100;
        const diameter = tool.diameter || 12, flutes = tool.flutes || 4;
        let rpm = (sfm * 1000) / (Math.PI * diameter), fpt, doc, woc;
        
        if (operation === 'roughing' || operation === 'adaptive') { fpt = 0.05 * (mi / 100); doc = diameter * 1.5; woc = diameter * 0.2; rpm *= 1.1; }
        else if (operation === 'finishing') { fpt = 0.03 * (mi / 100); doc = 0.5; woc = diameter * 0.5; }
        else if (operation === 'slotting') { fpt = 0.04 * (mi / 100); doc = diameter * 0.5; woc = diameter; rpm *= 0.8; }
        else { fpt = 0.04 * (mi / 100); doc = diameter * 0.5; woc = diameter * 0.5; }
        
        if (machine?.maxRPM) rpm = Math.min(rpm, machine.maxRPM);
        return { speed: Math.round(rpm), feed: Math.round(fpt * 10000) / 10000, doc: Math.round(doc * 100) / 100, woc: Math.round(woc * 100) / 100, feedrate: Math.round(rpm * fpt * flutes), surfaceSpeed: Math.round(rpm * Math.PI * diameter / 1000 * 10) / 10 };
    },
    
    _calcConfidence: function(mat, tool, params) {
        let c = 0.8;
        if (mat.source === 'inferred') c -= 0.1;
        if (mat.source === 'parsed') c -= 0.05;
        if (mat.source === 'default') c -= 0.2;
        if (tool.validationWarnings?.length > 0) c -= 0.1;
        if (params.learningApplied) c += 0.1;
        return Math.max(0.3, Math.min(1.0, c));
    },
    
    _getWarnings: function(mat, tool, params, machine) {
        const w = [];
        if (mat.source === 'default') w.push({ level: 'info', message: 'Material not identified - using default' });
        if (machine?.maxRPM && params.speed >= machine.maxRPM * 0.95) w.push({ level: 'warning', message: 'Speed near machine limit' });
        if (tool.validationWarnings) tool.validationWarnings.forEach(m => w.push({ level: 'info', message: m }));
        return w;
    },
    
    runSelfTests: function() {
        console.log('[CALCULATOR_RECOMMENDATION] Running self-tests...');
        const results = { passed: 0, failed: 0, tests: [] };
        
        try {
            const r = this.getRecommendation({ material: 'aluminum 6061', operation: 'roughing' });
            if (r.material && r.tool && r.parameters.speed > 0) { results.passed++; results.tests.push({ name: 'Get Recommendation', status: 'PASS' }); }
            else throw new Error('Invalid');
        } catch (e) { results.failed++; results.tests.push({ name: 'Get Recommendation', status: 'FAIL', error: e.message }); }
        
        try {
            const m = this.recognizeMaterial('304 stainless steel');
            if (m.category === 'stainless') { results.passed++; results.tests.push({ name: 'Recognize Material', status: 'PASS' }); }
            else throw new Error('Wrong: ' + m.category);
        } catch (e) { results.failed++; results.tests.push({ name: 'Recognize Material', status: 'FAIL', error: e.message }); }
        
        try {
            const t = this.recommendTools('titanium', 'roughing', 3);
            if (t.length > 0) { results.passed++; results.tests.push({ name: 'Recommend Tools', status: 'PASS' }); }
            else throw new Error('No tools');
        } catch (e) { results.failed++; results.tests.push({ name: 'Recommend Tools', status: 'FAIL', error: e.message }); }
        
        console.log('[CALCULATOR_RECOMMENDATION] Tests: ' + results.passed + '/' + (results.passed + results.failed) + ' passed');
        return results;
    }
};

if (typeof PRISM_GATEWAY !== 'undefined') {
    PRISM_GATEWAY.register('calculator.recommend', 'PRISM_CALCULATOR_RECOMMENDATION_ENGINE.getRecommendation');
    PRISM_GATEWAY.register('calculator.recommend.material', 'PRISM_CALCULATOR_RECOMMENDATION_ENGINE.recognizeMaterial');
    PRISM_GATEWAY.register('calculator.recommend.tools', 'PRISM_CALCULATOR_RECOMMENDATION_ENGINE.recommendTools');
}

console.log('[PRISM_CALCULATOR_RECOMMENDATION_ENGINE] Loaded v1.0.0');


// ═══════════════════════════════════════════════════════════════════════════
// PRISM_CALCULATOR_CHATTER_ENGINE v1.0.0
// FFT-based chatter prediction and stability lobe diagrams
// ═══════════════════════════════════════════════════════════════════════════

const PRISM_CALCULATOR_CHATTER_ENGINE = {
    version: '1.0.0',
    authority: 'PRISM_CALCULATOR_CHATTER_ENGINE',
    
    analyzeStability: function(params) {
        const { speed, doc, tool, machine, material } = params;
        const dynamics = this._getDynamics(tool, machine);
        const flutes = tool?.flutes || 4;
        const toothPassFreq = speed * flutes / 60;
        const blim = this._calcCriticalDepth(speed, dynamics, material, flutes);
        const stable = doc < blim, margin = blim / doc;
        const risk = this._calcRisk(doc, blim);
        
        return { stable, chatterRisk: risk.level, chatterProbability: risk.probability,
            toothPassingFrequency: toothPassFreq, naturalFrequency: dynamics.fn,
            stabilityMargin: Math.max(0, margin - 1), criticalDepth: blim,
            recommendations: this._getRecommendations(stable, risk, blim, doc),
            nearestStablePocket: this._findStablePocket(speed, doc, dynamics, material, flutes) };
    },
    
    generateSLD: function(params) {
        const { tool, machine, material, speedRange = { min: 1000, max: 15000, points: 100 } } = params;
        const dynamics = this._getDynamics(tool, machine), flutes = tool?.flutes || 4;
        const sld = { speeds: [], lobes: [], criticalDepths: [], metadata: { naturalFrequency: dynamics.fn, damping: dynamics.zeta, flutes } };
        
        const dSpeed = (speedRange.max - speedRange.min) / speedRange.points;
        for (let i = 0; i <= speedRange.points; i++) {
            const rpm = speedRange.min + i * dSpeed;
            sld.speeds.push(rpm);
            sld.criticalDepths.push(this._calcCriticalDepth(rpm, dynamics, material, flutes));
        }
        
        sld.stablePockets = this._identifyPockets(sld);
        return sld;
    },
    
    findStableConditions: function(params) {
        const { tool, machine, material, targetMRR } = params;
        const sld = this.generateSLD({ tool, machine, material });
        const viable = sld.stablePockets.filter(p => {
            const diameter = tool?.diameter || 12, feedrate = p.speed * 0.05 * (tool?.flutes || 4);
            return feedrate * p.maxDoc * diameter * 0.5 / 1000 >= targetMRR * 0.8;
        });
        
        if (viable.length === 0) return { found: false, message: 'No stable conditions for target MRR', alternatives: sld.stablePockets.slice(0, 3) };
        viable.sort((a, b) => (b.speed * b.maxDoc) - (a.speed * a.maxDoc));
        return { found: true, optimal: viable[0], alternatives: viable.slice(1, 4), sld };
    },
    
    _getDynamics: function(tool, machine) {
        const diameter = tool?.diameter || 12, stickout = tool?.stickout || diameter * 4;
        const fn = machine?.naturalFrequency || (3000 / (1 + stickout / 30));
        const zeta = machine?.dampingRatio || 0.03;
        const k = machine?.modalStiffness || (5e7 / (1 + stickout / 50));
        return { fn, zeta, k, omega_n: 2 * Math.PI * fn };
    },
    
    _calcCriticalDepth: function(rpm, dynamics, material, flutes) {
        const omega_t = 2 * Math.PI * rpm * flutes / 60;
        const r = omega_t / dynamics.omega_n;
        const G_real = (1 - r * r) / (Math.pow(1 - r * r, 2) + Math.pow(2 * dynamics.zeta * r, 2));
        const Kc = material?.specificCuttingForce || 2000;
        const blim = Math.abs(dynamics.k / (2 * Kc * flutes * Math.abs(G_real + 0.001)));
        return Math.max(0.1, Math.min(50, blim));
    },
    
    _calcRisk: function(doc, blim) {
        const ratio = doc / blim;
        if (ratio < 0.7) return { level: 'low', probability: 0.05 };
        if (ratio < 0.9) return { level: 'moderate', probability: 0.2 };
        if (ratio < 1.0) return { level: 'high', probability: 0.5 };
        if (ratio < 1.2) return { level: 'very_high', probability: 0.75 };
        return { level: 'certain', probability: 0.95 };
    },
    
    _getRecommendations: function(stable, risk, blim, doc) {
        const r = [];
        if (!stable) {
            r.push({ type: 'reduce_doc', message: 'Reduce DOC to below ' + blim.toFixed(2) + ' mm', priority: 'high' });
            r.push({ type: 'adjust_speed', message: 'Try different spindle speed for stable pocket', priority: 'medium' });
        } else if (risk.level === 'high') {
            r.push({ type: 'safety_margin', message: 'DOC close to stability limit', priority: 'medium' });
        }
        return r;
    },
    
    _findStablePocket: function(speed, doc, dynamics, material, flutes) {
        let best = null, minDist = Infinity;
        for (let rpm = speed - 2000; rpm <= speed + 2000; rpm += 100) {
            if (rpm < 500) continue;
            const blim = this._calcCriticalDepth(rpm, dynamics, material, flutes);
            if (doc < blim && Math.abs(rpm - speed) < minDist) { minDist = Math.abs(rpm - speed); best = { speed: rpm, maxDoc: blim }; }
        }
        return best;
    },
    
    _identifyPockets: function(sld) {
        const pockets = [];
        for (let i = 1; i < sld.criticalDepths.length - 1; i++) {
            const prev = sld.criticalDepths[i - 1], curr = sld.criticalDepths[i], next = sld.criticalDepths[i + 1];
            if (curr > prev && curr > next && curr > 2) pockets.push({ speed: Math.round(sld.speeds[i]), maxDoc: Math.round(curr * 100) / 100 });
        }
        pockets.sort((a, b) => b.maxDoc - a.maxDoc);
        return pockets;
    },
    
    runSelfTests: function() {
        console.log('[CALCULATOR_CHATTER] Running self-tests...');
        const results = { passed: 0, failed: 0, tests: [] };
        
        try {
            const r = this.analyzeStability({ speed: 8000, doc: 2.0, tool: { diameter: 12, flutes: 4 }, machine: { naturalFrequency: 800 }, material: { specificCuttingForce: 2000 } });
            if (r.stable !== undefined && r.chatterRisk) { results.passed++; results.tests.push({ name: 'Analyze Stability', status: 'PASS' }); }
            else throw new Error('Invalid');
        } catch (e) { results.failed++; results.tests.push({ name: 'Analyze Stability', status: 'FAIL', error: e.message }); }
        
        try {
            const sld = this.generateSLD({ tool: { diameter: 12, flutes: 4 }, machine: { naturalFrequency: 800 } });
            if (sld.criticalDepths.length > 0) { results.passed++; results.tests.push({ name: 'Generate SLD', status: 'PASS' }); }
            else throw new Error('No data');
        } catch (e) { results.failed++; results.tests.push({ name: 'Generate SLD', status: 'FAIL', error: e.message }); }
        
        console.log('[CALCULATOR_CHATTER] Tests: ' + results.passed + '/' + (results.passed + results.failed) + ' passed');
        return results;
    }
};

if (typeof PRISM_GATEWAY !== 'undefined') {
    PRISM_GATEWAY.register('calculator.chatter.analyze', 'PRISM_CALCULATOR_CHATTER_ENGINE.analyzeStability');
    PRISM_GATEWAY.register('calculator.chatter.sld', 'PRISM_CALCULATOR_CHATTER_ENGINE.generateSLD');
    PRISM_GATEWAY.register('calculator.chatter.findStable', 'PRISM_CALCULATOR_CHATTER_ENGINE.findStableConditions');
}

console.log('[PRISM_CALCULATOR_CHATTER_ENGINE] Loaded v1.0.0');


// ╔═══════════════════════════════════════════════════════════════════════════════════════════════════╗
// ║                    PRODUCT 2: POST PROCESSOR GENERATOR                                            ║
// ╚═══════════════════════════════════════════════════════════════════════════════════════════════════╝

// ═══════════════════════════════════════════════════════════════════════════
// PRISM_POST_OPTIMIZER v1.0.0
// G-code motion optimization and compression
// ═══════════════════════════════════════════════════════════════════════════

const PRISM_POST_OPTIMIZER = {
    version: '1.0.0',
    authority: 'PRISM_POST_OPTIMIZER',
    
    optimizeMotion: function(gcode, options = {}) {
        const { removeRedundant = true, optimizeRapids = true, arcTolerance = 0.005 } = options;
        let lines = gcode.split('\n');
        const stats = { originalLines: lines.length, removedRedundant: 0, rapidsOptimized: 0 };
        
        if (removeRedundant) { const r = this._removeRedundant(lines); lines = r.lines; stats.removedRedundant = r.removed; }
        if (optimizeRapids) { const r = this._optimizeRapids(lines); lines = r.lines; stats.rapidsOptimized = r.optimized; }
        
        return { gcode: lines.join('\n'), stats, reduction: ((stats.originalLines - lines.length) / stats.originalLines * 100).toFixed(1) + '%' };
    },
    
    compress: function(gcode, options = {}) {
        const { removeComments = false, removeWhitespace = true, removeBlockNumbers = false, precision = 4 } = options;
        let lines = gcode.split('\n'), compressed = [];
        
        for (let line of lines) {
            if (removeComments) line = line.replace(/\(.*?\)/g, '').replace(/;.*$/, '');
            if (removeWhitespace) line = line.trim().replace(/\s+/g, ' ');
            if (removeBlockNumbers) line = line.replace(/^N\d+\s*/i, '');
            line = line.replace(/([XYZABC])(-?\d+\.\d{5,})/gi, (m, a, n) => a + parseFloat(n).toFixed(precision));
            if (line.trim()) compressed.push(line);
        }
        
        const result = compressed.join('\n');
        return { gcode: result, originalSize: gcode.length, compressedSize: result.length, compression: ((1 - result.length / gcode.length) * 100).toFixed(1) + '%' };
    },
    
    analyzeOptimizations: function(gcode) {
        const lines = gcode.split('\n');
        const metrics = { totalLines: lines.length, rapidMoves: 0, linearMoves: 0, arcMoves: 0, comments: 0, consecutiveRapids: 0 };
        let lastWasRapid = false;
        
        for (const line of lines) {
            const u = line.toUpperCase().trim();
            if (u.startsWith('G00') || u.startsWith('G0 ')) { metrics.rapidMoves++; if (lastWasRapid) metrics.consecutiveRapids++; lastWasRapid = true; }
            else { lastWasRapid = false; }
            if (u.startsWith('G01') || u.startsWith('G1 ')) metrics.linearMoves++;
            if (u.startsWith('G02') || u.startsWith('G03') || u.startsWith('G2 ') || u.startsWith('G3 ')) metrics.arcMoves++;
            if (u.includes('(') || u.startsWith(';')) metrics.comments++;
        }
        
        const suggestions = [];
        if (metrics.consecutiveRapids > 10) suggestions.push({ type: 'rapid_opt', message: metrics.consecutiveRapids + ' consecutive rapids could be combined', impact: 'medium' });
        if (metrics.arcMoves < metrics.linearMoves * 0.05 && metrics.linearMoves > 100) suggestions.push({ type: 'arc_fitting', message: 'Many linears could be arcs', impact: 'high' });
        
        return { metrics, suggestions, score: Math.max(0, 100 - (metrics.consecutiveRapids > 10 ? 5 : 0) - (metrics.arcMoves < metrics.linearMoves * 0.05 ? 10 : 0)) };
    },
    
    _removeRedundant: function(lines) {
        const result = []; let removed = 0, lastX = null, lastY = null, lastZ = null;
        for (const line of lines) {
            const u = line.toUpperCase().trim();
            const xM = u.match(/X(-?\d+\.?\d*)/), yM = u.match(/Y(-?\d+\.?\d*)/), zM = u.match(/Z(-?\d+\.?\d*)/);
            const gM = u.match(/G0[01]/);
            
            let keep = true;
            if (gM && xM && xM[1] === lastX && yM && yM[1] === lastY && zM && zM[1] === lastZ) { keep = false; removed++; }
            if (xM) lastX = xM[1]; if (yM) lastY = yM[1]; if (zM) lastZ = zM[1];
            if (keep) result.push(line);
        }
        return { lines: result, removed };
    },
    
    _optimizeRapids: function(lines) {
        const result = []; let optimized = 0, rapidBuf = [];
        for (const line of lines) {
            const u = line.toUpperCase().trim();
            if (u.startsWith('G00') || u.startsWith('G0 ')) { rapidBuf.push(line); }
            else {
                if (rapidBuf.length > 1) { result.push(this._combineRapids(rapidBuf)); optimized += rapidBuf.length - 1; }
                else if (rapidBuf.length === 1) result.push(rapidBuf[0]);
                rapidBuf = []; result.push(line);
            }
        }
        if (rapidBuf.length > 1) { result.push(this._combineRapids(rapidBuf)); optimized += rapidBuf.length - 1; }
        else if (rapidBuf.length === 1) result.push(rapidBuf[0]);
        return { lines: result, optimized };
    },
    
    _combineRapids: function(rapids) {
        let fX = null, fY = null, fZ = null;
        for (const r of rapids) {
            const u = r.toUpperCase();
            const xM = u.match(/X(-?\d+\.?\d*)/), yM = u.match(/Y(-?\d+\.?\d*)/), zM = u.match(/Z(-?\d+\.?\d*)/);
            if (xM) fX = xM[1]; if (yM) fY = yM[1]; if (zM) fZ = zM[1];
        }
        let c = 'G00';
        if (fX !== null) c += ' X' + fX; if (fY !== null) c += ' Y' + fY; if (fZ !== null) c += ' Z' + fZ;
        return c;
    },
    
    runSelfTests: function() {
        console.log('[POST_OPTIMIZER] Running self-tests...');
        const results = { passed: 0, failed: 0, tests: [] };
        
        try {
            const r = this.optimizeMotion('G00 X0 Y0\nG00 X10 Y10\nG00 X20 Y20\nG01 X30 Y30 F500');
            if (r.gcode && r.stats) { results.passed++; results.tests.push({ name: 'Optimize Motion', status: 'PASS' }); }
            else throw new Error('Invalid');
        } catch (e) { results.failed++; results.tests.push({ name: 'Optimize Motion', status: 'FAIL', error: e.message }); }
        
        try {
            const r = this.compress('N10 G00 X1.123456789\n; comment\nN20 G01 Z-0.5', { removeComments: true, removeBlockNumbers: true });
            if (r.compressedSize < r.originalSize) { results.passed++; results.tests.push({ name: 'Compress', status: 'PASS' }); }
            else throw new Error('No compression');
        } catch (e) { results.failed++; results.tests.push({ name: 'Compress', status: 'FAIL', error: e.message }); }
        
        console.log('[POST_OPTIMIZER] Tests: ' + results.passed + '/' + (results.passed + results.failed) + ' passed');
        return results;
    }
};

if (typeof PRISM_GATEWAY !== 'undefined') {
    PRISM_GATEWAY.register('post.optimize.motion', 'PRISM_POST_OPTIMIZER.optimizeMotion');
    PRISM_GATEWAY.register('post.optimize.compress', 'PRISM_POST_OPTIMIZER.compress');
    PRISM_GATEWAY.register('post.optimize.analyze', 'PRISM_POST_OPTIMIZER.analyzeOptimizations');
}

console.log('[PRISM_POST_OPTIMIZER] Loaded v1.0.0');


// ═══════════════════════════════════════════════════════════════════════════
// PRISM_POST_ANALYSIS_AI v1.0.0
// AI-powered G-code analysis and controller identification
// ═══════════════════════════════════════════════════════════════════════════

const PRISM_POST_ANALYSIS_AI = {
    version: '1.0.0',
    authority: 'PRISM_POST_ANALYSIS_AI',
    
    controllerPatterns: {
        fanuc: { start: [/O\d{4}/, /%/], tool: [/M06/, /T\d+/], spindle: [/M03/, /M04/], end: [/M30/, /M02/] },
        siemens: { start: [/%MPF/, /%SPF/], tool: [/T=/, /M6/], spindle: [/M3/, /M4/], end: [/M30/, /M17/] },
        haas: { start: [/O\d{5}/, /%/], tool: [/M06/, /T\d+/], spindle: [/M03/, /M04/], end: [/M30/] },
        heidenhain: { start: [/BEGIN PGM/], tool: [/TOOL CALL/], spindle: [/M3/, /M4/], end: [/END PGM/] }
    },
    
    identifyController: function(gcode) {
        const content = gcode.split('\n').slice(0, 50).join('\n').toUpperCase();
        const scores = {};
        
        for (const [ctrl, patterns] of Object.entries(this.controllerPatterns)) {
            scores[ctrl] = 0;
            for (const p of patterns.start) if (p.test(content)) scores[ctrl] += 3;
            for (const p of patterns.tool) if (p.test(content)) scores[ctrl] += 1;
            for (const p of patterns.end) if (p.test(content)) scores[ctrl] += 2;
        }
        
        if (content.includes('BEGIN PGM')) scores.heidenhain = 100;
        if (content.includes('%MPF') || content.includes('%SPF')) scores.siemens = 100;
        
        let best = 'unknown', bestScore = 0;
        for (const [c, s] of Object.entries(scores)) if (s > bestScore) { bestScore = s; best = c; }
        
        return { controller: best, confidence: Math.min(1, bestScore / 15), scores };
    },
    
    deepAnalyze: function(gcode) {
        const lines = gcode.split('\n');
        const ctrlInfo = this.identifyController(gcode);
        
        return {
            controller: ctrlInfo,
            structure: this._analyzeStructure(lines),
            motion: this._analyzeMotion(lines),
            tooling: this._analyzeTooling(lines),
            safety: this._analyzeSafety(lines),
            recommendations: this._getRecommendations(ctrlInfo, gcode)
        };
    },
    
    detectErrors: function(gcode) {
        const lines = gcode.split('\n'), errors = [], warnings = [];
        let spindleOn = false;
        
        for (let i = 0; i < lines.length; i++) {
            const u = lines[i].toUpperCase().trim(), ln = i + 1;
            
            if ((u.includes('G01') || u.includes('G1 ')) && !spindleOn)
                warnings.push({ line: ln, type: 'spindle_off', message: 'Cut without spindle', severity: 'warning' });
            
            if (u.includes('M03') || u.includes('M04') || u.includes('M3 ') || u.includes('M4 ')) spindleOn = true;
            if (u.includes('M05') || u.includes('M5 ')) spindleOn = false;
            
            if ((u.includes('G02') || u.includes('G03') || u.includes('G2 ') || u.includes('G3 ')) && !u.includes('I') && !u.includes('J') && !u.includes('R'))
                errors.push({ line: ln, type: 'arc_missing_center', message: 'Arc missing I/J or R', severity: 'error' });
        }
        
        return { errors, warnings, errorCount: errors.length, warningCount: warnings.length };
    },
    
    suggestEnhancements: function(gcode) {
        const analysis = this.deepAnalyze(gcode), errorCheck = this.detectErrors(gcode), suggestions = [];
        
        for (const e of errorCheck.errors) suggestions.push({ type: 'error_fix', message: e.message, priority: 'critical', line: e.line });
        for (const issue of analysis.safety.issues) suggestions.push({ type: 'safety', message: issue.message, priority: 'high' });
        
        suggestions.sort((a, b) => ({ critical: 0, high: 1, medium: 2, low: 3 })[a.priority] - ({ critical: 0, high: 1, medium: 2, low: 3 })[b.priority]);
        return { suggestions, analysis, errors: errorCheck };
    },
    
    _analyzeStructure: function(lines) {
        const s = { hasHeader: false, hasSafetyBlock: false, hasToolChanges: false, hasComments: false };
        for (let i = 0; i < lines.length; i++) {
            const u = lines[i].toUpperCase();
            if (u.includes('(') || u.includes(';')) { s.hasComments = true; if (i < 10) s.hasHeader = true; }
            if (u.includes('M06') || u.includes('M6 ')) s.hasToolChanges = true;
            if (u.includes('G28') || u.includes('G53')) s.hasSafetyBlock = true;
        }
        return s;
    },
    
    _analyzeMotion: function(lines) {
        const m = { rapidMoves: 0, linearMoves: 0, arcMoves: 0, totalDistance: 0 };
        let lastX = 0, lastY = 0, lastZ = 0;
        for (const line of lines) {
            const u = line.toUpperCase();
            if (u.includes('G00') || u.includes('G0 ')) m.rapidMoves++;
            if (u.includes('G01') || u.includes('G1 ')) m.linearMoves++;
            if (u.includes('G02') || u.includes('G03')) m.arcMoves++;
            const xM = u.match(/X(-?\d+\.?\d*)/), yM = u.match(/Y(-?\d+\.?\d*)/), zM = u.match(/Z(-?\d+\.?\d*)/);
            const nX = xM ? parseFloat(xM[1]) : lastX, nY = yM ? parseFloat(yM[1]) : lastY, nZ = zM ? parseFloat(zM[1]) : lastZ;
            m.totalDistance += Math.sqrt(Math.pow(nX - lastX, 2) + Math.pow(nY - lastY, 2) + Math.pow(nZ - lastZ, 2));
            lastX = nX; lastY = nY; lastZ = nZ;
        }
        return m;
    },
    
    _analyzeTooling: function(lines) {
        const toolSet = new Set(); let changes = 0;
        for (const line of lines) {
            const u = line.toUpperCase(), m = u.match(/T(\d+)/);
            if (m) toolSet.add(m[1]);
            if (u.includes('M06') || u.includes('M6 ')) changes++;
        }
        return { tools: Array.from(toolSet).sort((a, b) => parseInt(a) - parseInt(b)), toolChanges: changes };
    },
    
    _analyzeSafety: function(lines) {
        const content = lines.join('\n').toUpperCase();
        const s = { hasHomeReturn: content.includes('G28') || content.includes('G53'),
            hasSafeZ: /G[09][01].*Z\d/.test(content),
            hasSpindleOff: content.includes('M05') || content.includes('M5 '),
            hasCoolantOff: content.includes('M09') || content.includes('M9 '),
            issues: [] };
        if (!s.hasSpindleOff) s.issues.push({ type: 'missing_spindle_stop', message: 'May not have M05 at end' });
        if (!s.hasCoolantOff) s.issues.push({ type: 'missing_coolant_stop', message: 'May not have M09 at end' });
        return s;
    },
    
    _getRecommendations: function(ctrlInfo, gcode) {
        const r = [];
        if (ctrlInfo.controller === 'fanuc' && !gcode.includes('G54')) r.push({ type: 'work_offset', message: 'Consider adding work offset G54', priority: 'low' });
        if (ctrlInfo.controller === 'haas' && !gcode.includes('G43')) r.push({ type: 'tool_length', message: 'Consider adding tool length comp G43', priority: 'medium' });
        return r;
    },
    
    runSelfTests: function() {
        console.log('[POST_ANALYSIS_AI] Running self-tests...');
        const results = { passed: 0, failed: 0, tests: [] };
        
        try {
            const r = this.identifyController('O1234\nG00 G90 G54\nT01 M06\nM03 S5000\nM30');
            if (r.controller && r.confidence > 0) { results.passed++; results.tests.push({ name: 'Identify Controller', status: 'PASS' }); }
            else throw new Error('Failed');
        } catch (e) { results.failed++; results.tests.push({ name: 'Identify Controller', status: 'FAIL', error: e.message }); }
        
        try {
            const r = this.detectErrors('G01 X10 Y10\nG02 X20 Y20\nM30');
            if (r.errors.length > 0) { results.passed++; results.tests.push({ name: 'Detect Errors', status: 'PASS' }); }
            else throw new Error('No errors found');
        } catch (e) { results.failed++; results.tests.push({ name: 'Detect Errors', status: 'FAIL', error: e.message }); }
        
        console.log('[POST_ANALYSIS_AI] Tests: ' + results.passed + '/' + (results.passed + results.failed) + ' passed');
        return results;
    }
};

if (typeof PRISM_GATEWAY !== 'undefined') {
    PRISM_GATEWAY.register('post.analyze.identify', 'PRISM_POST_ANALYSIS_AI.identifyController');
    PRISM_GATEWAY.register('post.analyze.deep', 'PRISM_POST_ANALYSIS_AI.deepAnalyze');
    PRISM_GATEWAY.register('post.analyze.errors', 'PRISM_POST_ANALYSIS_AI.detectErrors');
    PRISM_GATEWAY.register('post.analyze.enhance', 'PRISM_POST_ANALYSIS_AI.suggestEnhancements');
}

console.log('[PRISM_POST_ANALYSIS_AI] Loaded v1.0.0');


// ╔═══════════════════════════════════════════════════════════════════════════════════════════════════╗
// ║                    PRODUCT 3: BUSINESS/SHOP/ERP                                                   ║
// ╚═══════════════════════════════════════════════════════════════════════════════════════════════════╝

// ═══════════════════════════════════════════════════════════════════════════
// PRISM_SHOP_LEARNING_ENGINE v1.0.0
// Learns from job outcomes to improve estimates
// ═══════════════════════════════════════════════════════════════════════════

const PRISM_SHOP_LEARNING_ENGINE = {
    version: '1.0.0',
    authority: 'PRISM_SHOP_LEARNING_ENGINE',
    
    jobOutcomes: [],
    estimateAccuracy: { setup: [], cycle: [], total: [] },
    operatorPerformance: {},
    machinePerformance: {},
    
    estimationFactors: {
        setup_time: { mean: 1.0, variance: 0.15, observations: 0 },
        cycle_time: { mean: 1.0, variance: 0.1, observations: 0 },
        scrap_rate: { mean: 0.02, variance: 0.01, observations: 0 },
        cost_factor: { mean: 1.0, variance: 0.12, observations: 0 }
    },
    
    recordJobOutcome: function(params) {
        const { jobId, partNumber, quantity, material, estimatedTime, actualTime, estimatedCost, actualCost, quality, machine, operator, notes } = params;
        const timestamp = Date.now();
        
        const metrics = this._calcMetrics(estimatedTime, actualTime, estimatedCost, actualCost, quality);
        const outcome = { id: 'job_' + timestamp + '_' + Math.random().toString(36).substr(2, 9), timestamp, jobId, partNumber, quantity, material,
            estimated: { time: estimatedTime, cost: estimatedCost }, actual: { time: actualTime, cost: actualCost },
            quality, machine, operator, notes, metrics };
        
        this.jobOutcomes.push(outcome);
        this._updateFactors(outcome);
        if (operator) this._updateOperator(operator, outcome);
        if (machine) this._updateMachine(machine, outcome);
        
        if (typeof PRISM_EVENT_BUS !== 'undefined') PRISM_EVENT_BUS.publish('shop:learning:outcome', outcome);
        return outcome;
    },
    
    adjustTimeEstimate: function(baseEst, context = {}) {
        const { operator, machine, complexity } = context;
        let setupFactor = this.estimationFactors.setup_time.mean, cycleFactor = this.estimationFactors.cycle_time.mean;
        
        if (operator && this.operatorPerformance[operator]) {
            setupFactor *= this.operatorPerformance[operator].setupFactor || 1.0;
            cycleFactor *= this.operatorPerformance[operator].cycleFactor || 1.0;
        }
        if (machine && this.machinePerformance[machine]) cycleFactor *= this.machinePerformance[machine].efficiencyFactor || 1.0;
        if (complexity === 'high') { setupFactor *= 1.2; cycleFactor *= 1.1; }
        else if (complexity === 'low') { setupFactor *= 0.9; cycleFactor *= 0.95; }
        
        const adjusted = { setup: Math.round(baseEst.setup * setupFactor * 10) / 10, cycle: Math.round(baseEst.cycle * cycleFactor * 10) / 10 };
        adjusted.total = adjusted.setup + adjusted.cycle;
        
        return { base: baseEst, adjusted, factors: { setupFactor, cycleFactor },
            confidence: { setup: { low: Math.round(adjusted.setup * 0.85 * 10) / 10, high: Math.round(adjusted.setup * 1.15 * 10) / 10 } },
            learningApplied: true };
    },
    
    predictScrapRate: function(context = {}) {
        const { operator, complexity } = context;
        let rate = this.estimationFactors.scrap_rate.mean;
        if (operator && this.operatorPerformance[operator]) rate *= this.operatorPerformance[operator].qualityFactor || 1.0;
        if (complexity === 'high') rate *= 1.5;
        if (complexity === 'low') rate *= 0.7;
        return { predicted: rate, confidence: 1 - Math.sqrt(this.estimationFactors.scrap_rate.variance) };
    },
    
    getOperatorStats: function(opId) {
        return this.operatorPerformance[opId] || { setupFactor: 1.0, cycleFactor: 1.0, qualityFactor: 1.0, jobsCompleted: 0 };
    },
    
    getMachineStats: function(machId) {
        return this.machinePerformance[machId] || { efficiencyFactor: 1.0, jobsCompleted: 0 };
    },
    
    getStatistics: function() {
        const outcomes = this.jobOutcomes;
        return { totalJobs: outcomes.length,
            avgSetupAccuracy: this._calcAvg(this.estimateAccuracy.setup),
            avgCycleAccuracy: this._calcAvg(this.estimateAccuracy.cycle),
            operatorsTracked: Object.keys(this.operatorPerformance).length,
            machinesTracked: Object.keys(this.machinePerformance).length,
            estimationConfidence: { setup: ((1 - Math.sqrt(this.estimationFactors.setup_time.variance)) * 100).toFixed(1) + '%' }
        };
    },
    
    _calcMetrics: function(estTime, actTime, estCost, actCost, quality) {
        const m = {};
        if (estTime && actTime) { m.setupAccuracy = estTime.setup ? actTime.setup / estTime.setup : null; m.cycleAccuracy = estTime.cycle ? actTime.cycle / estTime.cycle : null; }
        if (estCost && actCost) m.costAccuracy = estCost.total ? actCost.total / estCost.total : null;
        if (quality) { m.passRate = quality.passed / (quality.passed + quality.failed + (quality.scrap || 0)); m.scrapRate = (quality.scrap || 0) / (quality.passed + quality.failed + (quality.scrap || 0)); }
        return m;
    },
    
    _updateFactors: function(outcome) {
        const m = outcome.metrics;
        if (m.setupAccuracy) { this._updateFactor('setup_time', m.setupAccuracy); this.estimateAccuracy.setup.push(m.setupAccuracy); }
        if (m.cycleAccuracy) { this._updateFactor('cycle_time', m.cycleAccuracy); this.estimateAccuracy.cycle.push(m.cycleAccuracy); }
        if (m.costAccuracy) this._updateFactor('cost_factor', m.costAccuracy);
        if (m.scrapRate !== undefined) this._updateFactor('scrap_rate', m.scrapRate);
    },
    
    _updateFactor: function(factor, obs) {
        const f = this.estimationFactors[factor];
        if (!f) return;
        const n = (f.observations || 0) + 1;
        f.mean = (f.mean * (n - 1) + obs) / n;
        f.variance = f.variance * 0.99;
        f.observations = n;
    },
    
    _updateOperator: function(opId, outcome) {
        if (!this.operatorPerformance[opId]) this.operatorPerformance[opId] = { setupFactor: 1.0, cycleFactor: 1.0, qualityFactor: 1.0, jobsCompleted: 0 };
        const p = this.operatorPerformance[opId], n = p.jobsCompleted + 1, m = outcome.metrics;
        if (m.setupAccuracy) p.setupFactor = (p.setupFactor * p.jobsCompleted + m.setupAccuracy) / n;
        if (m.cycleAccuracy) p.cycleFactor = (p.cycleFactor * p.jobsCompleted + m.cycleAccuracy) / n;
        if (m.passRate !== undefined) p.qualityFactor = (p.qualityFactor * p.jobsCompleted + m.passRate / 0.98) / n;
        p.jobsCompleted = n;
    },
    
    _updateMachine: function(machId, outcome) {
        if (!this.machinePerformance[machId]) this.machinePerformance[machId] = { efficiencyFactor: 1.0, jobsCompleted: 0 };
        const p = this.machinePerformance[machId], n = p.jobsCompleted + 1, m = outcome.metrics;
        if (m.cycleAccuracy) p.efficiencyFactor = (p.efficiencyFactor * p.jobsCompleted + m.cycleAccuracy) / n;
        p.jobsCompleted = n;
    },
    
    _calcAvg: function(arr) {
        if (arr.length === 0) return 'N/A';
        return (arr.reduce((a, b) => a + b, 0) / arr.length * 100).toFixed(1) + '%';
    },
    
    runSelfTests: function() {
        console.log('[SHOP_LEARNING] Running self-tests...');
        const results = { passed: 0, failed: 0, tests: [] };
        
        try {
            const r = this.recordJobOutcome({ jobId: 'TEST-001', partNumber: 'PART-123', quantity: 100,
                estimatedTime: { setup: 30, cycle: 120, total: 150 }, actualTime: { setup: 28, cycle: 125, total: 153 },
                estimatedCost: { total: 900 }, actualCost: { total: 900 }, quality: { passed: 98, failed: 2, scrap: 0 }, operator: 'OP-001', machine: 'MACH-001' });
            if (r.id && r.metrics) { results.passed++; results.tests.push({ name: 'Record Job Outcome', status: 'PASS' }); }
            else throw new Error('Invalid');
        } catch (e) { results.failed++; results.tests.push({ name: 'Record Job Outcome', status: 'FAIL', error: e.message }); }
        
        try {
            const r = this.adjustTimeEstimate({ setup: 30, cycle: 120, total: 150 }, { operator: 'OP-001' });
            if (r.adjusted && r.confidence) { results.passed++; results.tests.push({ name: 'Adjust Time', status: 'PASS' }); }
            else throw new Error('Invalid');
        } catch (e) { results.failed++; results.tests.push({ name: 'Adjust Time', status: 'FAIL', error: e.message }); }
        
        console.log('[SHOP_LEARNING] Tests: ' + results.passed + '/' + (results.passed + results.failed) + ' passed');
        return results;
    }
};

if (typeof PRISM_GATEWAY !== 'undefined') {
    PRISM_GATEWAY.register('shop.learning.outcome', 'PRISM_SHOP_LEARNING_ENGINE.recordJobOutcome');
    PRISM_GATEWAY.register('shop.learning.adjustTime', 'PRISM_SHOP_LEARNING_ENGINE.adjustTimeEstimate');
    PRISM_GATEWAY.register('shop.learning.scrapRate', 'PRISM_SHOP_LEARNING_ENGINE.predictScrapRate');
    PRISM_GATEWAY.register('shop.learning.stats', 'PRISM_SHOP_LEARNING_ENGINE.getStatistics');
}

console.log('[PRISM_SHOP_LEARNING_ENGINE] Loaded v1.0.0');


// ═══════════════════════════════════════════════════════════════════════════
// PRISM_SHOP_OPTIMIZER v1.0.0
// GA/ACO scheduling and bottleneck analysis
// ═══════════════════════════════════════════════════════════════════════════

const PRISM_SHOP_OPTIMIZER = {
    version: '1.0.0',
    authority: 'PRISM_SHOP_OPTIMIZER',
    
    optimizeSchedule: function(params) {
        const { jobs, machines, constraints = {}, objective = 'makespan' } = params;
        const config = { popSize: 50, generations: 100, crossoverRate: 0.8, mutationRate: 0.1 };
        const bounds = this._calcBounds(jobs, machines);
        
        let population = this._initPop(jobs, config.popSize);
        let globalBest = null, globalBestFitness = -Infinity;
        
        for (let gen = 0; gen < config.generations; gen++) {
            const evaluated = population.map(c => ({ chromosome: c, fitness: this._evalSchedule(c, machines, constraints, objective) }));
            for (const ind of evaluated) {
                if (ind.fitness > globalBestFitness) { globalBestFitness = ind.fitness; globalBest = [...ind.chromosome]; }
            }
            const selected = this._tournament(evaluated, config.popSize);
            const offspring = this._crossover(selected, config.crossoverRate);
            this._mutate(offspring, config.mutationRate);
            population = offspring;
        }
        
        const schedule = this._buildSchedule(globalBest, machines);
        return { schedule, metrics: { makespan: this._calcMakespan(schedule), utilization: this._calcUtilization(schedule, machines) },
            fitness: globalBestFitness, generations: config.generations };
    },
    
    optimizeOperationSequence: function(params) {
        const { operations, setupMatrix } = params;
        const n = operations.length;
        if (n < 2) return { sequence: operations, totalSetup: 0 };
        
        const config = { ants: 20, iterations: 50, alpha: 1.0, beta: 2.0, rho: 0.1, Q: 100 };
        const pheromone = Array(n).fill(null).map(() => Array(n).fill(1.0));
        let best = null, bestLen = Infinity;
        
        for (let iter = 0; iter < config.iterations; iter++) {
            const solutions = [];
            for (let ant = 0; ant < config.ants; ant++) {
                const sol = this._antBuild(operations, pheromone, setupMatrix, config);
                const len = this._seqLen(sol, setupMatrix, operations);
                solutions.push({ sequence: sol, length: len });
                if (len < bestLen) { bestLen = len; best = [...sol]; }
            }
            for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) pheromone[i][j] *= (1 - config.rho);
            for (const sol of solutions) {
                const deposit = config.Q / sol.length;
                for (let i = 0; i < sol.sequence.length - 1; i++) {
                    const from = operations.indexOf(sol.sequence[i]), to = operations.indexOf(sol.sequence[i + 1]);
                    pheromone[from][to] += deposit;
                }
            }
        }
        
        const origLen = this._seqLen(operations, setupMatrix, operations);
        return { sequence: best, totalSetup: bestLen, improvement: origLen > 0 ? ((origLen - bestLen) / origLen * 100).toFixed(1) + '%' : 'N/A' };
    },
    
    analyzeBottlenecks: function(params) {
        const { machines, currentSchedule } = params;
        const analysis = { bottlenecks: [], machineLoading: {}, recommendations: [] };
        
        for (const m of machines) {
            const jobs = currentSchedule?.filter(s => s.machine === m.id) || [];
            const totalTime = jobs.reduce((sum, j) => sum + (j.duration || 0), 0);
            const available = m.availableHours || 480;
            analysis.machineLoading[m.id] = { name: m.name || m.id, totalTime, availableTime: available,
                utilization: (totalTime / available * 100).toFixed(1) + '%', isBottleneck: totalTime > available * 0.9 };
            
            if (totalTime > available * 0.9) {
                analysis.bottlenecks.push({ type: 'machine_overload', machine: m.id, utilization: totalTime / available, severity: totalTime > available ? 'critical' : 'high' });
                analysis.recommendations.push({ type: 'offload', message: 'Consider offloading work from ' + m.id, priority: totalTime > available ? 'critical' : 'high' });
            }
        }
        return analysis;
    },
    
    johnsonsAlgorithm: function(jobs) {
        const list1 = [], list2 = [];
        for (const j of jobs) { if (j.machine1Time < j.machine2Time) list1.push(j); else list2.push(j); }
        list1.sort((a, b) => a.machine1Time - b.machine1Time);
        list2.sort((a, b) => b.machine2Time - a.machine2Time);
        const sequence = [...list1, ...list2];
        let m1End = 0, m2End = 0;
        for (const j of sequence) { m1End += j.machine1Time; m2End = Math.max(m2End, m1End) + j.machine2Time; }
        return { sequence: sequence.map(j => j.id), makespan: m2End, algorithm: 'Johnsons' };
    },
    
    _initPop: function(jobs, size) {
        const pop = [];
        for (let i = 0; i < size; i++) {
            const c = [...jobs];
            for (let j = c.length - 1; j > 0; j--) { const k = Math.floor(Math.random() * (j + 1)); [c[j], c[k]] = [c[k], c[j]]; }
            pop.push(c);
        }
        return pop;
    },
    
    _evalSchedule: function(chromosome, machines, constraints, objective) {
        const schedule = this._buildSchedule(chromosome, machines);
        const makespan = this._calcMakespan(schedule);
        return 1 / (makespan + 1);
    },
    
    _buildSchedule: function(chromosome, machines) {
        const schedule = [], machineEnd = {};
        for (const m of machines) machineEnd[m.id] = 0;
        
        for (const job of chromosome) {
            let bestMach = machines[0]?.id, earliest = Infinity;
            for (const m of machines) {
                if (!job.requiredMachine || job.requiredMachine === m.id) {
                    if (machineEnd[m.id] < earliest) { earliest = machineEnd[m.id]; bestMach = m.id; }
                }
            }
            const start = machineEnd[bestMach], duration = job.duration || job.processingTime || 60, end = start + duration;
            schedule.push({ jobId: job.id || job.jobId, machine: bestMach, start, end, duration });
            machineEnd[bestMach] = end;
        }
        return schedule;
    },
    
    _calcMakespan: function(schedule) { return schedule.length > 0 ? Math.max(...schedule.map(s => s.end)) : 0; },
    
    _calcUtilization: function(schedule, machines) {
        if (schedule.length === 0 || machines.length === 0) return 0;
        const makespan = this._calcMakespan(schedule);
        return schedule.reduce((sum, s) => sum + s.duration, 0) / (makespan * machines.length);
    },
    
    _tournament: function(evaluated, count) {
        const selected = [];
        for (let i = 0; i < count; i++) {
            const tournament = [];
            for (let j = 0; j < 3; j++) tournament.push(evaluated[Math.floor(Math.random() * evaluated.length)]);
            tournament.sort((a, b) => b.fitness - a.fitness);
            selected.push([...tournament[0].chromosome]);
        }
        return selected;
    },
    
    _crossover: function(pop, rate) {
        const offspring = [];
        for (let i = 0; i < pop.length; i += 2) {
            if (i + 1 < pop.length && Math.random() < rate) {
                const [c1, c2] = this._orderCrossover(pop[i], pop[i + 1]);
                offspring.push(c1, c2);
            } else {
                offspring.push([...pop[i]]);
                if (i + 1 < pop.length) offspring.push([...pop[i + 1]]);
            }
        }
        return offspring;
    },
    
    _orderCrossover: function(p1, p2) {
        const n = p1.length, start = Math.floor(Math.random() * n), end = start + Math.floor(Math.random() * (n - start));
        const c1 = new Array(n).fill(null), c2 = new Array(n).fill(null);
        for (let i = start; i <= end; i++) { c1[i] = p1[i]; c2[i] = p2[i]; }
        
        let idx1 = (end + 1) % n, idx2 = (end + 1) % n;
        for (let i = 0; i < n; i++) {
            const pos = (end + 1 + i) % n;
            if (!c1.includes(p2[pos])) { while (c1[idx1] !== null) idx1 = (idx1 + 1) % n; c1[idx1] = p2[pos]; }
            if (!c2.includes(p1[pos])) { while (c2[idx2] !== null) idx2 = (idx2 + 1) % n; c2[idx2] = p1[pos]; }
        }
        return [c1, c2];
    },
    
    _mutate: function(pop, rate) {
        for (const c of pop) {
            if (Math.random() < rate) { const i = Math.floor(Math.random() * c.length), j = Math.floor(Math.random() * c.length); [c[i], c[j]] = [c[j], c[i]]; }
        }
    },
    
    _antBuild: function(operations, pheromone, setupMatrix, config) {
        const n = operations.length, visited = new Set(), solution = [];
        let current = Math.floor(Math.random() * n);
        solution.push(operations[current]); visited.add(current);
        
        while (solution.length < n) {
            const probs = [];
            let total = 0;
            for (let j = 0; j < n; j++) {
                if (!visited.has(j)) {
                    const tau = Math.pow(pheromone[current][j], config.alpha);
                    const eta = setupMatrix ? Math.pow(1 / (setupMatrix[current][j] + 1), config.beta) : 1;
                    const prob = tau * eta; probs.push({ index: j, prob }); total += prob;
                }
            }
            let rand = Math.random() * total;
            for (const p of probs) { rand -= p.prob; if (rand <= 0) { current = p.index; break; } }
            solution.push(operations[current]); visited.add(current);
        }
        return solution;
    },
    
    _seqLen: function(sequence, setupMatrix, operations) {
        if (!setupMatrix || sequence.length < 2) return 0;
        let total = 0;
        for (let i = 0; i < sequence.length - 1; i++) {
            const from = operations.indexOf(sequence[i]), to = operations.indexOf(sequence[i + 1]);
            if (setupMatrix[from]?.[to] !== undefined) total += setupMatrix[from][to];
        }
        return total;
    },
    
    runSelfTests: function() {
        console.log('[SHOP_OPTIMIZER] Running self-tests...');
        const results = { passed: 0, failed: 0, tests: [] };
        
        try {
            const r = this.optimizeSchedule({ jobs: [{ id: 'J1', duration: 30 }, { id: 'J2', duration: 45 }], machines: [{ id: 'M1' }, { id: 'M2' }] });
            if (r.schedule && r.metrics.makespan > 0) { results.passed++; results.tests.push({ name: 'Optimize Schedule', status: 'PASS' }); }
            else throw new Error('Invalid');
        } catch (e) { results.failed++; results.tests.push({ name: 'Optimize Schedule', status: 'FAIL', error: e.message }); }
        
        try {
            const r = this.johnsonsAlgorithm([{ id: 'A', machine1Time: 5, machine2Time: 2 }, { id: 'B', machine1Time: 1, machine2Time: 6 }]);
            if (r.sequence.length === 2 && r.makespan > 0) { results.passed++; results.tests.push({ name: 'Johnsons', status: 'PASS' }); }
            else throw new Error('Invalid');
        } catch (e) { results.failed++; results.tests.push({ name: 'Johnsons', status: 'FAIL', error: e.message }); }
        
        console.log('[SHOP_OPTIMIZER] Tests: ' + results.passed + '/' + (results.passed + results.failed) + ' passed');
        return results;
    }
};

if (typeof PRISM_GATEWAY !== 'undefined') {
    PRISM_GATEWAY.register('shop.optimize.schedule', 'PRISM_SHOP_OPTIMIZER.optimizeSchedule');
    PRISM_GATEWAY.register('shop.optimize.sequence', 'PRISM_SHOP_OPTIMIZER.optimizeOperationSequence');
    PRISM_GATEWAY.register('shop.analyze.bottleneck', 'PRISM_SHOP_OPTIMIZER.analyzeBottlenecks');
    PRISM_GATEWAY.register('shop.optimize.johnson', 'PRISM_SHOP_OPTIMIZER.johnsonsAlgorithm');
}

console.log('[PRISM_SHOP_OPTIMIZER] Loaded v1.0.0');

// ═══════════════════════════════════════════════════════════════════════════════
// PRODUCT 3: BUSINESS/SHOP/ERP SYSTEM - QUOTING LEARNING
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_QUOTING_LEARNING = {
    version: '1.0.0',
    authority: 'PRISM_QUOTING_LEARNING',
    
    // Learning data storage
    learningData: {
        quotes: [],           // {quoteId, customerId, estimatedCost, actualCost, won, margin}
        materialCosts: {},    // materialId -> {avgCost, lastUpdated, samples}
        laborRates: {},       // operationType -> {avgRate, efficiency}
        setupTimes: {},       // machineType -> operationType -> {avgTime, samples}
        cycleAccuracy: [],    // {estimated, actual, partComplexity, materialType}
        wonLostPatterns: []   // {features, won, margin, competitorPrice}
    },
    
    // Bayesian priors for quote adjustments
    priors: {
        setup_factor: { mean: 1.0, variance: 0.04 },      // +/-20% typical
        cycle_factor: { mean: 1.0, variance: 0.0225 },    // +/-15% typical
        material_factor: { mean: 1.0, variance: 0.01 },   // +/-10% typical
        overhead_factor: { mean: 1.0, variance: 0.0625 }, // +/-25% typical
        margin_factor: { mean: 0.25, variance: 0.01 }     // 25% +/-10% typical
    },
    
    recordQuoteOutcome: function(params) {
        const { quoteId, customerId, estimatedCost, actualCost, won, finalPrice, competitorPrice = null } = params;
        
        const margin = won && actualCost > 0 ? (finalPrice - actualCost) / finalPrice : null;
        const accuracy = actualCost > 0 ? estimatedCost / actualCost : null;
        
        const record = {
            timestamp: Date.now(),
            quoteId, customerId, estimatedCost, actualCost, won, finalPrice, 
            competitorPrice, margin, accuracy
        };
        
        this.learningData.quotes.push(record);
        
        // Update Bayesian priors based on accuracy
        if (accuracy && accuracy > 0) {
            this._updateBayesianPrior('cycle_factor', accuracy);
        }
        
        // Track won/lost patterns
        if (competitorPrice) {
            this.learningData.wonLostPatterns.push({
                priceRatio: finalPrice / competitorPrice,
                won, margin,
                timestamp: Date.now()
            });
        }
        
        this._persistData();
        return record;
    },
    
    recordMaterialCost: function(materialId, actualCost, quantity) {
        if (!this.learningData.materialCosts[materialId]) {
            this.learningData.materialCosts[materialId] = { avgCost: actualCost, samples: 1, lastUpdated: Date.now() };
        } else {
            const mc = this.learningData.materialCosts[materialId];
            mc.avgCost = (mc.avgCost * mc.samples + actualCost) / (mc.samples + 1);
            mc.samples++;
            mc.lastUpdated = Date.now();
        }
        this._persistData();
    },
    
    recordSetupTime: function(machineType, operationType, actualTime) {
        const key = `${machineType}_${operationType}`;
        if (!this.learningData.setupTimes[key]) {
            this.learningData.setupTimes[key] = { avgTime: actualTime, samples: 1 };
        } else {
            const st = this.learningData.setupTimes[key];
            st.avgTime = (st.avgTime * st.samples + actualTime) / (st.samples + 1);
            st.samples++;
        }
        this._persistData();
    },
    
    adjustQuoteEstimate: function(baseEstimate) {
        const { setupCost = 0, cycleCost = 0, materialCost = 0, overhead = 0 } = baseEstimate;
        
        const adjustedSetup = setupCost * this.priors.setup_factor.mean;
        const adjustedCycle = cycleCost * this.priors.cycle_factor.mean;
        const adjustedMaterial = materialCost * this.priors.material_factor.mean;
        const adjustedOverhead = overhead * this.priors.overhead_factor.mean;
        
        const totalCost = adjustedSetup + adjustedCycle + adjustedMaterial + adjustedOverhead;
        const suggestedMargin = this.priors.margin_factor.mean;
        const suggestedPrice = totalCost / (1 - suggestedMargin);
        
        // Calculate confidence based on variance
        const confidence = 1 - Math.sqrt(
            (this.priors.setup_factor.variance + this.priors.cycle_factor.variance + 
             this.priors.material_factor.variance + this.priors.overhead_factor.variance) / 4
        );
        
        return {
            adjustedCost: totalCost,
            breakdown: { setup: adjustedSetup, cycle: adjustedCycle, material: adjustedMaterial, overhead: adjustedOverhead },
            suggestedPrice,
            suggestedMargin: suggestedMargin * 100,
            confidence: Math.max(0, Math.min(1, confidence)),
            confidenceInterval: {
                low: totalCost * 0.85,
                high: totalCost * 1.15
            }
        };
    },
    
    getOptimalMargin: function(customerHistory = null, partComplexity = 'medium', competitionLevel = 'normal') {
        let baseMargin = this.priors.margin_factor.mean;
        
        // Adjust for complexity
        const complexityAdjust = { low: -0.05, medium: 0, high: 0.05, extreme: 0.10 };
        baseMargin += complexityAdjust[partComplexity] || 0;
        
        // Adjust for competition
        const competitionAdjust = { low: 0.05, normal: 0, high: -0.03, fierce: -0.07 };
        baseMargin += competitionAdjust[competitionLevel] || 0;
        
        // Adjust based on won/lost patterns
        const recentPatterns = this.learningData.wonLostPatterns.slice(-50);
        if (recentPatterns.length >= 10) {
            const wonPatterns = recentPatterns.filter(p => p.won);
            const avgWonRatio = wonPatterns.length > 0 ? 
                wonPatterns.reduce((a, p) => a + p.priceRatio, 0) / wonPatterns.length : 1.0;
            
            // If we're winning at higher ratios, we can increase margin
            if (avgWonRatio > 1.05) baseMargin += 0.02;
            if (avgWonRatio < 0.95) baseMargin -= 0.02;
        }
        
        return {
            suggestedMargin: Math.max(0.10, Math.min(0.40, baseMargin)),
            reasoning: {
                base: this.priors.margin_factor.mean,
                complexityAdjust: complexityAdjust[partComplexity] || 0,
                competitionAdjust: competitionAdjust[competitionLevel] || 0,
                patternAdjust: baseMargin - this.priors.margin_factor.mean - (complexityAdjust[partComplexity] || 0) - (competitionAdjust[competitionLevel] || 0)
            }
        };
    },
    
    getWinProbability: function(proposedPrice, estimatedCost, competitorEstimate = null) {
        const margin = (proposedPrice - estimatedCost) / proposedPrice;
        const recentPatterns = this.learningData.wonLostPatterns.slice(-100);
        
        if (recentPatterns.length < 10) {
            // Not enough data, use simple heuristic
            if (margin < 0.15) return { probability: 0.7, confidence: 'low', dataPoints: recentPatterns.length };
            if (margin < 0.25) return { probability: 0.5, confidence: 'low', dataPoints: recentPatterns.length };
            if (margin < 0.35) return { probability: 0.3, confidence: 'low', dataPoints: recentPatterns.length };
            return { probability: 0.15, confidence: 'low', dataPoints: recentPatterns.length };
        }
        
        // Find similar margin quotes
        const similar = recentPatterns.filter(p => {
            const pMargin = p.margin || 0.25;
            return Math.abs(pMargin - margin) < 0.05;
        });
        
        const winRate = similar.length > 0 ? similar.filter(p => p.won).length / similar.length : 0.5;
        
        return {
            probability: winRate,
            confidence: similar.length >= 20 ? 'high' : similar.length >= 10 ? 'medium' : 'low',
            dataPoints: similar.length,
            historicalWinRate: this.learningData.quotes.filter(q => q.won).length / Math.max(1, this.learningData.quotes.length)
        };
    },
    
    getStatistics: function() {
        const quotes = this.learningData.quotes;
        const won = quotes.filter(q => q.won);
        const withActual = quotes.filter(q => q.actualCost > 0);
        
        const avgAccuracy = withActual.length > 0 ?
            withActual.reduce((a, q) => a + q.accuracy, 0) / withActual.length : null;
        
        const avgMargin = won.filter(q => q.margin).length > 0 ?
            won.filter(q => q.margin).reduce((a, q) => a + q.margin, 0) / won.filter(q => q.margin).length : null;
        
        return {
            totalQuotes: quotes.length,
            wonQuotes: won.length,
            winRate: quotes.length > 0 ? (won.length / quotes.length * 100).toFixed(1) + '%' : 'N/A',
            avgEstimateAccuracy: avgAccuracy ? (avgAccuracy * 100).toFixed(1) + '%' : 'N/A',
            avgActualMargin: avgMargin ? (avgMargin * 100).toFixed(1) + '%' : 'N/A',
            materialCostsTracked: Object.keys(this.learningData.materialCosts).length,
            setupTimesTracked: Object.keys(this.learningData.setupTimes).length,
            bayesianConfidence: (1 - Math.sqrt(this.priors.cycle_factor.variance)) * 100
        };
    },
    
    _updateBayesianPrior: function(priorName, observedValue) {
        const prior = this.priors[priorName];
        if (!prior) return;
        
        const priorPrecision = 1 / prior.variance;
        const likelihoodPrecision = 10; // Assume moderate confidence in observation
        const posteriorPrecision = priorPrecision + likelihoodPrecision;
        
        prior.mean = (priorPrecision * prior.mean + likelihoodPrecision * observedValue) / posteriorPrecision;
        prior.variance = 1 / posteriorPrecision;
    },
    
    _persistData: function() {
        try {
            localStorage.setItem('prism_quoting_learning', JSON.stringify({
                learningData: this.learningData,
                priors: this.priors
            }));
        } catch (e) { /* Storage unavailable */ }
    },
    
    loadPersistedData: function() {
        try {
            const saved = localStorage.getItem('prism_quoting_learning');
            if (saved) {
                const data = JSON.parse(saved);
                this.learningData = data.learningData || this.learningData;
                this.priors = data.priors || this.priors;
            }
        } catch (e) { /* Storage unavailable */ }
    },
    
    runSelfTests: function() {
        console.log('[QUOTING_LEARNING] Running self-tests...');
        const results = { passed: 0, failed: 0, tests: [] };
        
        try {
            const r = this.recordQuoteOutcome({ quoteId: 'Q1', customerId: 'C1', estimatedCost: 1000, actualCost: 950, won: true, finalPrice: 1300 });
            if (r.margin > 0 && r.accuracy > 0) { results.passed++; results.tests.push({ name: 'Record Quote', status: 'PASS' }); }
            else throw new Error('Invalid record');
        } catch (e) { results.failed++; results.tests.push({ name: 'Record Quote', status: 'FAIL', error: e.message }); }
        
        try {
            const r = this.adjustQuoteEstimate({ setupCost: 100, cycleCost: 500, materialCost: 200, overhead: 50 });
            if (r.adjustedCost > 0 && r.suggestedPrice > r.adjustedCost) { results.passed++; results.tests.push({ name: 'Adjust Quote', status: 'PASS' }); }
            else throw new Error('Invalid adjustment');
        } catch (e) { results.failed++; results.tests.push({ name: 'Adjust Quote', status: 'FAIL', error: e.message }); }
        
        try {
            const r = this.getOptimalMargin(null, 'high', 'normal');
            if (r.suggestedMargin >= 0.10 && r.suggestedMargin <= 0.40) { results.passed++; results.tests.push({ name: 'Optimal Margin', status: 'PASS' }); }
            else throw new Error('Invalid margin');
        } catch (e) { results.failed++; results.tests.push({ name: 'Optimal Margin', status: 'FAIL', error: e.message }); }
        
        try {
            const r = this.getWinProbability(1300, 1000);
            if (r.probability >= 0 && r.probability <= 1) { results.passed++; results.tests.push({ name: 'Win Probability', status: 'PASS' }); }
            else throw new Error('Invalid probability');
        } catch (e) { results.failed++; results.tests.push({ name: 'Win Probability', status: 'FAIL', error: e.message }); }
        
        console.log('[QUOTING_LEARNING] Tests: ' + results.passed + '/' + (results.passed + results.failed) + ' passed');
        return results;
    }
};

if (typeof PRISM_GATEWAY !== 'undefined') {
    PRISM_GATEWAY.register('quoting.record', 'PRISM_QUOTING_LEARNING.recordQuoteOutcome');
    PRISM_GATEWAY.register('quoting.adjust', 'PRISM_QUOTING_LEARNING.adjustQuoteEstimate');
    PRISM_GATEWAY.register('quoting.margin', 'PRISM_QUOTING_LEARNING.getOptimalMargin');
    PRISM_GATEWAY.register('quoting.winProb', 'PRISM_QUOTING_LEARNING.getWinProbability');
    PRISM_GATEWAY.register('quoting.stats', 'PRISM_QUOTING_LEARNING.getStatistics');
}

console.log('[PRISM_QUOTING_LEARNING] Loaded v1.0.0');

// ═══════════════════════════════════════════════════════════════════════════════
// PRODUCT 3: BUSINESS/SHOP/ERP SYSTEM - CUSTOMER MANAGER
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_CUSTOMER_MANAGER = {
    version: '1.0.0',
    authority: 'PRISM_CUSTOMER_MANAGER',
    
    // Customer database
    customers: {},
    
    // Customer schema
    createCustomer: function(params) {
        const { name, company = '', email = '', phone = '', address = {}, industry = '', notes = '' } = params;
        
        if (!name) throw new Error('Customer name required');
        
        const id = 'CUST-' + Date.now().toString(36).toUpperCase();
        
        this.customers[id] = {
            id, name, company, email, phone, address, industry, notes,
            created: Date.now(),
            modified: Date.now(),
            status: 'active',
            creditLimit: 0,
            paymentTerms: 'NET30',
            taxExempt: false,
            contacts: [],
            tags: [],
            customFields: {},
            // Analytics
            analytics: {
                totalOrders: 0,
                totalRevenue: 0,
                avgOrderValue: 0,
                lastOrderDate: null,
                firstOrderDate: null,
                lifetimeValue: 0,
                onTimePaymentRate: 1.0,
                avgPaymentDays: 0
            },
            // Communication history
            communications: [],
            // Order history (references)
            orderHistory: []
        };
        
        this._persistData();
        return this.customers[id];
    },
    
    updateCustomer: function(customerId, updates) {
        if (!this.customers[customerId]) throw new Error('Customer not found: ' + customerId);
        
        const customer = this.customers[customerId];
        const allowed = ['name', 'company', 'email', 'phone', 'address', 'industry', 'notes', 
                         'status', 'creditLimit', 'paymentTerms', 'taxExempt', 'tags', 'customFields'];
        
        for (const key of allowed) {
            if (updates[key] !== undefined) customer[key] = updates[key];
        }
        
        customer.modified = Date.now();
        this._persistData();
        return customer;
    },
    
    getCustomer: function(customerId) {
        return this.customers[customerId] || null;
    },
    
    searchCustomers: function(query, options = {}) {
        const { status = null, industry = null, minOrders = 0, minRevenue = 0, tags = [] } = options;
        const queryLower = query.toLowerCase();
        
        return Object.values(this.customers).filter(c => {
            // Text search
            const textMatch = !query || 
                c.name.toLowerCase().includes(queryLower) ||
                c.company.toLowerCase().includes(queryLower) ||
                c.email.toLowerCase().includes(queryLower);
            
            // Filters
            const statusMatch = !status || c.status === status;
            const industryMatch = !industry || c.industry === industry;
            const ordersMatch = c.analytics.totalOrders >= minOrders;
            const revenueMatch = c.analytics.totalRevenue >= minRevenue;
            const tagsMatch = tags.length === 0 || tags.some(t => c.tags.includes(t));
            
            return textMatch && statusMatch && industryMatch && ordersMatch && revenueMatch && tagsMatch;
        });
    },
    
    addContact: function(customerId, contact) {
        const customer = this.customers[customerId];
        if (!customer) throw new Error('Customer not found');
        
        const contactId = 'CONT-' + Date.now().toString(36).toUpperCase();
        customer.contacts.push({
            id: contactId,
            name: contact.name || '',
            title: contact.title || '',
            email: contact.email || '',
            phone: contact.phone || '',
            isPrimary: contact.isPrimary || customer.contacts.length === 0,
            created: Date.now()
        });
        
        this._persistData();
        return customer.contacts[customer.contacts.length - 1];
    },
    
    recordOrder: function(customerId, orderData) {
        const customer = this.customers[customerId];
        if (!customer) throw new Error('Customer not found');
        
        const { orderId, amount, date = Date.now() } = orderData;
        
        customer.orderHistory.push({ orderId, amount, date });
        customer.analytics.totalOrders++;
        customer.analytics.totalRevenue += amount;
        customer.analytics.avgOrderValue = customer.analytics.totalRevenue / customer.analytics.totalOrders;
        customer.analytics.lastOrderDate = date;
        if (!customer.analytics.firstOrderDate) customer.analytics.firstOrderDate = date;
        
        // Simplified LTV calculation (could use more sophisticated models)
        const monthsActive = (Date.now() - customer.analytics.firstOrderDate) / (30 * 24 * 60 * 60 * 1000);
        const ordersPerMonth = monthsActive > 0 ? customer.analytics.totalOrders / monthsActive : 1;
        customer.analytics.lifetimeValue = customer.analytics.avgOrderValue * ordersPerMonth * 24; // 2-year projection
        
        this._persistData();
        return customer.analytics;
    },
    
    recordPayment: function(customerId, paymentData) {
        const customer = this.customers[customerId];
        if (!customer) throw new Error('Customer not found');
        
        const { invoiceDate, paymentDate, amount, onTime } = paymentData;
        const paymentDays = (paymentDate - invoiceDate) / (24 * 60 * 60 * 1000);
        
        // Update payment analytics
        const n = customer.analytics.totalOrders || 1;
        customer.analytics.avgPaymentDays = ((customer.analytics.avgPaymentDays * (n - 1)) + paymentDays) / n;
        customer.analytics.onTimePaymentRate = ((customer.analytics.onTimePaymentRate * (n - 1)) + (onTime ? 1 : 0)) / n;
        
        this._persistData();
        return customer.analytics;
    },
    
    logCommunication: function(customerId, commData) {
        const customer = this.customers[customerId];
        if (!customer) throw new Error('Customer not found');
        
        customer.communications.push({
            id: 'COMM-' + Date.now().toString(36).toUpperCase(),
            type: commData.type || 'note', // email, call, meeting, note
            subject: commData.subject || '',
            content: commData.content || '',
            date: commData.date || Date.now(),
            user: commData.user || 'system'
        });
        
        this._persistData();
        return customer.communications[customer.communications.length - 1];
    },
    
    getCustomerSegments: function() {
        const customers = Object.values(this.customers);
        
        // RFM Segmentation (Recency, Frequency, Monetary)
        const now = Date.now();
        const thirtyDays = 30 * 24 * 60 * 60 * 1000;
        const ninetyDays = 90 * 24 * 60 * 60 * 1000;
        
        const segments = {
            champions: [],     // High value, recent, frequent
            loyal: [],         // Regular customers
            potential: [],     // Growing customers
            atRisk: [],        // Haven't ordered recently
            inactive: [],      // No orders in 90+ days
            new: []            // Recent first order
        };
        
        for (const c of customers) {
            if (c.status !== 'active') continue;
            
            const daysSinceOrder = c.analytics.lastOrderDate ? 
                (now - c.analytics.lastOrderDate) / (24 * 60 * 60 * 1000) : 999;
            
            const isHigh = c.analytics.totalRevenue > 10000;
            const isFrequent = c.analytics.totalOrders >= 5;
            const isRecent = daysSinceOrder < 30;
            const isNew = c.analytics.totalOrders === 1 && daysSinceOrder < 60;
            
            if (isNew) segments.new.push(c);
            else if (isHigh && isFrequent && isRecent) segments.champions.push(c);
            else if (isFrequent && isRecent) segments.loyal.push(c);
            else if (daysSinceOrder > 90) segments.inactive.push(c);
            else if (daysSinceOrder > 30) segments.atRisk.push(c);
            else segments.potential.push(c);
        }
        
        return segments;
    },
    
    getTopCustomers: function(limit = 10, sortBy = 'revenue') {
        const customers = Object.values(this.customers).filter(c => c.status === 'active');
        
        const sorters = {
            revenue: (a, b) => b.analytics.totalRevenue - a.analytics.totalRevenue,
            orders: (a, b) => b.analytics.totalOrders - a.analytics.totalOrders,
            ltv: (a, b) => b.analytics.lifetimeValue - a.analytics.lifetimeValue,
            recent: (a, b) => (b.analytics.lastOrderDate || 0) - (a.analytics.lastOrderDate || 0)
        };
        
        return customers.sort(sorters[sortBy] || sorters.revenue).slice(0, limit);
    },
    
    _persistData: function() {
        try {
            localStorage.setItem('prism_customers', JSON.stringify(this.customers));
        } catch (e) { /* Storage unavailable */ }
    },
    
    loadPersistedData: function() {
        try {
            const saved = localStorage.getItem('prism_customers');
            if (saved) this.customers = JSON.parse(saved);
        } catch (e) { /* Storage unavailable */ }
    },
    
    runSelfTests: function() {
        console.log('[CUSTOMER_MANAGER] Running self-tests...');
        const results = { passed: 0, failed: 0, tests: [] };
        
        try {
            const c = this.createCustomer({ name: 'Test Corp', company: 'Test Industries', email: 'test@test.com' });
            if (c.id && c.name === 'Test Corp') { results.passed++; results.tests.push({ name: 'Create Customer', status: 'PASS' }); }
            else throw new Error('Invalid customer');
            
            // Cleanup
            delete this.customers[c.id];
        } catch (e) { results.failed++; results.tests.push({ name: 'Create Customer', status: 'FAIL', error: e.message }); }
        
        try {
            const c = this.createCustomer({ name: 'Test2' });
            this.recordOrder(c.id, { orderId: 'O1', amount: 5000 });
            if (c.analytics.totalOrders === 1 && c.analytics.totalRevenue === 5000) { 
                results.passed++; results.tests.push({ name: 'Record Order', status: 'PASS' }); 
            }
            else throw new Error('Invalid analytics');
            delete this.customers[c.id];
        } catch (e) { results.failed++; results.tests.push({ name: 'Record Order', status: 'FAIL', error: e.message }); }
        
        try {
            const s = this.getCustomerSegments();
            if (s.champions && s.loyal && s.atRisk) { results.passed++; results.tests.push({ name: 'Segments', status: 'PASS' }); }
            else throw new Error('Invalid segments');
        } catch (e) { results.failed++; results.tests.push({ name: 'Segments', status: 'FAIL', error: e.message }); }
        
        console.log('[CUSTOMER_MANAGER] Tests: ' + results.passed + '/' + (results.passed + results.failed) + ' passed');
        return results;
    }
};

if (typeof PRISM_GATEWAY !== 'undefined') {
    PRISM_GATEWAY.register('customer.create', 'PRISM_CUSTOMER_MANAGER.createCustomer');
    PRISM_GATEWAY.register('customer.update', 'PRISM_CUSTOMER_MANAGER.updateCustomer');
    PRISM_GATEWAY.register('customer.get', 'PRISM_CUSTOMER_MANAGER.getCustomer');
    PRISM_GATEWAY.register('customer.search', 'PRISM_CUSTOMER_MANAGER.searchCustomers');
    PRISM_GATEWAY.register('customer.recordOrder', 'PRISM_CUSTOMER_MANAGER.recordOrder');
    PRISM_GATEWAY.register('customer.segments', 'PRISM_CUSTOMER_MANAGER.getCustomerSegments');
    PRISM_GATEWAY.register('customer.top', 'PRISM_CUSTOMER_MANAGER.getTopCustomers');
}

console.log('[PRISM_CUSTOMER_MANAGER] Loaded v1.0.0');

// ═══════════════════════════════════════════════════════════════════════════════
// PRODUCT 3: BUSINESS/SHOP/ERP SYSTEM - ORDER MANAGER
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_ORDER_MANAGER = {
    version: '1.0.0',
    authority: 'PRISM_ORDER_MANAGER',
    
    // Order database
    orders: {},
    workOrders: {},
    
    // Order statuses
    ORDER_STATUSES: ['quote', 'pending', 'confirmed', 'in_progress', 'complete', 'shipped', 'invoiced', 'closed', 'cancelled'],
    WO_STATUSES: ['created', 'released', 'in_progress', 'complete', 'on_hold', 'cancelled'],
    
    createOrder: function(params) {
        const { customerId, items = [], notes = '', dueDate = null, priority = 'normal' } = params;
        
        if (!customerId) throw new Error('Customer ID required');
        if (items.length === 0) throw new Error('Order must have items');
        
        const orderId = 'ORD-' + Date.now().toString(36).toUpperCase();
        
        // Calculate totals
        let subtotal = 0;
        const processedItems = items.map((item, idx) => {
            const lineTotal = (item.quantity || 1) * (item.unitPrice || 0);
            subtotal += lineTotal;
            return {
                lineNumber: idx + 1,
                partNumber: item.partNumber || '',
                description: item.description || '',
                quantity: item.quantity || 1,
                unitPrice: item.unitPrice || 0,
                lineTotal,
                material: item.material || '',
                operations: item.operations || [],
                estimatedHours: item.estimatedHours || 0
            };
        });
        
        const taxRate = 0; // Would come from customer/location
        const tax = subtotal * taxRate;
        const total = subtotal + tax;
        
        this.orders[orderId] = {
            id: orderId,
            customerId,
            status: 'quote',
            items: processedItems,
            notes,
            dueDate,
            priority,
            subtotal, tax, total,
            created: Date.now(),
            modified: Date.now(),
            statusHistory: [{ status: 'quote', timestamp: Date.now(), user: 'system' }],
            workOrders: [],
            shipments: [],
            invoices: [],
            attachments: []
        };
        
        this._persistData();
        return this.orders[orderId];
    },
    
    updateOrderStatus: function(orderId, newStatus, user = 'system', notes = '') {
        const order = this.orders[orderId];
        if (!order) throw new Error('Order not found');
        if (!this.ORDER_STATUSES.includes(newStatus)) throw new Error('Invalid status');
        
        const oldStatus = order.status;
        order.status = newStatus;
        order.modified = Date.now();
        order.statusHistory.push({ status: newStatus, from: oldStatus, timestamp: Date.now(), user, notes });
        
        // Auto-update customer analytics when complete
        if (newStatus === 'complete' || newStatus === 'shipped') {
            if (typeof PRISM_CUSTOMER_MANAGER !== 'undefined') {
                PRISM_CUSTOMER_MANAGER.recordOrder(order.customerId, { orderId, amount: order.total });
            }
        }
        
        this._persistData();
        return order;
    },
    
    createWorkOrder: function(orderId, params = {}) {
        const order = this.orders[orderId];
        if (!order) throw new Error('Order not found');
        
        const { lineNumbers = [], machineId = null, operatorId = null, scheduledStart = null } = params;
        
        const woId = 'WO-' + Date.now().toString(36).toUpperCase();
        
        // Get items for this work order
        const items = lineNumbers.length > 0 ?
            order.items.filter(i => lineNumbers.includes(i.lineNumber)) :
            order.items;
        
        const workOrder = {
            id: woId,
            orderId,
            customerId: order.customerId,
            status: 'created',
            items: items.map(i => ({ ...i, completedQty: 0, scrapQty: 0 })),
            machineId,
            operatorId,
            scheduledStart,
            actualStart: null,
            completedDate: null,
            totalEstimatedHours: items.reduce((a, i) => a + (i.estimatedHours || 0), 0),
            actualHours: 0,
            notes: '',
            created: Date.now(),
            modified: Date.now(),
            statusHistory: [{ status: 'created', timestamp: Date.now() }],
            timeEntries: [],
            qualityRecords: []
        };
        
        this.workOrders[woId] = workOrder;
        order.workOrders.push(woId);
        
        this._persistData();
        return workOrder;
    },
    
    updateWorkOrderStatus: function(woId, newStatus, details = {}) {
        const wo = this.workOrders[woId];
        if (!wo) throw new Error('Work order not found');
        if (!this.WO_STATUSES.includes(newStatus)) throw new Error('Invalid status');
        
        const oldStatus = wo.status;
        wo.status = newStatus;
        wo.modified = Date.now();
        wo.statusHistory.push({ status: newStatus, from: oldStatus, timestamp: Date.now(), ...details });
        
        if (newStatus === 'in_progress' && !wo.actualStart) wo.actualStart = Date.now();
        if (newStatus === 'complete') wo.completedDate = Date.now();
        
        this._persistData();
        return wo;
    },
    
    recordTimeEntry: function(woId, entry) {
        const wo = this.workOrders[woId];
        if (!wo) throw new Error('Work order not found');
        
        const { operatorId, hours, operation = '', notes = '' } = entry;
        
        wo.timeEntries.push({
            id: 'TE-' + Date.now().toString(36),
            operatorId, hours, operation, notes,
            timestamp: Date.now()
        });
        
        wo.actualHours += hours;
        wo.modified = Date.now();
        
        this._persistData();
        return wo;
    },
    
    recordProduction: function(woId, production) {
        const wo = this.workOrders[woId];
        if (!wo) throw new Error('Work order not found');
        
        const { lineNumber, completedQty, scrapQty = 0, notes = '' } = production;
        
        const item = wo.items.find(i => i.lineNumber === lineNumber);
        if (!item) throw new Error('Line not found');
        
        item.completedQty += completedQty;
        item.scrapQty += scrapQty;
        wo.modified = Date.now();
        
        // Check if all items complete
        const allComplete = wo.items.every(i => i.completedQty >= i.quantity);
        if (allComplete && wo.status === 'in_progress') {
            this.updateWorkOrderStatus(woId, 'complete');
        }
        
        this._persistData();
        return item;
    },
    
    getOrder: function(orderId) {
        return this.orders[orderId] || null;
    },
    
    getWorkOrder: function(woId) {
        return this.workOrders[woId] || null;
    },
    
    searchOrders: function(query = '', filters = {}) {
        const { status = null, customerId = null, fromDate = null, toDate = null, priority = null } = filters;
        const queryLower = query.toLowerCase();
        
        return Object.values(this.orders).filter(o => {
            const textMatch = !query || 
                o.id.toLowerCase().includes(queryLower) ||
                o.items.some(i => i.partNumber.toLowerCase().includes(queryLower) || i.description.toLowerCase().includes(queryLower));
            
            const statusMatch = !status || o.status === status;
            const customerMatch = !customerId || o.customerId === customerId;
            const dateMatch = (!fromDate || o.created >= fromDate) && (!toDate || o.created <= toDate);
            const priorityMatch = !priority || o.priority === priority;
            
            return textMatch && statusMatch && customerMatch && dateMatch && priorityMatch;
        });
    },
    
    getOrdersByStatus: function() {
        const byStatus = {};
        for (const status of this.ORDER_STATUSES) byStatus[status] = [];
        
        for (const order of Object.values(this.orders)) {
            if (byStatus[order.status]) byStatus[order.status].push(order);
        }
        
        return byStatus;
    },
    
    getWorkOrderQueue: function(machineId = null) {
        let wos = Object.values(this.workOrders).filter(wo => 
            wo.status === 'released' || wo.status === 'in_progress'
        );
        
        if (machineId) wos = wos.filter(wo => wo.machineId === machineId);
        
        // Sort by priority (from parent order) and scheduled start
        return wos.sort((a, b) => {
            const orderA = this.orders[a.orderId];
            const orderB = this.orders[b.orderId];
            const priorityOrder = { urgent: 0, high: 1, normal: 2, low: 3 };
            
            const pA = priorityOrder[orderA?.priority] ?? 2;
            const pB = priorityOrder[orderB?.priority] ?? 2;
            
            if (pA !== pB) return pA - pB;
            return (a.scheduledStart || a.created) - (b.scheduledStart || b.created);
        });
    },
    
    getMetrics: function(dateRange = null) {
        const orders = Object.values(this.orders);
        const workOrders = Object.values(this.workOrders);
        
        const active = orders.filter(o => !['closed', 'cancelled'].includes(o.status));
        const completed = orders.filter(o => o.status === 'closed');
        
        const completedWOs = workOrders.filter(wo => wo.status === 'complete');
        const avgEfficiency = completedWOs.length > 0 ?
            completedWOs.reduce((a, wo) => a + (wo.totalEstimatedHours / Math.max(0.1, wo.actualHours)), 0) / completedWOs.length : 1;
        
        return {
            totalOrders: orders.length,
            activeOrders: active.length,
            completedOrders: completed.length,
            totalValue: active.reduce((a, o) => a + o.total, 0),
            totalWorkOrders: workOrders.length,
            activeWorkOrders: workOrders.filter(wo => ['released', 'in_progress'].includes(wo.status)).length,
            avgEfficiency: (avgEfficiency * 100).toFixed(1) + '%',
            onTimeRate: 'N/A' // Would need due date tracking
        };
    },
    
    _persistData: function() {
        try {
            localStorage.setItem('prism_orders', JSON.stringify({ orders: this.orders, workOrders: this.workOrders }));
        } catch (e) { /* Storage unavailable */ }
    },
    
    loadPersistedData: function() {
        try {
            const saved = localStorage.getItem('prism_orders');
            if (saved) {
                const data = JSON.parse(saved);
                this.orders = data.orders || {};
                this.workOrders = data.workOrders || {};
            }
        } catch (e) { /* Storage unavailable */ }
    },
    
    runSelfTests: function() {
        console.log('[ORDER_MANAGER] Running self-tests...');
        const results = { passed: 0, failed: 0, tests: [] };
        
        try {
            const o = this.createOrder({ 
                customerId: 'C1', 
                items: [{ partNumber: 'P1', quantity: 10, unitPrice: 50 }] 
            });
            if (o.id && o.total === 500) { results.passed++; results.tests.push({ name: 'Create Order', status: 'PASS' }); }
            else throw new Error('Invalid order');
            
            // Test status update
            this.updateOrderStatus(o.id, 'confirmed');
            if (o.status === 'confirmed') { results.passed++; results.tests.push({ name: 'Update Status', status: 'PASS' }); }
            else throw new Error('Status not updated');
            
            // Test work order
            const wo = this.createWorkOrder(o.id);
            if (wo.id && wo.orderId === o.id) { results.passed++; results.tests.push({ name: 'Create WO', status: 'PASS' }); }
            else throw new Error('Invalid WO');
            
            // Cleanup
            delete this.orders[o.id];
            delete this.workOrders[wo.id];
        } catch (e) { 
            results.failed++; 
            results.tests.push({ name: 'Order Tests', status: 'FAIL', error: e.message }); 
        }
        
        try {
            const m = this.getMetrics();
            if (typeof m.totalOrders === 'number') { results.passed++; results.tests.push({ name: 'Metrics', status: 'PASS' }); }
            else throw new Error('Invalid metrics');
        } catch (e) { results.failed++; results.tests.push({ name: 'Metrics', status: 'FAIL', error: e.message }); }
        
        console.log('[ORDER_MANAGER] Tests: ' + results.passed + '/' + (results.passed + results.failed) + ' passed');
        return results;
    }
};

if (typeof PRISM_GATEWAY !== 'undefined') {
    PRISM_GATEWAY.register('order.create', 'PRISM_ORDER_MANAGER.createOrder');
    PRISM_GATEWAY.register('order.get', 'PRISM_ORDER_MANAGER.getOrder');
    PRISM_GATEWAY.register('order.updateStatus', 'PRISM_ORDER_MANAGER.updateOrderStatus');
    PRISM_GATEWAY.register('order.search', 'PRISM_ORDER_MANAGER.searchOrders');
    PRISM_GATEWAY.register('order.byStatus', 'PRISM_ORDER_MANAGER.getOrdersByStatus');
    PRISM_GATEWAY.register('workorder.create', 'PRISM_ORDER_MANAGER.createWorkOrder');
    PRISM_GATEWAY.register('workorder.get', 'PRISM_ORDER_MANAGER.getWorkOrder');
    PRISM_GATEWAY.register('workorder.updateStatus', 'PRISM_ORDER_MANAGER.updateWorkOrderStatus');
    PRISM_GATEWAY.register('workorder.queue', 'PRISM_ORDER_MANAGER.getWorkOrderQueue');
    PRISM_GATEWAY.register('workorder.time', 'PRISM_ORDER_MANAGER.recordTimeEntry');
    PRISM_GATEWAY.register('workorder.production', 'PRISM_ORDER_MANAGER.recordProduction');
    PRISM_GATEWAY.register('shop.metrics', 'PRISM_ORDER_MANAGER.getMetrics');
}

console.log('[PRISM_ORDER_MANAGER] Loaded v1.0.0');

// ═══════════════════════════════════════════════════════════════════════════════
// PRODUCT 3: BUSINESS/SHOP/ERP SYSTEM - QUALITY MANAGER
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_QUALITY_MANAGER = {
    version: '1.0.0',
    authority: 'PRISM_QUALITY_MANAGER',
    
    // Quality records
    inspections: {},
    ncrs: {},           // Non-Conformance Reports
    cars: {},           // Corrective Action Reports
    spcData: {},        // SPC control data by characteristic
    
    // Inspection types
    INSPECTION_TYPES: ['first_article', 'in_process', 'final', 'receiving', 'periodic'],
    NCR_STATUSES: ['open', 'under_review', 'disposition', 'closed'],
    DISPOSITIONS: ['use_as_is', 'rework', 'repair', 'scrap', 'return_to_vendor'],
    
    createInspection: function(params) {
        const { workOrderId, type = 'in_process', partNumber, quantity, inspector, characteristics = [] } = params;
        
        const id = 'INS-' + Date.now().toString(36).toUpperCase();
        
        this.inspections[id] = {
            id,
            workOrderId,
            type,
            partNumber,
            quantity,
            inspector,
            status: 'pending',
            created: Date.now(),
            completed: null,
            characteristics: characteristics.map((c, idx) => ({
                id: idx + 1,
                name: c.name || 'Characteristic ' + (idx + 1),
                nominal: c.nominal,
                upperLimit: c.upperLimit,
                lowerLimit: c.lowerLimit,
                unit: c.unit || 'mm',
                measurements: [],
                result: null  // pass, fail, pending
            })),
            overallResult: 'pending',
            notes: '',
            attachments: []
        };
        
        this._persistData();
        return this.inspections[id];
    },
    
    recordMeasurement: function(inspectionId, characteristicId, values) {
        const inspection = this.inspections[inspectionId];
        if (!inspection) throw new Error('Inspection not found');
        
        const char = inspection.characteristics.find(c => c.id === characteristicId);
        if (!char) throw new Error('Characteristic not found');
        
        // values can be a single number or array
        const measurements = Array.isArray(values) ? values : [values];
        char.measurements.push(...measurements.map(v => ({ value: v, timestamp: Date.now() })));
        
        // Check against limits
        const allPass = char.measurements.every(m => 
            m.value >= char.lowerLimit && m.value <= char.upperLimit
        );
        char.result = allPass ? 'pass' : 'fail';
        
        // Add to SPC data
        const spcKey = `${inspection.partNumber}_${char.name}`;
        if (!this.spcData[spcKey]) {
            this.spcData[spcKey] = {
                partNumber: inspection.partNumber,
                characteristic: char.name,
                nominal: char.nominal,
                upperLimit: char.upperLimit,
                lowerLimit: char.lowerLimit,
                measurements: []
            };
        }
        this.spcData[spcKey].measurements.push(...measurements.map(v => ({
            value: v,
            timestamp: Date.now(),
            inspectionId
        })));
        
        // Update overall inspection result
        this._updateInspectionResult(inspection);
        
        this._persistData();
        return char;
    },
    
    completeInspection: function(inspectionId, notes = '') {
        const inspection = this.inspections[inspectionId];
        if (!inspection) throw new Error('Inspection not found');
        
        inspection.status = 'complete';
        inspection.completed = Date.now();
        inspection.notes = notes;
        
        // Verify all characteristics have results
        for (const char of inspection.characteristics) {
            if (char.result === null || char.result === 'pending') {
                char.result = char.measurements.length > 0 ? 'pass' : 'incomplete';
            }
        }
        
        this._updateInspectionResult(inspection);
        
        // Auto-create NCR if failed
        if (inspection.overallResult === 'fail') {
            this.createNCR({
                inspectionId,
                partNumber: inspection.partNumber,
                workOrderId: inspection.workOrderId,
                description: 'Failed inspection: ' + inspection.characteristics.filter(c => c.result === 'fail').map(c => c.name).join(', '),
                quantity: inspection.quantity
            });
        }
        
        this._persistData();
        return inspection;
    },
    
    createNCR: function(params) {
        const { inspectionId = null, workOrderId = null, partNumber, description, quantity, defectType = 'dimensional' } = params;
        
        const id = 'NCR-' + Date.now().toString(36).toUpperCase();
        
        this.ncrs[id] = {
            id,
            inspectionId,
            workOrderId,
            partNumber,
            description,
            quantity,
            defectType,
            status: 'open',
            disposition: null,
            dispositionNotes: '',
            rootCause: '',
            created: Date.now(),
            closed: null,
            cost: 0,
            carId: null,  // linked Corrective Action
            history: [{ status: 'open', timestamp: Date.now() }]
        };
        
        this._persistData();
        return this.ncrs[id];
    },
    
    updateNCRDisposition: function(ncrId, disposition, notes = '', cost = 0) {
        const ncr = this.ncrs[ncrId];
        if (!ncr) throw new Error('NCR not found');
        if (!this.DISPOSITIONS.includes(disposition)) throw new Error('Invalid disposition');
        
        ncr.status = 'disposition';
        ncr.disposition = disposition;
        ncr.dispositionNotes = notes;
        ncr.cost = cost;
        ncr.history.push({ status: 'disposition', disposition, timestamp: Date.now() });
        
        this._persistData();
        return ncr;
    },
    
    closeNCR: function(ncrId, rootCause = '') {
        const ncr = this.ncrs[ncrId];
        if (!ncr) throw new Error('NCR not found');
        
        ncr.status = 'closed';
        ncr.closed = Date.now();
        ncr.rootCause = rootCause;
        ncr.history.push({ status: 'closed', timestamp: Date.now() });
        
        this._persistData();
        return ncr;
    },
    
    createCAR: function(params) {
        const { ncrId = null, title, description, assignedTo, dueDate } = params;
        
        const id = 'CAR-' + Date.now().toString(36).toUpperCase();
        
        // Link to NCR if provided
        if (ncrId && this.ncrs[ncrId]) {
            this.ncrs[ncrId].carId = id;
        }
        
        this.cars[id] = {
            id,
            ncrId,
            title,
            description,
            assignedTo,
            dueDate,
            status: 'open',
            rootCauseAnalysis: '',
            correctiveActions: [],
            preventiveActions: [],
            verificationDate: null,
            verificationNotes: '',
            effectiveness: null,  // effective, ineffective, partial
            created: Date.now(),
            closed: null
        };
        
        this._persistData();
        return this.cars[id];
    },
    
    getSPCAnalysis: function(partNumber, characteristicName) {
        const spcKey = `${partNumber}_${characteristicName}`;
        const spc = this.spcData[spcKey];
        if (!spc || spc.measurements.length < 2) return null;
        
        const values = spc.measurements.map(m => m.value);
        const n = values.length;
        
        // Calculate statistics
        const mean = values.reduce((a, b) => a + b, 0) / n;
        const variance = values.reduce((a, v) => a + Math.pow(v - mean, 2), 0) / (n - 1);
        const stdDev = Math.sqrt(variance);
        
        // Control limits (3-sigma)
        const ucl = mean + 3 * stdDev;
        const lcl = mean - 3 * stdDev;
        
        // Cp and Cpk (process capability)
        const usl = spc.upperLimit;
        const lsl = spc.lowerLimit;
        const cp = (usl - lsl) / (6 * stdDev);
        const cpk = Math.min((usl - mean) / (3 * stdDev), (mean - lsl) / (3 * stdDev));
        
        // Out of control points
        const outOfControl = values.filter(v => v > ucl || v < lcl).length;
        const outOfSpec = values.filter(v => v > usl || v < lsl).length;
        
        return {
            partNumber,
            characteristic: characteristicName,
            sampleSize: n,
            mean: mean.toFixed(4),
            stdDev: stdDev.toFixed(4),
            controlLimits: { ucl: ucl.toFixed(4), lcl: lcl.toFixed(4) },
            specLimits: { usl, lsl },
            cp: cp.toFixed(3),
            cpk: cpk.toFixed(3),
            processCapable: cpk >= 1.33,
            outOfControl,
            outOfSpec,
            trend: this._calculateTrend(values)
        };
    },
    
    getQualityMetrics: function(dateRange = null) {
        const inspections = Object.values(this.inspections);
        const ncrs = Object.values(this.ncrs);
        
        const completed = inspections.filter(i => i.status === 'complete');
        const passed = completed.filter(i => i.overallResult === 'pass');
        const failed = completed.filter(i => i.overallResult === 'fail');
        
        const openNCRs = ncrs.filter(n => n.status !== 'closed');
        const scrapNCRs = ncrs.filter(n => n.disposition === 'scrap');
        const totalNCRCost = ncrs.reduce((a, n) => a + (n.cost || 0), 0);
        
        return {
            totalInspections: inspections.length,
            completedInspections: completed.length,
            passRate: completed.length > 0 ? (passed.length / completed.length * 100).toFixed(1) + '%' : 'N/A',
            failRate: completed.length > 0 ? (failed.length / completed.length * 100).toFixed(1) + '%' : 'N/A',
            totalNCRs: ncrs.length,
            openNCRs: openNCRs.length,
            scrapRate: ncrs.length > 0 ? (scrapNCRs.length / ncrs.length * 100).toFixed(1) + '%' : 'N/A',
            totalNCRCost,
            avgNCRCost: ncrs.length > 0 ? (totalNCRCost / ncrs.length).toFixed(2) : 0,
            openCARs: Object.values(this.cars).filter(c => c.status === 'open').length
        };
    },
    
    _updateInspectionResult: function(inspection) {
        const results = inspection.characteristics.map(c => c.result);
        if (results.some(r => r === 'fail')) {
            inspection.overallResult = 'fail';
        } else if (results.every(r => r === 'pass')) {
            inspection.overallResult = 'pass';
        } else {
            inspection.overallResult = 'pending';
        }
    },
    
    _calculateTrend: function(values) {
        if (values.length < 5) return 'insufficient_data';
        
        const recent = values.slice(-5);
        const older = values.slice(-10, -5);
        
        if (older.length < 5) return 'insufficient_data';
        
        const recentMean = recent.reduce((a, b) => a + b, 0) / recent.length;
        const olderMean = older.reduce((a, b) => a + b, 0) / older.length;
        
        const diff = (recentMean - olderMean) / olderMean;
        
        if (diff > 0.05) return 'increasing';
        if (diff < -0.05) return 'decreasing';
        return 'stable';
    },
    
    _persistData: function() {
        try {
            localStorage.setItem('prism_quality', JSON.stringify({
                inspections: this.inspections,
                ncrs: this.ncrs,
                cars: this.cars,
                spcData: this.spcData
            }));
        } catch (e) { /* Storage unavailable */ }
    },
    
    loadPersistedData: function() {
        try {
            const saved = localStorage.getItem('prism_quality');
            if (saved) {
                const data = JSON.parse(saved);
                this.inspections = data.inspections || {};
                this.ncrs = data.ncrs || {};
                this.cars = data.cars || {};
                this.spcData = data.spcData || {};
            }
        } catch (e) { /* Storage unavailable */ }
    },
    
    runSelfTests: function() {
        console.log('[QUALITY_MANAGER] Running self-tests...');
        const results = { passed: 0, failed: 0, tests: [] };
        
        try {
            const ins = this.createInspection({
                workOrderId: 'WO1', type: 'first_article', partNumber: 'P1', quantity: 1, inspector: 'QC1',
                characteristics: [{ name: 'Diameter', nominal: 25.0, upperLimit: 25.05, lowerLimit: 24.95, unit: 'mm' }]
            });
            if (ins.id && ins.characteristics.length === 1) { results.passed++; results.tests.push({ name: 'Create Inspection', status: 'PASS' }); }
            else throw new Error('Invalid');
            
            this.recordMeasurement(ins.id, 1, [25.02, 25.01, 25.03]);
            const char = ins.characteristics[0];
            if (char.result === 'pass' && char.measurements.length === 3) { results.passed++; results.tests.push({ name: 'Record Measurement', status: 'PASS' }); }
            else throw new Error('Invalid measurement');
            
            delete this.inspections[ins.id];
        } catch (e) { results.failed++; results.tests.push({ name: 'Inspection Tests', status: 'FAIL', error: e.message }); }
        
        try {
            const ncr = this.createNCR({ partNumber: 'P1', description: 'Test NCR', quantity: 5 });
            if (ncr.id && ncr.status === 'open') { results.passed++; results.tests.push({ name: 'Create NCR', status: 'PASS' }); }
            else throw new Error('Invalid NCR');
            delete this.ncrs[ncr.id];
        } catch (e) { results.failed++; results.tests.push({ name: 'Create NCR', status: 'FAIL', error: e.message }); }
        
        try {
            const m = this.getQualityMetrics();
            if (typeof m.totalInspections === 'number') { results.passed++; results.tests.push({ name: 'Quality Metrics', status: 'PASS' }); }
            else throw new Error('Invalid metrics');
        } catch (e) { results.failed++; results.tests.push({ name: 'Quality Metrics', status: 'FAIL', error: e.message }); }
        
        console.log('[QUALITY_MANAGER] Tests: ' + results.passed + '/' + (results.passed + results.failed) + ' passed');
        return results;
    }
};

if (typeof PRISM_GATEWAY !== 'undefined') {
    PRISM_GATEWAY.register('quality.inspection.create', 'PRISM_QUALITY_MANAGER.createInspection');
    PRISM_GATEWAY.register('quality.inspection.measure', 'PRISM_QUALITY_MANAGER.recordMeasurement');
    PRISM_GATEWAY.register('quality.inspection.complete', 'PRISM_QUALITY_MANAGER.completeInspection');
    PRISM_GATEWAY.register('quality.ncr.create', 'PRISM_QUALITY_MANAGER.createNCR');
    PRISM_GATEWAY.register('quality.ncr.disposition', 'PRISM_QUALITY_MANAGER.updateNCRDisposition');
    PRISM_GATEWAY.register('quality.ncr.close', 'PRISM_QUALITY_MANAGER.closeNCR');
    PRISM_GATEWAY.register('quality.car.create', 'PRISM_QUALITY_MANAGER.createCAR');
    PRISM_GATEWAY.register('quality.spc', 'PRISM_QUALITY_MANAGER.getSPCAnalysis');
    PRISM_GATEWAY.register('quality.metrics', 'PRISM_QUALITY_MANAGER.getQualityMetrics');
}

console.log('[PRISM_QUALITY_MANAGER] Loaded v1.0.0');

// ═══════════════════════════════════════════════════════════════════════════════
// PRODUCT 3: BUSINESS/SHOP/ERP SYSTEM - REPORTING ENGINE
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_REPORTING_ENGINE = {
    version: '1.0.0',
    authority: 'PRISM_REPORTING_ENGINE',
    
    // Report definitions
    reports: {
        shop_dashboard: { name: 'Shop Dashboard', type: 'dashboard', refresh: 60000 },
        production_summary: { name: 'Production Summary', type: 'summary', period: 'daily' },
        quality_report: { name: 'Quality Report', type: 'detail', period: 'weekly' },
        customer_analysis: { name: 'Customer Analysis', type: 'analysis', period: 'monthly' },
        machine_utilization: { name: 'Machine Utilization', type: 'kpi', period: 'daily' },
        financial_summary: { name: 'Financial Summary', type: 'financial', period: 'monthly' },
        operator_performance: { name: 'Operator Performance', type: 'kpi', period: 'weekly' }
    },
    
    // KPI definitions
    kpis: {
        oee: { name: 'Overall Equipment Effectiveness', target: 85, unit: '%', direction: 'higher' },
        onTimeDelivery: { name: 'On-Time Delivery', target: 95, unit: '%', direction: 'higher' },
        firstPassYield: { name: 'First Pass Yield', target: 98, unit: '%', direction: 'higher' },
        scrapRate: { name: 'Scrap Rate', target: 2, unit: '%', direction: 'lower' },
        laborEfficiency: { name: 'Labor Efficiency', target: 90, unit: '%', direction: 'higher' },
        quoteWinRate: { name: 'Quote Win Rate', target: 40, unit: '%', direction: 'higher' },
        avgLeadTime: { name: 'Avg Lead Time', target: 5, unit: 'days', direction: 'lower' },
        revenuePerEmployee: { name: 'Revenue/Employee', target: 150000, unit: '$', direction: 'higher' }
    },
    
    generateDashboard: function() {
        // Collect data from all managers
        const orderMetrics = typeof PRISM_ORDER_MANAGER !== 'undefined' ? 
            PRISM_ORDER_MANAGER.getMetrics() : {};
        const qualityMetrics = typeof PRISM_QUALITY_MANAGER !== 'undefined' ? 
            PRISM_QUALITY_MANAGER.getQualityMetrics() : {};
        const quotingStats = typeof PRISM_QUOTING_LEARNING !== 'undefined' ? 
            PRISM_QUOTING_LEARNING.getStatistics() : {};
        const shopLearning = typeof PRISM_SHOP_LEARNING_ENGINE !== 'undefined' ?
            PRISM_SHOP_LEARNING_ENGINE.getStatistics() : {};
        
        // Calculate KPIs
        const kpiValues = this._calculateKPIs(orderMetrics, qualityMetrics, quotingStats, shopLearning);
        
        return {
            timestamp: Date.now(),
            summary: {
                activeOrders: orderMetrics.activeOrders || 0,
                activeWorkOrders: orderMetrics.activeWorkOrders || 0,
                orderValue: orderMetrics.totalValue || 0,
                openNCRs: qualityMetrics.openNCRs || 0
            },
            kpis: kpiValues,
            alerts: this._generateAlerts(kpiValues),
            charts: {
                orderStatus: this._getOrderStatusChart(),
                productionTrend: this._getProductionTrend(),
                qualityTrend: this._getQualityTrend()
            }
        };
    },
    
    generateProductionReport: function(period = 'daily', startDate = null, endDate = null) {
        const now = Date.now();
        const start = startDate || (period === 'daily' ? now - 24*60*60*1000 : 
                                    period === 'weekly' ? now - 7*24*60*60*1000 : 
                                    now - 30*24*60*60*1000);
        const end = endDate || now;
        
        const workOrders = typeof PRISM_ORDER_MANAGER !== 'undefined' ?
            Object.values(PRISM_ORDER_MANAGER.workOrders).filter(wo => 
                wo.created >= start && wo.created <= end
            ) : [];
        
        const completed = workOrders.filter(wo => wo.status === 'complete');
        const totalHours = completed.reduce((a, wo) => a + wo.actualHours, 0);
        const estimatedHours = completed.reduce((a, wo) => a + wo.totalEstimatedHours, 0);
        
        return {
            period,
            startDate: new Date(start).toISOString(),
            endDate: new Date(end).toISOString(),
            generated: new Date().toISOString(),
            summary: {
                workOrdersCreated: workOrders.length,
                workOrdersCompleted: completed.length,
                totalActualHours: totalHours.toFixed(1),
                totalEstimatedHours: estimatedHours.toFixed(1),
                efficiency: estimatedHours > 0 ? ((estimatedHours / totalHours) * 100).toFixed(1) + '%' : 'N/A'
            },
            byMachine: this._groupByMachine(completed),
            byOperator: this._groupByOperator(completed),
            details: completed.map(wo => ({
                id: wo.id,
                orderId: wo.orderId,
                estimatedHours: wo.totalEstimatedHours,
                actualHours: wo.actualHours,
                efficiency: wo.totalEstimatedHours > 0 ? 
                    ((wo.totalEstimatedHours / wo.actualHours) * 100).toFixed(1) + '%' : 'N/A'
            }))
        };
    },
    
    generateQualityReport: function(period = 'weekly') {
        const metrics = typeof PRISM_QUALITY_MANAGER !== 'undefined' ?
            PRISM_QUALITY_MANAGER.getQualityMetrics() : {};
        
        const ncrs = typeof PRISM_QUALITY_MANAGER !== 'undefined' ?
            Object.values(PRISM_QUALITY_MANAGER.ncrs) : [];
        
        // Group NCRs by defect type
        const byDefectType = {};
        for (const ncr of ncrs) {
            byDefectType[ncr.defectType] = (byDefectType[ncr.defectType] || 0) + 1;
        }
        
        // Pareto analysis
        const paretoData = Object.entries(byDefectType)
            .sort((a, b) => b[1] - a[1])
            .map(([type, count], idx, arr) => {
                const cumulative = arr.slice(0, idx + 1).reduce((a, [, c]) => a + c, 0);
                const total = arr.reduce((a, [, c]) => a + c, 0);
                return { defectType: type, count, cumulative, cumulativePercent: (cumulative / total * 100).toFixed(1) };
            });
        
        return {
            period,
            generated: new Date().toISOString(),
            summary: metrics,
            paretoAnalysis: paretoData,
            openNCRs: ncrs.filter(n => n.status !== 'closed').map(n => ({
                id: n.id,
                partNumber: n.partNumber,
                description: n.description,
                status: n.status,
                age: Math.floor((Date.now() - n.created) / (24*60*60*1000)) + ' days'
            })),
            recommendations: this._generateQualityRecommendations(paretoData, metrics)
        };
    },
    
    generateFinancialSummary: function(period = 'monthly') {
        const orders = typeof PRISM_ORDER_MANAGER !== 'undefined' ?
            Object.values(PRISM_ORDER_MANAGER.orders) : [];
        const quotes = typeof PRISM_QUOTING_LEARNING !== 'undefined' ?
            PRISM_QUOTING_LEARNING.learningData.quotes : [];
        
        const completedOrders = orders.filter(o => o.status === 'closed' || o.status === 'invoiced');
        const totalRevenue = completedOrders.reduce((a, o) => a + o.total, 0);
        
        const wonQuotes = quotes.filter(q => q.won);
        const avgMargin = wonQuotes.length > 0 ?
            wonQuotes.filter(q => q.margin).reduce((a, q) => a + q.margin, 0) / wonQuotes.filter(q => q.margin).length : 0;
        
        const qualityMetrics = typeof PRISM_QUALITY_MANAGER !== 'undefined' ?
            PRISM_QUALITY_MANAGER.getQualityMetrics() : {};
        
        return {
            period,
            generated: new Date().toISOString(),
            revenue: {
                total: totalRevenue,
                orderCount: completedOrders.length,
                avgOrderValue: completedOrders.length > 0 ? (totalRevenue / completedOrders.length).toFixed(2) : 0
            },
            quoting: {
                totalQuotes: quotes.length,
                wonQuotes: wonQuotes.length,
                winRate: quotes.length > 0 ? (wonQuotes.length / quotes.length * 100).toFixed(1) + '%' : 'N/A',
                avgMargin: (avgMargin * 100).toFixed(1) + '%'
            },
            costs: {
                qualityCost: qualityMetrics.totalNCRCost || 0,
                avgNCRCost: qualityMetrics.avgNCRCost || 0
            },
            profitability: {
                grossProfit: totalRevenue * avgMargin,
                grossMargin: (avgMargin * 100).toFixed(1) + '%'
            }
        };
    },
    
    generateCustomReport: function(config) {
        const { metrics = [], groupBy = null, filters = {}, format = 'json' } = config;
        
        const data = {};
        
        // Collect requested metrics
        if (metrics.includes('orders')) {
            data.orders = typeof PRISM_ORDER_MANAGER !== 'undefined' ?
                PRISM_ORDER_MANAGER.getMetrics() : {};
        }
        if (metrics.includes('quality')) {
            data.quality = typeof PRISM_QUALITY_MANAGER !== 'undefined' ?
                PRISM_QUALITY_MANAGER.getQualityMetrics() : {};
        }
        if (metrics.includes('quoting')) {
            data.quoting = typeof PRISM_QUOTING_LEARNING !== 'undefined' ?
                PRISM_QUOTING_LEARNING.getStatistics() : {};
        }
        if (metrics.includes('customers')) {
            data.customers = typeof PRISM_CUSTOMER_MANAGER !== 'undefined' ?
                { total: Object.keys(PRISM_CUSTOMER_MANAGER.customers).length,
                  segments: PRISM_CUSTOMER_MANAGER.getCustomerSegments() } : {};
        }
        
        return {
            config,
            generated: new Date().toISOString(),
            data
        };
    },
    
    exportReport: function(report, format = 'json') {
        if (format === 'json') {
            return JSON.stringify(report, null, 2);
        }
        
        if (format === 'csv') {
            // Simple CSV export for flat data
            const rows = [];
            const flatten = (obj, prefix = '') => {
                for (const [key, value] of Object.entries(obj)) {
                    const newKey = prefix ? `${prefix}.${key}` : key;
                    if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
                        flatten(value, newKey);
                    } else {
                        rows.push([newKey, Array.isArray(value) ? value.length : value]);
                    }
                }
            };
            flatten(report);
            return 'Key,Value\n' + rows.map(r => r.join(',')).join('\n');
        }
        
        return report;
    },
    
    _calculateKPIs: function(orderMetrics, qualityMetrics, quotingStats, shopLearning) {
        const kpiValues = {};
        
        // OEE (simplified)
        kpiValues.oee = {
            value: orderMetrics.avgEfficiency ? parseFloat(orderMetrics.avgEfficiency) : 0,
            target: this.kpis.oee.target,
            status: this._getKPIStatus('oee', parseFloat(orderMetrics.avgEfficiency) || 0)
        };
        
        // First Pass Yield
        const fpyValue = qualityMetrics.passRate ? parseFloat(qualityMetrics.passRate) : 100;
        kpiValues.firstPassYield = {
            value: fpyValue,
            target: this.kpis.firstPassYield.target,
            status: this._getKPIStatus('firstPassYield', fpyValue)
        };
        
        // Scrap Rate
        const scrapValue = qualityMetrics.scrapRate ? parseFloat(qualityMetrics.scrapRate) : 0;
        kpiValues.scrapRate = {
            value: scrapValue,
            target: this.kpis.scrapRate.target,
            status: this._getKPIStatus('scrapRate', scrapValue)
        };
        
        // Quote Win Rate
        const winRateValue = quotingStats.winRate ? parseFloat(quotingStats.winRate) : 0;
        kpiValues.quoteWinRate = {
            value: winRateValue,
            target: this.kpis.quoteWinRate.target,
            status: this._getKPIStatus('quoteWinRate', winRateValue)
        };
        
        return kpiValues;
    },
    
    _getKPIStatus: function(kpiName, value) {
        const kpi = this.kpis[kpiName];
        if (!kpi) return 'unknown';
        
        const diff = kpi.direction === 'higher' ? value - kpi.target : kpi.target - value;
        
        if (diff >= 0) return 'good';
        if (diff > -5) return 'warning';
        return 'critical';
    },
    
    _generateAlerts: function(kpiValues) {
        const alerts = [];
        
        for (const [name, kpi] of Object.entries(kpiValues)) {
            if (kpi.status === 'critical') {
                alerts.push({
                    level: 'critical',
                    kpi: name,
                    message: `${this.kpis[name]?.name || name} is below target: ${kpi.value}% vs ${kpi.target}%`
                });
            } else if (kpi.status === 'warning') {
                alerts.push({
                    level: 'warning',
                    kpi: name,
                    message: `${this.kpis[name]?.name || name} approaching target: ${kpi.value}% vs ${kpi.target}%`
                });
            }
        }
        
        return alerts;
    },
    
    _getOrderStatusChart: function() {
        if (typeof PRISM_ORDER_MANAGER === 'undefined') return [];
        
        const byStatus = PRISM_ORDER_MANAGER.getOrdersByStatus();
        return Object.entries(byStatus).map(([status, orders]) => ({
            status,
            count: orders.length,
            value: orders.reduce((a, o) => a + o.total, 0)
        }));
    },
    
    _getProductionTrend: function() {
        // Would aggregate production data over time
        return [];
    },
    
    _getQualityTrend: function() {
        // Would aggregate quality data over time
        return [];
    },
    
    _groupByMachine: function(workOrders) {
        const groups = {};
        for (const wo of workOrders) {
            const machine = wo.machineId || 'Unassigned';
            if (!groups[machine]) groups[machine] = { count: 0, hours: 0 };
            groups[machine].count++;
            groups[machine].hours += wo.actualHours;
        }
        return groups;
    },
    
    _groupByOperator: function(workOrders) {
        const groups = {};
        for (const wo of workOrders) {
            for (const te of wo.timeEntries || []) {
                const op = te.operatorId || 'Unknown';
                if (!groups[op]) groups[op] = { hours: 0, entries: 0 };
                groups[op].hours += te.hours;
                groups[op].entries++;
            }
        }
        return groups;
    },
    
    _generateQualityRecommendations: function(paretoData, metrics) {
        const recommendations = [];
        
        if (paretoData.length > 0 && parseFloat(paretoData[0].cumulativePercent) > 50) {
            recommendations.push({
                priority: 'high',
                issue: `${paretoData[0].defectType} defects account for ${paretoData[0].cumulativePercent}% of NCRs`,
                action: 'Focus corrective actions on this defect type for maximum impact'
            });
        }
        
        const passRate = parseFloat(metrics.passRate) || 100;
        if (passRate < 95) {
            recommendations.push({
                priority: 'high',
                issue: `First pass yield is ${metrics.passRate}`,
                action: 'Review inspection criteria and process controls'
            });
        }
        
        return recommendations;
    },
    
    runSelfTests: function() {
        console.log('[REPORTING_ENGINE] Running self-tests...');
        const results = { passed: 0, failed: 0, tests: [] };
        
        try {
            const d = this.generateDashboard();
            if (d.timestamp && d.summary && d.kpis) { results.passed++; results.tests.push({ name: 'Dashboard', status: 'PASS' }); }
            else throw new Error('Invalid dashboard');
        } catch (e) { results.failed++; results.tests.push({ name: 'Dashboard', status: 'FAIL', error: e.message }); }
        
        try {
            const r = this.generateProductionReport('daily');
            if (r.period && r.summary) { results.passed++; results.tests.push({ name: 'Production Report', status: 'PASS' }); }
            else throw new Error('Invalid report');
        } catch (e) { results.failed++; results.tests.push({ name: 'Production Report', status: 'FAIL', error: e.message }); }
        
        try {
            const r = this.generateQualityReport();
            if (r.summary && r.paretoAnalysis) { results.passed++; results.tests.push({ name: 'Quality Report', status: 'PASS' }); }
            else throw new Error('Invalid report');
        } catch (e) { results.failed++; results.tests.push({ name: 'Quality Report', status: 'FAIL', error: e.message }); }
        
        try {
            const r = this.generateFinancialSummary();
            if (r.revenue && r.quoting) { results.passed++; results.tests.push({ name: 'Financial Summary', status: 'PASS' }); }
            else throw new Error('Invalid report');
        } catch (e) { results.failed++; results.tests.push({ name: 'Financial Summary', status: 'FAIL', error: e.message }); }
        
        console.log('[REPORTING_ENGINE] Tests: ' + results.passed + '/' + (results.passed + results.failed) + ' passed');
        return results;
    }
};

if (typeof PRISM_GATEWAY !== 'undefined') {
    PRISM_GATEWAY.register('report.dashboard', 'PRISM_REPORTING_ENGINE.generateDashboard');
    PRISM_GATEWAY.register('report.production', 'PRISM_REPORTING_ENGINE.generateProductionReport');
    PRISM_GATEWAY.register('report.quality', 'PRISM_REPORTING_ENGINE.generateQualityReport');
    PRISM_GATEWAY.register('report.financial', 'PRISM_REPORTING_ENGINE.generateFinancialSummary');
    PRISM_GATEWAY.register('report.custom', 'PRISM_REPORTING_ENGINE.generateCustomReport');
    PRISM_GATEWAY.register('report.export', 'PRISM_REPORTING_ENGINE.exportReport');
}

