// SECTION 1: UNCONSTRAINED OPTIMIZATION
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_UNCONSTRAINED_OPTIMIZATION = {
    name: 'PRISM_UNCONSTRAINED_OPTIMIZATION',
    version: '1.0.0',
    source: 'MIT 6.251J - Mathematical Programming',
    
    // Linear Algebra Helpers
    _dot: function(a, b) {
        return a.reduce((sum, ai, i) => sum + ai * (b[i] || 0), 0);
    },
    
    _norm: function(v) {
        return Math.sqrt(v.reduce((sum, vi) => sum + vi * vi, 0));
    },
    
    _scale: function(v, s) {
        return v.map(vi => vi * s);
    },
    
    _add: function(a, b) {
        return a.map((ai, i) => ai + (b[i] || 0));
    },
    
    _sub: function(a, b) {
        return a.map((ai, i) => ai - (b[i] || 0));
    },
    
    _outerProduct: function(a, b) {
        return a.map(ai => b.map(bj => ai * bj));
    },
    
    _matVec: function(A, x) {
        return A.map(row => this._dot(row, x));
    },
    
    /**
     * L-BFGS (Limited-memory BFGS)
     * Memory-efficient quasi-Newton for large-scale problems
     * Source: MIT 6.251J - Optimization Methods
     */
    lbfgs: function(config) {
        const {
            f,              // Objective function
            gradient,       // Gradient function
            x0,             // Initial point
            m = 10,         // Memory size (number of corrections to store)
            maxIter = 1000,
            tol = 1e-8,
            c1 = 1e-4,      // Armijo condition parameter
            c2 = 0.9        // Wolfe condition parameter
        } = config;
        
        const n = x0.length;
        let x = [...x0];
        let g = gradient(x);
        
        // Storage for limited memory
        const s_list = [];  // s_k = x_{k+1} - x_k
        const y_list = [];  // y_k = g_{k+1} - g_k
        const rho_list = []; // rho_k = 1 / (y_k' s_k)
        
        const history = [{ x: [...x], f: f(x), gradNorm: this._norm(g) }];
        
        for (let iter = 0; iter < maxIter; iter++) {
            const gradNorm = this._norm(g);
            
            if (gradNorm < tol) {
                return {
                    x,
                    f: f(x),
                    converged: true,
                    iterations: iter,
                    history,
                    method: 'L-BFGS'
                };
            }
            
            // Two-loop recursion to compute search direction
            const d = this._lbfgsTwoLoop(g, s_list, y_list, rho_list);
            
            // Line search with Wolfe conditions
            const { alpha, x_new, g_new } = this._wolfeLineSearch(f, gradient, x, d, g, c1, c2);
            
            if (alpha === 0) {
                return { x, f: f(x), converged: false, iterations: iter, reason: 'Line search failed', history };
            }
            
            // Update storage
            const s = this._sub(x_new, x);
            const y = this._sub(g_new, g);
            const ys = this._dot(y, s);
            
            if (ys > 1e-10) {  // Curvature condition
                if (s_list.length >= m) {
                    s_list.shift();
                    y_list.shift();
                    rho_list.shift();
                }
                s_list.push(s);
                y_list.push(y);
                rho_list.push(1 / ys);
            }
            
            x = x_new;
            g = g_new;
            history.push({ x: [...x], f: f(x), gradNorm: this._norm(g), alpha });
        }
        
        return { x, f: f(x), converged: false, iterations: maxIter, history, method: 'L-BFGS' };
    },
    
    _lbfgsTwoLoop: function(g, s_list, y_list, rho_list) {
        const m = s_list.length;
        let q = [...g];
        const alpha = [];
        
        // First loop (backward)
        for (let i = m - 1; i >= 0; i--) {
            alpha[i] = rho_list[i] * this._dot(s_list[i], q);
            q = this._sub(q, this._scale(y_list[i], alpha[i]));
        }
        
        // Initial Hessian approximation (scaled identity)
        let gamma = 1;
        if (m > 0) {
            gamma = this._dot(s_list[m-1], y_list[m-1]) / this._dot(y_list[m-1], y_list[m-1]);
        }
        let r = this._scale(q, gamma);
        
        // Second loop (forward)
        for (let i = 0; i < m; i++) {
            const beta = rho_list[i] * this._dot(y_list[i], r);
            r = this._add(r, this._scale(s_list[i], alpha[i] - beta));
        }
        
        // Negate for descent direction
        return this._scale(r, -1);
    },
    
    _wolfeLineSearch: function(f, gradient, x, d, g, c1, c2, maxIter = 20) {
        let alpha = 1;
        const fx = f(x);
        const gd = this._dot(g, d);
        
        for (let i = 0; i < maxIter; i++) {
            const x_new = this._add(x, this._scale(d, alpha));
            const fx_new = f(x_new);
            
            // Armijo condition
            if (fx_new > fx + c1 * alpha * gd) {
                alpha *= 0.5;
                continue;
            }
            
            const g_new = gradient(x_new);
            
            // Curvature condition (weak Wolfe)
            if (this._dot(g_new, d) < c2 * gd) {
                alpha *= 2;
                if (alpha > 100) break;
                continue;
            }
            
            return { alpha, x_new, g_new };
        }
        
        // Return best found
        const x_new = this._add(x, this._scale(d, alpha));
        return { alpha, x_new, g_new: gradient(x_new) };
    },
    
    /**
     * Trust Region Method (Dogleg)
     * Source: MIT 6.251J - Nonlinear Optimization
     */
    trustRegion: function(config) {
        const {
            f,              // Objective function
            gradient,       // Gradient function
            hessian,        // Hessian function
            x0,
            initialRadius = 1.0,
            maxRadius = 10.0,
            eta = 0.1,      // Acceptance threshold
            maxIter = 100,
            tol = 1e-8
        } = config;
        
        let x = [...x0];
        let radius = initialRadius;
        const history = [{ x: [...x], f: f(x), radius }];
        
        for (let iter = 0; iter < maxIter; iter++) {
            const g = gradient(x);
            const gradNorm = this._norm(g);
            
            if (gradNorm < tol) {
                return { x, f: f(x), converged: true, iterations: iter, history, method: 'Trust Region' };
            }
            
            const H = hessian(x);
            const fx = f(x);
            
            // Compute dogleg step
            const p = this._doglegStep(g, H, radius);
            const x_new = this._add(x, p);
            const fx_new = f(x_new);
            
            // Compute actual vs predicted reduction
            const actualReduction = fx - fx_new;
            const predictedReduction = -(this._dot(g, p) + 0.5 * this._dot(p, this._matVec(H, p)));
            const rho = predictedReduction > 0 ? actualReduction / predictedReduction : 0;
            
            // Update trust region radius
            if (rho < 0.25) {
                radius *= 0.25;
            } else if (rho > 0.75 && Math.abs(this._norm(p) - radius) < 1e-10) {
                radius = Math.min(2 * radius, maxRadius);
            }
            
            // Accept or reject step
            if (rho > eta) {
                x = x_new;
            }
            
            history.push({ x: [...x], f: f(x), radius, rho, stepNorm: this._norm(p) });
        }
        
        return { x, f: f(x), converged: false, iterations: maxIter, history, method: 'Trust Region' };
    },
    
    _doglegStep: function(g, H, radius) {
        const n = g.length;
        
        // Compute Cauchy point (steepest descent direction)
        const gHg = this._dot(g, this._matVec(H, g));
        let tau_c = gHg > 0 ? this._norm(g) ** 2 / gHg : 1;
        const p_c = this._scale(g, -tau_c);
        
        // If Cauchy point outside trust region, return scaled Cauchy
        const p_c_norm = this._norm(p_c);
        if (p_c_norm >= radius) {
            return this._scale(g, -radius / this._norm(g));
        }
        
        // Compute Newton point
        const p_n = this._solveLinear(H, this._scale(g, -1));
        const p_n_norm = this._norm(p_n);
        
        // If Newton point inside trust region, return Newton
        if (p_n_norm <= radius) {
            return p_n;
        }
        
        // Dogleg: interpolate between Cauchy and Newton
        const d = this._sub(p_n, p_c);
        const a = this._dot(d, d);
        const b = 2 * this._dot(p_c, d);
        const c = this._dot(p_c, p_c) - radius * radius;
        const discriminant = b * b - 4 * a * c;
        const tau = (-b + Math.sqrt(Math.max(0, discriminant))) / (2 * a);
        
        return this._add(p_c, this._scale(d, Math.min(1, Math.max(0, tau))));
    },
    
    _solveLinear: function(A, b) {
        const n = b.length;
        const aug = A.map((row, i) => [...row, b[i]]);
        
        // Gaussian elimination with partial pivoting
        for (let i = 0; i < n; i++) {
            let maxRow = i;
            for (let k = i + 1; k < n; k++) {
                if (Math.abs(aug[k][i]) > Math.abs(aug[maxRow][i])) maxRow = k;
            }
            [aug[i], aug[maxRow]] = [aug[maxRow], aug[i]];
            
            if (Math.abs(aug[i][i]) < 1e-12) continue;
            
            for (let k = i + 1; k < n; k++) {
                const factor = aug[k][i] / aug[i][i];
                for (let j = i; j <= n; j++) {
                    aug[k][j] -= factor * aug[i][j];
                }
            }
        }
        
        // Back substitution
        const x = new Array(n).fill(0);
        for (let i = n - 1; i >= 0; i--) {
            x[i] = aug[i][n];
            for (let j = i + 1; j < n; j++) {
                x[i] -= aug[i][j] * x[j];
            }
            x[i] /= aug[i][i] || 1;
        }
        
        return x;
    },
    
    /**
     * Conjugate Gradient (Polak-Ribière variant)
     * Source: MIT 6.251J
     */
    conjugateGradient: function(config) {
        const {
            f,
            gradient,
            x0,
            maxIter = 1000,
            tol = 1e-8,
            restartInterval = null  // Restart every n iterations (null = n)
        } = config;
        
        const n = x0.length;
        const restart = restartInterval || n;
        
        let x = [...x0];
        let g = gradient(x);
        let d = this._scale(g, -1);  // Initial direction = -gradient
        
        const history = [{ x: [...x], f: f(x), gradNorm: this._norm(g) }];
        
        for (let iter = 0; iter < maxIter; iter++) {
            const gradNorm = this._norm(g);
            
            if (gradNorm < tol) {
                return { x, f: f(x), converged: true, iterations: iter, history, method: 'Conjugate Gradient' };
            }
            
            // Line search
            const alpha = this._backtrackingLineSearch(f, gradient, x, d, g);
            const x_new = this._add(x, this._scale(d, alpha));
            const g_new = gradient(x_new);
            
            // Polak-Ribière beta
            const g_diff = this._sub(g_new, g);
            let beta = this._dot(g_new, g_diff) / this._dot(g, g);
            beta = Math.max(0, beta);  // Reset to steepest descent if beta < 0
            
            // Restart periodically
            if ((iter + 1) % restart === 0) {
                beta = 0;
            }
            
            // Update direction
            d = this._add(this._scale(g_new, -1), this._scale(d, beta));
            
            x = x_new;
            g = g_new;
            history.push({ x: [...x], f: f(x), gradNorm: this._norm(g), alpha, beta });
        }
        
        return { x, f: f(x), converged: false, iterations: maxIter, history, method: 'Conjugate Gradient' };
    },
    
    _backtrackingLineSearch: function(f, gradient, x, d, g, c1 = 1e-4, rho = 0.5) {
        let alpha = 1;
        const fx = f(x);
        const gd = this._dot(g, d);
        
        for (let i = 0; i < 50; i++) {
            const x_new = this._add(x, this._scale(d, alpha));
            if (f(x_new) <= fx + c1 * alpha * gd) {
                return alpha;
            }
            alpha *= rho;
        }
        
        return alpha;
    }
};

// ═══════════════════════════════════════════════════════════════════════════════
// SECTION 2: CONSTRAINED OPTIMIZATION
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_CONSTRAINED_OPTIMIZATION_ENHANCED = {
    name: 'PRISM_CONSTRAINED_OPTIMIZATION_ENHANCED',
    version: '1.0.0',
    source: 'MIT 15.084j - Nonlinear Programming',
    
    /**
     * Augmented Lagrangian Method
     * Handles both equality and inequality constraints
     * Source: MIT 15.084j Lecture 13
     */
    augmentedLagrangian: function(config) {
        const {
            f,                    // Objective function
            gradient,             // Gradient of f
            equalityConstraints = [],  // h_i(x) = 0
            inequalityConstraints = [], // g_j(x) <= 0
            x0,
            rho0 = 1,             // Initial penalty parameter
            rhoMax = 1e6,
            rhoGrowth = 2,
            maxOuterIter = 50,
            maxInnerIter = 100,
            tol = 1e-6
        } = config;
        
        const nEq = equalityConstraints.length;
        const nIneq = inequalityConstraints.length;
        
        let x = [...x0];
        let lambda = new Array(nEq).fill(0);    // Equality multipliers
        let mu = new Array(nIneq).fill(0);      // Inequality multipliers
        let rho = rho0;
        
        const history = [];
        
        for (let outer = 0; outer < maxOuterIter; outer++) {
            // Define augmented Lagrangian
            const L_aug = (x) => {
                let val = f(x);
                
                // Equality constraints: L += lambda'h + (rho/2)||h||^2
                for (let i = 0; i < nEq; i++) {
                    const h = equalityConstraints[i](x);
                    val += lambda[i] * h + (rho / 2) * h * h;
                }
                
                // Inequality constraints with slack
                for (let j = 0; j < nIneq; j++) {
                    const g = inequalityConstraints[j](x);
                    const muRho = mu[j] + rho * g;
                    if (muRho > 0) {
                        val += muRho * muRho / (2 * rho) - mu[j] * mu[j] / (2 * rho);
                    }
                }
                
                return val;
            };
            
            // Gradient of augmented Lagrangian
            const gradL = (x) => {
                const grad = gradient(x);
                const eps = 1e-8;
                
                for (let i = 0; i < nEq; i++) {
                    const h = equalityConstraints[i](x);
                    // Numerical gradient of h
                    for (let k = 0; k < x.length; k++) {
                        const x_plus = [...x]; x_plus[k] += eps;
                        const x_minus = [...x]; x_minus[k] -= eps;
                        const dh = (equalityConstraints[i](x_plus) - equalityConstraints[i](x_minus)) / (2 * eps);
                        grad[k] += (lambda[i] + rho * h) * dh;
                    }
                }
                
                for (let j = 0; j < nIneq; j++) {
                    const g = inequalityConstraints[j](x);
                    const muRho = mu[j] + rho * g;
                    if (muRho > 0) {
                        for (let k = 0; k < x.length; k++) {
                            const x_plus = [...x]; x_plus[k] += eps;
                            const x_minus = [...x]; x_minus[k] -= eps;
                            const dg = (inequalityConstraints[j](x_plus) - inequalityConstraints[j](x_minus)) / (2 * eps);
                            grad[k] += muRho * dg;
                        }
                    }
                }
                
                return grad;
            };
            
            // Minimize augmented Lagrangian using L-BFGS
            const result = PRISM_UNCONSTRAINED_OPTIMIZATION.lbfgs({
                f: L_aug,
                gradient: gradL,
                x0: x,
                maxIter: maxInnerIter,
                tol: tol / 10
            });
            
            x = result.x;
            
            // Compute constraint violations
            let maxViolation = 0;
            const hVals = equalityConstraints.map(h => h(x));
            const gVals = inequalityConstraints.map(g => g(x));
            
            for (const h of hVals) maxViolation = Math.max(maxViolation, Math.abs(h));
            for (const g of gVals) maxViolation = Math.max(maxViolation, Math.max(0, g));
            
            history.push({
                outer,
                x: [...x],
                f: f(x),
                maxViolation,
                rho,
                lambda: [...lambda],
                mu: [...mu]
            });
            
            // Check convergence
            if (maxViolation < tol) {
                return {
                    x,
                    f: f(x),
                    converged: true,
                    outerIterations: outer + 1,
                    lambda,
                    mu,
                    history,
                    method: 'Augmented Lagrangian'
                };
            }
            
            // Update multipliers
            for (let i = 0; i < nEq; i++) {
                lambda[i] += rho * hVals[i];
            }
            for (let j = 0; j < nIneq; j++) {
                mu[j] = Math.max(0, mu[j] + rho * gVals[j]);
            }
            
            // Increase penalty
            rho = Math.min(rhoMax, rho * rhoGrowth);
        }
        
        return {
            x,
            f: f(x),
            converged: false,
            outerIterations: maxOuterIter,
            lambda,
            mu,
            history,
            method: 'Augmented Lagrangian'
        };
    },
    
    /**
     * Sequential Quadratic Programming (SQP)
     * State-of-the-art for nonlinear constrained optimization
     * Source: MIT 15.084j Lecture 14
     */
    sqp: function(config) {
        const {
            f,
            gradient,
            hessianApprox = 'bfgs',  // 'bfgs' or function
            equalityConstraints = [],
            inequalityConstraints = [],
            x0,
            maxIter = 100,
            tol = 1e-6
        } = config;
        
        const n = x0.length;
        let x = [...x0];
        let B = Array.from({ length: n }, (_, i) => 
            Array.from({ length: n }, (_, j) => i === j ? 1 : 0)
        ); // Initial Hessian approx = I
        
        const history = [];
        
        for (let iter = 0; iter < maxIter; iter++) {
            const fx = f(x);
            const gf = gradient(x);
            
            // Evaluate constraints
            const h = equalityConstraints.map(c => c(x));
            const g = inequalityConstraints.map(c => c(x));
            
            // Compute constraint Jacobians (numerically)
            const Ah = this._computeJacobian(equalityConstraints, x);
            const Ag = this._computeJacobian(inequalityConstraints, x);
            
            // Solve QP subproblem: min 0.5*p'Bp + gf'p s.t. Ah*p + h = 0, Ag*p + g <= 0
            const qpResult = this._solveQPSubproblem(B, gf, Ah, h, Ag, g);
            
            if (!qpResult.feasible) {
                return { x, f: fx, converged: false, reason: 'QP infeasible', iterations: iter, history };
            }
            
            const p = qpResult.p;
            const lambda_new = qpResult.lambda;
            const mu_new = qpResult.mu;
            
            // Check convergence (KKT conditions)
            const stepNorm = Math.sqrt(p.reduce((s, pi) => s + pi * pi, 0));
            if (stepNorm < tol) {
                return {
                    x,
                    f: fx,
                    converged: true,
                    iterations: iter,
                    lambda: lambda_new,
                    mu: mu_new,
                    history,
                    method: 'SQP'
                };
            }
            
            // Line search with merit function
            const alpha = this._sqpLineSearch(f, equalityConstraints, inequalityConstraints, x, p, mu_new);
            
            const x_new = x.map((xi, i) => xi + alpha * p[i]);
            const gf_new = gradient(x_new);
            
            // BFGS update for Hessian approximation
            const s = p.map(pi => alpha * pi);
            const y = this._computeLagrangianGradientDiff(gf, gf_new, lambda_new, mu_new, 
                equalityConstraints, inequalityConstraints, x, x_new);
            
            B = this._bfgsUpdate(B, s, y);
            
            history.push({
                iter,
                x: [...x],
                f: fx,
                stepNorm,
                alpha
            });
            
            x = x_new;
        }
        
        return { x, f: f(x), converged: false, iterations: maxIter, history, method: 'SQP' };
    },
    
    _computeJacobian: function(constraints, x, eps = 1e-8) {
        if (constraints.length === 0) return [];
        
        const m = constraints.length;
        const n = x.length;
        const J = [];
        
        for (let i = 0; i < m; i++) {
            const row = [];
            for (let j = 0; j < n; j++) {
                const x_plus = [...x]; x_plus[j] += eps;
                const x_minus = [...x]; x_minus[j] -= eps;
                row.push((constraints[i](x_plus) - constraints[i](x_minus)) / (2 * eps));
            }
            J.push(row);
        }
        
        return J;
    },
    
    _solveQPSubproblem: function(H, c, Aeq, beq, Aineq, bineq) {
        // Simplified QP solver using active set method
        const n = c.length;
        let p = new Array(n).fill(0);
        
        // If no constraints, solve unconstrained: p = -H^(-1) * c
        if (Aeq.length === 0 && Aineq.length === 0) {
            p = PRISM_UNCONSTRAINED_OPTIMIZATION._solveLinear(H, c.map(ci => -ci));
            return { feasible: true, p, lambda: [], mu: [] };
        }
        
        // Simple active set approach
        const activeSet = new Set();
        const maxIter = 100;
        
        for (let iter = 0; iter < maxIter; iter++) {
            // Solve equality-constrained QP with active inequalities
            const activeAineq = [...activeSet].map(i => Aineq[i]);
            const activeBineq = [...activeSet].map(i => bineq[i]);
            
            const { solution, lambdaEq, lambdaIneq } = this._solveEqualityQP(
                H, c, Aeq, beq.map(b => -b), activeAineq, activeBineq.map(b => -b)
            );
            
            // Check inactive constraints
            let violated = -1;
            let maxViolation = 0;
            
            for (let i = 0; i < Aineq.length; i++) {
                if (!activeSet.has(i)) {
                    const violation = Aineq[i].reduce((s, aij, j) => s + aij * solution[j], 0) + bineq[i];
                    if (violation > maxViolation + 1e-10) {
                        maxViolation = violation;
                        violated = i;
                    }
                }
            }
            
            if (violated >= 0) {
                activeSet.add(violated);
                continue;
            }
            
            // Check for negative multipliers
            let dropConstraint = -1;
            let minMultiplier = 0;
            
            const activeList = [...activeSet];
            for (let i = 0; i < lambdaIneq.length; i++) {
                if (lambdaIneq[i] < minMultiplier - 1e-10) {
                    minMultiplier = lambdaIneq[i];
                    dropConstraint = activeList[i];
                }
            }
            
            if (dropConstraint >= 0) {
                activeSet.delete(dropConstraint);
                continue;
            }
            
            return {
                feasible: true,
                p: solution,
                lambda: lambdaEq,
                mu: lambdaIneq
            };
        }
        
        return { feasible: false, p, lambda: [], mu: [] };
    },
    
    _solveEqualityQP: function(H, c, Aeq, beq, Aactive, bactive) {
        const n = c.length;
        const mEq = Aeq.length;
        const mActive = Aactive.length;
        const m = mEq + mActive;
        
        if (m === 0) {
            const solution = PRISM_UNCONSTRAINED_OPTIMIZATION._solveLinear(H, c.map(ci => -ci));
            return { solution, lambdaEq: [], lambdaIneq: [] };
        }
        
        // Build KKT system
        const size = n + m;
        const KKT = Array.from({ length: size }, () => new Array(size).fill(0));
        const rhs = new Array(size).fill(0);
        
        // H block
        for (let i = 0; i < n; i++) {
            for (let j = 0; j < n; j++) {
                KKT[i][j] = H[i][j];
            }
            rhs[i] = -c[i];
        }
        
        // Constraint blocks
        for (let i = 0; i < mEq; i++) {
            for (let j = 0; j < n; j++) {
                KKT[i + n][j] = Aeq[i][j];
                KKT[j][i + n] = Aeq[i][j];
            }
            rhs[i + n] = beq[i];
        }
        
        for (let i = 0; i < mActive; i++) {
            for (let j = 0; j < n; j++) {
                KKT[i + n + mEq][j] = Aactive[i][j];
                KKT[j][i + n + mEq] = Aactive[i][j];
            }
            rhs[i + n + mEq] = bactive[i];
        }
        
        const sol = PRISM_UNCONSTRAINED_OPTIMIZATION._solveLinear(KKT, rhs);
        
        return {
            solution: sol.slice(0, n),
            lambdaEq: sol.slice(n, n + mEq),
            lambdaIneq: sol.slice(n + mEq)
        };
    },
    
    _sqpLineSearch: function(f, eqCons, ineqCons, x, p, mu, rho = 1) {
        // Simple backtracking with L1 merit function
        let alpha = 1;
        const fx = f(x);
        
        const meritFunc = (x) => {
            let val = f(x);
            for (const h of eqCons) val += rho * Math.abs(h(x));
            for (const g of ineqCons) val += rho * Math.max(0, g(x));
            return val;
        };
        
        const merit0 = meritFunc(x);
        
        for (let i = 0; i < 20; i++) {
            const x_new = x.map((xi, j) => xi + alpha * p[j]);
            if (meritFunc(x_new) < merit0 - 0.0001 * alpha * Math.abs(merit0)) {
                return alpha;
            }
            alpha *= 0.5;
        }
        
        return alpha;
    },
    
    _computeLagrangianGradientDiff: function(gf, gf_new, lambda, mu, eqCons, ineqCons, x, x_new) {
        // Simplified: just use objective gradient difference
        return gf_new.map((gi, i) => gi - gf[i]);
    },
    
    _bfgsUpdate: function(B, s, y) {
        const n = s.length;
        const ys = PRISM_UNCONSTRAINED_OPTIMIZATION._dot(y, s);
        
        if (ys < 1e-10) return B; // Skip update if curvature condition not satisfied
        
        const Bs = PRISM_UNCONSTRAINED_OPTIMIZATION._matVec(B, s);
        const sBs = PRISM_UNCONSTRAINED_OPTIMIZATION._dot(s, Bs);
        
        const B_new = B.map((row, i) => row.map((bij, j) => {
            return bij - Bs[i] * Bs[j] / sBs + y[i] * y[j] / ys;
        }));
        
        return B_new;
    }
};

// ═══════════════════════════════════════════════════════════════════════════════
// SECTION 3: METAHEURISTIC OPTIMIZATION
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_METAHEURISTIC_OPTIMIZATION = {
    name: 'PRISM_METAHEURISTIC_OPTIMIZATION',
    version: '1.0.0',
    source: 'MIT 15.099 - Optimization Methods',
    
    /**
     * Tabu Search
     * Deterministic local search with memory
     * Source: MIT 15.099
     */
    tabuSearch: function(config) {
        const {
            initialSolution,
            costFunction,
            neighborhoodFunction,
            tabuTenure = 7,          // How long moves stay tabu
            maxIterations = 1000,
            maxNoImprove = 100,       // Stop if no improvement for this many iterations
            aspirationCriteria = true // Allow tabu moves that improve best
        } = config;
        
        let current = JSON.parse(JSON.stringify(initialSolution));
        let currentCost = costFunction(current);
        let best = JSON.parse(JSON.stringify(current));
        let bestCost = currentCost;
        
        const tabuList = new Map();  // move -> iteration when it becomes non-tabu
        const history = [{ iteration: 0, cost: currentCost, bestCost }];
        
        let noImproveCount = 0;
        
        for (let iter = 1; iter <= maxIterations; iter++) {
            const neighbors = neighborhoodFunction(current);
            
            if (neighbors.length === 0) break;
            
            // Find best non-tabu neighbor (or best tabu if aspiration)
            let bestNeighbor = null;
            let bestNeighborCost = Infinity;
            let bestMove = null;
            
            for (const { solution, move } of neighbors) {
                const cost = costFunction(solution);
                const moveKey = JSON.stringify(move);
                const isTabu = tabuList.has(moveKey) && tabuList.get(moveKey) > iter;
                
                // Aspiration: allow tabu if it improves global best
                const canUse = !isTabu || (aspirationCriteria && cost < bestCost);
                
                if (canUse && cost < bestNeighborCost) {
                    bestNeighborCost = cost;
                    bestNeighbor = solution;
                    bestMove = move;
                }
            }
            
            if (bestNeighbor === null) break;
            
            // Make the move
            current = JSON.parse(JSON.stringify(bestNeighbor));
            currentCost = bestNeighborCost;
            
            // Add to tabu list
            if (bestMove) {
                tabuList.set(JSON.stringify(bestMove), iter + tabuTenure);
                // Also add reverse move if applicable
                if (bestMove.reverse) {
                    tabuList.set(JSON.stringify(bestMove.reverse), iter + tabuTenure);
                }
            }
            
            // Update best
            if (currentCost < bestCost) {
                best = JSON.parse(JSON.stringify(current));
                bestCost = currentCost;
                noImproveCount = 0;
            } else {
                noImproveCount++;
            }
            
            // Clean old tabu entries
            if (iter % 50 === 0) {
                for (const [key, expiry] of tabuList) {
                    if (expiry <= iter) tabuList.delete(key);
                }
            }
            
            history.push({ iteration: iter, cost: currentCost, bestCost });
            
            // Early termination
            if (noImproveCount >= maxNoImprove) break;
        }
        
        return {
            solution: best,
            cost: bestCost,
            iterations: history.length - 1,
            history,
            method: 'Tabu Search'
        };
    }
};

// ═══════════════════════════════════════════════════════════════════════════════
// SECTION 4: MULTI-OBJECTIVE OPTIMIZATION
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_MULTI_OBJECTIVE = {
    name: 'PRISM_MULTI_OBJECTIVE',
    version: '1.0.0',
    source: 'MIT 15.099 - Multi-Objective Optimization',
    
    /**
     * NSGA-II (Non-dominated Sorting Genetic Algorithm II)
     * State-of-the-art multi-objective evolutionary algorithm
     * Source: MIT 15.099
     */
    nsgaII: function(config) {
        const {
            objectives,           // Array of objective functions (all minimization)
            bounds,               // [{min, max}, ...] for each variable
            populationSize = 100,
            maxGenerations = 200,
            crossoverProb = 0.9,
            mutationProb = 0.1
        } = config;
        
        const n = bounds.length;
        const numObjectives = objectives.length;
        
        // Initialize population
        let population = [];
        for (let i = 0; i < populationSize; i++) {
            const individual = bounds.map(b => b.min + Math.random() * (b.max - b.min));
            const fitness = objectives.map(f => f(individual));
            population.push({ x: individual, fitness, rank: 0, crowdingDistance: 0 });
        }
        
        const history = [];
        
        for (let gen = 0; gen < maxGenerations; gen++) {
            // Create offspring
            const offspring = [];
            while (offspring.length < populationSize) {
                // Tournament selection
                const parent1 = this._tournamentSelect(population);
                const parent2 = this._tournamentSelect(population);
                
                // Crossover
                let child1, child2;
                if (Math.random() < crossoverProb) {
                    [child1, child2] = this._sbxCrossover(parent1.x, parent2.x, bounds);
                } else {
                    child1 = [...parent1.x];
                    child2 = [...parent2.x];
                }
                
                // Mutation
                if (Math.random() < mutationProb) {
                    this._polynomialMutation(child1, bounds);
                }
                if (Math.random() < mutationProb) {
                    this._polynomialMutation(child2, bounds);
                }
                
                offspring.push({
                    x: child1,
                    fitness: objectives.map(f => f(child1)),
                    rank: 0,
                    crowdingDistance: 0
                });
                if (offspring.length < populationSize) {
                    offspring.push({
                        x: child2,
                        fitness: objectives.map(f => f(child2)),
                        rank: 0,
                        crowdingDistance: 0
                    });
                }
            }
            
            // Combine parent and offspring
            const combined = [...population, ...offspring];
            
            // Non-dominated sorting
            const fronts = this._nonDominatedSort(combined);
            
            // Select next generation
            population = [];
            let frontIndex = 0;
            
            while (population.length + fronts[frontIndex].length <= populationSize) {
                // Calculate crowding distance
                this._assignCrowdingDistance(fronts[frontIndex], numObjectives);
                
                for (const ind of fronts[frontIndex]) {
                    population.push(ind);
                }
                frontIndex++;
                
                if (frontIndex >= fronts.length) break;
            }
            
            // Fill remaining with crowding distance selection
            if (population.length < populationSize && frontIndex < fronts.length) {
                this._assignCrowdingDistance(fronts[frontIndex], numObjectives);
                fronts[frontIndex].sort((a, b) => b.crowdingDistance - a.crowdingDistance);
                
                while (population.length < populationSize) {
                    population.push(fronts[frontIndex].shift());
                }
            }
            
            // Record history
            const paretoFront = fronts[0].map(ind => ({
                x: [...ind.x],
                fitness: [...ind.fitness]
            }));
            history.push({ generation: gen, paretoFrontSize: paretoFront.length, paretoFront });
        }
        
        // Return final Pareto front
        const finalFronts = this._nonDominatedSort(population);
        const paretoFront = finalFronts[0].map(ind => ({
            x: [...ind.x],
            objectives: [...ind.fitness]
        }));
        
        return {
            paretoFront,
            generations: maxGenerations,
            history,
            method: 'NSGA-II'
        };
    },
    
    _tournamentSelect: function(population, tournamentSize = 2) {
        const candidates = [];
        for (let i = 0; i < tournamentSize; i++) {
            candidates.push(population[Math.floor(Math.random() * population.length)]);
        }
        
        candidates.sort((a, b) => {
            if (a.rank !== b.rank) return a.rank - b.rank;
            return b.crowdingDistance - a.crowdingDistance;
        });
        
        return candidates[0];
    },
    
    _sbxCrossover: function(parent1, parent2, bounds, eta = 20) {
        const n = parent1.length;
        const child1 = [];
        const child2 = [];
        
        for (let i = 0; i < n; i++) {
            if (Math.random() < 0.5) {
                // SBX
                const u = Math.random();
                const beta = u <= 0.5
                    ? Math.pow(2 * u, 1 / (eta + 1))
                    : Math.pow(1 / (2 * (1 - u)), 1 / (eta + 1));
                
                child1[i] = 0.5 * ((1 + beta) * parent1[i] + (1 - beta) * parent2[i]);
                child2[i] = 0.5 * ((1 - beta) * parent1[i] + (1 + beta) * parent2[i]);
            } else {
                child1[i] = parent1[i];
                child2[i] = parent2[i];
            }
            
            // Clip to bounds
            child1[i] = Math.max(bounds[i].min, Math.min(bounds[i].max, child1[i]));
            child2[i] = Math.max(bounds[i].min, Math.min(bounds[i].max, child2[i]));
        }
        
        return [child1, child2];
    },
    
    _polynomialMutation: function(x, bounds, eta = 20) {
        for (let i = 0; i < x.length; i++) {
            if (Math.random() < 1 / x.length) {
                const u = Math.random();
                const delta = u < 0.5
                    ? Math.pow(2 * u, 1 / (eta + 1)) - 1
                    : 1 - Math.pow(2 * (1 - u), 1 / (eta + 1));
                
                x[i] += delta * (bounds[i].max - bounds[i].min);
                x[i] = Math.max(bounds[i].min, Math.min(bounds[i].max, x[i]));
            }
        }
    },
    
    _nonDominatedSort: function(population) {
        const n = population.length;
        const S = new Array(n).fill(null).map(() => []);
        const dominationCount = new Array(n).fill(0);
        const fronts = [[]];
        
        for (let i = 0; i < n; i++) {
            for (let j = 0; j < n; j++) {
                if (i === j) continue;
                
                if (this._dominates(population[i], population[j])) {
                    S[i].push(j);
                } else if (this._dominates(population[j], population[i])) {
                    dominationCount[i]++;
                }
            }
            
            if (dominationCount[i] === 0) {
                population[i].rank = 0;
                fronts[0].push(population[i]);
            }
        }
        
        let frontIndex = 0;
        while (fronts[frontIndex].length > 0) {
            const nextFront = [];
            
            for (const p of fronts[frontIndex]) {
                const pIndex = population.indexOf(p);
                for (const qIndex of S[pIndex]) {
                    dominationCount[qIndex]--;
                    if (dominationCount[qIndex] === 0) {
                        population[qIndex].rank = frontIndex + 1;
                        nextFront.push(population[qIndex]);
                    }
                }
            }
            
            frontIndex++;
            fronts.push(nextFront);
        }
        
        return fronts.filter(f => f.length > 0);
    },
    
    _dominates: function(a, b) {
        let dominated = false;
        for (let i = 0; i < a.fitness.length; i++) {
            if (a.fitness[i] > b.fitness[i]) return false;
            if (a.fitness[i] < b.fitness[i]) dominated = true;
        }
        return dominated;
    },
    
    _assignCrowdingDistance: function(front, numObjectives) {
        const n = front.length;
        if (n === 0) return;
        
        for (const ind of front) {
            ind.crowdingDistance = 0;
        }
        
        for (let m = 0; m < numObjectives; m++) {
            front.sort((a, b) => a.fitness[m] - b.fitness[m]);
            
            front[0].crowdingDistance = Infinity;
            front[n - 1].crowdingDistance = Infinity;
            
            const fMin = front[0].fitness[m];
            const fMax = front[n - 1].fitness[m];
            const range = fMax - fMin || 1;
            
            for (let i = 1; i < n - 1; i++) {
                front[i].crowdingDistance += 
                    (front[i + 1].fitness[m] - front[i - 1].fitness[m]) / range;
            }
        }
    },
    
    /**
     * MOEA/D (Multi-objective Evolutionary Algorithm based on Decomposition)
     * Source: MIT 15.099
     */
    moead: function(config) {
        const {
            objectives,
            bounds,
            populationSize = 100,
            maxGenerations = 200,
            neighborhoodSize = 20,
            crossoverProb = 0.9
        } = config;
        
        const n = bounds.length;
        const numObjectives = objectives.length;
        
        // Generate uniformly distributed weight vectors
        const weights = this._generateWeightVectors(populationSize, numObjectives);
        
        // Initialize population
        const population = [];
        for (let i = 0; i < populationSize; i++) {
            const x = bounds.map(b => b.min + Math.random() * (b.max - b.min));
            population.push({
                x,
                fitness: objectives.map(f => f(x)),
                weight: weights[i]
            });
        }
        
        // Compute neighborhoods based on weight distance
        const neighborhoods = this._computeNeighborhoods(weights, neighborhoodSize);
        
        // Reference point (ideal point)
        let z = new Array(numObjectives).fill(Infinity);
        for (const ind of population) {
            for (let m = 0; m < numObjectives; m++) {
                z[m] = Math.min(z[m], ind.fitness[m]);
            }
        }
        
        const history = [];
        
        for (let gen = 0; gen < maxGenerations; gen++) {
            for (let i = 0; i < populationSize; i++) {
                // Select parents from neighborhood
                const neighborhood = neighborhoods[i];
                const p1Index = neighborhood[Math.floor(Math.random() * neighborhood.length)];
                const p2Index = neighborhood[Math.floor(Math.random() * neighborhood.length)];
                
                // Generate offspring
                let offspring;
                if (Math.random() < crossoverProb) {
                    [offspring] = this._sbxCrossover(
                        population[p1Index].x,
                        population[p2Index].x,
                        bounds
                    );
                } else {
                    offspring = [...population[i].x];
                }
                
                this._polynomialMutation(offspring, bounds);
                
                const offspringFitness = objectives.map(f => f(offspring));
                
                // Update reference point
                for (let m = 0; m < numObjectives; m++) {
                    z[m] = Math.min(z[m], offspringFitness[m]);
                }
                
                // Update neighbors
                for (const j of neighborhood) {
                    const tch_offspring = this._tchebycheff(offspringFitness, weights[j], z);
                    const tch_current = this._tchebycheff(population[j].fitness, weights[j], z);
                    
                    if (tch_offspring < tch_current) {
                        population[j].x = [...offspring];
                        population[j].fitness = [...offspringFitness];
                    }
                }
            }
            
            history.push({
                generation: gen,
                referencePoint: [...z]
            });
        }
        
        // Extract Pareto front
        const paretoFront = this._extractParetoFront(population);
        
        return {
            paretoFront: paretoFront.map(ind => ({
                x: [...ind.x],
                objectives: [...ind.fitness]
            })),
            referencePoint: z,
            generations: maxGenerations,
            history,
            method: 'MOEA/D'
        };
    },
    
    _generateWeightVectors: function(n, m) {
        if (m === 2) {
            return Array.from({ length: n }, (_, i) => [i / (n - 1), 1 - i / (n - 1)]);
        }
        
        // For m > 2, use simplex-lattice design
        const weights = [];
        const H = Math.round(Math.pow(n, 1 / (m - 1)));
        
        const generate = (current, remaining, depth) => {
            if (depth === m - 1) {
                weights.push([...current, remaining]);
                return;
            }
            
            for (let i = 0; i <= H; i++) {
                const w = i / H;
                if (w <= remaining + 1e-10) {
                    generate([...current, w], remaining - w, depth + 1);
                }
            }
        };
        
        generate([], 1, 0);
        return weights.slice(0, n);
    },
    
    _computeNeighborhoods: function(weights, size) {
        const n = weights.length;
        const neighborhoods = [];
        
        for (let i = 0; i < n; i++) {
            const distances = [];
            for (let j = 0; j < n; j++) {
                let dist = 0;
                for (let k = 0; k < weights[i].length; k++) {
                    dist += (weights[i][k] - weights[j][k]) ** 2;
                }
                distances.push({ index: j, dist });
            }
            
            distances.sort((a, b) => a.dist - b.dist);
            neighborhoods.push(distances.slice(0, size).map(d => d.index));
        }
        
        return neighborhoods;
    },
    
    _tchebycheff: function(fitness, weight, z) {
        let max = -Infinity;
        for (let i = 0; i < fitness.length; i++) {
            const val = weight[i] * Math.abs(fitness[i] - z[i]);
            if (val > max) max = val;
        }
        return max;
    },
    
    _extractParetoFront: function(population) {
        const front = [];
        
        for (const p of population) {
            let dominated = false;
            for (const q of population) {
                if (this._dominates(q, p)) {
                    dominated = true;
                    break;
                }
            }
            if (!dominated) {
                front.push(p);
            }
        }
        
        return front;
    },
    
    /**
     * Pareto Front Utilities
     */
    paretoUtils: {
        /**
         * Calculate hypervolume indicator
         */
        hypervolume: function(front, referencePoint) {
            // 2D hypervolume calculation
            if (front.length === 0) return 0;
            if (front[0].objectives.length !== 2) {
                console.warn('Hypervolume: Only 2D supported');
                return 0;
            }
            
            const sorted = [...front].sort((a, b) => a.objectives[0] - b.objectives[0]);
            let volume = 0;
            let prevY = referencePoint[1];
            
            for (const point of sorted) {
                const width = referencePoint[0] - point.objectives[0];
                const height = prevY - point.objectives[1];
                if (width > 0 && height > 0) {
                    volume += width * height;
                }
                prevY = Math.min(prevY, point.objectives[1]);
            }
            
            return volume;
        },
        
        /**
         * Find knee point (maximum distance from line connecting extremes)
         */
        findKneePoint: function(front) {
            if (front.length < 3) return front[0];
            
            const sorted = [...front].sort((a, b) => a.objectives[0] - b.objectives[0]);
            const first = sorted[0].objectives;
            const last = sorted[sorted.length - 1].objectives;
            
            let maxDist = -Infinity;
            let kneePoint = sorted[0];
            
            for (const point of sorted) {
                // Distance from point to line connecting first and last
                const x0 = point.objectives[0];
                const y0 = point.objectives[1];
                const x1 = first[0], y1 = first[1];
                const x2 = last[0], y2 = last[1];
                
                const dist = Math.abs((y2 - y1) * x0 - (x2 - x1) * y0 + x2 * y1 - y2 * x1) /
                    Math.sqrt((y2 - y1) ** 2 + (x2 - x1) ** 2);
                
                if (dist > maxDist) {
                    maxDist = dist;
                    kneePoint = point;
                }
            }
            
            return kneePoint;
        },
        
        /**
         * Select solution closest to ideal point
         */
        selectClosestToIdeal: function(front, idealPoint) {
            let minDist = Infinity;
            let closest = front[0];
            
            for (const point of front) {
                let dist = 0;
                for (let i = 0; i < idealPoint.length; i++) {
                    dist += (point.objectives[i] - idealPoint[i]) ** 2;
                }
                dist = Math.sqrt(dist);
                
                if (dist < minDist) {
                    minDist = dist;
                    closest = point;
                }
            }
            
            return closest;
        }
    }
};

// ═══════════════════════════════════════════════════════════════════════════════
// SECTION 5: MANUFACTURING OPTIMIZATION APPLICATIONS
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_MFG_OPTIMIZATION_ADVANCED = {
    name: 'PRISM_MFG_OPTIMIZATION_ADVANCED',
    version: '1.0.0',
    source: 'PRISM Innovation - Manufacturing Optimization',
    
    /**
     * Multi-objective cutting parameter optimization
     * Objectives: Minimize time, cost, surface roughness
     */
    optimizeCuttingParametersMO: function(config) {
        const {
            material,
            tool,
            machine,
            weights = { time: 0.4, cost: 0.3, quality: 0.3 }
        } = config;
        
        const speedBounds = { min: 50, max: machine.maxRPM || 5000 };
        const feedBounds = { min: 0.01, max: tool.maxFeed || 0.5 };
        const docBounds = { min: 0.1, max: tool.maxDOC || 5 };
        
        // Objective functions
        const objectives = [
            // Minimize cycle time (maximize MRR)
            (x) => {
                const [speed, feed, doc] = x;
                const mrr = speed * feed * doc;
                return 1000 / mrr; // Time inversely proportional to MRR
            },
            // Minimize cost (tool wear)
            (x) => {
                const [speed, feed, doc] = x;
                // Taylor tool life approximation
                const toolLife = Math.pow(100 / speed, 3) * 60;
                const wearRate = 1 / toolLife;
                return wearRate * 100;
            },
            // Minimize surface roughness
            (x) => {
                const [speed, feed, doc] = x;
                // Simplified Ra calculation
                const Ra = (feed * feed * 1000) / (8 * (tool.noseRadius || 0.8));
                return Ra;
            }
        ];
        
        const result = PRISM_MULTI_OBJECTIVE.nsgaII({
            objectives,
            bounds: [speedBounds, feedBounds, docBounds],
            populationSize: 50,
            maxGenerations: 100
        });
        
        // Find compromise solution using weighted sum
        const compromiseSolution = result.paretoFront.reduce((best, point) => {
            const score = weights.time * point.objectives[0] +
                         weights.cost * point.objectives[1] +
                         weights.quality * point.objectives[2];
            if (!best || score < best.score) {
                return { ...point, score };
            }
            return best;
        }, null);
        
        return {
            paretoFront: result.paretoFront,
            compromiseSolution: {
                speed: compromiseSolution.x[0],
                feed: compromiseSolution.x[1],
                doc: compromiseSolution.x[2],
                objectives: {
                    time: compromiseSolution.objectives[0],
                    cost: compromiseSolution.objectives[1],
                    surfaceRoughness: compromiseSolution.objectives[2]
                }
            },
            method: 'NSGA-II Multi-Objective'
        };
    },
    
    /**
     * Job shop scheduling using Tabu Search
     */
    scheduleJobShopTabu: function(config) {
        const {
            jobs,           // Array of jobs, each with operations
            machines,       // Array of machine capacities
            initialSchedule = null
        } = config;
        
        // Create initial schedule (greedy)
        let schedule = initialSchedule;
        if (!schedule) {
            schedule = this._createGreedySchedule(jobs, machines);
        }
        
        return PRISM_METAHEURISTIC_OPTIMIZATION.tabuSearch({
            initialSolution: schedule,
            costFunction: (s) => this._calculateMakespan(s),
            neighborhoodFunction: (s) => this._generateScheduleNeighbors(s, jobs, machines),
            tabuTenure: Math.max(5, Math.floor(jobs.length / 2)),
            maxIterations: 500,
            maxNoImprove: 50
        });
    },
    
    _createGreedySchedule: function(jobs, machines) {
        // Simple greedy: assign operations in order of shortest processing time
        const schedule = machines.map(() => []);
        const jobProgress = jobs.map(() => 0);
        
        const operations = [];
        for (let j = 0; j < jobs.length; j++) {
            for (let o = 0; o < jobs[j].operations.length; o++) {
                operations.push({
                    job: j,
                    op: o,
                    machine: jobs[j].operations[o].machine,
                    time: jobs[j].operations[o].time
                });
            }
        }
        
        operations.sort((a, b) => a.time - b.time);
        
        for (const op of operations) {
            schedule[op.machine].push(op);
        }
        
        return schedule;
    },
    
    _calculateMakespan: function(schedule) {
        const machineEndTimes = schedule.map(() => 0);
        const jobEndTimes = {};
        
        for (let m = 0; m < schedule.length; m++) {
            for (const op of schedule[m]) {
                const jobKey = `${op.job}`;
                const prevOpEnd = jobEndTimes[jobKey] || 0;
                const machineReady = machineEndTimes[m];
                
                const startTime = Math.max(prevOpEnd, machineReady);
                const endTime = startTime + op.time;
                
                machineEndTimes[m] = endTime;
                jobEndTimes[jobKey] = endTime;
            }
        }
        
        return Math.max(...machineEndTimes);
    },
    
    _generateScheduleNeighbors: function(schedule, jobs, machines) {
        const neighbors = [];
        
        // Swap moves within each machine
        for (let m = 0; m < schedule.length; m++) {
            for (let i = 0; i < schedule[m].length - 1; i++) {
                for (let j = i + 1; j < schedule[m].length; j++) {
                    const newSchedule = schedule.map(s => [...s]);
                    [newSchedule[m][i], newSchedule[m][j]] = [newSchedule[m][j], newSchedule[m][i]];
                    
                    neighbors.push({
                        solution: newSchedule,
                        move: { type: 'swap', machine: m, i, j },
                        reverse: { type: 'swap', machine: m, i: j, j: i }
                    });
                }
            }
        }
        
        return neighbors;
    },
    
    /**
     * Toolpath sequence optimization using L-BFGS for continuous relaxation
     */
    optimizeToolpathSequence: function(points, costFunction) {
        // Use Christofides + 2-Opt from Session 2 for discrete optimization
        const result = PRISM_MFG_OPTIMIZATION.optimizeRapidPath(points);
        return result;
    }
};

