// ═══════════════════════════════════════════════════════════════════════════════
// SECTION 1: MULTI-OBJECTIVE SCALARIZATION METHODS
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_MULTI_OBJECTIVE_SCALARIZATION = {
    name: 'PRISM_MULTI_OBJECTIVE_SCALARIZATION',
    version: '1.0.0',
    source: 'MIT 15.099 - Optimization Methods',
    
    /**
     * Epsilon-Constraint Method
     * Optimize one objective while constraining others
     * Source: MIT 15.099
     */
    epsilonConstraint: function(config) {
        const {
            objectives,      // Array of objective functions [f1, f2, ...]
            constraints = [],// Original constraints
            bounds,          // Variable bounds [{min, max}, ...]
            primaryIndex = 0,// Which objective to optimize
            epsilons,        // Bounds for other objectives [ε1, ε2, ...]
            solver = 'gradient', // 'gradient' or 'pso'
            maxIter = 1000
        } = config;
        
        const n = bounds.length;
        const numObjectives = objectives.length;
        
        // Validate epsilons
        if (!epsilons || epsilons.length !== numObjectives - 1) {
            throw new Error('Must provide epsilon bounds for all non-primary objectives');
        }
        
        // Create augmented constraint function
        const augmentedConstraints = [...constraints];
        let epsilonIdx = 0;
        
        for (let i = 0; i < numObjectives; i++) {
            if (i !== primaryIndex) {
                const objIdx = i;
                const eps = epsilons[epsilonIdx++];
                augmentedConstraints.push((x) => objectives[objIdx](x) - eps);
            }
        }
        
        // Solve constrained single-objective problem
        const primaryObj = objectives[primaryIndex];
        
        if (solver === 'pso') {
            return this._solvePSO(primaryObj, augmentedConstraints, bounds, maxIter);
        } else {
            return this._solveGradient(primaryObj, augmentedConstraints, bounds, maxIter);
        }
    },
    
    /**
     * Generate Pareto front using epsilon-constraint
     */
    generateParetoEpsilon: function(config) {
        const {
            objectives,
            bounds,
            numPoints = 20,
            constraints = []
        } = config;
        
        if (objectives.length !== 2) {
            throw new Error('Pareto generation currently supports 2 objectives');
        }
        
        // First find extreme points
        const paretoFront = [];
        
        // Find range of f2 by optimizing f2 alone
        const f2Min = this._findMinimum(objectives[1], bounds);
        const f2Max = this._findMaximum(objectives[1], bounds);
        
        // Generate epsilon values
        const epsilonRange = f2Max.value - f2Min.value;
        
        for (let i = 0; i < numPoints; i++) {
            const epsilon = f2Min.value + (i / (numPoints - 1)) * epsilonRange;
            
            try {
                const result = this.epsilonConstraint({
                    objectives,
                    constraints,
                    bounds,
                    primaryIndex: 0,
                    epsilons: [epsilon],
                    maxIter: 500
                });
                
                if (result.feasible) {
                    paretoFront.push({
                        x: result.x,
                        f1: objectives[0](result.x),
                        f2: objectives[1](result.x)
                    });
                }
            } catch (e) {
                // Infeasible for this epsilon, skip
            }
        }
        
        // Remove dominated solutions
        return this._filterDominated(paretoFront);
    },
    
    /**
     * Goal Programming
     * Minimize deviations from target values
     * Source: MIT 15.099
     */
    goalProgramming: function(config) {
        const {
            objectives,      // [{fn, target, weight, priority}]
            bounds,
            constraints = [],
            method = 'weighted', // 'weighted', 'lexicographic', 'minmax'
            maxIter = 1000
        } = config;
        
        const n = bounds.length;
        
        if (method === 'weighted') {
            // Weighted goal programming
            const goalObjective = (x) => {
                let totalDeviation = 0;
                for (const goal of objectives) {
                    const value = goal.fn(x);
                    const deviation = Math.abs(value - goal.target);
                    totalDeviation += (goal.weight || 1) * deviation;
                }
                return totalDeviation;
            };
            
            return this._solveGradient(goalObjective, constraints, bounds, maxIter);
            
        } else if (method === 'minmax') {
            // Minimize maximum deviation (Chebyshev)
            const minmaxObjective = (x) => {
                let maxDeviation = 0;
                for (const goal of objectives) {
                    const value = goal.fn(x);
                    const normalizedDev = Math.abs(value - goal.target) / (goal.target || 1);
                    maxDeviation = Math.max(maxDeviation, (goal.weight || 1) * normalizedDev);
                }
                return maxDeviation;
            };
            
            return this._solveGradient(minmaxObjective, constraints, bounds, maxIter);
            
        } else {
            // Lexicographic - solve in priority order
            return this.lexicographic({
                objectives: objectives.map(g => ({
                    fn: (x) => Math.abs(g.fn(x) - g.target),
                    priority: g.priority || 1
                })),
                bounds,
                constraints,
                maxIter
            });
        }
    },
    
    /**
     * Lexicographic Method
     * Solve objectives in strict priority order
     * Source: MIT 15.099
     */
    lexicographic: function(config) {
        const {
            objectives,      // [{fn, priority}] - lower priority = more important
            bounds,
            constraints = [],
            tolerance = 0.01, // Allow this much degradation from optimal
            maxIter = 1000
        } = config;
        
        // Sort by priority (ascending - lower number = higher priority)
        const sortedObj = [...objectives].sort((a, b) => (a.priority || 1) - (b.priority || 1));
        
        let currentConstraints = [...constraints];
        let x = bounds.map(b => (b.min + b.max) / 2); // Initial point
        let results = [];
        
        for (let level = 0; level < sortedObj.length; level++) {
            const obj = sortedObj[level];
            
            // Optimize this objective subject to all constraints
            const result = this._solveGradient(obj.fn, currentConstraints, bounds, maxIter, x);
            
            if (!result.feasible) {
                return {
                    feasible: false,
                    level,
                    reason: `Infeasible at priority level ${level}`
                };
            }
            
            x = result.x;
            const optimalValue = obj.fn(x);
            results.push({ priority: obj.priority, optimalValue });
            
            // Add constraint: this objective must stay within tolerance of optimal
            const allowedValue = optimalValue * (1 + tolerance);
            currentConstraints.push((x) => obj.fn(x) - allowedValue);
        }
        
        return {
            feasible: true,
            x,
            objectives: sortedObj.map(o => o.fn(x)),
            results,
            method: 'lexicographic'
        };
    },
    
    // Helper: Gradient-based solver with constraints
    _solveGradient: function(objective, constraints, bounds, maxIter, x0 = null) {
        const n = bounds.length;
        let x = x0 || bounds.map(b => (b.min + b.max) / 2);
        
        const penalty = 1000;
        const lr = 0.01;
        
        const penalizedObj = (x) => {
            let val = objective(x);
            
            // Constraint violations
            for (const c of constraints) {
                const violation = Math.max(0, c(x));
                val += penalty * violation * violation;
            }
            
            // Bound violations
            for (let i = 0; i < n; i++) {
                if (x[i] < bounds[i].min) val += penalty * Math.pow(bounds[i].min - x[i], 2);
                if (x[i] > bounds[i].max) val += penalty * Math.pow(x[i] - bounds[i].max, 2);
            }
            
            return val;
        };
        
        // Gradient descent with numerical gradient
        for (let iter = 0; iter < maxIter; iter++) {
            const grad = this._numericalGradient(penalizedObj, x);
            const gradNorm = Math.sqrt(grad.reduce((s, g) => s + g * g, 0));
            
            if (gradNorm < 1e-8) break;
            
            // Update
            for (let i = 0; i < n; i++) {
                x[i] -= lr * grad[i];
                x[i] = Math.max(bounds[i].min, Math.min(bounds[i].max, x[i]));
            }
        }
        
        // Check feasibility
        const feasible = constraints.every(c => c(x) <= 1e-6);
        
        return {
            x,
            value: objective(x),
            feasible,
            method: 'gradient'
        };
    },
    
    _solvePSO: function(objective, constraints, bounds, maxIter) {
        const n = bounds.length;
        const swarmSize = 30;
        const penalty = 10000;
        
        const penalizedObj = (x) => {
            let val = objective(x);
            for (const c of constraints) {
                const violation = Math.max(0, c(x));
                val += penalty * violation * violation;
            }
            return val;
        };
        
        // Initialize swarm
        let particles = [];
        let globalBest = null;
        let globalBestValue = Infinity;
        
        for (let i = 0; i < swarmSize; i++) {
            const pos = bounds.map(b => b.min + Math.random() * (b.max - b.min));
            const vel = bounds.map(b => (Math.random() - 0.5) * (b.max - b.min) * 0.1);
            const value = penalizedObj(pos);
            
            particles.push({
                position: pos,
                velocity: vel,
                bestPosition: [...pos],
                bestValue: value
            });
            
            if (value < globalBestValue) {
                globalBestValue = value;
                globalBest = [...pos];
            }
        }
        
        const w = 0.7, c1 = 1.5, c2 = 1.5;
        
        for (let iter = 0; iter < maxIter; iter++) {
            for (const p of particles) {
                // Update velocity
                for (let i = 0; i < n; i++) {
                    p.velocity[i] = w * p.velocity[i]
                        + c1 * Math.random() * (p.bestPosition[i] - p.position[i])
                        + c2 * Math.random() * (globalBest[i] - p.position[i]);
                }
                
                // Update position
                for (let i = 0; i < n; i++) {
                    p.position[i] += p.velocity[i];
                    p.position[i] = Math.max(bounds[i].min, Math.min(bounds[i].max, p.position[i]));
                }
                
                // Evaluate
                const value = penalizedObj(p.position);
                
                if (value < p.bestValue) {
                    p.bestValue = value;
                    p.bestPosition = [...p.position];
                    
                    if (value < globalBestValue) {
                        globalBestValue = value;
                        globalBest = [...p.position];
                    }
                }
            }
        }
        
        const feasible = constraints.every(c => c(globalBest) <= 1e-6);
        
        return {
            x: globalBest,
            value: objective(globalBest),
            feasible,
            method: 'pso'
        };
    },
    
    _numericalGradient: function(f, x, h = 1e-6) {
        const grad = [];
        const fx = f(x);
        
        for (let i = 0; i < x.length; i++) {
            const xh = [...x];
            xh[i] += h;
            grad.push((f(xh) - fx) / h);
        }
        
        return grad;
    },
    
    _findMinimum: function(f, bounds) {
        const result = this._solveGradient(f, [], bounds, 500);
        return { x: result.x, value: result.value };
    },
    
    _findMaximum: function(f, bounds) {
        const negF = (x) => -f(x);
        const result = this._solveGradient(negF, [], bounds, 500);
        return { x: result.x, value: f(result.x) };
    },
    
    _filterDominated: function(solutions) {
        return solutions.filter((s, i) => {
            for (let j = 0; j < solutions.length; j++) {
                if (i !== j) {
                    const other = solutions[j];
                    if (other.f1 <= s.f1 && other.f2 <= s.f2 &&
                        (other.f1 < s.f1 || other.f2 < s.f2)) {
                        return false; // s is dominated
                    }
                }
            }
            return true;
        });
    }
};

// ═══════════════════════════════════════════════════════════════════════════════
// SECTION 2: LINEAR PROGRAMMING SOLVERS
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_LP_SOLVERS = {
    name: 'PRISM_LP_SOLVERS',
    version: '1.0.0',
    source: 'MIT 15.083j - Integer Programming & 15.084j - Nonlinear Programming',
    
    /**
     * Revised Simplex Method
     * Standard LP solver: min c'x s.t. Ax = b, x >= 0
     * Source: MIT 15.083j
     */
    revisedSimplex: function(config) {
        const {
            c,      // Objective coefficients (n)
            A,      // Constraint matrix (m x n)
            b,      // RHS (m)
            maxIter = 1000
        } = config;
        
        const m = A.length;
        const n = c.length;
        
        // Add slack variables for standard form
        // Assuming Ax <= b, convert to Ax + s = b
        const fullA = A.map((row, i) => {
            const newRow = [...row];
            for (let j = 0; j < m; j++) {
                newRow.push(i === j ? 1 : 0);
            }
            return newRow;
        });
        
        const fullC = [...c, ...new Array(m).fill(0)];
        const totalVars = n + m;
        
        // Initial basis: slack variables
        let basis = [];
        for (let i = 0; i < m; i++) {
            basis.push(n + i);
        }
        
        // Initial BFS: x_slack = b, x_original = 0
        let x = new Array(totalVars).fill(0);
        for (let i = 0; i < m; i++) {
            x[n + i] = b[i];
            if (b[i] < 0) {
                return { feasible: false, reason: 'Negative RHS not supported' };
            }
        }
        
        for (let iter = 0; iter < maxIter; iter++) {
            // Compute reduced costs
            const B = basis.map(j => fullA.map(row => row[j]));
            const cB = basis.map(j => fullC[j]);
            
            // Solve B'y = cB for dual variables
            const y = this._solveSystem(this._transpose(B), cB);
            
            // Find entering variable (most negative reduced cost)
            let entering = -1;
            let minReducedCost = -1e-10;
            
            for (let j = 0; j < totalVars; j++) {
                if (!basis.includes(j)) {
                    const col = fullA.map(row => row[j]);
                    const reducedCost = fullC[j] - this._dot(y, col);
                    
                    if (reducedCost < minReducedCost) {
                        minReducedCost = reducedCost;
                        entering = j;
                    }
                }
            }
            
            if (entering === -1) {
                // Optimal
                const solution = new Array(n).fill(0);
                for (let i = 0; i < m; i++) {
                    if (basis[i] < n) {
                        solution[basis[i]] = x[basis[i]];
                    }
                }
                
                return {
                    feasible: true,
                    optimal: true,
                    x: solution,
                    objective: this._dot(c, solution),
                    iterations: iter
                };
            }
            
            // Compute direction
            const enteringCol = fullA.map(row => row[entering]);
            const d = this._solveSystem(B, enteringCol);
            
            // Ratio test for leaving variable
            let leaving = -1;
            let minRatio = Infinity;
            
            for (let i = 0; i < m; i++) {
                if (d[i] > 1e-10) {
                    const ratio = x[basis[i]] / d[i];
                    if (ratio < minRatio) {
                        minRatio = ratio;
                        leaving = i;
                    }
                }
            }
            
            if (leaving === -1) {
                return { feasible: true, optimal: false, unbounded: true };
            }
            
            // Update solution
            const step = minRatio;
            for (let i = 0; i < m; i++) {
                x[basis[i]] -= step * d[i];
            }
            x[entering] = step;
            
            // Update basis
            basis[leaving] = entering;
        }
        
        return { feasible: true, optimal: false, reason: 'Max iterations' };
    },
    
    /**
     * Primal-Dual Interior Point Method
     * Large-scale LP solver
     * Source: MIT 15.084j Lectures 14-15
     */
    primalDualInteriorPoint: function(config) {
        const {
            c,          // Objective (n)
            A,          // Constraints (m x n)
            b,          // RHS (m)
            maxIter = 100,
            tol = 1e-8
        } = config;
        
        const m = A.length;
        const n = c.length;
        
        // Initialize strictly feasible points
        let x = new Array(n).fill(1);  // Primal variables
        let s = new Array(n).fill(1);  // Slack variables
        let y = new Array(m).fill(0);  // Dual variables
        
        // Centering parameter
        const sigma = 0.1;
        
        for (let iter = 0; iter < maxIter; iter++) {
            // Compute residuals
            const Ax = this._matVec(A, x);
            const rb = b.map((bi, i) => bi - Ax[i]);  // Primal residual
            
            const ATy = this._matVec(this._transpose(A), y);
            const rc = c.map((ci, i) => ci - ATy[i] - s[i]);  // Dual residual
            
            const mu = this._dot(x, s) / n;  // Duality gap
            
            // Check convergence
            const rbNorm = Math.sqrt(this._dot(rb, rb));
            const rcNorm = Math.sqrt(this._dot(rc, rc));
            
            if (rbNorm < tol && rcNorm < tol && mu < tol) {
                return {
                    feasible: true,
                    optimal: true,
                    x,
                    objective: this._dot(c, x),
                    dualObjective: this._dot(b, y),
                    iterations: iter,
                    dualityGap: mu
                };
            }
            
            // Compute Newton direction (simplified)
            // Full system: [0 A' I; A 0 0; S 0 X] [dx; dy; ds] = [rc; rb; sigma*mu*e - XSe]
            
            // Using normal equations approach
            const XinvS = x.map((xi, i) => s[i] / (xi + 1e-10));
            const targetGap = sigma * mu;
            
            // Affine direction
            const { dx, dy, ds } = this._solveIPSystem(A, XinvS, x, s, rb, rc, targetGap);
            
            // Step length (fraction to boundary)
            let alphaP = 1, alphaD = 1;
            const tau = 0.995;
            
            for (let i = 0; i < n; i++) {
                if (dx[i] < 0) alphaP = Math.min(alphaP, -tau * x[i] / dx[i]);
                if (ds[i] < 0) alphaD = Math.min(alphaD, -tau * s[i] / ds[i]);
            }
            
            // Update
            for (let i = 0; i < n; i++) {
                x[i] += alphaP * dx[i];
                s[i] += alphaD * ds[i];
            }
            for (let i = 0; i < m; i++) {
                y[i] += alphaD * dy[i];
            }
        }
        
        return {
            feasible: true,
            optimal: false,
            x,
            objective: this._dot(c, x),
            reason: 'Max iterations'
        };
    },
    
    _solveIPSystem: function(A, XinvS, x, s, rb, rc, targetGap) {
        const m = A.length;
        const n = A[0].length;
        
        // Simplified: use gradient of barrier function
        const dx = new Array(n).fill(0);
        const dy = new Array(m).fill(0);
        const ds = new Array(n).fill(0);
        
        // Compute modified RHS
        const rhs = rc.map((rci, i) => -rci + targetGap / (x[i] + 1e-10));
        
        // Diagonal scaling
        const D = x.map((xi, i) => xi / (s[i] + 1e-10));
        
        // Form A*D*A' (normal equations)
        const ADA = [];
        for (let i = 0; i < m; i++) {
            ADA[i] = [];
            for (let j = 0; j < m; j++) {
                let sum = 0;
                for (let k = 0; k < n; k++) {
                    sum += A[i][k] * D[k] * A[j][k];
                }
                ADA[i][j] = sum;
            }
        }
        
        // RHS for normal equations
        const rhsNormal = [];
        for (let i = 0; i < m; i++) {
            let sum = rb[i];
            for (let k = 0; k < n; k++) {
                sum += A[i][k] * D[k] * rhs[k];
            }
            rhsNormal[i] = sum;
        }
        
        // Solve for dy
        const dyResult = this._solveSystem(ADA, rhsNormal);
        for (let i = 0; i < m; i++) dy[i] = dyResult[i];
        
        // Back-substitute for dx
        const ATdy = this._matVec(this._transpose(A), dy);
        for (let i = 0; i < n; i++) {
            dx[i] = D[i] * (rhs[i] - ATdy[i]);
        }
        
        // Compute ds
        for (let i = 0; i < n; i++) {
            ds[i] = -rc[i] - ATdy[i];
        }
        
        return { dx, dy, ds };
    },
    
    /**
     * Active Set Method for QP
     * min 0.5*x'Hx + c'x s.t. Ax <= b
     * Source: MIT 15.084j Lectures 6-8
     */
    activeSetQP: function(config) {
        const {
            H,          // Hessian (n x n, positive definite)
            c,          // Linear term (n)
            A,          // Inequality constraints (m x n)
            b,          // RHS (m)
            x0 = null,  // Initial feasible point
            maxIter = 1000
        } = config;
        
        const n = H.length;
        const m = A.length;
        
        // Find initial feasible point if not provided
        let x = x0 || this._findFeasiblePoint(A, b, n);
        if (!x) {
            return { feasible: false, reason: 'Could not find feasible point' };
        }
        
        // Initialize working set (active constraints)
        let workingSet = [];
        for (let i = 0; i < m; i++) {
            const slack = b[i] - this._dot(A[i], x);
            if (Math.abs(slack) < 1e-8) {
                workingSet.push(i);
            }
        }
        
        for (let iter = 0; iter < maxIter; iter++) {
            // Compute gradient
            const g = this._add(this._matVec(H, x), c);
            
            // Solve equality-constrained QP subproblem
            // min 0.5*p'Hp + g'p s.t. A_W*p = 0
            
            const AW = workingSet.map(i => A[i]);
            
            let p;
            if (workingSet.length === 0) {
                // Unconstrained: p = -H^{-1}g
                p = this._solveSystem(H, g.map(gi => -gi));
            } else {
                // KKT system
                const result = this._solveKKT(H, g, AW);
                p = result.p;
            }
            
            const pNorm = Math.sqrt(this._dot(p, p));
            
            if (pNorm < 1e-10) {
                // Check Lagrange multipliers
                if (workingSet.length === 0) {
                    // Optimal
                    return {
                        feasible: true,
                        optimal: true,
                        x,
                        objective: 0.5 * this._dot(x, this._matVec(H, x)) + this._dot(c, x),
                        iterations: iter
                    };
                }
                
                // Compute multipliers
                const lambdas = this._computeLambdas(H, c, x, A, workingSet);
                
                // Find most negative multiplier
                let minLambda = 0;
                let minIdx = -1;
                for (let i = 0; i < workingSet.length; i++) {
                    if (lambdas[i] < minLambda) {
                        minLambda = lambdas[i];
                        minIdx = i;
                    }
                }
                
                if (minIdx === -1) {
                    // All multipliers non-negative - optimal
                    return {
                        feasible: true,
                        optimal: true,
                        x,
                        objective: 0.5 * this._dot(x, this._matVec(H, x)) + this._dot(c, x),
                        iterations: iter,
                        activeConstraints: workingSet
                    };
                }
                
                // Remove constraint with most negative multiplier
                workingSet.splice(minIdx, 1);
                
            } else {
                // Compute step length
                let alpha = 1;
                let blockingConstraint = -1;
                
                for (let i = 0; i < m; i++) {
                    if (!workingSet.includes(i)) {
                        const ap = this._dot(A[i], p);
                        if (ap > 1e-10) {
                            const slack = b[i] - this._dot(A[i], x);
                            const ratio = slack / ap;
                            if (ratio < alpha) {
                                alpha = ratio;
                                blockingConstraint = i;
                            }
                        }
                    }
                }
                
                // Take step
                x = this._add(x, p.map(pi => alpha * pi));
                
                // Add blocking constraint to working set
                if (alpha < 1 && blockingConstraint >= 0) {
                    workingSet.push(blockingConstraint);
                }
            }
        }
        
        return {
            feasible: true,
            optimal: false,
            x,
            reason: 'Max iterations'
        };
    },
    
    _solveKKT: function(H, g, AW) {
        const n = H.length;
        const m = AW.length;
        
        if (m === 0) {
            return { p: this._solveSystem(H, g.map(gi => -gi)) };
        }
        
        // Build KKT matrix [H A'; A 0]
        const size = n + m;
        const KKT = [];
        
        for (let i = 0; i < n; i++) {
            KKT[i] = [...H[i]];
            for (let j = 0; j < m; j++) {
                KKT[i].push(AW[j][i]);
            }
        }
        
        for (let i = 0; i < m; i++) {
            KKT[n + i] = [...AW[i], ...new Array(m).fill(0)];
        }
        
        // RHS: [-g; 0]
        const rhs = [...g.map(gi => -gi), ...new Array(m).fill(0)];
        
        // Solve
        const sol = this._solveSystem(KKT, rhs);
        
        return {
            p: sol.slice(0, n),
            lambda: sol.slice(n)
        };
    },
    
    _computeLambdas: function(H, c, x, A, workingSet) {
        // λ = (A_W H^{-1} A_W')^{-1} (A_W H^{-1} g + A_W x - b_W)
        const g = this._add(this._matVec(H, x), c);
        const AW = workingSet.map(i => A[i]);
        
        if (AW.length === 0) return [];
        
        // Simplified: use gradient projection
        const lambdas = [];
        for (let i = 0; i < workingSet.length; i++) {
            const ai = AW[i];
            lambdas.push(this._dot(ai, g) / this._dot(ai, ai));
        }
        
        return lambdas;
    },
    
    _findFeasiblePoint: function(A, b, n) {
        // Phase I: minimize sum of violations
        let x = new Array(n).fill(0);
        
        for (let iter = 0; iter < 100; iter++) {
            let maxViolation = 0;
            let violatingConstraint = -1;
            
            for (let i = 0; i < A.length; i++) {
                const violation = this._dot(A[i], x) - b[i];
                if (violation > maxViolation) {
                    maxViolation = violation;
                    violatingConstraint = i;
                }
            }
            
            if (maxViolation <= 1e-8) {
                return x;
            }
            
            // Move away from violated constraint
            const a = A[violatingConstraint];
            const step = maxViolation / this._dot(a, a);
            x = this._add(x, a.map(ai => -step * ai));
        }
        
        return null;
    },
    
    // Linear algebra helpers
    _dot: function(a, b) {
        return a.reduce((sum, ai, i) => sum + ai * (b[i] || 0), 0);
    },
    
    _add: function(a, b) {
        return a.map((ai, i) => ai + (b[i] || 0));
    },
    
    _matVec: function(A, x) {
        return A.map(row => this._dot(row, x));
    },
    
    _transpose: function(A) {
        if (A.length === 0) return [];
        return A[0].map((_, j) => A.map(row => row[j]));
    },
    
    _solveSystem: function(A, b) {
        // Gaussian elimination with partial pivoting
        const n = A.length;
        const aug = A.map((row, i) => [...row, b[i]]);
        
        for (let col = 0; col < n; col++) {
            // Find pivot
            let maxRow = col;
            for (let row = col + 1; row < n; row++) {
                if (Math.abs(aug[row][col]) > Math.abs(aug[maxRow][col])) {
                    maxRow = row;
                }
            }
            [aug[col], aug[maxRow]] = [aug[maxRow], aug[col]];
            
            if (Math.abs(aug[col][col]) < 1e-12) continue;
            
            // Eliminate
            for (let row = col + 1; row < n; row++) {
                const factor = aug[row][col] / aug[col][col];
                for (let j = col; j <= n; j++) {
                    aug[row][j] -= factor * aug[col][j];
                }
            }
        }
        
        // Back substitution
        const x = new Array(n).fill(0);
        for (let i = n - 1; i >= 0; i--) {
            let sum = aug[i][n];
            for (let j = i + 1; j < n; j++) {
                sum -= aug[i][j] * x[j];
            }
            x[i] = Math.abs(aug[i][i]) > 1e-12 ? sum / aug[i][i] : 0;
        }
        
        return x;
    }
};

// ═══════════════════════════════════════════════════════════════════════════════
// SECTION 3: ROBUST OPTIMIZATION
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_ROBUST_OPTIMIZATION = {
    name: 'PRISM_ROBUST_OPTIMIZATION',
    version: '1.0.0',
    source: 'MIT 15.099 - Robust Optimization',
    
    /**
     * Robust Optimization with Uncertainty Sets
     * Find solution that performs well under worst-case uncertainty
     */
    robustOptimization: function(config) {
        const {
            objective,       // (x, scenario) => value
            bounds,          // [{min, max}]
            uncertainParams, // [{nominal, min, max}]
            uncertaintyBudget = 1.0, // Γ - how many params can deviate
            numScenarios = 100,
            method = 'worstCase' // 'worstCase', 'expected', 'cvar'
        } = config;
        
        // Generate scenarios
        const scenarios = this.generateScenarios({
            params: uncertainParams,
            numScenarios,
            budget: uncertaintyBudget
        });
        
        if (method === 'worstCase') {
            // Minimize worst-case cost
            const robustObjective = (x) => {
                let worstCase = -Infinity;
                for (const scenario of scenarios) {
                    const value = objective(x, scenario);
                    if (value > worstCase) worstCase = value;
                }
                return worstCase;
            };
            
            return this._optimizeRobust(robustObjective, bounds);
            
        } else if (method === 'expected') {
            // Minimize expected cost
            const expectedObjective = (x) => {
                let sum = 0;
                for (const scenario of scenarios) {
                    sum += objective(x, scenario);
                }
                return sum / scenarios.length;
            };
            
            return this._optimizeRobust(expectedObjective, bounds);
            
        } else if (method === 'cvar') {
            // Minimize Conditional Value at Risk (CVaR)
            const alpha = 0.95; // 95% confidence
            
            const cvarObjective = (x) => {
                const costs = scenarios.map(s => objective(x, s)).sort((a, b) => b - a);
                const numWorst = Math.ceil((1 - alpha) * costs.length);
                return costs.slice(0, numWorst).reduce((a, b) => a + b, 0) / numWorst;
            };
            
            return this._optimizeRobust(cvarObjective, bounds);
        }
    },
    
    /**
     * Generate uncertainty scenarios
     */
    generateScenarios: function(config) {
        const {
            params,         // [{nominal, min, max}]
            numScenarios,
            budget = Infinity,
            method = 'uniform' // 'uniform', 'latin', 'sobol'
        } = config;
        
        const scenarios = [];
        const k = params.length;
        
        if (method === 'latin') {
            // Latin Hypercube Sampling
            const intervals = params.map(() => {
                const cuts = [];
                for (let i = 0; i < numScenarios; i++) {
                    cuts.push(i);
                }
                // Shuffle
                for (let i = cuts.length - 1; i > 0; i--) {
                    const j = Math.floor(Math.random() * (i + 1));
                    [cuts[i], cuts[j]] = [cuts[j], cuts[i]];
                }
                return cuts;
            });
            
            for (let i = 0; i < numScenarios; i++) {
                const scenario = {};
                let deviationSum = 0;
                
                for (let j = 0; j < k; j++) {
                    const p = params[j];
                    const interval = intervals[j][i];
                    const u = (interval + Math.random()) / numScenarios;
                    const value = p.min + u * (p.max - p.min);
                    scenario[j] = value;
                    scenario[`param${j}`] = value;
                    
                    const deviation = Math.abs(value - p.nominal) / ((p.max - p.min) / 2);
                    deviationSum += deviation;
                }
                
                // Enforce budget constraint
                if (deviationSum <= budget) {
                    scenarios.push(scenario);
                }
            }
            
        } else {
            // Uniform random
            for (let i = 0; i < numScenarios; i++) {
                const scenario = {};
                let deviationSum = 0;
                
                for (let j = 0; j < k; j++) {
                    const p = params[j];
                    const value = p.min + Math.random() * (p.max - p.min);
                    scenario[j] = value;
                    scenario[`param${j}`] = value;
                    
                    const deviation = Math.abs(value - p.nominal) / ((p.max - p.min) / 2);
                    deviationSum += deviation;
                }
                
                if (budget === Infinity || deviationSum <= budget) {
                    scenarios.push(scenario);
                }
            }
        }
        
        // Add nominal scenario
        const nominal = {};
        for (let j = 0; j < k; j++) {
            nominal[j] = params[j].nominal;
            nominal[`param${j}`] = params[j].nominal;
        }
        scenarios.unshift(nominal);
        
        return scenarios;
    },
    
    /**
     * Sensitivity Analysis
     * Analyze how solution changes with parameter variations
     */
    sensitivityAnalysis: function(config) {
        const {
            objective,
            optimalX,
            params,
            numSamples = 50
        } = config;
        
        const baseline = objective(optimalX, params.map(p => p.nominal));
        const sensitivities = [];
        
        for (let i = 0; i < params.length; i++) {
            const p = params[i];
            const range = p.max - p.min;
            const impacts = [];
            
            for (let j = 0; j < numSamples; j++) {
                const delta = (j / (numSamples - 1) - 0.5) * range;
                const scenario = params.map((pp, idx) => 
                    idx === i ? pp.nominal + delta : pp.nominal
                );
                
                const value = objective(optimalX, scenario);
                impacts.push({
                    paramValue: p.nominal + delta,
                    objectiveValue: value,
                    change: value - baseline
                });
            }
            
            // Compute sensitivity metrics
            const objectiveRange = Math.max(...impacts.map(x => x.objectiveValue)) - 
                                  Math.min(...impacts.map(x => x.objectiveValue));
            
            sensitivities.push({
                paramIndex: i,
                paramName: p.name || `param${i}`,
                nominalValue: p.nominal,
                objectiveRange,
                sensitivity: objectiveRange / range, // Normalized sensitivity
                impacts
            });
        }
        
        // Sort by sensitivity
        sensitivities.sort((a, b) => b.sensitivity - a.sensitivity);
        
        return {
            baseline,
            sensitivities,
            mostSensitive: sensitivities[0]?.paramName,
            leastSensitive: sensitivities[sensitivities.length - 1]?.paramName
        };
    },
    
    _optimizeRobust: function(objective, bounds) {
        const n = bounds.length;
        let x = bounds.map(b => (b.min + b.max) / 2);
        let bestX = [...x];
        let bestValue = objective(x);
        
        const maxIter = 500;
        const lr = 0.05;
        
        for (let iter = 0; iter < maxIter; iter++) {
            // Numerical gradient
            const grad = [];
            const fx = objective(x);
            
            for (let i = 0; i < n; i++) {
                const h = (bounds[i].max - bounds[i].min) * 0.001;
                const xh = [...x];
                xh[i] += h;
                grad[i] = (objective(xh) - fx) / h;
            }
            
            // Update
            for (let i = 0; i < n; i++) {
                x[i] -= lr * grad[i];
                x[i] = Math.max(bounds[i].min, Math.min(bounds[i].max, x[i]));
            }
            
            const value = objective(x);
            if (value < bestValue) {
                bestValue = value;
                bestX = [...x];
            }
        }
        
        return {
            x: bestX,
            value: bestValue,
            method: 'robust_gradient'
        };
    }
};

// ═══════════════════════════════════════════════════════════════════════════════
// SECTION 4: MANUFACTURING OPTIMIZATION APPLICATIONS (SESSION 3B)
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_MFG_OPTIMIZATION_ADVANCED_B = {
    name: 'PRISM_MFG_OPTIMIZATION_ADVANCED_B',
    version: '1.0.0',
    source: 'PRISM Innovation - Advanced Manufacturing Optimization',
    
    /**
     * Multi-objective cutting parameter optimization with goals
     */
    goalBasedCuttingParams: function(config) {
        const {
            material,
            tool,
            machine,
            goals = [
                { metric: 'mrr', target: 50, weight: 1, priority: 1 },      // cm³/min
                { metric: 'surfaceFinish', target: 1.6, weight: 1, priority: 2 }, // Ra
                { metric: 'toolLife', target: 60, weight: 1, priority: 3 }  // minutes
            ]
        } = config;
        
        const bounds = [
            { min: 50, max: machine.maxRPM || 5000 },   // Speed (RPM)
            { min: 0.05, max: tool.maxFeed || 0.3 },   // Feed (mm/rev)
            { min: 0.5, max: tool.maxDOC || 3 }        // DOC (mm)
        ];
        
        const objectives = goals.map(g => ({
            fn: (x) => {
                const [rpm, feed, doc] = x;
                const speed = Math.PI * (tool.diameter || 10) * rpm / 1000;
                
                switch (g.metric) {
                    case 'mrr':
                        return speed * feed * doc / 10; // Simplified MRR
                    case 'surfaceFinish':
                        return feed * feed / (8 * (tool.noseRadius || 0.8)) * 1000; // Ra
                    case 'toolLife':
                        const C = material.taylorC || 200;
                        const n = material.taylorn || 0.25;
                        return C / Math.pow(speed, 1/n); // Taylor tool life
                    default:
                        return 0;
                }
            },
            target: g.target,
            weight: g.weight,
            priority: g.priority
        }));
        
        return PRISM_MULTI_OBJECTIVE_SCALARIZATION.goalProgramming({
            objectives,
            bounds,
            method: 'weighted'
        });
    },
    
    /**
     * Robust cutting parameter optimization
     */
    robustCuttingParams: function(config) {
        const {
            material,
            tool,
            machine,
            objective = 'minimize_cost', // 'minimize_cost', 'maximize_mrr'
            materialUncertainty = 0.1,   // 10% hardness variation
            toolUncertainty = 0.05       // 5% tool condition variation
        } = config;
        
        const bounds = [
            { min: 50, max: machine.maxRPM || 5000 },
            { min: 0.05, max: tool.maxFeed || 0.3 },
            { min: 0.5, max: tool.maxDOC || 3 }
        ];
        
        const uncertainParams = [
            {
                name: 'hardness',
                nominal: material.hardness || 200,
                min: (material.hardness || 200) * (1 - materialUncertainty),
                max: (material.hardness || 200) * (1 + materialUncertainty)
            },
            {
                name: 'toolCondition',
                nominal: 1.0,
                min: 1 - toolUncertainty,
                max: 1 + toolUncertainty
            }
        ];
        
        const costObjective = (x, scenario) => {
            const [rpm, feed, doc] = x;
            const hardness = scenario[0] || scenario.param0;
            const toolCond = scenario[1] || scenario.param1;
            
            const speed = Math.PI * (tool.diameter || 10) * rpm / 1000;
            const mrr = speed * feed * doc / 10;
            
            // Tool life affected by hardness and condition
            const hardnessRatio = hardness / (material.hardness || 200);
            const toolLife = (60 / Math.pow(speed / 100, 4)) * (1 / hardnessRatio) * toolCond;
            
            if (objective === 'maximize_mrr') {
                return -mrr; // Negative for maximization
            } else {
                // Cost = machining time cost + tool cost
                const machiningTime = 1 / mrr; // Simplified
                const toolCost = (tool.cost || 50) / toolLife;
                return machiningTime * 10 + toolCost;
            }
        };
        
        return PRISM_ROBUST_OPTIMIZATION.robustOptimization({
            objective: costObjective,
            bounds,
            uncertainParams,
            uncertaintyBudget: 1.5,
            numScenarios: 50,
            method: 'worstCase'
        });
    },
    
    /**
     * Lexicographic machining optimization
     * Safety > Quality > Productivity
     */
    safetyCriticalOptimization: function(config) {
        const {
            material,
            tool,
            machine,
            maxPower = machine.maxPower || 15, // kW
            maxForce = machine.maxForce || 5000, // N
            targetRa = 1.6 // μm
        } = config;
        
        const bounds = [
            { min: 50, max: machine.maxRPM || 5000 },
            { min: 0.05, max: tool.maxFeed || 0.3 },
            { min: 0.5, max: tool.maxDOC || 3 }
        ];
        
        const objectives = [
            {
                // Priority 1: Minimize power violation
                fn: (x) => {
                    const [rpm, feed, doc] = x;
                    const speed = Math.PI * (tool.diameter || 10) * rpm / 1000;
                    const mrr = speed * feed * doc;
                    const power = mrr * (material.specificCuttingForce || 2500) / 60000;
                    return Math.max(0, power - maxPower);
                },
                priority: 1
            },
            {
                // Priority 2: Minimize force violation
                fn: (x) => {
                    const [rpm, feed, doc] = x;
                    const Kc = material.specificCuttingForce || 2500;
                    const force = Kc * feed * doc;
                    return Math.max(0, force - maxForce);
                },
                priority: 2
            },
            {
                // Priority 3: Minimize surface finish deviation
                fn: (x) => {
                    const [rpm, feed, doc] = x;
                    const Ra = feed * feed / (8 * (tool.noseRadius || 0.8)) * 1000;
                    return Math.abs(Ra - targetRa);
                },
                priority: 3
            },
            {
                // Priority 4: Maximize MRR (minimize negative MRR)
                fn: (x) => {
                    const [rpm, feed, doc] = x;
                    const speed = Math.PI * (tool.diameter || 10) * rpm / 1000;
                    return -speed * feed * doc / 10;
                },
                priority: 4
            }
        ];
        
        return PRISM_MULTI_OBJECTIVE_SCALARIZATION.lexicographic({
            objectives,
            bounds,
            tolerance: 0.05
        });
    }
};

