// ═══════════════════════════════════════════════════════════════════════════════
// SECTION 1: CUTTING MECHANICS (MIT 2.008)
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_CUTTING_MECHANICS = {
    name: 'PRISM_CUTTING_MECHANICS',
    version: '1.0.0',
    source: 'MIT 2.008 - Manufacturing Process Technology',
    
    /**
     * Complete Merchant's Circle Analysis
     * Orthogonal cutting force model
     * Source: MIT 2.008
     */
    merchantCircle: function(params) {
        const {
            width,          // Width of cut (mm)
            depth,          // Uncut chip thickness (mm)
            rakeAngle,      // Tool rake angle (degrees)
            frictionCoef,   // Friction coefficient at tool-chip interface
            shearStrength,  // Material shear strength (MPa)
            chipRatio = null // Optional: measured chip ratio
        } = params;
        
        const alpha = rakeAngle * Math.PI / 180; // Rake angle in radians
        const beta = Math.atan(frictionCoef);    // Friction angle
        
        // Calculate shear angle using Merchant's equation (minimum energy)
        // φ = 45° + α/2 - β/2
        let phi;
        if (chipRatio !== null && chipRatio > 0) {
            // From measured chip ratio
            phi = Math.atan(chipRatio * Math.cos(alpha) / (1 - chipRatio * Math.sin(alpha)));
        } else {
            // Merchant's equation
            phi = Math.PI / 4 + alpha / 2 - beta / 2;
        }
        
        // Shear plane area
        const As = (width * depth) / Math.sin(phi);
        
        // Shear force
        const Fs = shearStrength * As;
        
        // Resultant force
        const R = Fs / Math.cos(phi + beta - alpha);
        
        // Cutting force (tangential)
        const Fc = R * Math.cos(beta - alpha);
        
        // Thrust force (radial)
        const Ft = R * Math.sin(beta - alpha);
        
        // Normal force on shear plane
        const Fn = Fs * Math.tan(phi + beta - alpha);
        
        // Friction force on rake face
        const F = R * Math.sin(beta);
        
        // Normal force on rake face
        const N = R * Math.cos(beta);
        
        // Calculated chip ratio
        const rc = Math.sin(phi) / Math.cos(phi - alpha);
        
        // Specific cutting energy
        const specificEnergy = Fc / (width * depth); // N/mm² or MPa
        
        return {
            shearAngle: phi * 180 / Math.PI,      // degrees
            shearAngleRad: phi,
            chipRatio: rc,
            chipThickness: depth / rc,             // mm
            shearForce: Fs,                        // N
            cuttingForce: Fc,                      // N
            thrustForce: Ft,                       // N
            resultantForce: R,                     // N
            frictionForce: F,                      // N
            normalForce: N,                        // N
            shearPlaneArea: As,                    // mm²
            specificCuttingEnergy: specificEnergy, // MPa
            frictionAngle: beta * 180 / Math.PI,
            powerRequired: null // Set when velocity known
        };
    },
    
    /**
     * Oblique Cutting Model
     * 3D cutting with inclination angle
     * Source: MIT 2.008
     */
    obliqueCutting: function(params) {
        const {
            width,
            depth,
            rakeAngle,      // Normal rake angle (degrees)
            inclinationAngle, // Inclination angle (degrees)
            frictionCoef,
            shearStrength,
            cuttingSpeed    // m/min
        } = params;
        
        const alpha_n = rakeAngle * Math.PI / 180;
        const i = inclinationAngle * Math.PI / 180;
        const beta = Math.atan(frictionCoef);
        
        // Effective rake angle
        const tanAlphaE = Math.tan(alpha_n) * Math.cos(i);
        const alpha_e = Math.atan(tanAlphaE);
        
        // Chip flow angle (Stabler's rule: η ≈ i)
        const eta = i;
        
        // Shear angle (modified for oblique)
        const phi = Math.PI / 4 + alpha_e / 2 - beta / 2;
        
        // Shear velocity direction
        const Vs = cuttingSpeed * Math.cos(i) / Math.cos(phi - alpha_n);
        
        // Shear plane area
        const As = (width * depth) / (Math.sin(phi) * Math.cos(i));
        
        // Shear force
        const Fs = shearStrength * As;
        
        // Force components
        const Fc = Fs * Math.cos(beta - alpha_e) / (Math.cos(phi + beta - alpha_e) * Math.cos(i));
        const Ft = Fs * Math.sin(beta - alpha_e) / (Math.cos(phi + beta - alpha_e) * Math.cos(eta));
        const Fr = Fc * Math.tan(i) - Ft * Math.tan(eta); // Radial force
        
        // Power
        const power = Fc * cuttingSpeed / 60000; // kW
        
        return {
            effectiveRakeAngle: alpha_e * 180 / Math.PI,
            chipFlowAngle: eta * 180 / Math.PI,
            shearAngle: phi * 180 / Math.PI,
            shearVelocity: Vs,
            cuttingForce: Fc,
            thrustForce: Ft,
            radialForce: Fr,
            resultantForce: Math.sqrt(Fc*Fc + Ft*Ft + Fr*Fr),
            power: power,
            specificEnergy: Fc / (width * depth)
        };
    },
    
    /**
     * Kienzle Cutting Force Model
     * Empirical model widely used in industry
     */
    kienzleForce: function(params) {
        const {
            width,          // mm
            depth,          // mm (chip thickness)
            kc1_1,          // Specific cutting force at h=1mm, b=1mm (N/mm²)
            mc,             // Kienzle exponent (typically 0.2-0.4)
            cuttingSpeed,   // m/min
            rakeAngle = 0,  // degrees
            wearCorrection = 1.0, // VB wear factor
            coolingCorrection = 1.0 // Coolant factor
        } = params;
        
        // Specific cutting force with chip thickness correction
        const kc = kc1_1 / Math.pow(depth, mc);
        
        // Rake angle correction
        const rakeCorrection = 1 - 0.01 * (rakeAngle - 6);
        
        // Final cutting force
        const Fc = kc * width * depth * rakeCorrection * wearCorrection * coolingCorrection;
        
        // Thrust force (typically 0.3-0.5 of Fc)
        const Ft = Fc * 0.4;
        
        // Power
        const power = Fc * cuttingSpeed / 60000; // kW
        
        return {
            specificCuttingForce: kc,
            cuttingForce: Fc,
            thrustForce: Ft,
            power: power,
            corrections: {
                rake: rakeCorrection,
                wear: wearCorrection,
                cooling: coolingCorrection
            }
        };
    },
    
    /**
     * Material Removal Rate
     */
    calculateMRR: function(params) {
        const { cuttingSpeed, feed, depthOfCut, efficiency = 0.9 } = params;
        
        // MRR in mm³/min
        const mrr = cuttingSpeed * 1000 * feed * depthOfCut;
        
        // Effective MRR accounting for air cuts
        const effectiveMRR = mrr * efficiency;
        
        // Convert to cm³/min
        const mrrCm3 = mrr / 1000;
        
        return {
            mrr: mrr,              // mm³/min
            mrrCm3: mrrCm3,        // cm³/min
            effectiveMRR: effectiveMRR,
            volumePerHour: mrr * 60 / 1000000 // liters/hour
        };
    }
};

// ═══════════════════════════════════════════════════════════════════════════════
// SECTION 2: THERMAL MODELING (MIT 2.008, 2.51)
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_THERMAL_MODELING = {
    name: 'PRISM_THERMAL_MODELING',
    version: '1.0.0',
    source: 'MIT 2.008, 2.51 - Thermal Science',
    
    /**
     * Loewen-Shaw Temperature Model
     * Analytical cutting temperature prediction
     * Source: MIT 2.008
     */
    loewenShawTemperature: function(params) {
        const {
            cuttingSpeed,    // m/min
            feed,            // mm/rev
            depthOfCut,      // mm
            specificCuttingForce, // N/mm²
            materialDensity,  // kg/m³
            specificHeat,     // J/(kg·K)
            thermalConductivity, // W/(m·K)
            ambientTemp = 20  // °C
        } = params;
        
        const V = cuttingSpeed / 60; // m/s
        const t = feed; // uncut chip thickness
        const b = depthOfCut;
        
        // Cutting force
        const Fc = specificCuttingForce * t * b;
        
        // Power
        const P = Fc * V; // W
        
        // Thermal diffusivity
        const alpha = thermalConductivity / (materialDensity * specificHeat);
        
        // Peclet number (ratio of convection to conduction)
        const Pe = V * t / (2 * alpha);
        
        // Temperature rise in shear zone (Loewen-Shaw)
        // ΔT = (0.4 * u * V) / (ρ * c * sqrt(α * L))
        const u = specificCuttingForce; // Specific energy
        const L = t; // Characteristic length
        
        const deltaT = (0.4 * u * V * 1e6) / (materialDensity * specificHeat * Math.sqrt(alpha * L / 1000));
        
        // Tool-chip interface temperature (higher)
        // Typically 1.2-1.5x shear zone temperature
        const interfaceTemp = ambientTemp + deltaT * 1.3;
        
        // Maximum tool temperature (slightly lower due to conduction)
        const maxToolTemp = ambientTemp + deltaT * 1.1;
        
        return {
            shearZoneTemp: ambientTemp + deltaT,
            interfaceTemp: interfaceTemp,
            maxToolTemp: maxToolTemp,
            pecletNumber: Pe,
            powerGenerated: P,
            temperatureRise: deltaT,
            heatPartition: {
                chip: 0.75,    // 75% to chip
                tool: 0.15,    // 15% to tool
                workpiece: 0.10 // 10% to workpiece
            }
        };
    },
    
    /**
     * Trigger Equation (Simplified)
     * Quick temperature estimation
     */
    triggerTemperature: function(params) {
        const {
            specificEnergy, // J/mm³
            cuttingSpeed,   // m/min
            thermalNumber   // Non-dimensional thermal number (0.1-1.0)
        } = params;
        
        // θ = C * u^a * V^b
        // Typical values: a=0.9, b=0.3, C depends on material
        const C = 300;
        const a = 0.9;
        const b = 0.3;
        
        const temperature = C * Math.pow(specificEnergy, a) * Math.pow(cuttingSpeed / 100, b) * thermalNumber;
        
        return {
            temperature: temperature,
            criticalTemp: 800, // Typical tool degradation temperature
            safetyMargin: (800 - temperature) / 800 * 100
        };
    },
    
    /**
     * Fourier Heat Conduction (1D Finite Difference)
     * For transient thermal analysis
     */
    fourierConduction1D: function(config) {
        const {
            length,          // Domain length (mm)
            nodes = 50,      // Number of nodes
            timeSteps = 100,
            dt,              // Time step (s)
            thermalDiffusivity, // α = k/(ρ*c)
            initialTemp,     // Initial temperature distribution (array or value)
            leftBC,          // { type: 'dirichlet'|'neumann', value: T or flux }
            rightBC,         // { type: 'dirichlet'|'neumann', value: T or flux }
            heatSource = null // { position, magnitude }
        } = config;
        
        const dx = length / (nodes - 1);
        const Fo = thermalDiffusivity * dt / (dx * dx); // Fourier number
        
        // Stability check
        if (Fo > 0.5) {
            console.warn(`Fourier number ${Fo.toFixed(3)} > 0.5, solution may be unstable`);
        }
        
        // Initialize temperature array
        let T = new Array(nodes);
        if (Array.isArray(initialTemp)) {
            T = [...initialTemp];
        } else {
            T.fill(initialTemp);
        }
        
        const history = [{ time: 0, T: [...T] }];
        
        // Time stepping (explicit method)
        for (let n = 0; n < timeSteps; n++) {
            const Tnew = [...T];
            
            // Interior nodes
            for (let i = 1; i < nodes - 1; i++) {
                Tnew[i] = T[i] + Fo * (T[i+1] - 2*T[i] + T[i-1]);
                
                // Add heat source if present
                if (heatSource && Math.abs((i * dx) - heatSource.position) < dx) {
                    Tnew[i] += heatSource.magnitude * dt;
                }
            }
            
            // Boundary conditions
            if (leftBC.type === 'dirichlet') {
                Tnew[0] = leftBC.value;
            } else { // Neumann
                Tnew[0] = Tnew[1] - leftBC.value * dx;
            }
            
            if (rightBC.type === 'dirichlet') {
                Tnew[nodes-1] = rightBC.value;
            } else { // Neumann
                Tnew[nodes-1] = Tnew[nodes-2] + rightBC.value * dx;
            }
            
            T = Tnew;
            
            if ((n + 1) % 10 === 0) {
                history.push({ time: (n + 1) * dt, T: [...T] });
            }
        }
        
        return {
            finalTemperature: T,
            maxTemp: Math.max(...T),
            minTemp: Math.min(...T),
            history,
            fourierNumber: Fo,
            stable: Fo <= 0.5
        };
    },
    
    /**
     * Thermal Expansion Compensation
     */
    thermalExpansion: function(params) {
        const {
            length,              // mm
            temperatureChange,   // ΔT in °C
            expansionCoefficient // α in 1/°C (e.g., steel: 12e-6)
        } = params;
        
        const expansion = length * expansionCoefficient * temperatureChange;
        
        return {
            expansion: expansion,      // mm
            expansionMicrons: expansion * 1000, // μm
            strainPercent: expansionCoefficient * temperatureChange * 100,
            compensation: -expansion   // Negative to compensate
        };
    }
};

// ═══════════════════════════════════════════════════════════════════════════════
// SECTION 3: TOOL WEAR MODELS (MIT 2.008)
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_TOOL_WEAR_MODELS = {
    name: 'PRISM_TOOL_WEAR_MODELS',
    version: '1.0.0',
    source: 'MIT 2.008 - Tool Wear Theory',
    
    /**
     * Extended Taylor Tool Life
     * V * T^n * f^m * d^p = C
     */
    extendedTaylor: function(params) {
        const {
            cuttingSpeed,    // m/min
            feed,            // mm/rev
            depthOfCut,      // mm
            C,               // Taylor constant
            n,               // Speed exponent (0.1-0.4)
            m = 0.1,         // Feed exponent
            p = 0.1          // Depth exponent
        } = params;
        
        // T = (C / (V * f^m * d^p))^(1/n)
        const T = Math.pow(C / (cuttingSpeed * Math.pow(feed, m) * Math.pow(depthOfCut, p)), 1/n);
        
        // Sensitivity analysis
        const speedSensitivity = -1/n;   // %T / %V
        const feedSensitivity = -m/n;    // %T / %f
        const depthSensitivity = -p/n;   // %T / %d
        
        return {
            toolLife: T,           // minutes
            toolLifeHours: T / 60,
            speedSensitivity,
            feedSensitivity,
            depthSensitivity,
            dominantFactor: Math.abs(speedSensitivity) > Math.abs(feedSensitivity) ? 'speed' : 'feed'
        };
    },
    
    /**
     * Usui's Diffusion Wear Model
     * For crater wear at high temperatures
     */
    usuiWearModel: function(params) {
        const {
            normalStress,     // MPa (on rake face)
            slidingVelocity,  // m/min
            temperature,      // °C (tool-chip interface)
            wearCoefficient = 1e-12, // A (material dependent)
            activationEnergy = 80000, // Q (J/mol)
            gasConstant = 8.314      // R (J/(mol·K))
        } = params;
        
        const T_kelvin = temperature + 273.15;
        const V = slidingVelocity / 60; // m/s
        
        // Usui equation: dW/dt = A * σ * V * exp(-Q/(R*T))
        const wearRate = wearCoefficient * normalStress * V * 
                        Math.exp(-activationEnergy / (gasConstant * T_kelvin));
        
        // Convert to μm/min
        const wearRateMicrons = wearRate * 1e6 * 60;
        
        return {
            wearRate: wearRate,            // m/s
            wearRateMicrons: wearRateMicrons, // μm/min
            temperatureSensitivity: activationEnergy / (gasConstant * T_kelvin * T_kelvin),
            criticalTemp: activationEnergy / (gasConstant * Math.log(wearCoefficient * normalStress * V / 1e-7)) - 273.15
        };
    },
    
    /**
     * Archard Abrasive Wear Model
     * For flank wear
     */
    archardWearModel: function(params) {
        const {
            normalLoad,       // N
            slidingDistance,  // m
            hardness,         // MPa (workpiece hardness)
            wearCoefficient = 1e-4 // K (dimensionless, 1e-4 to 1e-7 typical)
        } = params;
        
        // Archard equation: V = K * F * s / H
        // V = wear volume, K = coefficient, F = load, s = distance, H = hardness
        const wearVolume = wearCoefficient * normalLoad * slidingDistance / hardness;
        
        // Convert to linear wear (assuming wear area)
        const wearArea = 1; // mm² (assumed contact area)
        const linearWear = wearVolume / wearArea;
        
        return {
            wearVolume: wearVolume,      // mm³
            linearWear: linearWear,      // mm
            linearWearMicrons: linearWear * 1000, // μm
            specificWearRate: wearCoefficient / hardness
        };
    },
    
    /**
     * Combined Flank Wear Prediction
     * VB = f(time, speed, feed, material)
     */
    predictFlankWear: function(params) {
        const {
            cuttingTime,      // minutes
            cuttingSpeed,     // m/min
            feed,             // mm/rev
            materialHardness, // HRC or HB
            toolGrade = 'carbide', // 'hss', 'carbide', 'ceramic', 'cbn'
            coolant = true
        } = params;
        
        // Empirical wear coefficients by tool grade
        const coefficients = {
            hss:     { a: 0.001, b: 1.5, c: 0.3 },
            carbide: { a: 0.0003, b: 1.2, c: 0.2 },
            ceramic: { a: 0.0001, b: 0.9, c: 0.15 },
            cbn:     { a: 0.00005, b: 0.7, c: 0.1 }
        };
        
        const { a, b, c } = coefficients[toolGrade] || coefficients.carbide;
        
        // VB = a * t^0.5 * V^b * f^c * (HB/200)
        const hardnessFactor = materialHardness / 200;
        const coolantFactor = coolant ? 0.7 : 1.0;
        
        const VB = a * Math.sqrt(cuttingTime) * Math.pow(cuttingSpeed / 100, b) * 
                   Math.pow(feed / 0.1, c) * hardnessFactor * coolantFactor;
        
        // Typical limits
        const limits = {
            roughing: 0.6,    // mm
            finishing: 0.3,   // mm
            precision: 0.15   // mm
        };
        
        return {
            flankWear: VB,    // mm
            flankWearMicrons: VB * 1000, // μm
            roughingLife: Math.pow(limits.roughing / (a * coolantFactor * hardnessFactor * 
                          Math.pow(cuttingSpeed/100, b) * Math.pow(feed/0.1, c)), 2),
            finishingLife: Math.pow(limits.finishing / (a * coolantFactor * hardnessFactor * 
                           Math.pow(cuttingSpeed/100, b) * Math.pow(feed/0.1, c)), 2),
            status: VB < 0.15 ? 'good' : VB < 0.3 ? 'monitor' : VB < 0.6 ? 'replace_soon' : 'replace_now'
        };
    },
    
    /**
     * Crater Wear Depth
     */
    predictCraterWear: function(params) {
        const {
            cuttingTime,
            temperature,
            normalStress,
            toolMaterial = 'carbide'
        } = params;
        
        // Temperature-dependent crater wear
        const T_kelvin = temperature + 273.15;
        const Q = 80000; // Activation energy J/mol
        const R = 8.314;
        
        // KT = C * t * exp(-Q/RT)
        const C = toolMaterial === 'carbide' ? 1e-5 : 
                  toolMaterial === 'ceramic' ? 5e-6 : 2e-6;
        
        const KT = C * cuttingTime * Math.exp(-Q / (R * T_kelvin)) * normalStress / 1000;
        
        return {
            craterDepth: KT,         // mm
            craterDepthMicrons: KT * 1000, // μm
            criticalDepth: 0.1,      // mm
            remainingLife: KT < 0.1 ? (0.1 - KT) / (KT / cuttingTime) : 0
        };
    }
};

// ═══════════════════════════════════════════════════════════════════════════════
// SECTION 4: VIBRATION & CHATTER (MIT 2.003, 2.14)
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_VIBRATION_ANALYSIS = {
    name: 'PRISM_VIBRATION_ANALYSIS',
    version: '1.0.0',
    source: 'MIT 2.003, 2.14 - Dynamics & Control',
    
    /**
     * Single DOF Vibration Analysis
     */
    singleDOF: function(params) {
        const {
            mass,           // kg
            stiffness,      // N/m
            damping         // N·s/m
        } = params;
        
        // Natural frequency
        const omega_n = Math.sqrt(stiffness / mass); // rad/s
        const f_n = omega_n / (2 * Math.PI);         // Hz
        
        // Damping ratio
        const zeta = damping / (2 * Math.sqrt(stiffness * mass));
        
        // Damped natural frequency
        const omega_d = omega_n * Math.sqrt(1 - zeta * zeta);
        const f_d = omega_d / (2 * Math.PI);
        
        // Quality factor
        const Q = 1 / (2 * zeta);
        
        // Critical damping
        const c_critical = 2 * Math.sqrt(stiffness * mass);
        
        return {
            naturalFrequency: f_n,       // Hz
            naturalFrequencyRad: omega_n, // rad/s
            dampedFrequency: f_d,        // Hz
            dampingRatio: zeta,
            qualityFactor: Q,
            criticalDamping: c_critical,
            dampingType: zeta < 1 ? 'underdamped' : zeta === 1 ? 'critically_damped' : 'overdamped'
        };
    },
    
    /**
     * Frequency Response Function (FRF)
     * Transfer function magnitude and phase
     */
    frequencyResponse: function(params) {
        const {
            mass,
            stiffness,
            damping,
            frequencyRange = [0, 500], // Hz
            numPoints = 200
        } = params;
        
        const omega_n = Math.sqrt(stiffness / mass);
        const zeta = damping / (2 * Math.sqrt(stiffness * mass));
        
        const frequencies = [];
        const magnitude = [];
        const phase = [];
        const realPart = [];
        const imagPart = [];
        
        for (let i = 0; i < numPoints; i++) {
            const f = frequencyRange[0] + (frequencyRange[1] - frequencyRange[0]) * i / (numPoints - 1);
            const omega = 2 * Math.PI * f;
            const r = omega / omega_n;
            
            // H(jω) = 1 / (k * (1 - r² + j*2*ζ*r))
            const denom_real = 1 - r * r;
            const denom_imag = 2 * zeta * r;
            const denom_mag_sq = denom_real * denom_real + denom_imag * denom_imag;
            
            const H_real = denom_real / (stiffness * denom_mag_sq);
            const H_imag = -denom_imag / (stiffness * denom_mag_sq);
            const H_mag = Math.sqrt(H_real * H_real + H_imag * H_imag);
            const H_phase = Math.atan2(H_imag, H_real) * 180 / Math.PI;
            
            frequencies.push(f);
            magnitude.push(H_mag);
            phase.push(H_phase);
            realPart.push(H_real);
            imagPart.push(H_imag);
        }
        
        // Find peak (resonance)
        const maxMag = Math.max(...magnitude);
        const peakIndex = magnitude.indexOf(maxMag);
        
        return {
            frequencies,
            magnitude,
            phase,
            realPart,
            imagPart,
            resonanceFrequency: frequencies[peakIndex],
            peakMagnitude: maxMag,
            staticCompliance: 1 / stiffness
        };
    },
    
    /**
     * Complete Stability Lobe Diagram Generator
     * For chatter prediction
     * Source: MIT 2.14
     */
    stabilityLobeDiagram: function(params) {
        const {
            naturalFrequency, // Hz
            dampingRatio,
            stiffness,        // N/m
            specificCuttingForce, // N/mm²
            numTeeth,         // Number of cutting teeth
            radialImmersion = 1.0, // ae/D ratio
            rpmRange = [1000, 20000],
            numPoints = 100
        } = params;
        
        const omega_n = 2 * Math.PI * naturalFrequency;
        const Ks = specificCuttingForce;
        
        // Average directional factor (depends on radial immersion)
        const phi_s = Math.acos(1 - 2 * radialImmersion);
        const alpha_xx = (1 / (2 * Math.PI)) * (phi_s - Math.sin(2 * phi_s) / 2);
        
        const lobes = [];
        
        // Generate multiple lobes
        for (let k = 0; k < 10; k++) {
            const lobe = { rpm: [], doc: [], lobeNumber: k };
            
            for (let i = 0; i < numPoints; i++) {
                // Phase angle
                const epsilon = -2 * Math.PI * i / numPoints;
                
                // Chatter frequency
                const omega_c = omega_n * Math.sqrt(1 - dampingRatio * dampingRatio);
                
                // Spindle speed for this lobe
                const N = (60 * omega_c) / (2 * Math.PI * (k + epsilon / (2 * Math.PI)) * numTeeth);
                
                if (N >= rpmRange[0] && N <= rpmRange[1]) {
                    // FRF at chatter frequency
                    const r = omega_c / omega_n;
                    const G_real = (1 - r * r) / ((1 - r * r) * (1 - r * r) + (2 * dampingRatio * r) * (2 * dampingRatio * r));
                    const G_imag = (-2 * dampingRatio * r) / ((1 - r * r) * (1 - r * r) + (2 * dampingRatio * r) * (2 * dampingRatio * r));
                    
                    // Stability limit
                    const b_lim = -1 / (2 * Ks * alpha_xx * numTeeth * G_real / stiffness);
                    
                    if (b_lim > 0 && b_lim < 50) { // Reasonable limits
                        lobe.rpm.push(N);
                        lobe.doc.push(b_lim);
                    }
                }
            }
            
            if (lobe.rpm.length > 0) {
                // Sort by RPM
                const sorted = lobe.rpm.map((rpm, i) => ({ rpm, doc: lobe.doc[i] }))
                                       .sort((a, b) => a.rpm - b.rpm);
                lobe.rpm = sorted.map(x => x.rpm);
                lobe.doc = sorted.map(x => x.doc);
                lobes.push(lobe);
            }
        }
        
        // Find sweet spots (local maxima in stability)
        const sweetSpots = [];
        for (const lobe of lobes) {
            for (let i = 1; i < lobe.doc.length - 1; i++) {
                if (lobe.doc[i] > lobe.doc[i-1] && lobe.doc[i] > lobe.doc[i+1]) {
                    sweetSpots.push({ rpm: lobe.rpm[i], maxDoc: lobe.doc[i] });
                }
            }
        }
        sweetSpots.sort((a, b) => b.maxDoc - a.maxDoc);
        
        return {
            lobes,
            sweetSpots: sweetSpots.slice(0, 5),
            parameters: {
                naturalFrequency,
                dampingRatio,
                stiffness,
                specificCuttingForce
            }
        };
    },
    
    /**
     * Chatter Detection from Measured Signal
     * Using FFT analysis
     */
    detectChatter: function(params) {
        const {
            signal,           // Time-domain signal array
            sampleRate,       // Hz
            spindleRPM,
            numTeeth,
            naturalFrequency  // Machine natural frequency
        } = params;
        
        const N = signal.length;
        
        // Simple DFT (for demonstration - use FFT in production)
        const spectrum = [];
        for (let k = 0; k < N / 2; k++) {
            let real = 0, imag = 0;
            for (let n = 0; n < N; n++) {
                const angle = 2 * Math.PI * k * n / N;
                real += signal[n] * Math.cos(angle);
                imag -= signal[n] * Math.sin(angle);
            }
            const magnitude = Math.sqrt(real * real + imag * imag) / N;
            const frequency = k * sampleRate / N;
            spectrum.push({ frequency, magnitude });
        }
        
        // Find peaks
        const peaks = [];
        for (let i = 1; i < spectrum.length - 1; i++) {
            if (spectrum[i].magnitude > spectrum[i-1].magnitude &&
                spectrum[i].magnitude > spectrum[i+1].magnitude &&
                spectrum[i].magnitude > 0.1 * Math.max(...spectrum.map(s => s.magnitude))) {
                peaks.push(spectrum[i]);
            }
        }
        
        // Tooth passing frequency
        const toothPassingFreq = spindleRPM * numTeeth / 60;
        
        // Check for chatter indicators
        const chatterIndicators = peaks.filter(p => {
            const nearNatural = Math.abs(p.frequency - naturalFrequency) < naturalFrequency * 0.1;
            const notHarmonic = peaks.every(h => 
                Math.abs(p.frequency - h.frequency * Math.round(p.frequency / h.frequency)) > 5
            );
            return nearNatural || (p.magnitude > 0.5 * Math.max(...peaks.map(x => x.magnitude)) && notHarmonic);
        });
        
        const chatterDetected = chatterIndicators.length > 0;
        
        return {
            chatterDetected,
            chatterFrequencies: chatterIndicators.map(p => p.frequency),
            dominantFrequency: peaks.length > 0 ? peaks.reduce((a, b) => a.magnitude > b.magnitude ? a : b).frequency : null,
            toothPassingFrequency: toothPassingFreq,
            spectrum: spectrum.filter((_, i) => i % 10 === 0), // Downsample for output
            recommendation: chatterDetected ? 
                `Reduce spindle speed to ${Math.round(spindleRPM * 0.85)} RPM or increase to ${Math.round(spindleRPM * 1.15)} RPM` :
                'Stable cutting conditions'
        };
    }
};

// ═══════════════════════════════════════════════════════════════════════════════
// SECTION 5: STRUCTURAL MECHANICS (MIT 2.001, 2.72)
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_STRUCTURAL_MECHANICS = {
    name: 'PRISM_STRUCTURAL_MECHANICS',
    version: '1.0.0',
    source: 'MIT 2.001, 2.72 - Mechanics of Materials',
    
    /**
     * Hertz Contact Mechanics
     * Sphere-on-flat and cylinder-on-flat
     */
    hertzContact: function(params) {
        const {
            type = 'sphere_flat', // 'sphere_flat', 'cylinder_flat', 'sphere_sphere'
            load,                 // N
            radius1,              // mm (sphere or cylinder radius)
            radius2 = Infinity,   // mm (second body radius, Infinity for flat)
            E1,                   // MPa (Young's modulus body 1)
            E2,                   // MPa (Young's modulus body 2)
            nu1 = 0.3,           // Poisson's ratio body 1
            nu2 = 0.3,           // Poisson's ratio body 2
            length = 1           // mm (for cylinder contact)
        } = params;
        
        // Effective modulus
        const E_star = 1 / ((1 - nu1*nu1) / E1 + (1 - nu2*nu2) / E2);
        
        // Effective radius
        const R_eff = 1 / (1/radius1 + (radius2 === Infinity ? 0 : 1/radius2));
        
        let contactRadius, maxPressure, maxShearStress, approach;
        
        if (type === 'sphere_flat' || type === 'sphere_sphere') {
            // Hertz sphere contact
            contactRadius = Math.pow((3 * load * R_eff) / (4 * E_star), 1/3);
            maxPressure = (3 * load) / (2 * Math.PI * contactRadius * contactRadius);
            maxShearStress = 0.31 * maxPressure; // At depth z = 0.48a
            approach = Math.pow(contactRadius, 2) / R_eff;
            
        } else if (type === 'cylinder_flat') {
            // Hertz cylinder contact
            const halfWidth = Math.sqrt((4 * load * R_eff) / (Math.PI * E_star * length));
            contactRadius = halfWidth;
            maxPressure = (2 * load) / (Math.PI * halfWidth * length);
            maxShearStress = 0.30 * maxPressure;
            approach = (load / (Math.PI * E_star * length)) * (Math.log(4 * R_eff / halfWidth) + 0.5);
        }
        
        return {
            contactRadius: contactRadius,     // mm
            contactArea: Math.PI * contactRadius * contactRadius, // mm²
            maxPressure: maxPressure,         // MPa
            meanPressure: maxPressure * 2/3,  // MPa
            maxShearStress: maxShearStress,   // MPa
            approach: approach,               // mm (elastic deformation)
            effectiveModulus: E_star,
            effectiveRadius: R_eff
        };
    },
    
    /**
     * Stress Concentration Factors
     */
    stressConcentration: function(params) {
        const {
            type,    // 'hole', 'fillet', 'groove', 'shoulder'
            geometry // Type-specific parameters
        } = params;
        
        let Kt;
        
        switch (type) {
            case 'hole':
                // Circular hole in infinite plate
                Kt = 3.0;
                break;
                
            case 'fillet':
                // Shoulder fillet
                const { D, d, r } = geometry; // Major diameter, minor diameter, fillet radius
                const ratio_D_d = D / d;
                const ratio_r_d = r / d;
                // Peterson's formula approximation
                Kt = 1 + (ratio_D_d - 1) * (0.27 + 1.57 * Math.sqrt(ratio_D_d - 1)) / 
                     (1 + 0.775 * Math.pow(ratio_r_d, 0.5));
                Kt = Math.min(Kt, 3.5); // Cap at reasonable value
                break;
                
            case 'groove':
                // U-groove in shaft
                const { D_g, d_g, r_g } = geometry;
                Kt = 1 + 2 * Math.sqrt((D_g - d_g) / (2 * r_g));
                break;
                
            case 'shoulder':
                // Sharp shoulder
                Kt = 2.5;
                break;
                
            default:
                Kt = 1.5;
        }
        
        return {
            Kt: Kt,
            stressMultiplier: Kt,
            recommendation: Kt > 2 ? 'Add fillet radius to reduce concentration' : 'Acceptable'
        };
    },
    
    /**
     * Goodman Fatigue Analysis
     * Modified Goodman diagram for fatigue life
     */
    goodmanFatigue: function(params) {
        const {
            meanStress,        // MPa
            alternatingStress, // MPa
            ultimateStrength,  // MPa
            yieldStrength,     // MPa
            enduranceLimit,    // MPa (Se' = 0.5*Sut for steel)
            Kt = 1,           // Stress concentration
            Kf = null,        // Fatigue stress concentration (calculated if null)
            surfaceFactor = 0.9,   // ka
            sizeFactor = 0.85,     // kb
            loadFactor = 1.0,      // kc
            tempFactor = 1.0,      // kd
            reliabilityFactor = 0.814 // ke (99% reliability)
        } = params;
        
        // Modified endurance limit
        const Se = surfaceFactor * sizeFactor * loadFactor * tempFactor * reliabilityFactor * enduranceLimit;
        
        // Fatigue stress concentration (notch sensitivity)
        let Kf_calc;
        if (Kf === null) {
            // Peterson's equation: Kf = 1 + q*(Kt - 1)
            // q depends on material and notch radius, assume q = 0.8
            const q = 0.8;
            Kf_calc = 1 + q * (Kt - 1);
        } else {
            Kf_calc = Kf;
        }
        
        // Corrected stresses
        const sigma_a = Kf_calc * alternatingStress;
        const sigma_m = Kf_calc * meanStress;
        
        // Modified Goodman criterion
        // σa/Se + σm/Sut = 1/n
        const goodmanFactor = sigma_a / Se + sigma_m / ultimateStrength;
        const safetyFactor = 1 / goodmanFactor;
        
        // Yield criterion (Langer)
        const yieldFactor = (sigma_a + sigma_m) / yieldStrength;
        const yieldSafety = 1 / yieldFactor;
        
        // Determine failure mode
        const failureMode = safetyFactor < yieldSafety ? 'fatigue' : 'yield';
        const criticalSafety = Math.min(safetyFactor, yieldSafety);
        
        return {
            modifiedEnduranceLimit: Se,
            fatigueConcentration: Kf_calc,
            correctedAlternatingStress: sigma_a,
            correctedMeanStress: sigma_m,
            goodmanSafetyFactor: safetyFactor,
            yieldSafetyFactor: yieldSafety,
            criticalSafetyFactor: criticalSafety,
            failureMode,
            safe: criticalSafety > 1.5,
            recommendation: criticalSafety < 1 ? 'FAILURE PREDICTED - Redesign required' :
                           criticalSafety < 1.5 ? 'Marginal safety - Consider redesign' :
                           criticalSafety < 2 ? 'Acceptable for non-critical applications' :
                           'Safe design'
        };
    },
    
    /**
     * Euler Buckling Analysis
     */
    eulerBuckling: function(params) {
        const {
            length,           // mm
            momentOfInertia,  // mm⁴
            youngsModulus,    // MPa
            endCondition = 'pinned_pinned', // 'fixed_fixed', 'fixed_free', 'fixed_pinned', 'pinned_pinned'
            crossSectionArea, // mm²
            appliedLoad       // N (optional, for safety factor)
        } = params;
        
        // Effective length factor (K)
        const K = {
            'fixed_fixed': 0.5,
            'fixed_pinned': 0.7,
            'pinned_pinned': 1.0,
            'fixed_free': 2.0
        }[endCondition] || 1.0;
        
        // Effective length
        const Le = K * length;
        
        // Critical buckling load
        const Pcr = Math.PI * Math.PI * youngsModulus * momentOfInertia / (Le * Le);
        
        // Slenderness ratio
        const radiusOfGyration = Math.sqrt(momentOfInertia / crossSectionArea);
        const slenderness = Le / radiusOfGyration;
        
        // Critical stress
        const sigmaCr = Pcr / crossSectionArea;
        
        // Safety factor if load given
        let safetyFactor = null;
        if (appliedLoad) {
            safetyFactor = Pcr / appliedLoad;
        }
        
        return {
            criticalLoad: Pcr,        // N
            criticalStress: sigmaCr,  // MPa
            effectiveLength: Le,      // mm
            slendernessRatio: slenderness,
            radiusOfGyration: radiusOfGyration,
            safetyFactor,
            recommendation: slenderness > 120 ? 'Long column - Euler valid' :
                           slenderness > 60 ? 'Intermediate - Use Johnson formula' :
                           'Short column - Yielding governs'
        };
    }
};

// ═══════════════════════════════════════════════════════════════════════════════
// SECTION 6: DYNAMICS (MIT 2.003)
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_DYNAMICS = {
    name: 'PRISM_DYNAMICS',
    version: '1.0.0',
    source: 'MIT 2.003 - Dynamics and Control I',
    
    /**
     * Newton-Euler Dynamics for Rigid Body
     */
    newtonEulerDynamics: function(params) {
        const {
            mass,             // kg
            inertiaMatrix,    // 3x3 matrix [Ixx, Ixy, Ixz; Iyx, Iyy, Iyz; Izx, Izy, Izz]
            angularVelocity,  // [wx, wy, wz] rad/s
            angularAccel,     // [αx, αy, αz] rad/s²
            externalForce,    // [Fx, Fy, Fz] N
            externalMoment,   // [Mx, My, Mz] N·m
            comPosition,      // [x, y, z] Center of mass position
            comVelocity,      // [vx, vy, vz] m/s
            comAccel          // [ax, ay, az] m/s²
        } = params;
        
        // Newton's equation: F = m*a
        const netForce = [
            externalForce[0] - mass * comAccel[0],
            externalForce[1] - mass * comAccel[1],
            externalForce[2] - mass * comAccel[2]
        ];
        
        // Euler's equation: M = I*α + ω × (I*ω)
        // I*ω
        const I = inertiaMatrix;
        const w = angularVelocity;
        const Iw = [
            I[0][0]*w[0] + I[0][1]*w[1] + I[0][2]*w[2],
            I[1][0]*w[0] + I[1][1]*w[1] + I[1][2]*w[2],
            I[2][0]*w[0] + I[2][1]*w[1] + I[2][2]*w[2]
        ];
        
        // ω × (I*ω)
        const wxIw = [
            w[1]*Iw[2] - w[2]*Iw[1],
            w[2]*Iw[0] - w[0]*Iw[2],
            w[0]*Iw[1] - w[1]*Iw[0]
        ];
        
        // I*α
        const alpha = angularAccel;
        const Ialpha = [
            I[0][0]*alpha[0] + I[0][1]*alpha[1] + I[0][2]*alpha[2],
            I[1][0]*alpha[0] + I[1][1]*alpha[1] + I[1][2]*alpha[2],
            I[2][0]*alpha[0] + I[2][1]*alpha[1] + I[2][2]*alpha[2]
        ];
        
        // Required moment = I*α + ω×(I*ω)
        const requiredMoment = [
            Ialpha[0] + wxIw[0],
            Ialpha[1] + wxIw[1],
            Ialpha[2] + wxIw[2]
        ];
        
        // Net moment (external - required)
        const netMoment = [
            externalMoment[0] - requiredMoment[0],
            externalMoment[1] - requiredMoment[1],
            externalMoment[2] - requiredMoment[2]
        ];
        
        // Kinetic energy
        const T_trans = 0.5 * mass * (comVelocity[0]**2 + comVelocity[1]**2 + comVelocity[2]**2);
        const T_rot = 0.5 * (w[0]*Iw[0] + w[1]*Iw[1] + w[2]*Iw[2]);
        
        return {
            netForce,
            netMoment,
            gyroscopicMoment: wxIw,
            kineticEnergyTranslational: T_trans,
            kineticEnergyRotational: T_rot,
            totalKineticEnergy: T_trans + T_rot,
            angularMomentum: Iw
        };
    },
    
    /**
     * Inertia Matrix Computation for Common Shapes
     */
    computeInertiaMatrix: function(params) {
        const {
            shape,    // 'cylinder', 'sphere', 'box', 'rod'
            mass,     // kg
            dimensions // Shape-specific: {radius, length} or {a, b, c}
        } = params;
        
        let I;
        
        switch (shape) {
            case 'cylinder':
                // Solid cylinder about its axis
                const { radius, length } = dimensions;
                const Izz = 0.5 * mass * radius * radius;
                const Ixx = mass * (3 * radius * radius + length * length) / 12;
                I = [
                    [Ixx, 0, 0],
                    [0, Ixx, 0],
                    [0, 0, Izz]
                ];
                break;
                
            case 'sphere':
                // Solid sphere
                const r = dimensions.radius;
                const I_sphere = 0.4 * mass * r * r;
                I = [
                    [I_sphere, 0, 0],
                    [0, I_sphere, 0],
                    [0, 0, I_sphere]
                ];
                break;
                
            case 'box':
                // Rectangular box
                const { a, b, c } = dimensions; // width, height, depth
                I = [
                    [mass * (b*b + c*c) / 12, 0, 0],
                    [0, mass * (a*a + c*c) / 12, 0],
                    [0, 0, mass * (a*a + b*b) / 12]
                ];
                break;
                
            case 'rod':
                // Slender rod about center
                const L = dimensions.length;
                const I_rod = mass * L * L / 12;
                I = [
                    [I_rod, 0, 0],
                    [0, I_rod, 0],
                    [0, 0, 0]
                ];
                break;
                
            default:
                I = [[1, 0, 0], [0, 1, 0], [0, 0, 1]];
        }
        
        return {
            inertiaMatrix: I,
            principalMoments: [I[0][0], I[1][1], I[2][2]],
            trace: I[0][0] + I[1][1] + I[2][2]
        };
    },
    
    /**
     * Coriolis and Centrifugal Terms
     * For rotating reference frames
     */
    coriolisEffect: function(params) {
        const {
            angularVelocity, // [wx, wy, wz] rad/s of rotating frame
            velocity,        // [vx, vy, vz] m/s relative velocity in rotating frame
            position,        // [x, y, z] m position in rotating frame
            mass            // kg
        } = params;
        
        const w = angularVelocity;
        const v = velocity;
        const r = position;
        
        // Coriolis acceleration: -2 * ω × v
        const coriolisAccel = [
            -2 * (w[1]*v[2] - w[2]*v[1]),
            -2 * (w[2]*v[0] - w[0]*v[2]),
            -2 * (w[0]*v[1] - w[1]*v[0])
        ];
        
        // Centrifugal acceleration: -ω × (ω × r)
        // First compute ω × r
        const wxr = [
            w[1]*r[2] - w[2]*r[1],
            w[2]*r[0] - w[0]*r[2],
            w[0]*r[1] - w[1]*r[0]
        ];
        
        // Then -ω × (ω × r)
        const centrifugalAccel = [
            -(w[1]*wxr[2] - w[2]*wxr[1]),
            -(w[2]*wxr[0] - w[0]*wxr[2]),
            -(w[0]*wxr[1] - w[1]*wxr[0])
        ];
        
        // Forces
        const coriolisForce = coriolisAccel.map(a => mass * a);
        const centrifugalForce = centrifugalAccel.map(a => mass * a);
        
        return {
            coriolisAcceleration: coriolisAccel,
            centrifugalAcceleration: centrifugalAccel,
            coriolisForce,
            centrifugalForce,
            totalFictitiousForce: [
                coriolisForce[0] + centrifugalForce[0],
                coriolisForce[1] + centrifugalForce[1],
                coriolisForce[2] + centrifugalForce[2]
            ]
        };
    }
};

// ═══════════════════════════════════════════════════════════════════════════════
// SECTION 7: MANUFACTURING APPLICATIONS (SESSION 4)
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_MFG_PHYSICS = {
    name: 'PRISM_MFG_PHYSICS',
    version: '1.0.0',
    source: 'PRISM Innovation - Manufacturing Physics',
    
    /**
     * Complete Cutting Analysis
     * Combines force, temperature, and wear prediction
     */
    completeCuttingAnalysis: function(params) {
        const {
            material,         // {shearStrength, density, specificHeat, thermalConductivity, hardness}
            tool,            // {rakeAngle, diameter, noseRadius, grade}
            cutting          // {speed, feed, depthOfCut, width}
        } = params;
        
        const { speed, feed, depthOfCut, width } = cutting;
        
        // Force analysis
        const forces = PRISM_CUTTING_MECHANICS.merchantCircle({
            width: width || depthOfCut,
            depth: feed,
            rakeAngle: tool.rakeAngle || 6,
            frictionCoef: 0.5,
            shearStrength: material.shearStrength || 400
        });
        
        // Add power
        forces.power = forces.cuttingForce * speed / 60000; // kW
        
        // Thermal analysis
        const thermal = PRISM_THERMAL_MODELING.loewenShawTemperature({
            cuttingSpeed: speed,
            feed: feed,
            depthOfCut: depthOfCut,
            specificCuttingForce: forces.specificCuttingEnergy,
            materialDensity: material.density || 7850,
            specificHeat: material.specificHeat || 500,
            thermalConductivity: material.thermalConductivity || 50
        });
        
        // Tool life prediction
        const toolLife = PRISM_TOOL_WEAR_MODELS.extendedTaylor({
            cuttingSpeed: speed,
            feed: feed,
            depthOfCut: depthOfCut,
            C: 300,
            n: tool.grade === 'ceramic' ? 0.4 : tool.grade === 'carbide' ? 0.25 : 0.15,
            m: 0.1,
            p: 0.1
        });
        
        // Flank wear prediction at 15 min
        const wear = PRISM_TOOL_WEAR_MODELS.predictFlankWear({
            cuttingTime: 15,
            cuttingSpeed: speed,
            feed: feed,
            materialHardness: material.hardness || 200,
            toolGrade: tool.grade || 'carbide'
        });
        
        // MRR
        const mrr = PRISM_CUTTING_MECHANICS.calculateMRR({
            cuttingSpeed: speed,
            feed: feed,
            depthOfCut: depthOfCut
        });
        
        return {
            forces: {
                cutting: forces.cuttingForce,
                thrust: forces.thrustForce,
                resultant: forces.resultantForce,
                power: forces.power,
                specificEnergy: forces.specificCuttingEnergy
            },
            thermal: {
                shearZoneTemp: thermal.shearZoneTemp,
                interfaceTemp: thermal.interfaceTemp,
                maxToolTemp: thermal.maxToolTemp
            },
            toolLife: {
                minutes: toolLife.toolLife,
                hours: toolLife.toolLifeHours
            },
            wear: {
                flankWear15min: wear.flankWear,
                status: wear.status
            },
            mrr: {
                value: mrr.mrr,
                cm3PerMin: mrr.mrrCm3
            },
            recommendations: this._generateRecommendations(forces, thermal, toolLife, wear)
        };
    },
    
    _generateRecommendations: function(forces, thermal, toolLife, wear) {
        const recs = [];
        
        if (thermal.maxToolTemp > 700) {
            recs.push('High temperature detected - Consider reducing speed or adding coolant');
        }
        
        if (toolLife.toolLife < 15) {
            recs.push('Short tool life - Reduce cutting speed by 10-20%');
        }
        
        if (forces.power > 10) {
            recs.push('High power consumption - Verify machine capability');
        }
        
        if (wear.status === 'replace_soon' || wear.status === 'replace_now') {
            recs.push('Monitor tool wear closely or replace tool');
        }
        
        if (recs.length === 0) {
            recs.push('Operating parameters within acceptable ranges');
        }
        
        return recs;
    },
    
    /**
     * Machine Dynamics Check
     * Verify cutting parameters against machine limits
     */
    checkMachineDynamics: function(params) {
        const {
            machine,    // {maxRPM, maxPower, maxTorque, naturalFrequency, dampingRatio, stiffness}
            tool,       // {diameter, numFlutes, overhang}
            cutting     // {speed, feed, depthOfCut}
        } = params;
        
        // Calculate RPM
        const rpm = (cutting.speed * 1000) / (Math.PI * tool.diameter);
        
        // Check power
        const estimatedPower = cutting.speed * cutting.feed * cutting.depthOfCut * 2.5 / 60000;
        const powerOK = estimatedPower <= machine.maxPower;
        
        // Check torque
        const estimatedTorque = (estimatedPower * 1000 * 60) / (2 * Math.PI * rpm);
        const torqueOK = estimatedTorque <= machine.maxTorque;
        
        // Stability check
        let stabilityOK = true;
        let sweetSpotRPM = null;
        
        if (machine.naturalFrequency && machine.dampingRatio && machine.stiffness) {
            const sld = PRISM_VIBRATION_ANALYSIS.stabilityLobeDiagram({
                naturalFrequency: machine.naturalFrequency,
                dampingRatio: machine.dampingRatio,
                stiffness: machine.stiffness,
                specificCuttingForce: 2500,
                numTeeth: tool.numFlutes || 4,
                rpmRange: [rpm * 0.5, rpm * 1.5]
            });
            
            // Find if current RPM/DOC is stable
            for (const lobe of sld.lobes) {
                for (let i = 0; i < lobe.rpm.length; i++) {
                    if (Math.abs(lobe.rpm[i] - rpm) < 100) {
                        if (cutting.depthOfCut > lobe.doc[i]) {
                            stabilityOK = false;
                        }
                    }
                }
            }
            
            if (sld.sweetSpots.length > 0) {
                sweetSpotRPM = sld.sweetSpots[0].rpm;
            }
        }
        
        return {
            rpm,
            rpmOK: rpm <= machine.maxRPM,
            estimatedPower,
            powerOK,
            estimatedTorque,
            torqueOK,
            stabilityOK,
            sweetSpotRPM,
            overallOK: rpm <= machine.maxRPM && powerOK && torqueOK && stabilityOK,
            recommendations: !stabilityOK ? [`Consider RPM ${sweetSpotRPM?.toFixed(0)} for better stability`] : []
        };
    }
};

