        const faces = [[0, 1, 3], [1, 2, 3], [0, 3, 2]];
        
        const smoothed = PRISM_MESH_SMOOTHING.laplacianSmooth(vertices, faces, 0.5, 3);
        
        // Check that center vertex moved
