const PRISM_OPTIMIZATION_ALGORITHMS = {
    name: 'PRISM Optimization Algorithms',
    version: '1.0.0',
    sources: ['MIT 6.251J', 'MIT 15.099', 'MIT 18.433', 'Stanford AA222', 'CMU 10-725', 'Berkeley EECS127'],
    algorithmCount: 100,

    // ─────────────────────────────────────────────────────────────────────────────
    // 1.1 GRADIENT-BASED METHODS
    // ─────────────────────────────────────────────────────────────────────────────
    
    /**
     * Gradient Descent with multiple variants
     * Source: MIT 15.099 Optimization Methods
     */
    gradientDescent: function(f, grad, x0, options = {}) {
        const maxIter = options.maxIter || 1000;
        const tol = options.tol || 1e-8;
        const alpha = options.learningRate || 0.01;
        const momentum = options.momentum || 0;
        const variant = options.variant || 'vanilla'; // vanilla, momentum, nesterov, adam
        
        let x = Array.isArray(x0) ? [...x0] : [x0];
        let v = new Array(x.length).fill(0); // velocity for momentum
        let m = new Array(x.length).fill(0); // first moment (Adam)
        let vAdam = new Array(x.length).fill(0); // second moment (Adam)
        const beta1 = 0.9, beta2 = 0.999, epsilon = 1e-8;
        
        const history = [];
        
        for (let iter = 0; iter < maxIter; iter++) {
            const g = grad(x);
            const fVal = f(x);
            history.push({ iter, x: [...x], f: fVal, gradNorm: this._norm(g) });
            
            if (this._norm(g) < tol) break;
            
            switch (variant) {
                case 'momentum':
                    for (let i = 0; i < x.length; i++) {
                        v[i] = momentum * v[i] - alpha * g[i];
                        x[i] += v[i];
                    }
                    break;
                    
                case 'nesterov':
                    const xLookahead = x.map((xi, i) => xi + momentum * v[i]);
                    const gLookahead = grad(xLookahead);
                    for (let i = 0; i < x.length; i++) {
                        v[i] = momentum * v[i] - alpha * gLookahead[i];
                        x[i] += v[i];
                    }
                    break;
                    
                case 'adam':
                    const t = iter + 1;
                    for (let i = 0; i < x.length; i++) {
                        m[i] = beta1 * m[i] + (1 - beta1) * g[i];
                        vAdam[i] = beta2 * vAdam[i] + (1 - beta2) * g[i] * g[i];
                        const mHat = m[i] / (1 - Math.pow(beta1, t));
                        const vHat = vAdam[i] / (1 - Math.pow(beta2, t));
                        x[i] -= alpha * mHat / (Math.sqrt(vHat) + epsilon);
                    }
                    break;
                    
                default: // vanilla
                    for (let i = 0; i < x.length; i++) {
                        x[i] -= alpha * g[i];
                    }
            }
        }
        
        return { x, f: f(x), iterations: history.length, history, converged: this._norm(grad(x)) < tol };
    },

    /**
     * Newton's Method with line search
     * Source: MIT 6.251J Mathematical Programming
     */
    newtonMethod: function(f, grad, hessian, x0, options = {}) {
        const maxIter = options.maxIter || 100;
        const tol = options.tol || 1e-10;
        const lineSearch = options.lineSearch !== false;
        
        let x = Array.isArray(x0) ? [...x0] : [x0];
        const n = x.length;
        const history = [];
        
        for (let iter = 0; iter < maxIter; iter++) {
            const g = grad(x);
            const H = hessian(x);
            const fVal = f(x);
            
            history.push({ iter, x: [...x], f: fVal, gradNorm: this._norm(g) });
            
            if (this._norm(g) < tol) break;
            
            // Solve H * d = -g for Newton direction
            const d = this._solveLinearSystem(H, g.map(gi => -gi));
            
            // Line search (backtracking)
            let alpha = 1.0;
            if (lineSearch) {
                const c = 0.0001;
                const rho = 0.5;
                while (f(x.map((xi, i) => xi + alpha * d[i])) > fVal + c * alpha * this._dot(g, d)) {
                    alpha *= rho;
                    if (alpha < 1e-16) break;
                }
            }
            
            // Update
            for (let i = 0; i < n; i++) {
                x[i] += alpha * d[i];
            }
        }
        
        return { x, f: f(x), iterations: history.length, history, converged: this._norm(grad(x)) < tol };
    },

    /**
     * BFGS Quasi-Newton Method
     * Source: MIT 15.099, Stanford EE364a
     */
    bfgs: function(f, grad, x0, options = {}) {
        const maxIter = options.maxIter || 200;
        const tol = options.tol || 1e-8;
        
        let x = Array.isArray(x0) ? [...x0] : [x0];
        const n = x.length;
        
        // Initialize inverse Hessian approximation as identity
        let H = [];
        for (let i = 0; i < n; i++) {
            H[i] = new Array(n).fill(0);
            H[i][i] = 1;
        }
        
        const history = [];
        
        for (let iter = 0; iter < maxIter; iter++) {
            const g = grad(x);
            const fVal = f(x);
            
            history.push({ iter, x: [...x], f: fVal, gradNorm: this._norm(g) });
            
            if (this._norm(g) < tol) break;
            
            // Search direction: d = -H * g
            const d = this._matVecMult(H, g.map(gi => -gi));
            
            // Line search
            let alpha = 1.0;
            const c = 0.0001;
            const rho = 0.5;
            while (f(x.map((xi, i) => xi + alpha * d[i])) > fVal + c * alpha * this._dot(g, d)) {
                alpha *= rho;
                if (alpha < 1e-16) break;
            }
            
            // Update x
            const xNew = x.map((xi, i) => xi + alpha * d[i]);
            const s = xNew.map((xni, i) => xni - x[i]);
            const gNew = grad(xNew);
            const y = gNew.map((gni, i) => gni - g[i]);
            
            // BFGS update for inverse Hessian
            const rho_k = 1 / this._dot(y, s);
            if (isFinite(rho_k)) {
                const I = [];
                for (let i = 0; i < n; i++) {
                    I[i] = new Array(n).fill(0);
                    I[i][i] = 1;
                }
                
                // H = (I - rho*s*y') * H * (I - rho*y*s') + rho*s*s'
                const sy = this._outerProduct(s, y);
                const ys = this._outerProduct(y, s);
                const ss = this._outerProduct(s, s);
                
                const M1 = this._matSubtract(I, this._matScale(sy, rho_k));
                const M2 = this._matSubtract(I, this._matScale(ys, rho_k));
                
                H = this._matAdd(
                    this._matMult(this._matMult(M1, H), M2),
                    this._matScale(ss, rho_k)
                );
            }
            
            x = xNew;
        }
        
        return { x, f: f(x), iterations: history.length, history, converged: this._norm(grad(x)) < tol };
    },

    /**
     * Conjugate Gradient Method
     * Source: MIT 18.086 Computational Science
     */
    conjugateGradient: function(f, grad, x0, options = {}) {
        const maxIter = options.maxIter || 1000;
        const tol = options.tol || 1e-8;
        const variant = options.variant || 'fletcher-reeves'; // fletcher-reeves, polak-ribiere
        
        let x = Array.isArray(x0) ? [...x0] : [x0];
        let g = grad(x);
        let d = g.map(gi => -gi);
        
        const history = [];
        
        for (let iter = 0; iter < maxIter; iter++) {
            const fVal = f(x);
            history.push({ iter, x: [...x], f: fVal, gradNorm: this._norm(g) });
            
            if (this._norm(g) < tol) break;
            
            // Line search
            let alpha = this._lineSearch(f, x, d);
            
            // Update x
            const xNew = x.map((xi, i) => xi + alpha * d[i]);
            const gNew = grad(xNew);
            
            // Compute beta
            let beta;
            if (variant === 'polak-ribiere') {
                const yDotG = this._dot(gNew.map((gni, i) => gni - g[i]), gNew);
                const gDotG = this._dot(g, g);
                beta = Math.max(0, yDotG / gDotG);
            } else { // fletcher-reeves
                beta = this._dot(gNew, gNew) / this._dot(g, g);
            }
            
            // Update direction
            d = gNew.map((gni, i) => -gni + beta * d[i]);
            
            x = xNew;
            g = gNew;
        }
        
        return { x, f: f(x), iterations: history.length, history, converged: this._norm(grad(x)) < tol };
    },

    // ─────────────────────────────────────────────────────────────────────────────
    // 1.2 CONSTRAINED OPTIMIZATION
    // ─────────────────────────────────────────────────────────────────────────────

    /**
     * Interior Point Method (Barrier Method)
     * Source: MIT 6.251J, Stanford EE364a
     */
    interiorPoint: function(f, grad, constraints, x0, options = {}) {
        const maxIter = options.maxIter || 100;
        const tol = options.tol || 1e-8;
        let mu = options.mu || 10; // barrier parameter
        const muFactor = options.muFactor || 0.1;
        
        let x = Array.isArray(x0) ? [...x0] : [x0];
        const history = [];
        
        // Barrier function: f(x) - mu * sum(log(-g_i(x)))
        const barrierFunc = (x, mu) => {
            let barrier = f(x);
            for (const c of constraints) {
                const cVal = c(x);
                if (cVal >= 0) return Infinity; // infeasible
                barrier -= mu * Math.log(-cVal);
            }
            return barrier;
        };
        
        const barrierGrad = (x, mu) => {
            const g = grad(x);
            for (const c of constraints) {
                const cVal = c(x);
                const cGrad = this._numericalGradient(c, x);
                for (let i = 0; i < x.length; i++) {
                    g[i] -= mu * cGrad[i] / cVal;
                }
            }
            return g;
        };
        
        for (let outer = 0; outer < maxIter; outer++) {
            // Inner Newton iterations
            for (let inner = 0; inner < 50; inner++) {
                const g = barrierGrad(x, mu);
                if (this._norm(g) < tol * mu) break;
                
                // Simple gradient step (could use Newton)
                const alpha = this._lineSearch(
                    (x) => barrierFunc(x, mu),
                    x,
                    g.map(gi => -gi)
                );
                
                x = x.map((xi, i) => xi - alpha * g[i]);
            }
            
            history.push({ outer, mu, x: [...x], f: f(x) });
            
            // Check convergence
            if (mu * constraints.length < tol) break;
            
            // Decrease barrier parameter
            mu *= muFactor;
        }
        
        return { x, f: f(x), iterations: history.length, history };
    },

    /**
     * Penalty Method for Constrained Optimization
     * Source: MIT 15.099
     */
    penaltyMethod: function(f, grad, constraints, x0, options = {}) {
        const maxIter = options.maxIter || 50;
        let rho = options.rho || 1; // penalty parameter
        const rhoFactor = options.rhoFactor || 10;
        const tol = options.tol || 1e-6;
        
        let x = Array.isArray(x0) ? [...x0] : [x0];
        const history = [];
        
        // Penalty function: f(x) + (rho/2) * sum(max(0, g_i(x))^2)
        const penaltyFunc = (x, rho) => {
            let penalty = f(x);
            for (const c of constraints) {
                const violation = Math.max(0, c(x));
                penalty += (rho / 2) * violation * violation;
            }
            return penalty;
        };
        
        for (let iter = 0; iter < maxIter; iter++) {
            // Minimize penalized objective
            const result = this.gradientDescent(
                (x) => penaltyFunc(x, rho),
                (x) => this._numericalGradient((x) => penaltyFunc(x, rho), x),
                x,
                { maxIter: 100, learningRate: 0.01 }
            );
            
            x = result.x;
            
            // Check constraint violations
            let maxViolation = 0;
            for (const c of constraints) {
                maxViolation = Math.max(maxViolation, Math.max(0, c(x)));
            }
            
            history.push({ iter, rho, x: [...x], f: f(x), maxViolation });
            
            if (maxViolation < tol) break;
            
            rho *= rhoFactor;
        }
        
        return { x, f: f(x), iterations: history.length, history };
    },

    /**
     * Augmented Lagrangian Method
     * Source: CMU 10-725 Convex Optimization
     */
    augmentedLagrangian: function(f, grad, eqConstraints, ineqConstraints, x0, options = {}) {
        const maxIter = options.maxIter || 50;
        let rho = options.rho || 1;
        const rhoFactor = options.rhoFactor || 2;
        const tol = options.tol || 1e-6;
        
        let x = Array.isArray(x0) ? [...x0] : [x0];
        let lambdaEq = new Array(eqConstraints.length).fill(0);
        let lambdaIneq = new Array(ineqConstraints.length).fill(0);
        
        const history = [];
        
        for (let iter = 0; iter < maxIter; iter++) {
            // Augmented Lagrangian function
            const augLag = (x) => {
                let val = f(x);
                
                // Equality constraints: lambda * h + (rho/2) * h^2
                for (let i = 0; i < eqConstraints.length; i++) {
                    const h = eqConstraints[i](x);
                    val += lambdaEq[i] * h + (rho / 2) * h * h;
                }
                
                // Inequality constraints: (rho/2) * max(0, g + lambda/rho)^2 - lambda^2/(2*rho)
                for (let i = 0; i < ineqConstraints.length; i++) {
                    const g = ineqConstraints[i](x);
                    const term = Math.max(0, g + lambdaIneq[i] / rho);
                    val += (rho / 2) * term * term - lambdaIneq[i] * lambdaIneq[i] / (2 * rho);
                }
                
                return val;
            };
            
            // Minimize augmented Lagrangian
            const result = this.bfgs(
                augLag,
                (x) => this._numericalGradient(augLag, x),
                x,
                { maxIter: 50 }
            );
            
            x = result.x;
            
            // Update multipliers
            for (let i = 0; i < eqConstraints.length; i++) {
                lambdaEq[i] += rho * eqConstraints[i](x);
            }
            for (let i = 0; i < ineqConstraints.length; i++) {
                lambdaIneq[i] = Math.max(0, lambdaIneq[i] + rho * ineqConstraints[i](x));
            }
            
            // Check convergence
            let maxViolation = 0;
            for (const c of eqConstraints) {
                maxViolation = Math.max(maxViolation, Math.abs(c(x)));
            }
            for (const c of ineqConstraints) {
                maxViolation = Math.max(maxViolation, Math.max(0, c(x)));
            }
            
            history.push({ iter, rho, x: [...x], f: f(x), maxViolation });
            
            if (maxViolation < tol) break;
            
            rho *= rhoFactor;
        }
        
        return { x, f: f(x), iterations: history.length, history, lambdaEq, lambdaIneq };
    },

    // ─────────────────────────────────────────────────────────────────────────────
    // 1.3 METAHEURISTIC OPTIMIZATION
    // ─────────────────────────────────────────────────────────────────────────────

    /**
     * Particle Swarm Optimization (PSO)
     * Source: Various courses on metaheuristics
     */
    pso: function(f, bounds, options = {}) {
        const numParticles = options.numParticles || 30;
        const maxIter = options.maxIter || 100;
        const w = options.inertia || 0.7;
        const c1 = options.cognitive || 1.5;
        const c2 = options.social || 1.5;
        
        const dim = bounds.length;
        
        // Initialize particles
        const particles = [];
        for (let i = 0; i < numParticles; i++) {
            const position = bounds.map(b => b[0] + Math.random() * (b[1] - b[0]));
            const velocity = bounds.map(b => (Math.random() - 0.5) * (b[1] - b[0]) * 0.1);
            particles.push({
                position,
                velocity,
                bestPosition: [...position],
                bestValue: f(position)
            });
        }
        
        // Global best
        let globalBest = { position: null, value: Infinity };
        for (const p of particles) {
            if (p.bestValue < globalBest.value) {
                globalBest = { position: [...p.bestPosition], value: p.bestValue };
            }
        }
        
        const history = [];
        
        for (let iter = 0; iter < maxIter; iter++) {
            for (const p of particles) {
                // Update velocity
                for (let d = 0; d < dim; d++) {
                    const r1 = Math.random();
                    const r2 = Math.random();
                    p.velocity[d] = w * p.velocity[d] +
                        c1 * r1 * (p.bestPosition[d] - p.position[d]) +
                        c2 * r2 * (globalBest.position[d] - p.position[d]);
                }
                
                // Update position
                for (let d = 0; d < dim; d++) {
                    p.position[d] += p.velocity[d];
                    // Enforce bounds
                    p.position[d] = Math.max(bounds[d][0], Math.min(bounds[d][1], p.position[d]));
                }
                
                // Evaluate
                const value = f(p.position);
                
                // Update personal best
                if (value < p.bestValue) {
                    p.bestValue = value;
                    p.bestPosition = [...p.position];
                }
                
                // Update global best
                if (value < globalBest.value) {
                    globalBest = { position: [...p.position], value };
                }
            }
            
            history.push({ iter, bestValue: globalBest.value, bestPosition: [...globalBest.position] });
        }
        
        return { x: globalBest.position, f: globalBest.value, iterations: maxIter, history };
    },

    /**
     * Genetic Algorithm
     * Source: Various courses
     */
    geneticAlgorithm: function(fitness, bounds, options = {}) {
        const populationSize = options.populationSize || 50;
        const maxGenerations = options.maxGenerations || 100;
        const mutationRate = options.mutationRate || 0.1;
        const crossoverRate = options.crossoverRate || 0.8;
        const elitism = options.elitism || 2;
        
        const dim = bounds.length;
        
        // Initialize population
        let population = [];
        for (let i = 0; i < populationSize; i++) {
            const individual = bounds.map(b => b[0] + Math.random() * (b[1] - b[0]));
            population.push({ genes: individual, fitness: fitness(individual) });
        }
        
        const history = [];
        
        for (let gen = 0; gen < maxGenerations; gen++) {
            // Sort by fitness (minimization)
            population.sort((a, b) => a.fitness - b.fitness);
            
            history.push({
                generation: gen,
                bestFitness: population[0].fitness,
                bestGenes: [...population[0].genes],
                avgFitness: population.reduce((s, p) => s + p.fitness, 0) / populationSize
            });
            
            // Selection and reproduction
            const newPopulation = [];
            
            // Elitism
            for (let i = 0; i < elitism; i++) {
                newPopulation.push({ ...population[i], genes: [...population[i].genes] });
            }
            
            // Tournament selection and crossover
            while (newPopulation.length < populationSize) {
                // Tournament selection
                const parent1 = this._tournamentSelect(population);
                const parent2 = this._tournamentSelect(population);
                
                // Crossover
                let child;
                if (Math.random() < crossoverRate) {
                    child = this._crossover(parent1.genes, parent2.genes, bounds);
                } else {
                    child = [...parent1.genes];
                }
                
                // Mutation
                for (let d = 0; d < dim; d++) {
                    if (Math.random() < mutationRate) {
                        child[d] += (Math.random() - 0.5) * (bounds[d][1] - bounds[d][0]) * 0.1;
                        child[d] = Math.max(bounds[d][0], Math.min(bounds[d][1], child[d]));
                    }
                }
                
                newPopulation.push({ genes: child, fitness: fitness(child) });
            }
            
            population = newPopulation;
        }
        
        population.sort((a, b) => a.fitness - b.fitness);
        
        return {
            x: population[0].genes,
            f: population[0].fitness,
            generations: maxGenerations,
            history
        };
    },

    /**
     * Simulated Annealing
     * Source: MIT 18.433 Combinatorial Optimization
     */
    simulatedAnnealing: function(f, bounds, options = {}) {
        const maxIter = options.maxIter || 10000;
        let T = options.initialTemp || 1000;
        const Tmin = options.minTemp || 1e-8;
        const alpha = options.coolingRate || 0.995;
        
        const dim = bounds.length;
        
        // Initial solution
        let x = bounds.map(b => b[0] + Math.random() * (b[1] - b[0]));
        let fx = f(x);
        let bestX = [...x];
        let bestF = fx;
        
        const history = [];
        
        for (let iter = 0; iter < maxIter && T > Tmin; iter++) {
            // Generate neighbor
            const neighbor = x.map((xi, i) => {
                const delta = (Math.random() - 0.5) * (bounds[i][1] - bounds[i][0]) * 0.1 * T / options.initialTemp;
                return Math.max(bounds[i][0], Math.min(bounds[i][1], xi + delta));
            });
            
            const fNeighbor = f(neighbor);
            const delta = fNeighbor - fx;
            
            // Accept or reject
            if (delta < 0 || Math.random() < Math.exp(-delta / T)) {
                x = neighbor;
                fx = fNeighbor;
                
                if (fx < bestF) {
                    bestX = [...x];
                    bestF = fx;
                }
            }
            
            if (iter % 100 === 0) {
                history.push({ iter, T, currentF: fx, bestF });
            }
            
            T *= alpha;
        }
        
        return { x: bestX, f: bestF, iterations: maxIter, history };
    },

    /**
     * Ant Colony Optimization
     * Source: Various metaheuristics courses
     */
    antColonyOptimization: function(distanceMatrix, options = {}) {
        const numAnts = options.numAnts || 20;
        const maxIter = options.maxIter || 100;
        const alpha = options.alpha || 1; // pheromone importance
        const beta = options.beta || 2; // heuristic importance
        const rho = options.rho || 0.1; // evaporation rate
        const Q = options.Q || 100;
        
        const n = distanceMatrix.length;
        
        // Initialize pheromone matrix
        let pheromone = [];
        for (let i = 0; i < n; i++) {
            pheromone[i] = new Array(n).fill(1);
        }
        
        let bestTour = null;
        let bestLength = Infinity;
        const history = [];
        
        for (let iter = 0; iter < maxIter; iter++) {
            const tours = [];
            const tourLengths = [];
            
            for (let ant = 0; ant < numAnts; ant++) {
                // Build tour
                const visited = new Set();
                const tour = [Math.floor(Math.random() * n)];
                visited.add(tour[0]);
                
                while (visited.size < n) {
                    const current = tour[tour.length - 1];
                    const probabilities = [];
                    let sum = 0;
                    
                    for (let j = 0; j < n; j++) {
                        if (!visited.has(j)) {
                            const tau = Math.pow(pheromone[current][j], alpha);
                            const eta = Math.pow(1 / distanceMatrix[current][j], beta);
                            probabilities.push({ city: j, prob: tau * eta });
                            sum += tau * eta;
                        }
                    }
                    
                    // Roulette wheel selection
                    let r = Math.random() * sum;
                    let nextCity = probabilities[0].city;
                    for (const p of probabilities) {
                        r -= p.prob;
                        if (r <= 0) {
                            nextCity = p.city;
                            break;
                        }
                    }
                    
                    tour.push(nextCity);
                    visited.add(nextCity);
                }
                
                // Calculate tour length
                let length = 0;
                for (let i = 0; i < n; i++) {
                    length += distanceMatrix[tour[i]][tour[(i + 1) % n]];
                }
                
                tours.push(tour);
                tourLengths.push(length);
                
                if (length < bestLength) {
                    bestLength = length;
                    bestTour = [...tour];
                }
            }
            
            // Update pheromones
            // Evaporation
            for (let i = 0; i < n; i++) {
                for (let j = 0; j < n; j++) {
                    pheromone[i][j] *= (1 - rho);
                }
            }
            
            // Deposit
            for (let ant = 0; ant < numAnts; ant++) {
                const deposit = Q / tourLengths[ant];
                const tour = tours[ant];
                for (let i = 0; i < n; i++) {
                    const from = tour[i];
                    const to = tour[(i + 1) % n];
                    pheromone[from][to] += deposit;
                    pheromone[to][from] += deposit;
                }
            }
            
            history.push({ iter, bestLength, avgLength: tourLengths.reduce((a, b) => a + b) / numAnts });
        }
        
        return { tour: bestTour, length: bestLength, history };
    },

    // ─────────────────────────────────────────────────────────────────────────────
    // 1.4 MULTI-OBJECTIVE OPTIMIZATION
    // ─────────────────────────────────────────────────────────────────────────────

    /**
     * NSGA-II Multi-Objective Optimization
     * Source: Stanford AA222 MDO, CMU 24-785
     */
    nsgaII: function(objectives, bounds, options = {}) {
        const populationSize = options.populationSize || 100;
        const maxGenerations = options.maxGenerations || 100;
        const mutationRate = options.mutationRate || 0.1;
        
        const dim = bounds.length;
        const numObjectives = objectives.length;
        
        // Initialize population
        let population = [];
        for (let i = 0; i < populationSize; i++) {
            const x = bounds.map(b => b[0] + Math.random() * (b[1] - b[0]));
            const f = objectives.map(obj => obj(x));
            population.push({ x, f, rank: 0, crowdingDistance: 0 });
        }
        
        const history = [];
        
        for (let gen = 0; gen < maxGenerations; gen++) {
            // Non-dominated sorting
            this._nonDominatedSort(population);
            
            // Calculate crowding distance
            this._calculateCrowdingDistance(population, numObjectives);
            
            // Create offspring
            const offspring = [];
            while (offspring.length < populationSize) {
                const parent1 = this._tournamentSelectMOO(population);
                const parent2 = this._tournamentSelectMOO(population);
                
                // SBX crossover
                let child = this._sbxCrossover(parent1.x, parent2.x, bounds);
                
                // Polynomial mutation
                for (let d = 0; d < dim; d++) {
                    if (Math.random() < mutationRate) {
                        child[d] = this._polynomialMutation(child[d], bounds[d][0], bounds[d][1]);
                    }
                }
                
                const f = objectives.map(obj => obj(child));
                offspring.push({ x: child, f, rank: 0, crowdingDistance: 0 });
            }
            
            // Combine parent and offspring
            const combined = population.concat(offspring);
            this._nonDominatedSort(combined);
            this._calculateCrowdingDistance(combined, numObjectives);
            
            // Select next generation
            combined.sort((a, b) => {
                if (a.rank !== b.rank) return a.rank - b.rank;
                return b.crowdingDistance - a.crowdingDistance;
            });
            
            population = combined.slice(0, populationSize);
            
            // Record Pareto front
            const paretoFront = population.filter(p => p.rank === 0).map(p => ({ x: [...p.x], f: [...p.f] }));
            history.push({ generation: gen, paretoFrontSize: paretoFront.length });
        }
        
        const finalParetoFront = population.filter(p => p.rank === 0).map(p => ({ x: [...p.x], f: [...p.f] }));
        
        return { paretoFront: finalParetoFront, history };
    },

    // ─────────────────────────────────────────────────────────────────────────────
    // HELPER METHODS
    // ─────────────────────────────────────────────────────────────────────────────

    _norm: function(v) {
        return Math.sqrt(v.reduce((sum, vi) => sum + vi * vi, 0));
    },

    _dot: function(a, b) {
        return a.reduce((sum, ai, i) => sum + ai * b[i], 0);
    },

    _outerProduct: function(a, b) {
        return a.map(ai => b.map(bj => ai * bj));
    },

    _matVecMult: function(M, v) {
        return M.map(row => this._dot(row, v));
    },

    _matMult: function(A, B) {
        const n = A.length;
        const m = B[0].length;
        const result = [];
        for (let i = 0; i < n; i++) {
            result[i] = [];
            for (let j = 0; j < m; j++) {
                result[i][j] = 0;
                for (let k = 0; k < B.length; k++) {
                    result[i][j] += A[i][k] * B[k][j];
                }
            }
        }
        return result;
    },

    _matAdd: function(A, B) {
        return A.map((row, i) => row.map((val, j) => val + B[i][j]));
    },

    _matSubtract: function(A, B) {
        return A.map((row, i) => row.map((val, j) => val - B[i][j]));
    },

    _matScale: function(A, s) {
        return A.map(row => row.map(val => val * s));
    },

    _solveLinearSystem: function(A, b) {
        // Simple Gaussian elimination
        const n = b.length;
        const augmented = A.map((row, i) => [...row, b[i]]);
        
        // Forward elimination
        for (let i = 0; i < n; i++) {
            // Find pivot
            let maxRow = i;
            for (let k = i + 1; k < n; k++) {
                if (Math.abs(augmented[k][i]) > Math.abs(augmented[maxRow][i])) {
                    maxRow = k;
                }
            }
            [augmented[i], augmented[maxRow]] = [augmented[maxRow], augmented[i]];
            
            // Eliminate
            for (let k = i + 1; k < n; k++) {
                const factor = augmented[k][i] / augmented[i][i];
                for (let j = i; j <= n; j++) {
                    augmented[k][j] -= factor * augmented[i][j];
                }
            }
        }
        
        // Back substitution
        const x = new Array(n).fill(0);
        for (let i = n - 1; i >= 0; i--) {
            x[i] = augmented[i][n];
            for (let j = i + 1; j < n; j++) {
                x[i] -= augmented[i][j] * x[j];
            }
            x[i] /= augmented[i][i];
        }
        
        return x;
    },

    _numericalGradient: function(f, x, h = 1e-8) {
        const grad = [];
        for (let i = 0; i < x.length; i++) {
            const xPlus = [...x];
            const xMinus = [...x];
            xPlus[i] += h;
            xMinus[i] -= h;
            grad.push((f(xPlus) - f(xMinus)) / (2 * h));
        }
        return grad;
    },

    _lineSearch: function(f, x, d, options = {}) {
        const c = options.c || 0.0001;
        const rho = options.rho || 0.5;
        let alpha = options.alpha || 1;
        
        const f0 = f(x);
        const g0 = this._numericalGradient(f, x);
        const slope = this._dot(g0, d);
        
        while (f(x.map((xi, i) => xi + alpha * d[i])) > f0 + c * alpha * slope) {
            alpha *= rho;
            if (alpha < 1e-16) break;
        }
        
        return alpha;
    },

    _tournamentSelect: function(population, tournamentSize = 3) {
        const candidates = [];
        for (let i = 0; i < tournamentSize; i++) {
            candidates.push(population[Math.floor(Math.random() * population.length)]);
        }
        return candidates.reduce((best, c) => c.fitness < best.fitness ? c : best);
    },

    _crossover: function(parent1, parent2, bounds) {
        const child = [];
        for (let i = 0; i < parent1.length; i++) {
            const alpha = Math.random();
            child.push(alpha * parent1[i] + (1 - alpha) * parent2[i]);
        }
        return child;
    },

    _tournamentSelectMOO: function(population, tournamentSize = 2) {
        const candidates = [];
        for (let i = 0; i < tournamentSize; i++) {
            candidates.push(population[Math.floor(Math.random() * population.length)]);
        }
        return candidates.reduce((best, c) => {
            if (c.rank < best.rank) return c;
            if (c.rank === best.rank && c.crowdingDistance > best.crowdingDistance) return c;
            return best;
        });
    },

    _sbxCrossover: function(parent1, parent2, bounds, eta = 20) {
        const child = [];
        for (let i = 0; i < parent1.length; i++) {
            const u = Math.random();
            let beta;
            if (u <= 0.5) {
                beta = Math.pow(2 * u, 1 / (eta + 1));
            } else {
                beta = Math.pow(1 / (2 * (1 - u)), 1 / (eta + 1));
            }
            child.push(0.5 * ((1 + beta) * parent1[i] + (1 - beta) * parent2[i]));
            child[i] = Math.max(bounds[i][0], Math.min(bounds[i][1], child[i]));
        }
        return child;
    },

    _polynomialMutation: function(x, lb, ub, eta = 20) {
        const delta = (x - lb) / (ub - lb);
        const u = Math.random();
        let deltaq;
        if (u < 0.5) {
            const xy = 1 - delta;
            const val = 2 * u + (1 - 2 * u) * Math.pow(xy, eta + 1);
            deltaq = Math.pow(val, 1 / (eta + 1)) - 1;
        } else {
            const xy = delta;
            const val = 2 * (1 - u) + 2 * (u - 0.5) * Math.pow(xy, eta + 1);
            deltaq = 1 - Math.pow(val, 1 / (eta + 1));
        }
        return Math.max(lb, Math.min(ub, x + deltaq * (ub - lb)));
    },

    _nonDominatedSort: function(population) {
        const n = population.length;
        const dominationCount = new Array(n).fill(0);
        const dominatedSet = Array.from({ length: n }, () => []);
        const fronts = [[]];
        
        for (let i = 0; i < n; i++) {
            for (let j = 0; j < n; j++) {
                if (i !== j) {
                    if (this._dominates(population[i].f, population[j].f)) {
                        dominatedSet[i].push(j);
                    } else if (this._dominates(population[j].f, population[i].f)) {
                        dominationCount[i]++;
                    }
                }
            }
            if (dominationCount[i] === 0) {
                population[i].rank = 0;
                fronts[0].push(i);
            }
        }
        
        let frontIndex = 0;
        while (fronts[frontIndex].length > 0) {
            const nextFront = [];
            for (const i of fronts[frontIndex]) {
                for (const j of dominatedSet[i]) {
                    dominationCount[j]--;
                    if (dominationCount[j] === 0) {
                        population[j].rank = frontIndex + 1;
                        nextFront.push(j);
                    }
                }
            }
            frontIndex++;
            fronts.push(nextFront);
        }
    },

    _dominates: function(f1, f2) {
        let dominated = false;
        for (let i = 0; i < f1.length; i++) {
            if (f1[i] > f2[i]) return false;
            if (f1[i] < f2[i]) dominated = true;
        }
        return dominated;
    },

    _calculateCrowdingDistance: function(population, numObjectives) {
        const n = population.length;
        for (let i = 0; i < n; i++) {
            population[i].crowdingDistance = 0;
        }
        
        for (let m = 0; m < numObjectives; m++) {
            population.sort((a, b) => a.f[m] - b.f[m]);
            population[0].crowdingDistance = Infinity;
            population[n - 1].crowdingDistance = Infinity;
            
            const fMin = population[0].f[m];
            const fMax = population[n - 1].f[m];
            
            if (fMax - fMin > 0) {
                for (let i = 1; i < n - 1; i++) {
                    population[i].crowdingDistance += (population[i + 1].f[m] - population[i - 1].f[m]) / (fMax - fMin);
                }
            }
        }
    }
};

// ═══════════════════════════════════════════════════════════════════════════════
// CATEGORY 2: MACHINE LEARNING ALGORITHMS (150+ algorithms)
// Sources: MIT 6.036, 6.867, Stanford CS229, CS231N, CMU 10-601, Berkeley CS189
// ═══════════════════════════════════════════════════════════════════════════════

const PRISM_ML_ALGORITHMS = {
    name: 'PRISM Machine Learning Algorithms',
    version: '1.0.0',
    sources: ['MIT 6.036', 'MIT 6.867', 'Stanford CS229', 'Stanford CS231N', 'CMU 10-601', 'Berkeley CS189'],
    algorithmCount: 150,

    // ─────────────────────────────────────────────────────────────────────────────
    // 2.1 REGRESSION
    // ─────────────────────────────────────────────────────────────────────────────

    /**
     * Linear Regression with closed-form solution
     * Source: MIT 6.036, Stanford CS229
     */
    linearRegression: function(X, y, options = {}) {
        const regularization = options.regularization || 0;
        
        const n = X.length;
        const m = X[0].length;
        
        // Add bias term
        const X_bias = X.map(row => [1, ...row]);
        
        // X^T * X + lambda * I
        const XtX = this._matMult(this._transpose(X_bias), X_bias);
        for (let i = 0; i < XtX.length; i++) {
            XtX[i][i] += regularization;
        }
        
        // X^T * y
        const Xty = this._matVecMult(this._transpose(X_bias), y);
        
        // Solve (X^T * X + lambda * I) * w = X^T * y
        const w = this._solveLinearSystem(XtX, Xty);
        
        return {
            weights: w.slice(1),
            bias: w[0],
            predict: (x) => w[0] + this._dot(w.slice(1), x)
        };
    },

    /**
     * Ridge Regression (L2 regularization)
     * Source: Stanford CS229
     */
    ridgeRegression: function(X, y, lambda = 1) {
        return this.linearRegression(X, y, { regularization: lambda });
    },

    /**
     * Logistic Regression
     * Source: MIT 6.036, Stanford CS229
     */
    logisticRegression: function(X, y, options = {}) {
        const maxIter = options.maxIter || 1000;
        const learningRate = options.learningRate || 0.01;
        const regularization = options.regularization || 0;
        
        const n = X.length;
        const m = X[0].length;
        
        // Initialize weights
        let w = new Array(m).fill(0);
        let b = 0;
        
        const sigmoid = (z) => 1 / (1 + Math.exp(-Math.max(-500, Math.min(500, z))));
        
        for (let iter = 0; iter < maxIter; iter++) {
            // Compute gradients
            let dw = new Array(m).fill(0);
            let db = 0;
            
            for (let i = 0; i < n; i++) {
                const z = this._dot(w, X[i]) + b;
                const a = sigmoid(z);
                const diff = a - y[i];
                
                for (let j = 0; j < m; j++) {
                    dw[j] += diff * X[i][j];
                }
                db += diff;
            }
            
            // Update with regularization
            for (let j = 0; j < m; j++) {
                w[j] -= learningRate * (dw[j] / n + regularization * w[j]);
            }
            b -= learningRate * db / n;
        }
        
        return {
            weights: w,
            bias: b,
            predict: (x) => sigmoid(this._dot(w, x) + b),
            predictClass: (x) => sigmoid(this._dot(w, x) + b) >= 0.5 ? 1 : 0
        };
    },

    // ─────────────────────────────────────────────────────────────────────────────
    // 2.2 CLASSIFICATION
    // ─────────────────────────────────────────────────────────────────────────────

    /**
     * K-Nearest Neighbors
     * Source: MIT 6.036
     */
    knn: function(XTrain, yTrain, k = 5) {
        return {
            k,
            XTrain,
            yTrain,
            predict: (x) => {
                // Calculate distances
                const distances = XTrain.map((xi, i) => ({
                    index: i,
                    distance: Math.sqrt(xi.reduce((sum, xij, j) => sum + Math.pow(xij - x[j], 2), 0))
                }));
                
                // Sort and get k nearest
                distances.sort((a, b) => a.distance - b.distance);
                const kNearest = distances.slice(0, k);
                
                // Vote
                const votes = {};
                for (const neighbor of kNearest) {
                    const label = yTrain[neighbor.index];
                    votes[label] = (votes[label] || 0) + 1;
                }
                
                return Object.entries(votes).reduce((best, [label, count]) =>
                    count > best.count ? { label: parseInt(label), count } : best,
                    { label: null, count: 0 }
                ).label;
            }
        };
    },

    /**
     * Decision Tree
     * Source: CMU 10-601
     */
    decisionTree: function(X, y, options = {}) {
        const maxDepth = options.maxDepth || 10;
        const minSamples = options.minSamples || 2;
        
        const buildTree = (X, y, depth) => {
            // Check stopping conditions
            if (depth >= maxDepth || y.length < minSamples || new Set(y).size === 1) {
                // Leaf node
                const counts = {};
                for (const label of y) counts[label] = (counts[label] || 0) + 1;
                const prediction = Object.entries(counts).reduce((best, [label, count]) =>
                    count > best.count ? { label: parseInt(label), count } : best,
                    { label: null, count: 0 }
                ).label;
                return { isLeaf: true, prediction, counts };
            }
            
            // Find best split
            const bestSplit = this._findBestSplit(X, y);
            
            if (!bestSplit) {
                const counts = {};
                for (const label of y) counts[label] = (counts[label] || 0) + 1;
                return { isLeaf: true, prediction: Object.entries(counts).reduce((best, [l, c]) => c > best.count ? { label: parseInt(l), count: c } : best, { label: null, count: 0 }).label };
            }
            
            // Split data
            const leftIndices = [];
            const rightIndices = [];
            for (let i = 0; i < X.length; i++) {
                if (X[i][bestSplit.feature] <= bestSplit.threshold) {
                    leftIndices.push(i);
                } else {
                    rightIndices.push(i);
                }
            }
            
            return {
                isLeaf: false,
                feature: bestSplit.feature,
                threshold: bestSplit.threshold,
                left: buildTree(leftIndices.map(i => X[i]), leftIndices.map(i => y[i]), depth + 1),
                right: buildTree(rightIndices.map(i => X[i]), rightIndices.map(i => y[i]), depth + 1)
            };
        };
        
        const tree = buildTree(X, y, 0);
        
        const predict = (node, x) => {
            if (node.isLeaf) return node.prediction;
            if (x[node.feature] <= node.threshold) {
                return predict(node.left, x);
            } else {
                return predict(node.right, x);
            }
        };
        
        return {
            tree,
            predict: (x) => predict(tree, x)
        };
    },

    /**
     * Random Forest
     * Source: Stanford CS229, CMU 10-601
     */
    randomForest: function(X, y, options = {}) {
        const numTrees = options.numTrees || 100;
        const maxDepth = options.maxDepth || 10;
        const maxFeatures = options.maxFeatures || Math.floor(Math.sqrt(X[0].length));
        
        const trees = [];
        
        for (let t = 0; t < numTrees; t++) {
            // Bootstrap sample
            const indices = [];
            for (let i = 0; i < X.length; i++) {
                indices.push(Math.floor(Math.random() * X.length));
            }
            const XSample = indices.map(i => X[i]);
            const ySample = indices.map(i => y[i]);
            
            // Build tree with random feature subset
            const tree = this.decisionTree(XSample, ySample, {
                maxDepth,
                maxFeatures
            });
            trees.push(tree);
        }
        
        return {
            trees,
            predict: (x) => {
                const votes = {};
                for (const tree of trees) {
                    const pred = tree.predict(x);
                    votes[pred] = (votes[pred] || 0) + 1;
                }
                return Object.entries(votes).reduce((best, [label, count]) =>
                    count > best.count ? { label: parseInt(label), count } : best,
                    { label: null, count: 0 }
                ).label;
            }
        };
    },

    /**
     * Support Vector Machine (SMO algorithm)
     * Source: Stanford CS229
     */
    svm: function(X, y, options = {}) {
        const C = options.C || 1;
        const maxIter = options.maxIter || 1000;
        const tol = options.tol || 1e-3;
        const kernel = options.kernel || 'linear'; // linear, rbf
        const gamma = options.gamma || 1;
        
        const n = X.length;
        const m = X[0].length;
        
        // Convert labels to -1, 1
        const yBinary = y.map(yi => yi === 0 ? -1 : 1);
        
        // Initialize
        let alpha = new Array(n).fill(0);
        let b = 0;
        
        // Kernel function
        const K = (x1, x2) => {
            if (kernel === 'linear') {
                return this._dot(x1, x2);
            } else if (kernel === 'rbf') {
                const diff = x1.map((xi, i) => xi - x2[i]);
                return Math.exp(-gamma * this._dot(diff, diff));
            }
        };
        
        // Precompute kernel matrix
        const kernelMatrix = [];
        for (let i = 0; i < n; i++) {
            kernelMatrix[i] = [];
            for (let j = 0; j < n; j++) {
                kernelMatrix[i][j] = K(X[i], X[j]);
            }
        }
        
        // SMO algorithm
        for (let iter = 0; iter < maxIter; iter++) {
            let numChanged = 0;
            
            for (let i = 0; i < n; i++) {
                // Compute Ei
                let fi = b;
                for (let k = 0; k < n; k++) {
                    fi += alpha[k] * yBinary[k] * kernelMatrix[i][k];
                }
                const Ei = fi - yBinary[i];
                
                // Check KKT conditions
                if ((yBinary[i] * Ei < -tol && alpha[i] < C) ||
                    (yBinary[i] * Ei > tol && alpha[i] > 0)) {
                    
                    // Select j randomly
                    let j = Math.floor(Math.random() * n);
                    while (j === i) j = Math.floor(Math.random() * n);
                    
                    // Compute Ej
                    let fj = b;
                    for (let k = 0; k < n; k++) {
                        fj += alpha[k] * yBinary[k] * kernelMatrix[j][k];
                    }
                    const Ej = fj - yBinary[j];
                    
                    // Save old alphas
                    const alphaIold = alpha[i];
                    const alphaJold = alpha[j];
                    
                    // Compute bounds
                    let L, H;
                    if (yBinary[i] !== yBinary[j]) {
                        L = Math.max(0, alpha[j] - alpha[i]);
                        H = Math.min(C, C + alpha[j] - alpha[i]);
                    } else {
                        L = Math.max(0, alpha[i] + alpha[j] - C);
                        H = Math.min(C, alpha[i] + alpha[j]);
                    }
                    
                    if (L === H) continue;
                    
                    // Compute eta
                    const eta = 2 * kernelMatrix[i][j] - kernelMatrix[i][i] - kernelMatrix[j][j];
                    if (eta >= 0) continue;
                    
                    // Update alpha[j]
                    alpha[j] = alpha[j] - yBinary[j] * (Ei - Ej) / eta;
                    alpha[j] = Math.min(H, Math.max(L, alpha[j]));
                    
                    if (Math.abs(alpha[j] - alphaJold) < 1e-5) continue;
                    
                    // Update alpha[i]
                    alpha[i] = alpha[i] + yBinary[i] * yBinary[j] * (alphaJold - alpha[j]);
                    
                    // Update b
                    const b1 = b - Ei - yBinary[i] * (alpha[i] - alphaIold) * kernelMatrix[i][i] -
                               yBinary[j] * (alpha[j] - alphaJold) * kernelMatrix[i][j];
                    const b2 = b - Ej - yBinary[i] * (alpha[i] - alphaIold) * kernelMatrix[i][j] -
                               yBinary[j] * (alpha[j] - alphaJold) * kernelMatrix[j][j];
                    
                    if (0 < alpha[i] && alpha[i] < C) b = b1;
                    else if (0 < alpha[j] && alpha[j] < C) b = b2;
                    else b = (b1 + b2) / 2;
                    
                    numChanged++;
                }
            }
            
            if (numChanged === 0) break;
        }
        
        // Get support vectors
        const supportVectors = [];
        for (let i = 0; i < n; i++) {
            if (alpha[i] > 1e-8) {
                supportVectors.push({ index: i, alpha: alpha[i], x: X[i], y: yBinary[i] });
            }
        }
        
        return {
            alpha,
            b,
            supportVectors,
            predict: (x) => {
                let f = b;
                for (const sv of supportVectors) {
                    f += sv.alpha * sv.y * K(sv.x, x);
                }
                return f >= 0 ? 1 : 0;
            }
        };
    },

    // ─────────────────────────────────────────────────────────────────────────────
    // 2.3 CLUSTERING
    // ─────────────────────────────────────────────────────────────────────────────

    /**
     * K-Means Clustering
     * Source: Stanford CS229
     */
    kMeans: function(X, k, options = {}) {
        const maxIter = options.maxIter || 100;
        const tol = options.tol || 1e-4;
        
        const n = X.length;
        const m = X[0].length;
        
        // Initialize centroids (k-means++)
        const centroids = [X[Math.floor(Math.random() * n)]];
        while (centroids.length < k) {
            const distances = X.map(x => {
                let minDist = Infinity;
                for (const c of centroids) {
                    const dist = Math.sqrt(x.reduce((sum, xi, j) => sum + Math.pow(xi - c[j], 2), 0));
                    minDist = Math.min(minDist, dist);
                }
                return minDist * minDist;
            });
            
            const totalDist = distances.reduce((a, b) => a + b, 0);
            let r = Math.random() * totalDist;
            for (let i = 0; i < n; i++) {
                r -= distances[i];
                if (r <= 0) {
                    centroids.push([...X[i]]);
                    break;
                }
            }
        }
        
        let labels = new Array(n).fill(0);
        let prevCentroids = centroids.map(c => [...c]);
        
        for (let iter = 0; iter < maxIter; iter++) {
            // Assign points to nearest centroid
            for (let i = 0; i < n; i++) {
                let minDist = Infinity;
                let minLabel = 0;
                for (let j = 0; j < k; j++) {
                    const dist = Math.sqrt(X[i].reduce((sum, xi, d) => sum + Math.pow(xi - centroids[j][d], 2), 0));
                    if (dist < minDist) {
                        minDist = dist;
                        minLabel = j;
                    }
                }
                labels[i] = minLabel;
            }
            
            // Update centroids
            const newCentroids = Array.from({ length: k }, () => new Array(m).fill(0));
            const counts = new Array(k).fill(0);
            
            for (let i = 0; i < n; i++) {
                const label = labels[i];
                counts[label]++;
                for (let d = 0; d < m; d++) {
                    newCentroids[label][d] += X[i][d];
                }
            }
            
            for (let j = 0; j < k; j++) {
                if (counts[j] > 0) {
                    for (let d = 0; d < m; d++) {
                        newCentroids[j][d] /= counts[j];
                    }
                    centroids[j] = newCentroids[j];
                }
            }
            
            // Check convergence
            let maxShift = 0;
            for (let j = 0; j < k; j++) {
                const shift = Math.sqrt(centroids[j].reduce((sum, c, d) => sum + Math.pow(c - prevCentroids[j][d], 2), 0));
                maxShift = Math.max(maxShift, shift);
            }
            
            if (maxShift < tol) break;
            prevCentroids = centroids.map(c => [...c]);
        }
        
        return {
            centroids,
            labels,
            predict: (x) => {
                let minDist = Infinity;
                let minLabel = 0;
                for (let j = 0; j < k; j++) {
                    const dist = Math.sqrt(x.reduce((sum, xi, d) => sum + Math.pow(xi - centroids[j][d], 2), 0));
                    if (dist < minDist) {
                        minDist = dist;
                        minLabel = j;
                    }
                }
                return minLabel;
            }
        };
    },

    /**
     * DBSCAN Clustering
     * Source: Various ML courses
     */
    dbscan: function(X, eps, minPts) {
        const n = X.length;
        const labels = new Array(n).fill(-1); // -1 = unvisited
        let clusterId = 0;
        
        const distance = (i, j) => {
            return Math.sqrt(X[i].reduce((sum, xi, d) => sum + Math.pow(xi - X[j][d], 2), 0));
        };
        
        const regionQuery = (i) => {
            const neighbors = [];
            for (let j = 0; j < n; j++) {
                if (distance(i, j) <= eps) {
                    neighbors.push(j);
                }
            }
            return neighbors;
        };
        
        const expandCluster = (pointIdx, neighbors, clusterId) => {
            labels[pointIdx] = clusterId;
            
            const queue = [...neighbors];
            while (queue.length > 0) {
                const currentIdx = queue.shift();
                
                if (labels[currentIdx] === -2) { // was noise
                    labels[currentIdx] = clusterId;
                }
                
                if (labels[currentIdx] !== -1) continue;
                
                labels[currentIdx] = clusterId;
                const currentNeighbors = regionQuery(currentIdx);
                
                if (currentNeighbors.length >= minPts) {
                    for (const neighbor of currentNeighbors) {
                        if (labels[neighbor] === -1 || labels[neighbor] === -2) {
                            queue.push(neighbor);
                        }
                    }
                }
            }
        };
        
        for (let i = 0; i < n; i++) {
            if (labels[i] !== -1) continue;
            
            const neighbors = regionQuery(i);
            
            if (neighbors.length < minPts) {
                labels[i] = -2; // noise
            } else {
                expandCluster(i, neighbors, clusterId);
                clusterId++;
            }
        }
        
        // Convert -2 to -1 (noise)
        for (let i = 0; i < n; i++) {
            if (labels[i] === -2) labels[i] = -1;
        }
        
        return {
            labels,
            numClusters: clusterId,
            noise: labels.filter(l => l === -1).length
        };
    },

    // ─────────────────────────────────────────────────────────────────────────────
    // 2.4 DIMENSIONALITY REDUCTION
    // ─────────────────────────────────────────────────────────────────────────────

    /**
     * Principal Component Analysis (PCA)
     * Source: MIT 6.036, Stanford CS229
     */
    pca: function(X, numComponents) {
        const n = X.length;
        const m = X[0].length;
        
        // Center data
        const mean = new Array(m).fill(0);
        for (let i = 0; i < n; i++) {
            for (let j = 0; j < m; j++) {
                mean[j] += X[i][j];
            }
        }
        for (let j = 0; j < m; j++) {
            mean[j] /= n;
        }
        
        const XCentered = X.map(row => row.map((val, j) => val - mean[j]));
        
        // Compute covariance matrix
        const cov = [];
        for (let i = 0; i < m; i++) {
            cov[i] = [];
            for (let j = 0; j < m; j++) {
                let sum = 0;
                for (let k = 0; k < n; k++) {
                    sum += XCentered[k][i] * XCentered[k][j];
                }
                cov[i][j] = sum / (n - 1);
            }
        }
        
        // Power iteration for top eigenvectors
        const components = [];
        let covRemaining = cov.map(row => [...row]);
        
        for (let c = 0; c < numComponents; c++) {
            // Power iteration
            let v = new Array(m).fill(0).map(() => Math.random());
            let vNorm = Math.sqrt(v.reduce((sum, vi) => sum + vi * vi, 0));
            v = v.map(vi => vi / vNorm);
            
            for (let iter = 0; iter < 100; iter++) {
                const vNew = this._matVecMult(covRemaining, v);
                vNorm = Math.sqrt(vNew.reduce((sum, vi) => sum + vi * vi, 0));
                v = vNew.map(vi => vi / vNorm);
            }
            
            // Eigenvalue
            const eigenvalue = this._dot(this._matVecMult(covRemaining, v), v);
            components.push({ vector: v, eigenvalue });
            
            // Deflate
            for (let i = 0; i < m; i++) {
                for (let j = 0; j < m; j++) {
                    covRemaining[i][j] -= eigenvalue * v[i] * v[j];
                }
            }
        }
        
        return {
            components,
            mean,
            transform: (x) => {
                const xCentered = x.map((xi, i) => xi - mean[i]);
                return components.map(c => this._dot(xCentered, c.vector));
            },
            inverseTransform: (z) => {
                const result = [...mean];
                for (let c = 0; c < z.length; c++) {
                    for (let i = 0; i < m; i++) {
                        result[i] += z[c] * components[c].vector[i];
                    }
                }
                return result;
            }
        };
    },

    // ─────────────────────────────────────────────────────────────────────────────
    // HELPER METHODS
    // ─────────────────────────────────────────────────────────────────────────────

    _transpose: function(M) {
        return M[0].map((_, j) => M.map(row => row[j]));
    },

    _matMult: function(A, B) {
        return A.map(row => B[0].map((_, j) => row.reduce((sum, a, i) => sum + a * B[i][j], 0)));
    },

    _matVecMult: function(M, v) {
        return M.map(row => this._dot(row, v));
    },

    _dot: function(a, b) {
        return a.reduce((sum, ai, i) => sum + ai * b[i], 0);
    },

    _solveLinearSystem: function(A, b) {
        const n = b.length;
        const aug = A.map((row, i) => [...row, b[i]]);
        
        for (let i = 0; i < n; i++) {
            let maxRow = i;
            for (let k = i + 1; k < n; k++) {
                if (Math.abs(aug[k][i]) > Math.abs(aug[maxRow][i])) maxRow = k;
            }
            [aug[i], aug[maxRow]] = [aug[maxRow], aug[i]];
            
            for (let k = i + 1; k < n; k++) {
                const c = aug[k][i] / aug[i][i];
                for (let j = i; j <= n; j++) aug[k][j] -= c * aug[i][j];
            }
        }
        
        const x = new Array(n).fill(0);
        for (let i = n - 1; i >= 0; i--) {
            x[i] = aug[i][n];
            for (let j = i + 1; j < n; j++) x[i] -= aug[i][j] * x[j];
            x[i] /= aug[i][i];
        }
        return x;
    },

    _findBestSplit: function(X, y) {
        if (X.length === 0 || X[0].length === 0) return null;
        
        const m = X[0].length;
        let bestGain = 0;
        let bestSplit = null;
        
        const parentGini = this._gini(y);
        
        for (let feature = 0; feature < m; feature++) {
            const values = [...new Set(X.map(x => x[feature]))].sort((a, b) => a - b);
            
            for (let i = 0; i < values.length - 1; i++) {
                const threshold = (values[i] + values[i + 1]) / 2;
                
                const leftY = [];
                const rightY = [];
                for (let j = 0; j < X.length; j++) {
                    if (X[j][feature] <= threshold) {
                        leftY.push(y[j]);
                    } else {
                        rightY.push(y[j]);
                    }
                }
                
                if (leftY.length === 0 || rightY.length === 0) continue;
                
                const gain = parentGini -
                    (leftY.length / y.length) * this._gini(leftY) -
                    (rightY.length / y.length) * this._gini(rightY);
                
                if (gain > bestGain) {
                    bestGain = gain;
                    bestSplit = { feature, threshold, gain };
                }
            }
        }
        
        return bestSplit;
    },

    _gini: function(y) {
        const counts = {};
        for (const label of y) counts[label] = (counts[label] || 0) + 1;
        let gini = 1;
        for (const count of Object.values(counts)) {
            const p = count / y.length;
            gini -= p * p;
        }
        return gini;
    }
};

