// ═══════════════════════════════════════════════════════════════════════════════════════════
// PHASE 2 MULTI-OBJECTIVE OPTIMIZATION
// Sources: Stanford AA222, MIT 15.099, CMU 24-785
// Protocol J: Innovation-First Development
// ═══════════════════════════════════════════════════════════════════════════════════════════

const PRISM_PHASE2_MULTI_OBJECTIVE = {
    name: 'Phase 2 Multi-Objective Optimization',
    version: '1.0.0',
    source: 'Stanford AA222, MIT 15.099, CMU 24-785',
    
    /**
     * NSGA-II (Non-dominated Sorting Genetic Algorithm II)
     * Source: Stanford AA222 - MDO, CMU 24-785
     * The gold standard for multi-objective optimization
     */
    nsgaII: function(objectives, bounds, options = {}) {
        const config = {
            populationSize: options.populationSize || 100,
            maxGenerations: options.maxGenerations || 100,
            crossoverRate: options.crossoverRate || 0.9,
            mutationRate: options.mutationRate || 0.1,
            crossoverEta: options.crossoverEta || 20,
            mutationEta: options.mutationEta || 20
        };
        
        const dim = bounds.length;
        const numObjectives = objectives.length;
        
        // Initialize population
        let population = [];
        for (let i = 0; i < config.populationSize; i++) {
            const x = bounds.map(b => b[0] + Math.random() * (b[1] - b[0]));
            const f = objectives.map(obj => obj(x));
            population.push({ x, f, rank: 0, crowdingDistance: 0 });
        }
        
        // Main NSGA-II loop
        for (let gen = 0; gen < config.maxGenerations; gen++) {
            // Non-dominated sorting
            this._nonDominatedSort(population);
            
            // Calculate crowding distance
            this._calculateCrowdingDistance(population, numObjectives);
            
            // Create offspring
            const offspring = [];
            while (offspring.length < config.populationSize) {
                const parent1 = this._tournamentSelect(population);
                const parent2 = this._tournamentSelect(population);
                
                // SBX crossover
                let child1, child2;
                if (Math.random() < config.crossoverRate) {
                    [child1, child2] = this._sbxCrossover(parent1.x, parent2.x, bounds, config.crossoverEta);
                } else {
                    child1 = [...parent1.x];
                    child2 = [...parent2.x];
                }
                
                // Polynomial mutation
                child1 = this._polynomialMutation(child1, bounds, config.mutationRate, config.mutationEta);
                child2 = this._polynomialMutation(child2, bounds, config.mutationRate, config.mutationEta);
                
                offspring.push({ 
                    x: child1, 
                    f: objectives.map(obj => obj(child1)), 
                    rank: 0, 
                    crowdingDistance: 0 
                });
                
                if (offspring.length < config.populationSize) {
                    offspring.push({ 
                        x: child2, 
                        f: objectives.map(obj => obj(child2)), 
                        rank: 0, 
                        crowdingDistance: 0 
                    });
                }
            }
            
            // Combine and select
            const combined = population.concat(offspring);
            this._nonDominatedSort(combined);
            this._calculateCrowdingDistance(combined, numObjectives);
            
            // Select next generation
            combined.sort((a, b) => {
                if (a.rank !== b.rank) return a.rank - b.rank;
                return b.crowdingDistance - a.crowdingDistance;
            });
            
            population = combined.slice(0, config.populationSize);
        }
        
        // Extract Pareto front (rank 0 solutions)
        const paretoFront = population.filter(p => p.rank === 0);
        
        return {
            paretoFront: paretoFront.map(p => ({ x: p.x, objectives: p.f })),
            population: population.map(p => ({ x: p.x, objectives: p.f, rank: p.rank })),
            generations: config.maxGenerations,
            numObjectives,
            source: 'Stanford AA222 - NSGA-II'
        };
    },
    
    /**
     * NSGA-II for Manufacturing Optimization
     * Protocol J: Innovation - combines NSGA-II with manufacturing domain knowledge
     */
    nsgaIIManufacturing: function(params) {
        const {
            material,
            tool,
            machine,
            constraints = {}
        } = params;
        
        // Define manufacturing objectives
        const objectives = [
            // Objective 1: Maximize MRR (productivity)
            (x) => {
                const [speed, feed, doc] = x;
                return -(speed * feed * doc); // Negative because NSGA-II minimizes
            },
            // Objective 2: Maximize tool life
            (x) => {
                const [speed, feed, doc] = x;
                const n = material?.taylorN || 0.25;
                const C = material?.taylorC || 300;
                const toolLife = Math.pow(C / speed, 1/n) * Math.pow(0.1/feed, 0.2);
                return -toolLife; // Negative to maximize
            },
            // Objective 3: Minimize surface roughness
            (x) => {
                const [speed, feed, doc] = x;
                const r = tool?.noseRadius || 0.8;
                return (feed * feed) / (32 * r) * 1000; // Ra in μm
            }
        ];
        
        // Define bounds
        const bounds = [
            [constraints.speedMin || 50, constraints.speedMax || 400],    // Speed m/min
            [constraints.feedMin || 0.05, constraints.feedMax || 0.4],   // Feed mm/tooth
            [constraints.docMin || 0.5, constraints.docMax || 8]         // DOC mm
        ];
        
        // Run NSGA-II
        const result = this.nsgaII(objectives, bounds, {
            populationSize: 80,
            maxGenerations: 100
        });
        
        // Format results for manufacturing
        return {
            paretoFront: result.paretoFront.map(p => ({
                speed: p.x[0],
                feed: p.x[1],
                doc: p.x[2],
                mrr: -p.objectives[0],
                toolLife: -p.objectives[1],
                surfaceRoughness: p.objectives[2]
            })),
            bestProductivity: this._findBest(result.paretoFront, 0),
            bestToolLife: this._findBest(result.paretoFront, 1),
            bestSurfaceFinish: this._findBestMin(result.paretoFront, 2),
            balancedSolution: this._findBalanced(result.paretoFront),
            source: 'Stanford AA222 + MIT 2.008 - NSGA-II Manufacturing'
        };
    },
    
    _findBest: function(front, objIndex) {
        let best = front[0];
        for (const p of front) {
            if (p.objectives[objIndex] < best.objectives[objIndex]) {
                best = p;
            }
        }
        return { x: best.x, value: -best.objectives[objIndex] };
    },
    
    _findBestMin: function(front, objIndex) {
        let best = front[0];
        for (const p of front) {
            if (p.objectives[objIndex] < best.objectives[objIndex]) {
                best = p;
            }
        }
        return { x: best.x, value: best.objectives[objIndex] };
    },
    
    _findBalanced: function(front) {
        // Find solution closest to ideal point (normalized)
        const numObj = front[0].objectives.length;
        
        // Find min/max for normalization
        const mins = new Array(numObj).fill(Infinity);
        const maxs = new Array(numObj).fill(-Infinity);
        
        for (const p of front) {
            for (let i = 0; i < numObj; i++) {
                mins[i] = Math.min(mins[i], p.objectives[i]);
                maxs[i] = Math.max(maxs[i], p.objectives[i]);
            }
        }
        
        // Find closest to ideal
        let bestDist = Infinity;
        let best = front[0];
        
        for (const p of front) {
            let dist = 0;
            for (let i = 0; i < numObj; i++) {
                const range = maxs[i] - mins[i] || 1;
                const normalized = (p.objectives[i] - mins[i]) / range;
                dist += normalized * normalized;
            }
            if (dist < bestDist) {
                bestDist = dist;
                best = p;
            }
        }
        
        return { x: best.x, objectives: best.objectives };
    },
    
    /**
     * Get Pareto front from population
     */
    getParetoFront: function(solutions) {
        const front = [];
        
        for (let i = 0; i < solutions.length; i++) {
            let dominated = false;
            
            for (let j = 0; j < solutions.length; j++) {
                if (i === j) continue;
                
                if (this._dominates(solutions[j], solutions[i])) {
                    dominated = true;
                    break;
                }
            }
            
            if (!dominated) {
                front.push(solutions[i]);
            }
        }
        
        return front;
    },
    
    _dominates: function(a, b) {
        let dominated = true;
        let strictlyBetter = false;
        
        for (let i = 0; i < a.objectives.length; i++) {
            if (a.objectives[i] > b.objectives[i]) {
                dominated = false;
                break;
            }
            if (a.objectives[i] < b.objectives[i]) {
                strictlyBetter = true;
            }
        }
        
        return dominated && strictlyBetter;
    },
    
    _nonDominatedSort: function(population) {
        const n = population.length;
        const domination = new Array(n).fill(null).map(() => []);
        const dominatedBy = new Array(n).fill(0);
        
        // Calculate domination
        for (let i = 0; i < n; i++) {
            for (let j = i + 1; j < n; j++) {
                if (this._dominates(population[i], population[j])) {
                    domination[i].push(j);
                    dominatedBy[j]++;
                } else if (this._dominates(population[j], population[i])) {
                    domination[j].push(i);
                    dominatedBy[i]++;
                }
            }
        }
        
        // Assign ranks
        let rank = 0;
        let currentFront = [];
        
        for (let i = 0; i < n; i++) {
            if (dominatedBy[i] === 0) {
                population[i].rank = rank;
                currentFront.push(i);
            }
        }
        
        while (currentFront.length > 0) {
            const nextFront = [];
            
            for (const i of currentFront) {
                for (const j of domination[i]) {
                    dominatedBy[j]--;
                    if (dominatedBy[j] === 0) {
                        population[j].rank = rank + 1;
                        nextFront.push(j);
                    }
                }
            }
            
            rank++;
            currentFront = nextFront;
        }
    },
    
    _calculateCrowdingDistance: function(population, numObjectives) {
        const n = population.length;
        
        for (const p of population) {
            p.crowdingDistance = 0;
        }
        
        for (let obj = 0; obj < numObjectives; obj++) {
            population.sort((a, b) => a.f[obj] - b.f[obj]);
            
            population[0].crowdingDistance = Infinity;
            population[n - 1].crowdingDistance = Infinity;
            
            const range = population[n - 1].f[obj] - population[0].f[obj] || 1;
            
            for (let i = 1; i < n - 1; i++) {
                population[i].crowdingDistance += 
                    (population[i + 1].f[obj] - population[i - 1].f[obj]) / range;
            }
        }
    },
    
    _tournamentSelect: function(population, k = 2) {
        let best = population[Math.floor(Math.random() * population.length)];
        
        for (let i = 1; i < k; i++) {
            const candidate = population[Math.floor(Math.random() * population.length)];
            if (candidate.rank < best.rank || 
                (candidate.rank === best.rank && candidate.crowdingDistance > best.crowdingDistance)) {
                best = candidate;
            }
        }
        
        return best;
    },
    
    _sbxCrossover: function(p1, p2, bounds, eta) {
        const dim = p1.length;
        const c1 = new Array(dim);
        const c2 = new Array(dim);
        
        for (let i = 0; i < dim; i++) {
            if (Math.random() < 0.5) {
                const u = Math.random();
                let beta;
                
                if (u <= 0.5) {
                    beta = Math.pow(2 * u, 1 / (eta + 1));
                } else {
                    beta = Math.pow(1 / (2 * (1 - u)), 1 / (eta + 1));
                }
                
                c1[i] = 0.5 * ((1 + beta) * p1[i] + (1 - beta) * p2[i]);
                c2[i] = 0.5 * ((1 - beta) * p1[i] + (1 + beta) * p2[i]);
            } else {
                c1[i] = p1[i];
                c2[i] = p2[i];
            }
            
            c1[i] = Math.max(bounds[i][0], Math.min(bounds[i][1], c1[i]));
            c2[i] = Math.max(bounds[i][0], Math.min(bounds[i][1], c2[i]));
        }
        
        return [c1, c2];
    },
    
    _polynomialMutation: function(x, bounds, rate, eta) {
        const dim = x.length;
        const mutated = [...x];
        
        for (let i = 0; i < dim; i++) {
            if (Math.random() < rate) {
                const u = Math.random();
                let delta;
                
                if (u < 0.5) {
                    delta = Math.pow(2 * u, 1 / (eta + 1)) - 1;
                } else {
                    delta = 1 - Math.pow(2 * (1 - u), 1 / (eta + 1));
                }
                
                mutated[i] = x[i] + delta * (bounds[i][1] - bounds[i][0]);
                mutated[i] = Math.max(bounds[i][0], Math.min(bounds[i][1], mutated[i]));
            }
        }
        
        return mutated;
    }
};

// ═══════════════════════════════════════════════════════════════════════════════════════════
// PHASE 2 CONSTRAINED OPTIMIZATION
// Sources: MIT 6.251J, MIT 15.084
// ═══════════════════════════════════════════════════════════════════════════════════════════

const PRISM_PHASE2_CONSTRAINED = {
    name: 'Phase 2 Constrained Optimization',
    version: '1.0.0',
    source: 'MIT 6.251J, MIT 15.084',
    
    /**
     * Interior Point Method (Log Barrier)
     * Source: MIT 6.251J - Mathematical Programming
     */
    interiorPoint: function(f, constraints, x0, options = {}) {
        const config = {
            maxIter: options.maxIter || 100,
            mu: options.mu || 10,          // Barrier parameter multiplier
            tol: options.tol || 1e-6,
            t0: options.t0 || 1            // Initial barrier parameter
        };
        
        let x = [...x0];
        let t = config.t0;
        
        const barrierGradient = (x, t) => {
            const grad = this._numericalGradient(y => f(y), x);
            
            for (const g of constraints) {
                const gVal = g(x);
                if (gVal >= 0) return null; // Infeasible
                
                const gGrad = this._numericalGradient(g, x);
                for (let i = 0; i < grad.length; i++) {
                    grad[i] -= (1 / (t * gVal)) * gGrad[i];
                }
            }
            
            return grad;
        };
        
        for (let iter = 0; iter < config.maxIter; iter++) {
            // Newton step on barrier problem
            for (let inner = 0; inner < 20; inner++) {
                const grad = barrierGradient(x, t);
                if (!grad) {
                    // Backtrack to feasible region
                    for (let i = 0; i < x.length; i++) {
                        x[i] = x0[i] + 0.5 * (x[i] - x0[i]);
                    }
                    continue;
                }
                
                const gradNorm = Math.sqrt(grad.reduce((s, g) => s + g*g, 0));
                if (gradNorm < config.tol) break;
                
                // Gradient descent step
                const alpha = 0.01 / (1 + iter);
                for (let i = 0; i < x.length; i++) {
                    x[i] -= alpha * grad[i];
                }
            }
            
            // Check duality gap
            const m = constraints.length;
            if (m / t < config.tol) {
                return {
                    optimal: x,
                    value: f(x),
                    iterations: iter,
                    converged: true,
                    source: 'MIT 6.251J - Interior Point'
                };
            }
            
            t *= config.mu;
        }
        
        return {
            optimal: x,
            value: f(x),
            iterations: config.maxIter,
            converged: false,
            source: 'MIT 6.251J - Interior Point'
        };
    },
    
    /**
     * Barrier Method
     */
    barrierMethod: function(f, constraints, x0, options = {}) {
        return this.interiorPoint(f, constraints, x0, options);
    },
    
    /**
     * Augmented Lagrangian Method
     * Source: MIT 6.251J
     */
    augmentedLagrangian: function(f, equalityConstraints, inequalityConstraints, x0, options = {}) {
        const config = {
            maxIter: options.maxIter || 50,
            rho: options.rho || 1,           // Penalty parameter
            rhoMax: options.rhoMax || 1e6,
            innerIter: options.innerIter || 50,
            tol: options.tol || 1e-6
        };
        
        let x = [...x0];
        let lambda = new Array(equalityConstraints.length).fill(0);
        let mu = new Array(inequalityConstraints.length).fill(0);
        let rho = config.rho;
        
        for (let iter = 0; iter < config.maxIter; iter++) {
            // Minimize augmented Lagrangian
            const augLagrangian = (y) => {
                let L = f(y);
                
                // Equality constraints
                for (let i = 0; i < equalityConstraints.length; i++) {
                    const h = equalityConstraints[i](y);
                    L += lambda[i] * h + (rho / 2) * h * h;
                }
                
                // Inequality constraints (with slack)
                for (let i = 0; i < inequalityConstraints.length; i++) {
                    const g = inequalityConstraints[i](y);
                    const term = Math.max(0, mu[i] + rho * g);
                    L += (term * term - mu[i] * mu[i]) / (2 * rho);
                }
                
                return L;
            };
            
            // Inner optimization (gradient descent)
            for (let inner = 0; inner < config.innerIter; inner++) {
                const grad = this._numericalGradient(augLagrangian, x);
                const gradNorm = Math.sqrt(grad.reduce((s, g) => s + g*g, 0));
                
                if (gradNorm < config.tol) break;
                
                const alpha = 0.01;
                for (let i = 0; i < x.length; i++) {
                    x[i] -= alpha * grad[i];
                }
            }
            
            // Update multipliers
            for (let i = 0; i < equalityConstraints.length; i++) {
                lambda[i] += rho * equalityConstraints[i](x);
            }
            
            for (let i = 0; i < inequalityConstraints.length; i++) {
                mu[i] = Math.max(0, mu[i] + rho * inequalityConstraints[i](x));
            }
            
            // Check convergence
            let maxViolation = 0;
            for (const h of equalityConstraints) {
                maxViolation = Math.max(maxViolation, Math.abs(h(x)));
            }
            for (const g of inequalityConstraints) {
                maxViolation = Math.max(maxViolation, Math.max(0, g(x)));
            }
            
            if (maxViolation < config.tol) {
                return {
                    optimal: x,
                    value: f(x),
                    lambda,
                    mu,
                    iterations: iter,
                    converged: true,
                    source: 'MIT 6.251J - Augmented Lagrangian'
                };
            }
            
            // Increase penalty
            rho = Math.min(rho * 2, config.rhoMax);
        }
        
        return {
            optimal: x,
            value: f(x),
            lambda,
            mu,
            iterations: config.maxIter,
            converged: false,
            source: 'MIT 6.251J - Augmented Lagrangian'
        };
    },
    
    /**
     * Sequential Quadratic Programming (SQP)
     * Source: MIT 6.251J
     */
    sqp: function(f, equalityConstraints, inequalityConstraints, x0, options = {}) {
        const config = {
            maxIter: options.maxIter || 100,
            tol: options.tol || 1e-6
        };
        
        let x = [...x0];
        const n = x.length;
        let B = []; // Approximate Hessian
        for (let i = 0; i < n; i++) {
            B[i] = new Array(n).fill(0);
            B[i][i] = 1;
        }
        
        for (let iter = 0; iter < config.maxIter; iter++) {
            const grad = this._numericalGradient(f, x);
            
            // Solve QP subproblem (simplified)
            const p = grad.map(g => -g * 0.1);
            
            // Line search
            let alpha = 1;
            const c1 = 1e-4;
            const fx = f(x);
            
            for (let ls = 0; ls < 20; ls++) {
                const xNew = x.map((xi, i) => xi + alpha * p[i]);
                
                let feasible = true;
                for (const g of inequalityConstraints) {
                    if (g(xNew) > 0) feasible = false;
                }
                
                if (feasible && f(xNew) < fx + c1 * alpha * grad.reduce((s, g, i) => s + g * p[i], 0)) {
                    break;
                }
                
                alpha *= 0.5;
            }
            
            // Update
            const xNew = x.map((xi, i) => xi + alpha * p[i]);
            
            // Check convergence
            const gradNorm = Math.sqrt(grad.reduce((s, g) => s + g*g, 0));
            if (gradNorm < config.tol) {
                return {
                    optimal: xNew,
                    value: f(xNew),
                    iterations: iter,
                    converged: true,
                    source: 'MIT 6.251J - SQP'
                };
            }
            
            x = xNew;
        }
        
        return {
            optimal: x,
            value: f(x),
            iterations: config.maxIter,
            converged: false,
            source: 'MIT 6.251J - SQP'
        };
    },
    
    /**
     * Penalty Method
     */
    penaltyMethod: function(f, constraints, x0, options = {}) {
        const config = {
            maxIter: options.maxIter || 50,
            rho: options.rho || 1,
            rhoMax: options.rhoMax || 1e8
        };
        
        let x = [...x0];
        let rho = config.rho;
        
        for (let iter = 0; iter < config.maxIter; iter++) {
            // Penalized objective
            const penalized = (y) => {
                let val = f(y);
                for (const g of constraints) {
                    const gVal = g(y);
                    if (gVal > 0) {
                        val += rho * gVal * gVal;
                    }
                }
                return val;
            };
            
            // Minimize penalized problem (gradient descent)
            for (let inner = 0; inner < 100; inner++) {
                const grad = this._numericalGradient(penalized, x);
                const gradNorm = Math.sqrt(grad.reduce((s, g) => s + g*g, 0));
                if (gradNorm < 1e-6) break;
                
                const alpha = 0.01;
                for (let i = 0; i < x.length; i++) {
                    x[i] -= alpha * grad[i];
                }
            }
            
            // Check feasibility
            let maxViolation = 0;
            for (const g of constraints) {
                maxViolation = Math.max(maxViolation, Math.max(0, g(x)));
            }
            
            if (maxViolation < 1e-6) {
                return {
                    optimal: x,
                    value: f(x),
                    iterations: iter,
                    converged: true,
                    source: 'MIT 6.251J - Penalty Method'
                };
            }
            
            rho = Math.min(rho * 10, config.rhoMax);
        }
        
        return {
            optimal: x,
            value: f(x),
            iterations: config.maxIter,
            converged: false,
            source: 'MIT 6.251J - Penalty Method'
        };
    },
    
    _numericalGradient: function(f, x, h = 1e-6) {
        const n = x.length;
        const grad = new Array(n);
        
        for (let i = 0; i < n; i++) {
            const xPlus = [...x];
            const xMinus = [...x];
            xPlus[i] += h;
            xMinus[i] -= h;
            grad[i] = (f(xPlus) - f(xMinus)) / (2 * h);
        }
        
        return grad;
    }
};

// ═══════════════════════════════════════════════════════════════════════════════════════════
// PHASE 2 METAHEURISTICS
// Sources: MIT 18.433
// ═══════════════════════════════════════════════════════════════════════════════════════════

const PRISM_PHASE2_METAHEURISTICS = {
    name: 'Phase 2 Metaheuristics',
    version: '1.0.0',
    source: 'MIT 18.433',
    
    /**
     * Simulated Annealing
     * Source: MIT 18.433 - Combinatorial Optimization
     */
    simulatedAnnealing: function(f, neighbor, x0, options = {}) {
        const config = {
            T0: options.T0 || 1000,
            Tmin: options.Tmin || 0.001,
            alpha: options.alpha || 0.95,
            iterPerTemp: options.iterPerTemp || 100
        };
        
        let x = typeof x0 === 'function' ? x0() : [...x0];
        let fx = f(x);
        let best = { x: [...x], fx };
        let T = config.T0;
        let iterations = 0;
        
        while (T > config.Tmin) {
            for (let i = 0; i < config.iterPerTemp; i++) {
                const xNew = neighbor(x);
                const fxNew = f(xNew);
                const delta = fxNew - fx;
                
                if (delta < 0 || Math.random() < Math.exp(-delta / T)) {
                    x = xNew;
                    fx = fxNew;
                    
                    if (fx < best.fx) {
                        best = { x: [...x], fx };
                    }
                }
                
                iterations++;
            }
            
            T *= config.alpha;
        }
        
        return {
            optimal: best.x,
            value: best.fx,
            iterations,
            finalTemperature: T,
            source: 'MIT 18.433 - Simulated Annealing'
        };
    },
    
    /**
     * Tabu Search
     * Source: MIT 18.433
     */
    tabuSearch: function(f, neighbors, x0, options = {}) {
        const config = {
            maxIter: options.maxIter || 1000,
            tabuSize: options.tabuSize || 20
        };
        
        let x = [...x0];
        let fx = f(x);
        let best = { x: [...x], fx };
        const tabuList = [];
        
        const isTabu = (move) => {
            return tabuList.some(t => 
                t.length === move.length && 
                t.every((v, i) => Math.abs(v - move[i]) < 1e-10)
            );
        };
        
        for (let iter = 0; iter < config.maxIter; iter++) {
            const candidateMoves = neighbors(x);
            
            let bestMove = null;
            let bestMoveFx = Infinity;
            
            for (const move of candidateMoves) {
                const moveFx = f(move);
                
                // Accept if not tabu or if aspiration criteria met
                if (!isTabu(move) || moveFx < best.fx) {
                    if (moveFx < bestMoveFx) {
                        bestMove = move;
                        bestMoveFx = moveFx;
                    }
                }
            }
            
            if (bestMove) {
                x = bestMove;
                fx = bestMoveFx;
                
                // Update tabu list
                tabuList.push([...x]);
                if (tabuList.length > config.tabuSize) {
                    tabuList.shift();
                }
                
                if (fx < best.fx) {
                    best = { x: [...x], fx };
                }
            }
        }
        
        return {
            optimal: best.x,
            value: best.fx,
            iterations: config.maxIter,
            source: 'MIT 18.433 - Tabu Search'
        };
    },
    
    /**
     * Branch and Bound
     * Source: MIT 18.433
     */
    branchAndBound: function(problem, options = {}) {
        const config = {
            maxNodes: options.maxNodes || 10000
        };
        
        const { objective, variables, constraints, bounds } = problem;
        const n = variables.length;
        
        let bestSolution = null;
        let bestValue = Infinity;
        let nodesExplored = 0;
        
        // Node: { bounds, level, fixedVars }
        const stack = [{ bounds: bounds.map(b => [...b]), level: 0, fixedVars: [] }];
        
        while (stack.length > 0 && nodesExplored < config.maxNodes) {
            const node = stack.pop();
            nodesExplored++;
            
            // Solve LP relaxation (simplified - just evaluate at midpoint)
            const x = node.bounds.map(b => (b[0] + b[1]) / 2);
            const value = objective(x);
            
            // Pruning
            if (value >= bestValue) continue;
            
            // Check if integer feasible
            let allInteger = true;
            let fractionalIdx = -1;
            
            for (let i = 0; i < n; i++) {
                if (variables[i].type === 'integer') {
                    if (Math.abs(x[i] - Math.round(x[i])) > 1e-6) {
                        allInteger = false;
                        fractionalIdx = i;
                        break;
                    }
                }
            }
            
            if (allInteger) {
                // Check constraints
                let feasible = true;
                if (constraints) {
                    for (const c of constraints) {
                        if (!c(x)) {
                            feasible = false;
                            break;
                        }
                    }
                }
                
                if (feasible && value < bestValue) {
                    bestValue = value;
                    bestSolution = [...x];
                }
            } else {
                // Branch
                const left = {
                    bounds: node.bounds.map(b => [...b]),
                    level: node.level + 1,
                    fixedVars: [...node.fixedVars]
                };
                left.bounds[fractionalIdx][1] = Math.floor(x[fractionalIdx]);
                
                const right = {
                    bounds: node.bounds.map(b => [...b]),
                    level: node.level + 1,
                    fixedVars: [...node.fixedVars]
                };
                right.bounds[fractionalIdx][0] = Math.ceil(x[fractionalIdx]);
                
                if (left.bounds[fractionalIdx][0] <= left.bounds[fractionalIdx][1]) {
                    stack.push(left);
                }
                if (right.bounds[fractionalIdx][0] <= right.bounds[fractionalIdx][1]) {
                    stack.push(right);
                }
            }
        }
        
        return {
            optimal: bestSolution,
            value: bestValue,
            nodesExplored,
            source: 'MIT 18.433 - Branch and Bound'
        };
    }
};

// ═══════════════════════════════════════════════════════════════════════════════════════════
// PHASE 2 ADVANCED MACHINE LEARNING
// Sources: Stanford CS229, MIT 6.036, Berkeley CS189
// ═══════════════════════════════════════════════════════════════════════════════════════════

const PRISM_PHASE2_ADVANCED_ML = {
    name: 'Phase 2 Advanced Machine Learning',
    version: '1.0.0',
    source: 'Stanford CS229, MIT 6.036, Berkeley CS189',
    
    /**
     * Support Vector Machine (SVM) using SMO algorithm
     * Source: Stanford CS229
     */
    svm: function(X, y, options = {}) {
        const config = {
            C: options.C || 1.0,           // Regularization
            tol: options.tol || 1e-3,
            maxPasses: options.maxPasses || 100,
            kernel: options.kernel || 'linear'
        };
        
        const n = X.length;
        const m = X[0].length;
        
        // Initialize
        const alpha = new Array(n).fill(0);
        let b = 0;
        let passes = 0;
        
        // Kernel function
        const kernel = (x1, x2) => {
            if (config.kernel === 'linear') {
                return x1.reduce((sum, v, i) => sum + v * x2[i], 0);
            } else if (config.kernel === 'rbf') {
                const gamma = options.gamma || 0.1;
                const diff = x1.reduce((sum, v, i) => sum + Math.pow(v - x2[i], 2), 0);
                return Math.exp(-gamma * diff);
            }
            return x1.reduce((sum, v, i) => sum + v * x2[i], 0);
        };
        
        // SMO algorithm
        while (passes < config.maxPasses) {
            let numChangedAlphas = 0;
            
            for (let i = 0; i < n; i++) {
                // Calculate Ei
                let fi = b;
                for (let j = 0; j < n; j++) {
                    fi += alpha[j] * y[j] * kernel(X[j], X[i]);
                }
                const Ei = fi - y[i];
                
                if ((y[i] * Ei < -config.tol && alpha[i] < config.C) ||
                    (y[i] * Ei > config.tol && alpha[i] > 0)) {
                    
                    // Select j randomly
                    let j = Math.floor(Math.random() * n);
                    while (j === i) j = Math.floor(Math.random() * n);
                    
                    // Calculate Ej
                    let fj = b;
                    for (let k = 0; k < n; k++) {
                        fj += alpha[k] * y[k] * kernel(X[k], X[j]);
                    }
                    const Ej = fj - y[j];
                    
                    const alphaIOld = alpha[i];
                    const alphaJOld = alpha[j];
                    
                    // Compute L and H
                    let L, H;
                    if (y[i] !== y[j]) {
                        L = Math.max(0, alpha[j] - alpha[i]);
                        H = Math.min(config.C, config.C + alpha[j] - alpha[i]);
                    } else {
                        L = Math.max(0, alpha[i] + alpha[j] - config.C);
                        H = Math.min(config.C, alpha[i] + alpha[j]);
                    }
                    
                    if (L === H) continue;
                    
                    // Compute eta
                    const eta = 2 * kernel(X[i], X[j]) - kernel(X[i], X[i]) - kernel(X[j], X[j]);
                    if (eta >= 0) continue;
                    
                    // Update alpha[j]
                    alpha[j] = alpha[j] - (y[j] * (Ei - Ej)) / eta;
                    alpha[j] = Math.max(L, Math.min(H, alpha[j]));
                    
                    if (Math.abs(alpha[j] - alphaJOld) < 1e-5) continue;
                    
                    // Update alpha[i]
                    alpha[i] = alpha[i] + y[i] * y[j] * (alphaJOld - alpha[j]);
                    
                    // Compute b
                    const b1 = b - Ei - y[i] * (alpha[i] - alphaIOld) * kernel(X[i], X[i])
                        - y[j] * (alpha[j] - alphaJOld) * kernel(X[i], X[j]);
                    const b2 = b - Ej - y[i] * (alpha[i] - alphaIOld) * kernel(X[i], X[j])
                        - y[j] * (alpha[j] - alphaJOld) * kernel(X[j], X[j]);
                    
                    if (0 < alpha[i] && alpha[i] < config.C) {
                        b = b1;
                    } else if (0 < alpha[j] && alpha[j] < config.C) {
                        b = b2;
                    } else {
                        b = (b1 + b2) / 2;
                    }
                    
                    numChangedAlphas++;
                }
            }
            
            if (numChangedAlphas === 0) {
                passes++;
            } else {
                passes = 0;
            }
        }
        
        // Extract support vectors
        const supportVectors = [];
        for (let i = 0; i < n; i++) {
            if (alpha[i] > 1e-5) {
                supportVectors.push({ index: i, alpha: alpha[i], x: X[i], y: y[i] });
            }
        }
        
        return {
            alpha,
            b,
            supportVectors,
            kernel: config.kernel,
            predict: (xNew) => {
                let sum = b;
                for (const sv of supportVectors) {
                    sum += sv.alpha * sv.y * kernel(sv.x, xNew);
                }
                return sum >= 0 ? 1 : -1;
            },
            source: 'Stanford CS229 - SVM (SMO)'
        };
    },
    
    /**
     * SVM Classify helper
     */
    svmClassify: function(model, X) {
        return X.map(x => model.predict(x));
    },
    
    /**
     * DBSCAN Clustering
     * Source: Various - Density-based clustering
     */
    dbscan: function(X, eps, minPts) {
        const n = X.length;
        const labels = new Array(n).fill(-1); // -1 = unvisited
        let clusterId = 0;
        
        const distance = (a, b) => {
            return Math.sqrt(a.reduce((sum, v, i) => sum + Math.pow(v - b[i], 2), 0));
        };
        
        const regionQuery = (idx) => {
            const neighbors = [];
            for (let i = 0; i < n; i++) {
                if (distance(X[idx], X[i]) <= eps) {
                    neighbors.push(i);
                }
            }
            return neighbors;
        };
        
        const expandCluster = (idx, neighbors, clusterId) => {
            labels[idx] = clusterId;
            const queue = [...neighbors];
            
            while (queue.length > 0) {
                const currentIdx = queue.shift();
                
                if (labels[currentIdx] === -2) { // Noise becomes border point
                    labels[currentIdx] = clusterId;
                }
                
                if (labels[currentIdx] !== -1) continue;
                
                labels[currentIdx] = clusterId;
                const currentNeighbors = regionQuery(currentIdx);
                
                if (currentNeighbors.length >= minPts) {
                    for (const neighbor of currentNeighbors) {
                        if (labels[neighbor] === -1 || labels[neighbor] === -2) {
                            queue.push(neighbor);
                        }
                    }
                }
            }
        };
        
        for (let i = 0; i < n; i++) {
            if (labels[i] !== -1) continue;
            
            const neighbors = regionQuery(i);
            
            if (neighbors.length < minPts) {
                labels[i] = -2; // Noise
            } else {
                expandCluster(i, neighbors, clusterId);
                clusterId++;
            }
        }
        
        // Convert -2 to -1 (noise)
        for (let i = 0; i < n; i++) {
            if (labels[i] === -2) labels[i] = -1;
        }
        
        return {
            labels,
            numClusters: clusterId,
            noise: labels.filter(l => l === -1).length,
            source: 'DBSCAN Clustering'
        };
    },
    
    /**
     * Principal Component Analysis (PCA)
     * Source: MIT 6.036, Stanford CS229
     */
    pca: function(X, numComponents) {
        const n = X.length;
        const m = X[0].length;
        
        // Center data
        const mean = new Array(m).fill(0);
        for (let i = 0; i < n; i++) {
            for (let j = 0; j < m; j++) {
                mean[j] += X[i][j];
            }
        }
        for (let j = 0; j < m; j++) {
            mean[j] /= n;
        }
        
        const XCentered = X.map(row => row.map((val, j) => val - mean[j]));
        
        // Compute covariance matrix
        const cov = [];
        for (let i = 0; i < m; i++) {
            cov[i] = [];
            for (let j = 0; j < m; j++) {
                let sum = 0;
                for (let k = 0; k < n; k++) {
                    sum += XCentered[k][i] * XCentered[k][j];
                }
                cov[i][j] = sum / (n - 1);
            }
        }
        
        // Power iteration for eigenvectors (simplified)
        const components = [];
        let covCopy = cov.map(row => [...row]);
        
        for (let comp = 0; comp < Math.min(numComponents, m); comp++) {
            // Power iteration
            let v = new Array(m).fill(0).map(() => Math.random());
            let vNorm = Math.sqrt(v.reduce((s, x) => s + x*x, 0));
            v = v.map(x => x / vNorm);
            
            for (let iter = 0; iter < 100; iter++) {
                // v = Cv
                const vNew = new Array(m).fill(0);
                for (let i = 0; i < m; i++) {
                    for (let j = 0; j < m; j++) {
                        vNew[i] += covCopy[i][j] * v[j];
                    }
                }
                
                vNorm = Math.sqrt(vNew.reduce((s, x) => s + x*x, 0));
                if (vNorm < 1e-10) break;
                
                v = vNew.map(x => x / vNorm);
            }
            
            // Eigenvalue
            let eigenvalue = 0;
            for (let i = 0; i < m; i++) {
                for (let j = 0; j < m; j++) {
                    eigenvalue += covCopy[i][j] * v[i] * v[j];
                }
            }
            
            components.push({ vector: v, eigenvalue });
            
            // Deflate
            for (let i = 0; i < m; i++) {
                for (let j = 0; j < m; j++) {
                    covCopy[i][j] -= eigenvalue * v[i] * v[j];
                }
            }
        }
        
        // Calculate explained variance
        const totalVar = components.reduce((s, c) => s + c.eigenvalue, 0);
        const explainedVariance = components.map(c => c.eigenvalue / totalVar);
        
        return {
            components: components.map(c => c.vector),
            eigenvalues: components.map(c => c.eigenvalue),
            explainedVariance,
            mean,
            transform: (xNew) => {
                const centered = xNew.map((v, i) => v - mean[i]);
                return components.map(c => 
                    c.vector.reduce((sum, v, i) => sum + v * centered[i], 0)
                );
            },
            source: 'MIT 6.036 - PCA'
        };
    },
    
    /**
     * PCA Transform helper
     */
    pcaTransform: function(model, X) {
        return X.map(x => model.transform(x));
    },
    
    /**
     * Logistic Regression
     * Source: Stanford CS229
     */
    logisticRegression: function(X, y, options = {}) {
        const config = {
            learningRate: options.learningRate || 0.1,
            maxIter: options.maxIter || 1000,
            tol: options.tol || 1e-6
        };
        
        const n = X.length;
        const m = X[0].length;
        
        // Add bias term
        const Xb = X.map(row => [1, ...row]);
        const w = new Array(m + 1).fill(0);
        
        const sigmoid = (z) => 1 / (1 + Math.exp(-Math.max(-500, Math.min(500, z))));
        
        for (let iter = 0; iter < config.maxIter; iter++) {
            const grad = new Array(m + 1).fill(0);
            
            for (let i = 0; i < n; i++) {
                const z = Xb[i].reduce((sum, x, j) => sum + w[j] * x, 0);
                const h = sigmoid(z);
                const error = h - y[i];
                
                for (let j = 0; j <= m; j++) {
                    grad[j] += error * Xb[i][j];
                }
            }
            
            // Update weights
            let gradNorm = 0;
            for (let j = 0; j <= m; j++) {
                grad[j] /= n;
                w[j] -= config.learningRate * grad[j];
                gradNorm += grad[j] * grad[j];
            }
            
            if (Math.sqrt(gradNorm) < config.tol) break;
        }
        
        return {
            weights: w,
            predict: (xNew) => {
                const xb = [1, ...xNew];
                const z = xb.reduce((sum, x, j) => sum + w[j] * x, 0);
                return sigmoid(z);
            },
            classify: (xNew) => {
                const xb = [1, ...xNew];
                const z = xb.reduce((sum, x, j) => sum + w[j] * x, 0);
                return sigmoid(z) >= 0.5 ? 1 : 0;
            },
            source: 'Stanford CS229 - Logistic Regression'
        };
    },
    
    /**
     * K-Nearest Neighbors
     * Source: Stanford CS229
     */
    knn: function(X, y, k = 5) {
        return {
            X,
            y,
            k,
            predict: function(xNew) {
                const distances = X.map((x, i) => ({
                    distance: Math.sqrt(x.reduce((sum, v, j) => sum + Math.pow(v - xNew[j], 2), 0)),
                    label: y[i]
                }));
                
                distances.sort((a, b) => a.distance - b.distance);
                const neighbors = distances.slice(0, k);
                
                // Vote
                const votes = {};
                for (const n of neighbors) {
                    votes[n.label] = (votes[n.label] || 0) + 1;
                }
                
                let maxVotes = 0;
                let prediction = neighbors[0].label;
                for (const [label, count] of Object.entries(votes)) {
                    if (count > maxVotes) {
                        maxVotes = count;
                        prediction = parseInt(label);
                    }
                }
                
                return prediction;
            },
            source: 'Stanford CS229 - KNN'
        };
    },
    
    /**
     * Decision Tree
     * Source: Stanford CS229
     */
    decisionTree: function(X, y, options = {}) {
        const config = {
            maxDepth: options.maxDepth || 10,
            minSamplesLeaf: options.minSamplesLeaf || 2
        };
        
        const buildTree = (X, y, depth) => {
            if (depth >= config.maxDepth || X.length <= config.minSamplesLeaf) {
                // Leaf node - majority vote
                const counts = {};
                for (const label of y) {
                    counts[label] = (counts[label] || 0) + 1;
                }
                let maxCount = 0;
                let prediction = y[0];
                for (const [label, count] of Object.entries(counts)) {
                    if (count > maxCount) {
                        maxCount = count;
                        prediction = parseInt(label);
                    }
                }
                return { isLeaf: true, prediction };
            }
            
            // Find best split
            const m = X[0].length;
            let bestGain = -Infinity;
            let bestFeature = 0;
            let bestThreshold = 0;
            
            const entropy = (labels) => {
                const counts = {};
                for (const l of labels) counts[l] = (counts[l] || 0) + 1;
                let e = 0;
                for (const count of Object.values(counts)) {
                    const p = count / labels.length;
                    if (p > 0) e -= p * Math.log2(p);
                }
                return e;
            };
            
            const parentEntropy = entropy(y);
            
            for (let f = 0; f < m; f++) {
                const values = [...new Set(X.map(x => x[f]))].sort((a, b) => a - b);
                
                for (let i = 0; i < values.length - 1; i++) {
                    const threshold = (values[i] + values[i + 1]) / 2;
                    
                    const leftIdx = X.map((x, idx) => x[f] <= threshold ? idx : -1).filter(i => i >= 0);
                    const rightIdx = X.map((x, idx) => x[f] > threshold ? idx : -1).filter(i => i >= 0);
                    
                    if (leftIdx.length < config.minSamplesLeaf || rightIdx.length < config.minSamplesLeaf) continue;
                    
                    const leftY = leftIdx.map(i => y[i]);
                    const rightY = rightIdx.map(i => y[i]);
                    
                    const gain = parentEntropy - 
                        (leftY.length / y.length) * entropy(leftY) - 
                        (rightY.length / y.length) * entropy(rightY);
                    
                    if (gain > bestGain) {
                        bestGain = gain;
                        bestFeature = f;
                        bestThreshold = threshold;
                    }
                }
            }
            
            if (bestGain <= 0) {
                const counts = {};
                for (const label of y) counts[label] = (counts[label] || 0) + 1;
                let maxCount = 0;
                let prediction = y[0];
                for (const [label, count] of Object.entries(counts)) {
                    if (count > maxCount) {
                        maxCount = count;
                        prediction = parseInt(label);
                    }
                }
                return { isLeaf: true, prediction };
            }
            
            const leftIdx = X.map((x, idx) => x[bestFeature] <= bestThreshold ? idx : -1).filter(i => i >= 0);
            const rightIdx = X.map((x, idx) => x[bestFeature] > bestThreshold ? idx : -1).filter(i => i >= 0);
            
            return {
                isLeaf: false,
                feature: bestFeature,
                threshold: bestThreshold,
                left: buildTree(leftIdx.map(i => X[i]), leftIdx.map(i => y[i]), depth + 1),
                right: buildTree(rightIdx.map(i => X[i]), rightIdx.map(i => y[i]), depth + 1)
            };
        };
        
        const tree = buildTree(X, y, 0);
        
        const predictOne = (node, x) => {
            if (node.isLeaf) return node.prediction;
            if (x[node.feature] <= node.threshold) {
                return predictOne(node.left, x);
            } else {
                return predictOne(node.right, x);
            }
        };
        
        return {
            tree,
            predict: (xNew) => predictOne(tree, xNew),
            source: 'Stanford CS229 - Decision Tree'
        };
    },
    
    /**
     * Gradient Boosting
     * Source: Stanford CS229
     */
    gradientBoosting: function(X, y, options = {}) {
        const config = {
            numTrees: options.numTrees || 50,
            learningRate: options.learningRate || 0.1,
            maxDepth: options.maxDepth || 3
        };
        
        const n = X.length;
        const trees = [];
        let predictions = new Array(n).fill(0);
        
        // Initial prediction (mean for regression)
        const mean = y.reduce((a, b) => a + b, 0) / n;
        predictions = predictions.map(() => mean);
        
        for (let t = 0; t < config.numTrees; t++) {
            // Calculate residuals
            const residuals = y.map((yi, i) => yi - predictions[i]);
            
            // Fit tree to residuals
            const tree = this.decisionTree(X, residuals.map(r => r > 0 ? 1 : 0), { maxDepth: config.maxDepth });
            
            // Store tree with residuals for regression
            trees.push({
                tree: tree.tree,
                predict: (x) => {
                    const pred = tree.predict(x);
                    return pred === 1 ? config.learningRate : -config.learningRate;
                }
            });
            
            // Update predictions
            for (let i = 0; i < n; i++) {
                predictions[i] += trees[t].predict(X[i]);
            }
        }
        
        return {
            trees,
            initialPrediction: mean,
            predict: (xNew) => {
                let pred = mean;
                for (const tree of trees) {
                    pred += tree.predict(xNew);
                }
                return pred;
            },
            source: 'Stanford CS229 - Gradient Boosting'
        };
    },
    
    /**
     * AdaBoost
     * Source: Stanford CS229
     */
    adaBoost: function(X, y, options = {}) {
        const config = {
            numEstimators: options.numEstimators || 50
        };
        
        const n = X.length;
        let weights = new Array(n).fill(1 / n);
        const estimators = [];
        
        for (let t = 0; t < config.numEstimators; t++) {
            // Train weak learner (decision stump)
            const stump = this._trainStump(X, y, weights);
            
            // Calculate error
            let error = 0;
            for (let i = 0; i < n; i++) {
                if (stump.predict(X[i]) !== y[i]) {
                    error += weights[i];
                }
            }
            
            if (error >= 0.5) break;
            
            // Calculate alpha
            const alpha = 0.5 * Math.log((1 - error) / (error + 1e-10));
            
            estimators.push({ stump, alpha });
            
            // Update weights
            let sumWeights = 0;
            for (let i = 0; i < n; i++) {
                const prediction = stump.predict(X[i]);
                weights[i] *= Math.exp(-alpha * y[i] * prediction);
                sumWeights += weights[i];
            }
            
            // Normalize
            weights = weights.map(w => w / sumWeights);
        }
        
        return {
            estimators,
            predict: (xNew) => {
                let sum = 0;
                for (const { stump, alpha } of estimators) {
                    sum += alpha * stump.predict(xNew);
                }
                return sum >= 0 ? 1 : -1;
            },
            source: 'Stanford CS229 - AdaBoost'
        };
    },
    
    _trainStump: function(X, y, weights) {
        const n = X.length;
        const m = X[0].length;
        
        let bestError = Infinity;
        let bestFeature = 0;
        let bestThreshold = 0;
        let bestPolarity = 1;
        
        for (let f = 0; f < m; f++) {
            const values = [...new Set(X.map(x => x[f]))].sort((a, b) => a - b);
            
            for (let i = 0; i < values.length; i++) {
                const threshold = values[i];
                
                for (const polarity of [1, -1]) {
                    let error = 0;
                    for (let j = 0; j < n; j++) {
                        const pred = polarity * (X[j][f] <= threshold ? 1 : -1);
                        if (pred !== y[j]) {
                            error += weights[j];
                        }
                    }
                    
                    if (error < bestError) {
                        bestError = error;
                        bestFeature = f;
                        bestThreshold = threshold;
                        bestPolarity = polarity;
                    }
                }
            }
        }
        
        return {
            feature: bestFeature,
            threshold: bestThreshold,
            polarity: bestPolarity,
            predict: (x) => bestPolarity * (x[bestFeature] <= bestThreshold ? 1 : -1)
        };
    },
    
    /**
     * Naive Bayes
     * Source: Stanford CS229
     */
    naiveBayes: function(X, y) {
        const n = X.length;
        const m = X[0].length;
        
        // Get unique classes
        const classes = [...new Set(y)];
        
        // Calculate priors and likelihoods
        const priors = {};
        const means = {};
        const variances = {};
        
        for (const c of classes) {
            const classData = X.filter((_, i) => y[i] === c);
            priors[c] = classData.length / n;
            
            means[c] = new Array(m).fill(0);
            variances[c] = new Array(m).fill(0);
            
            for (const x of classData) {
                for (let j = 0; j < m; j++) {
                    means[c][j] += x[j];
                }
            }
            for (let j = 0; j < m; j++) {
                means[c][j] /= classData.length;
            }
            
            for (const x of classData) {
                for (let j = 0; j < m; j++) {
                    variances[c][j] += Math.pow(x[j] - means[c][j], 2);
                }
            }
            for (let j = 0; j < m; j++) {
                variances[c][j] = variances[c][j] / classData.length + 1e-6;
            }
        }
        
        const gaussianPdf = (x, mean, variance) => {
            return Math.exp(-Math.pow(x - mean, 2) / (2 * variance)) / Math.sqrt(2 * Math.PI * variance);
        };
        
        return {
            classes,
            priors,
            means,
            variances,
            predict: (xNew) => {
                let bestClass = classes[0];
                let bestProb = -Infinity;
                
                for (const c of classes) {
                    let logProb = Math.log(priors[c]);
                    
                    for (let j = 0; j < m; j++) {
                        logProb += Math.log(gaussianPdf(xNew[j], means[c][j], variances[c][j]) + 1e-10);
                    }
                    
                    if (logProb > bestProb) {
                        bestProb = logProb;
                        bestClass = c;
                    }
                }
                
                return bestClass;
            },
            source: 'Stanford CS229 - Naive Bayes'
        };
    }
};

// ═══════════════════════════════════════════════════════════════════════════════════════════
// PHASE 2 REINFORCEMENT LEARNING
// Sources: Stanford CS234, Berkeley CS285
// ═══════════════════════════════════════════════════════════════════════════════════════════

const PRISM_PHASE2_REINFORCEMENT_LEARNING = {
    name: 'Phase 2 Reinforcement Learning',
    version: '1.0.0',
    source: 'Stanford CS234, Berkeley CS285',
    
    /**
     * Q-Learning
     * Source: Stanford CS234
     */
    qLearning: function(env, options = {}) {
        const config = {
            episodes: options.episodes || 1000,
            alpha: options.alpha || 0.1,           // Learning rate
            gamma: options.gamma || 0.99,          // Discount factor
            epsilon: options.epsilon || 0.1,       // Exploration rate
            epsilonDecay: options.epsilonDecay || 0.995
        };
        
        const Q = {};
        let epsilon = config.epsilon;
        const rewards = [];
        
        const getQ = (s, a) => {
            const key = `${JSON.stringify(s)}_${a}`;
            if (!(key in Q)) Q[key] = 0;
            return Q[key];
        };
        
        const setQ = (s, a, val) => {
            Q[`${JSON.stringify(s)}_${a}`] = val;
        };
        
        const getMaxQ = (s) => {
            let maxQ = -Infinity;
            for (const a of env.actions) {
                maxQ = Math.max(maxQ, getQ(s, a));
            }
            return maxQ === -Infinity ? 0 : maxQ;
        };
        
        const selectAction = (s) => {
            if (Math.random() < epsilon) {
                return env.actions[Math.floor(Math.random() * env.actions.length)];
            }
            let bestA = env.actions[0];
            let bestQ = getQ(s, bestA);
            for (const a of env.actions) {
                const q = getQ(s, a);
                if (q > bestQ) {
                    bestQ = q;
                    bestA = a;
                }
            }
            return bestA;
        };
        
        for (let ep = 0; ep < config.episodes; ep++) {
            let s = env.reset();
            let totalReward = 0;
            let done = false;
            
            while (!done) {
                const a = selectAction(s);
                const { nextState, reward, done: isDone } = env.step(s, a);
                
                // Q-learning update
                const oldQ = getQ(s, a);
                const newQ = oldQ + config.alpha * (reward + config.gamma * getMaxQ(nextState) - oldQ);
                setQ(s, a, newQ);
                
                s = nextState;
                totalReward += reward;
                done = isDone;
            }
            
            rewards.push(totalReward);
            epsilon *= config.epsilonDecay;
        }
        
        return {
            Q,
            rewards,
            getPolicy: () => {
                const policy = {};
                for (const key of Object.keys(Q)) {
                    const [stateStr, action] = key.split('_');
                    const state = stateStr;
                    if (!(state in policy) || Q[key] > Q[`${state}_${policy[state]}`]) {
                        policy[state] = action;
                    }
                }
                return policy;
            },
            source: 'Stanford CS234 - Q-Learning'
        };
    },
    
    /**
     * SARSA (State-Action-Reward-State-Action)
     * Source: Stanford CS234
     */
    sarsa: function(env, options = {}) {
        const config = {
            episodes: options.episodes || 1000,
            alpha: options.alpha || 0.1,
            gamma: options.gamma || 0.99,
            epsilon: options.epsilon || 0.1
        };
        
        const Q = {};
        const rewards = [];
        
        const getQ = (s, a) => {
            const key = `${JSON.stringify(s)}_${a}`;
            if (!(key in Q)) Q[key] = 0;
            return Q[key];
        };
        
        const setQ = (s, a, val) => {
            Q[`${JSON.stringify(s)}_${a}`] = val;
        };
        
        const selectAction = (s) => {
            if (Math.random() < config.epsilon) {
                return env.actions[Math.floor(Math.random() * env.actions.length)];
            }
            let bestA = env.actions[0];
            let bestQ = getQ(s, bestA);
            for (const a of env.actions) {
                if (getQ(s, a) > bestQ) {
                    bestQ = getQ(s, a);
                    bestA = a;
                }
            }
            return bestA;
        };
        
        for (let ep = 0; ep < config.episodes; ep++) {
            let s = env.reset();
            let a = selectAction(s);
            let totalReward = 0;
            let done = false;
            
            while (!done) {
                const { nextState, reward, done: isDone } = env.step(s, a);
                const nextA = selectAction(nextState);
                
                // SARSA update (on-policy)
                const oldQ = getQ(s, a);
                const newQ = oldQ + config.alpha * (reward + config.gamma * getQ(nextState, nextA) - oldQ);
                setQ(s, a, newQ);
                
                s = nextState;
                a = nextA;
                totalReward += reward;
                done = isDone;
            }
            
            rewards.push(totalReward);
        }
        
        return {
            Q,
            rewards,
            source: 'Stanford CS234 - SARSA'
        };
    },
    
    /**
     * Actor-Critic
     * Source: Berkeley CS285
     */
    actorCritic: function(env, options = {}) {
        const config = {
            episodes: options.episodes || 1000,
            actorLR: options.actorLR || 0.01,
            criticLR: options.criticLR || 0.1,
            gamma: options.gamma || 0.99
        };
        
        // Simple linear function approximation
        const numFeatures = env.stateSize || 4;
        const numActions = env.actions.length;
        
        // Actor weights (policy)
        let actorW = new Array(numActions).fill(null).map(() => 
            new Array(numFeatures).fill(0).map(() => Math.random() * 0.1)
        );
        
        // Critic weights (value function)
        let criticW = new Array(numFeatures).fill(0);
        
        const softmax = (logits) => {
            const maxLogit = Math.max(...logits);
            const exp = logits.map(l => Math.exp(l - maxLogit));
            const sum = exp.reduce((a, b) => a + b, 0);
            return exp.map(e => e / sum);
        };
        
        const getFeatures = (s) => {
            return Array.isArray(s) ? s : [s, s*s, Math.sin(s), 1];
        };
        
        const getValue = (s) => {
            const features = getFeatures(s);
            return features.reduce((sum, f, i) => sum + f * criticW[i], 0);
        };
        
        const getActionProbs = (s) => {
            const features = getFeatures(s);
            const logits = actorW.map(w => 
                features.reduce((sum, f, i) => sum + f * w[i], 0)
            );
            return softmax(logits);
        };
        
        const rewards = [];
        
        for (let ep = 0; ep < config.episodes; ep++) {
            let s = env.reset();
            let totalReward = 0;
            let done = false;
            
            while (!done) {
                const probs = getActionProbs(s);
                
                // Sample action
                const r = Math.random();
                let cumProb = 0;
                let aIdx = 0;
                for (let i = 0; i < probs.length; i++) {
                    cumProb += probs[i];
                    if (r < cumProb) {
                        aIdx = i;
                        break;
                    }
                }
                const a = env.actions[aIdx];
                
                const { nextState, reward, done: isDone } = env.step(s, a);
                
                // TD error (advantage estimate)
                const tdTarget = reward + (isDone ? 0 : config.gamma * getValue(nextState));
                const tdError = tdTarget - getValue(s);
                
                // Update critic
                const features = getFeatures(s);
                for (let i = 0; i < criticW.length; i++) {
                    criticW[i] += config.criticLR * tdError * features[i];
                }
                
                // Update actor (policy gradient)
                for (let i = 0; i < numActions; i++) {
                    const indicator = i === aIdx ? 1 : 0;
                    for (let j = 0; j < numFeatures; j++) {
                        actorW[i][j] += config.actorLR * tdError * (indicator - probs[i]) * features[j];
                    }
                }
                
                s = nextState;
                totalReward += reward;
                done = isDone;
            }
            
            rewards.push(totalReward);
        }
        
        return {
            actorW,
            criticW,
            rewards,
            getPolicy: (s) => {
                const probs = getActionProbs(s);
                let maxIdx = 0;
                for (let i = 1; i < probs.length; i++) {
                    if (probs[i] > probs[maxIdx]) maxIdx = i;
                }
                return env.actions[maxIdx];
            },
            source: 'Berkeley CS285 - Actor-Critic'
        };
    },
    
    /**
     * Policy Gradient (REINFORCE)
     * Source: Stanford CS234
     */
    policyGradient: function(env, options = {}) {
        const config = {
            episodes: options.episodes || 1000,
            learningRate: options.learningRate || 0.01,
            gamma: options.gamma || 0.99
        };
        
        const numFeatures = env.stateSize || 4;
        const numActions = env.actions.length;
        
        let weights = new Array(numActions).fill(null).map(() => 
            new Array(numFeatures).fill(0).map(() => Math.random() * 0.1)
        );
        
        const getFeatures = (s) => Array.isArray(s) ? s : [s, s*s, Math.sin(s), 1];
        
        const softmax = (logits) => {
            const maxLogit = Math.max(...logits);
            const exp = logits.map(l => Math.exp(l - maxLogit));
            const sum = exp.reduce((a, b) => a + b, 0);
            return exp.map(e => e / sum);
        };
        
        const rewards = [];
        
        for (let ep = 0; ep < config.episodes; ep++) {
            const trajectory = [];
            let s = env.reset();
            let done = false;
            
            // Generate episode
            while (!done) {
                const features = getFeatures(s);
                const logits = weights.map(w => 
                    features.reduce((sum, f, i) => sum + f * w[i], 0)
                );
                const probs = softmax(logits);
                
                const r = Math.random();
                let cumProb = 0;
                let aIdx = 0;
                for (let i = 0; i < probs.length; i++) {
                    cumProb += probs[i];
                    if (r < cumProb) {
                        aIdx = i;
                        break;
                    }
                }
                
                const a = env.actions[aIdx];
                const { nextState, reward, done: isDone } = env.step(s, a);
                
                trajectory.push({ s, aIdx, reward, probs, features });
                s = nextState;
                done = isDone;
            }
            
            // Calculate returns
            let G = 0;
            for (let t = trajectory.length - 1; t >= 0; t--) {
                G = trajectory[t].reward + config.gamma * G;
                trajectory[t].G = G;
            }
            
            // Update weights
            for (const step of trajectory) {
                for (let i = 0; i < numActions; i++) {
                    const indicator = i === step.aIdx ? 1 : 0;
                    for (let j = 0; j < numFeatures; j++) {
                        weights[i][j] += config.learningRate * step.G * 
                            (indicator - step.probs[i]) * step.features[j];
                    }
                }
            }
            
            rewards.push(trajectory.reduce((sum, s) => sum + s.reward, 0));
        }
        
        return {
            weights,
            rewards,
            source: 'Stanford CS234 - REINFORCE'
        };
    },
    
    /**
     * TD(λ)
     * Source: Stanford CS234
     */
    tdLambda: function(env, options = {}) {
        const config = {
            episodes: options.episodes || 500,
            alpha: options.alpha || 0.1,
            gamma: options.gamma || 0.99,
            lambda: options.lambda || 0.8
        };
        
        const V = {};
        const getV = (s) => V[JSON.stringify(s)] || 0;
        const setV = (s, val) => { V[JSON.stringify(s)] = val; };
        
        for (let ep = 0; ep < config.episodes; ep++) {
            const eligibility = {};
            let s = env.reset();
            let done = false;
            
            while (!done) {
                const a = env.actions[Math.floor(Math.random() * env.actions.length)];
                const { nextState, reward, done: isDone } = env.step(s, a);
                
                const delta = reward + (isDone ? 0 : config.gamma * getV(nextState)) - getV(s);
                
                // Update eligibility
                const sKey = JSON.stringify(s);
                eligibility[sKey] = (eligibility[sKey] || 0) + 1;
                
                // Update all states
                for (const key of Object.keys(eligibility)) {
                    const currentV = V[key] || 0;
                    V[key] = currentV + config.alpha * delta * eligibility[key];
                    eligibility[key] *= config.gamma * config.lambda;
                }
                
                s = nextState;
                done = isDone;
            }
        }
        
        return {
            V,
            source: 'Stanford CS234 - TD(λ)'
        };
    },
    
    /**
     * Adaptive Machining RL Environment
     * Protocol J: Innovation - RL for manufacturing
     */
    adaptiveMachining: function(options = {}) {
        const config = {
            episodes: options.episodes || 500
        };
        
        // Simple machining environment
        const env = {
            actions: ['increase_speed', 'decrease_speed', 'increase_feed', 'decrease_feed', 'maintain'],
            stateSize: 4,
            reset: () => [100, 0.1, 0.5, 50], // [speed, feed, wear, quality]
            step: (state, action) => {
                let [speed, feed, wear, quality] = state;
                
                // Apply action
                switch(action) {
                    case 'increase_speed': speed = Math.min(200, speed * 1.1); break;
                    case 'decrease_speed': speed = Math.max(50, speed * 0.9); break;
                    case 'increase_feed': feed = Math.min(0.3, feed * 1.1); break;
                    case 'decrease_feed': feed = Math.max(0.05, feed * 0.9); break;
                }
                
                // Update wear and quality
                wear += (speed / 100) * (feed / 0.1) * 0.01;
                quality = Math.max(0, 100 - wear * 10 - Math.abs(speed - 120) * 0.1);
                
                // Reward: balance productivity and quality
                const mrr = speed * feed;
                const reward = mrr * 0.1 + quality * 0.5 - wear * 2;
                
                const done = wear > 1 || quality < 20;
                
                return {
                    nextState: [speed, feed, wear, quality],
                    reward,
                    done
                };
            }
        };
        
        // Train with Actor-Critic
        const result = this.actorCritic(env, config);
        
        return {
            ...result,
            env,
            recommend: (state) => result.getPolicy(state),
            source: 'PRISM Innovation - RL Adaptive Machining'
        };
    },
    
    /**
     * Feed Rate Control RL
     */
    feedRateControl: function(options = {}) {
        const env = {
            actions: [-0.02, -0.01, 0, 0.01, 0.02], // Feed rate adjustments
            stateSize: 3,
            reset: () => [0.1, 500, 0], // [current_feed, cutting_force, error]
            step: (state, action) => {
                let [feed, force, error] = state;
                feed = Math.max(0.05, Math.min(0.3, feed + action));
                force = 400 + feed * 1000 + (Math.random() - 0.5) * 50;
                
                const targetForce = 500;
                error = force - targetForce;
                const reward = -Math.abs(error) / 100;
                
                return {
                    nextState: [feed, force, error],
                    reward,
                    done: false
                };
            }
        };
        
        return this.qLearning(env, options);
    }
};

// ═══════════════════════════════════════════════════════════════════════════════════════════
// PHASE 2 QUALITY SYSTEM
// Sources: MIT 2.830, Georgia Tech
// ═══════════════════════════════════════════════════════════════════════════════════════════

const PRISM_PHASE2_QUALITY_SYSTEM = {
    name: 'Phase 2 Quality System',
    version: '1.0.0',
    source: 'MIT 2.830, Georgia Tech',
    
    /**
     * Control Chart Analysis
     * Source: MIT 2.830
     */
    controlChart: function(data, options = {}) {
        const n = data.length;
        const mean = data.reduce((a, b) => a + b, 0) / n;
        const stdDev = Math.sqrt(data.reduce((sum, x) => sum + Math.pow(x - mean, 2), 0) / (n - 1));
        
        const UCL = mean + 3 * stdDev;
        const LCL = mean - 3 * stdDev;
        const UWL = mean + 2 * stdDev; // Warning limits
        const LWL = mean - 2 * stdDev;
        
        // Check for out of control points
        const outOfControl = [];
        const warnings = [];
        
        for (let i = 0; i < n; i++) {
            if (data[i] > UCL || data[i] < LCL) {
                outOfControl.push({ index: i, value: data[i], type: 'beyond_control_limit' });
            } else if (data[i] > UWL || data[i] < LWL) {
                warnings.push({ index: i, value: data[i], type: 'warning_zone' });
            }
        }
        
        // Check for runs (7 consecutive points on one side)
        for (let i = 0; i <= n - 7; i++) {
            const run = data.slice(i, i + 7);
            if (run.every(x => x > mean) || run.every(x => x < mean)) {
                outOfControl.push({ index: i, type: 'run_of_7' });
            }
        }
        
        // Check for trends (7 consecutive increasing or decreasing)
        for (let i = 0; i <= n - 7; i++) {
            let increasing = true, decreasing = true;
            for (let j = 1; j < 7; j++) {
                if (data[i + j] <= data[i + j - 1]) increasing = false;
                if (data[i + j] >= data[i + j - 1]) decreasing = false;
            }
            if (increasing || decreasing) {
                outOfControl.push({ index: i, type: 'trend' });
            }
        }
        
        return {
            mean,
            stdDev,
            UCL,
            LCL,
            UWL,
            LWL,
            inControl: outOfControl.length === 0,
            outOfControl,
            warnings,
            source: 'MIT 2.830 - Control Chart'
        };
    },
    
    /**
     * X-bar and R Chart
     * Source: MIT 2.830
     */
    xBarRChart: function(subgroups) {
        const k = subgroups.length;
        const n = subgroups[0].length;
        
        // Calculate subgroup means and ranges
        const xBars = subgroups.map(sg => sg.reduce((a, b) => a + b, 0) / n);
        const ranges = subgroups.map(sg => Math.max(...sg) - Math.min(...sg));
        
        // Grand mean and average range
        const xBarBar = xBars.reduce((a, b) => a + b, 0) / k;
        const rBar = ranges.reduce((a, b) => a + b, 0) / k;
        
        // Control chart constants (for sample size 2-10)
        const A2 = [0, 0, 1.880, 1.023, 0.729, 0.577, 0.483, 0.419, 0.373, 0.337, 0.308];
        const D3 = [0, 0, 0, 0, 0, 0, 0, 0.076, 0.136, 0.184, 0.223];
        const D4 = [0, 0, 3.267, 2.574, 2.282, 2.114, 2.004, 1.924, 1.864, 1.816, 1.777];
        
        // X-bar chart limits
        const xBarUCL = xBarBar + A2[n] * rBar;
        const xBarLCL = xBarBar - A2[n] * rBar;
        
        // R chart limits
        const rUCL = D4[n] * rBar;
        const rLCL = D3[n] * rBar;
        
        return {
            xBarBar,
            rBar,
            xBarChart: {
                centerLine: xBarBar,
                UCL: xBarUCL,
                LCL: xBarLCL,
                values: xBars
            },
            rChart: {
                centerLine: rBar,
                UCL: rUCL,
                LCL: rLCL,
                values: ranges
            },
            source: 'MIT 2.830 - X-bar R Chart'
        };
    },
    
    /**
     * CUSUM Chart
     * Source: MIT 2.830
     */
    cusumChart: function(data, target, options = {}) {
        const config = {
            k: options.k || 0.5,    // Slack value
            h: options.h || 5       // Decision interval
        };
        
        const n = data.length;
        const sigma = Math.sqrt(data.reduce((sum, x) => sum + Math.pow(x - target, 2), 0) / (n - 1));
        
        const cusumHigh = [0];
        const cusumLow = [0];
        const outOfControl = [];
        
        for (let i = 0; i < n; i++) {
            const z = (data[i] - target) / sigma;
            
            cusumHigh.push(Math.max(0, cusumHigh[i] + z - config.k));
            cusumLow.push(Math.min(0, cusumLow[i] + z + config.k));
            
            if (cusumHigh[i + 1] > config.h) {
                outOfControl.push({ index: i, type: 'high', value: cusumHigh[i + 1] });
            }
            if (cusumLow[i + 1] < -config.h) {
                outOfControl.push({ index: i, type: 'low', value: cusumLow[i + 1] });
            }
        }
        
        return {
            cusumHigh: cusumHigh.slice(1),
            cusumLow: cusumLow.slice(1),
            h: config.h,
            outOfControl,
            inControl: outOfControl.length === 0,
            source: 'MIT 2.830 - CUSUM Chart'
        };
    },
    
    /**
     * Process Capability Analysis
     * Source: MIT 2.830
     */
    processCapability: function(data, LSL, USL) {
        const n = data.length;
        const mean = data.reduce((a, b) => a + b, 0) / n;
        const stdDev = Math.sqrt(data.reduce((sum, x) => sum + Math.pow(x - mean, 2), 0) / (n - 1));
        
        // Cp - Process capability (potential)
        const Cp = (USL - LSL) / (6 * stdDev);
        
        // Cpk - Process capability (actual, accounts for centering)
        const Cpu = (USL - mean) / (3 * stdDev);
        const Cpl = (mean - LSL) / (3 * stdDev);
        const Cpk = Math.min(Cpu, Cpl);
        
        // Pp and Ppk (using overall standard deviation)
        const Pp = Cp;  // Same for normal distribution assumption
        const Ppk = Cpk;
        
        // PPM (Parts Per Million) defective
        const zUpper = (USL - mean) / stdDev;
        const zLower = (mean - LSL) / stdDev;
        const ppmUpper = this._normalCDF(-zUpper) * 1e6;
        const ppmLower = this._normalCDF(-zLower) * 1e6;
        const ppmTotal = ppmUpper + ppmLower;
        
        // Sigma level
        const sigmaLevel = Math.min(zUpper, zLower);
        
        return {
            Cp,
            Cpk,
            Cpu,
            Cpl,
            Pp,
            Ppk,
            mean,
            stdDev,
            ppm: {
                upper: ppmUpper,
                lower: ppmLower,
                total: ppmTotal
            },
            sigmaLevel,
            capable: Cpk >= 1.33,
            interpretation: Cpk >= 1.67 ? 'Excellent' : 
                           Cpk >= 1.33 ? 'Good' : 
                           Cpk >= 1.0 ? 'Marginal' : 'Poor',
            source: 'MIT 2.830 - Process Capability'
        };
    },
    
    /**
     * Calculate Cpk
     */
    calculateCpk: function(data, LSL, USL) {
        return this.processCapability(data, LSL, USL).Cpk;
    },
    
    _normalCDF: function(z) {
        const a1 = 0.254829592;
        const a2 = -0.284496736;
        const a3 = 1.421413741;
        const a4 = -1.453152027;
        const a5 = 1.061405429;
        const p = 0.3275911;
        
        const sign = z < 0 ? -1 : 1;
        z = Math.abs(z) / Math.sqrt(2);
        
        const t = 1 / (1 + p * z);
        const y = 1 - (((((a5 * t + a4) * t) + a3) * t + a2) * t + a1) * t * Math.exp(-z * z);
        
        return 0.5 * (1 + sign * y);
    },
    
    /**
     * OEE (Overall Equipment Effectiveness)
     * Source: Georgia Tech
     */
    calculateOEE: function(params) {
        const {
            plannedProductionTime,
            actualRunTime,
            totalParts,
            goodParts,
            idealCycleTime
        } = params;
        
        // Availability = Actual Run Time / Planned Production Time
        const availability = actualRunTime / plannedProductionTime;
        
        // Performance = (Ideal Cycle Time × Total Parts) / Actual Run Time
        const performance = (idealCycleTime * totalParts) / actualRunTime;
        
        // Quality = Good Parts / Total Parts
        const quality = goodParts / totalParts;
        
        // OEE = Availability × Performance × Quality
        const oee = availability * performance * quality;
        
        // Six big losses
        const losses = {
            breakdowns: plannedProductionTime - actualRunTime,
            setupAdjustment: 0, // Would need additional data
            idlingMinorStops: actualRunTime - (idealCycleTime * totalParts),
            reducedSpeed: 0, // Captured in performance
            defects: (totalParts - goodParts) * idealCycleTime,
            reducedYield: 0 // Would need startup data
        };
        
        return {
            oee: oee * 100,
            availability: availability * 100,
            performance: Math.min(performance * 100, 100),
            quality: quality * 100,
            losses,
            worldClass: oee >= 0.85,
            interpretation: oee >= 0.85 ? 'World Class' :
                           oee >= 0.65 ? 'Acceptable' :
                           oee >= 0.40 ? 'Needs Improvement' : 'Unacceptable',
            source: 'Georgia Tech - OEE'
        };
    },
    
    /**
     * Six Sigma Level Calculation
     * Source: Georgia Tech
     */
    sixSigmaLevel: function(defects, opportunities, units) {
        // DPMO = (Defects / (Opportunities × Units)) × 1,000,000
        const dpmo = (defects / (opportunities * units)) * 1e6;
        
        // Sigma level from DPMO (approximation)
        let sigma = 0;
        const dpmoTable = [
            { dpmo: 3.4, sigma: 6 },
            { dpmo: 233, sigma: 5 },
            { dpmo: 6210, sigma: 4 },
            { dpmo: 66807, sigma: 3 },
            { dpmo: 308538, sigma: 2 },
            { dpmo: 691462, sigma: 1 }
        ];
        
        for (const entry of dpmoTable) {
            if (dpmo <= entry.dpmo) {
                sigma = entry.sigma;
                break;
            }
        }
        
        // More precise calculation using inverse normal
        if (sigma === 0 && dpmo > 0) {
            sigma = 0.8406 + Math.sqrt(29.37 - 2.221 * Math.log(dpmo));
        }
        
        const yield_ = (1 - dpmo / 1e6) * 100;
        
        return {
            dpmo,
            sigmaLevel: sigma,
            yield: yield_,
            defectsPerUnit: defects / units,
            interpretation: sigma >= 6 ? 'Six Sigma (World Class)' :
                           sigma >= 5 ? 'Excellent' :
                           sigma >= 4 ? 'Good' :
                           sigma >= 3 ? 'Average' : 'Poor',
            source: 'Georgia Tech - Six Sigma'
        };
    },
    
    /**
     * Pareto Analysis
     * Source: Georgia Tech
     */
    paretoAnalysis: function(categories) {
        // categories: [{name, count}, ...]
        const total = categories.reduce((sum, c) => sum + c.count, 0);
        
        // Sort by count descending
        const sorted = [...categories].sort((a, b) => b.count - a.count);
        
        // Calculate percentages and cumulative
        let cumulative = 0;
        const analysis = sorted.map(c => {
            const percentage = (c.count / total) * 100;
            cumulative += percentage;
            return {
                ...c,
                percentage,
                cumulative
            };
        });
        
        // Find vital few (80/20 rule)
        const vitalFew = analysis.filter(c => c.cumulative <= 80);
        const trivialMany = analysis.filter(c => c.cumulative > 80);
        
        return {
            analysis,
            vitalFew,
            trivialMany,
            total,
            recommendation: `Focus on ${vitalFew.length} categories to address ${Math.round(vitalFew[vitalFew.length - 1]?.cumulative || 0)}% of issues`,
            source: 'Georgia Tech - Pareto Analysis'
        };
    },
    
    /**
     * FMEA Analysis
     * Source: Georgia Tech
     */
    fmeaAnalysis: function(failures) {
        // failures: [{mode, severity, occurrence, detection}, ...]
        
        const analyzed = failures.map(f => ({
            ...f,
            rpn: f.severity * f.occurrence * f.detection // Risk Priority Number
        }));
        
        // Sort by RPN descending
        analyzed.sort((a, b) => b.rpn - a.rpn);
        
        // Risk levels
        const withRisk = analyzed.map(f => ({
            ...f,
            riskLevel: f.rpn >= 200 ? 'High' :
                       f.rpn >= 100 ? 'Medium' : 'Low',
            action: f.rpn >= 200 ? 'Immediate action required' :
                    f.rpn >= 100 ? 'Action recommended' : 'Monitor'
        }));
        
        return {
            failures: withRisk,
            highRisk: withRisk.filter(f => f.riskLevel === 'High'),
            totalRPN: withRisk.reduce((sum, f) => sum + f.rpn, 0),
            maxRPN: Math.max(...withRisk.map(f => f.rpn)),
            source: 'Georgia Tech - FMEA'
        };
    }
};

// ═══════════════════════════════════════════════════════════════════════════════════════════
// PHASE 2 ADVANCED SIGNAL PROCESSING
// Sources: MIT 18.086
// ═══════════════════════════════════════════════════════════════════════════════════════════

const PRISM_PHASE2_ADVANCED_SIGNAL = {
    name: 'Phase 2 Advanced Signal Processing',
    version: '1.0.0',
    source: 'MIT 18.086',
    
    /**
     * Spectrogram (STFT-based)
     * Source: MIT 18.086
     */
    spectrogram: function(signal, sampleRate, options = {}) {
        const config = {
            windowSize: options.windowSize || 256,
            hopSize: options.hopSize || 128,
            windowType: options.windowType || 'hann'
        };
        
        const n = signal.length;
        const numFrames = Math.floor((n - config.windowSize) / config.hopSize) + 1;
        const numBins = Math.floor(config.windowSize / 2) + 1;
        
        // Generate window
        const window = this._generateWindow(config.windowSize, config.windowType);
        
        const spectrogram = [];
        const times = [];
        const frequencies = [];
        
        // Calculate frequency bins
        for (let i = 0; i < numBins; i++) {
            frequencies.push(i * sampleRate / config.windowSize);
        }
        
        for (let frame = 0; frame < numFrames; frame++) {
            const start = frame * config.hopSize;
            times.push(start / sampleRate);
            
            // Extract and window frame
            const frameData = [];
            for (let i = 0; i < config.windowSize; i++) {
                frameData.push((signal[start + i] || 0) * window[i]);
            }
            
            // FFT
            const fft = this._fft(frameData);
            
            // Magnitude spectrum
            const magnitudes = [];
            for (let i = 0; i < numBins; i++) {
                const re = fft[2 * i];
                const im = fft[2 * i + 1];
                magnitudes.push(Math.sqrt(re * re + im * im));
            }
            
            spectrogram.push(magnitudes);
        }
        
        return {
            spectrogram,
            times,
            frequencies,
            sampleRate,
            windowSize: config.windowSize,
            hopSize: config.hopSize,
            source: 'MIT 18.086 - Spectrogram'
        };
    },
    
    /**
     * Short-Time Fourier Transform
     */
    stft: function(signal, sampleRate, windowSize = 256, hopSize = 128) {
        return this.spectrogram(signal, sampleRate, { windowSize, hopSize });
    },
    
    /**
     * Hilbert Transform
     * Source: MIT 18.086
     */
    hilbertTransform: function(signal) {
        const n = signal.length;
        
        // FFT
        const fft = this._fft(signal);
        
        // Apply Hilbert transform in frequency domain
        const hilbertFft = new Array(n * 2).fill(0);
        
        // DC and Nyquist
        hilbertFft[0] = fft[0];
        hilbertFft[1] = fft[1];
        if (n % 2 === 0) {
            hilbertFft[n] = fft[n];
            hilbertFft[n + 1] = fft[n + 1];
        }
        
        // Positive frequencies × 2
        for (let i = 1; i < n / 2; i++) {
            hilbertFft[2 * i] = 2 * fft[2 * i];
            hilbertFft[2 * i + 1] = 2 * fft[2 * i + 1];
        }
        
        // IFFT
        const analytic = this._ifft(hilbertFft);
        
        // Extract real and imaginary parts
        const real = [];
        const imag = [];
        for (let i = 0; i < n; i++) {
            real.push(analytic[2 * i]);
            imag.push(analytic[2 * i + 1]);
        }
        
        return {
            real,
            imaginary: imag,
            source: 'MIT 18.086 - Hilbert Transform'
        };
    },
    
    /**
     * Envelope Detection
     * Source: MIT 18.086
     */
    envelopeDetection: function(signal) {
        const hilbert = this.hilbertTransform(signal);
        
        // Envelope = |analytic signal| = sqrt(real² + imag²)
        const envelope = [];
        for (let i = 0; i < signal.length; i++) {
            envelope.push(Math.sqrt(
                hilbert.real[i] * hilbert.real[i] + 
                hilbert.imaginary[i] * hilbert.imaginary[i]
            ));
        }
        
        // Instantaneous phase
        const phase = [];
        for (let i = 0; i < signal.length; i++) {
            phase.push(Math.atan2(hilbert.imaginary[i], hilbert.real[i]));
        }
        
        // Instantaneous frequency
        const instFreq = [];
        for (let i = 1; i < phase.length; i++) {
            let dPhase = phase[i] - phase[i - 1];
            // Unwrap
            while (dPhase > Math.PI) dPhase -= 2 * Math.PI;
            while (dPhase < -Math.PI) dPhase += 2 * Math.PI;
            instFreq.push(dPhase / (2 * Math.PI));
        }
        
        return {
            envelope,
            phase,
            instantaneousFrequency: instFreq,
            source: 'MIT 18.086 - Envelope Detection'
        };
    },
    
    /**
     * Wavelet Transform (Haar wavelet)
     * Source: MIT 18.086
     */
    waveletTransform: function(signal, levels = 4) {
        let data = [...signal];
        
        // Pad to power of 2
        const n = Math.pow(2, Math.ceil(Math.log2(data.length)));
        while (data.length < n) data.push(0);
        
        const coefficients = [];
        const details = [];
        
        for (let level = 0; level < levels && data.length >= 2; level++) {
            const len = data.length;
            const approx = [];
            const detail = [];
            
            for (let i = 0; i < len / 2; i++) {
                // Haar wavelet
                approx.push((data[2 * i] + data[2 * i + 1]) / Math.sqrt(2));
                detail.push((data[2 * i] - data[2 * i + 1]) / Math.sqrt(2));
            }
            
            details.push(detail);
            data = approx;
        }
        
        coefficients.push(data); // Final approximation
        
        return {
            approximation: data,
            details,
            levels,
            source: 'MIT 18.086 - Wavelet Transform'
        };
    },
    
    /**
     * Cepstrum Analysis
     * Source: MIT 18.086
     */
    cepstrum: function(signal) {
        // FFT
        const fft = this._fft(signal);
        
        // Log magnitude
        const n = signal.length;
        const logMag = [];
        for (let i = 0; i < n; i++) {
            const re = fft[2 * i];
            const im = fft[2 * i + 1];
            logMag.push(Math.log(Math.sqrt(re * re + im * im) + 1e-10));
        }
        
        // IFFT of log magnitude
        const cepstrum = this._ifft(this._fft(logMag));
        
        // Extract real part
        const realCepstrum = [];
        for (let i = 0; i < n; i++) {
            realCepstrum.push(cepstrum[2 * i]);
        }
        
        return {
            cepstrum: realCepstrum,
            source: 'MIT 18.086 - Cepstrum'
        };
    },
    
    _generateWindow: function(size, type) {
        const window = new Array(size);
        
        switch (type) {
            case 'hann':
                for (let i = 0; i < size; i++) {
                    window[i] = 0.5 * (1 - Math.cos(2 * Math.PI * i / (size - 1)));
                }
                break;
            case 'hamming':
                for (let i = 0; i < size; i++) {
                    window[i] = 0.54 - 0.46 * Math.cos(2 * Math.PI * i / (size - 1));
                }
                break;
            case 'blackman':
                for (let i = 0; i < size; i++) {
                    window[i] = 0.42 - 0.5 * Math.cos(2 * Math.PI * i / (size - 1)) + 
                               0.08 * Math.cos(4 * Math.PI * i / (size - 1));
                }
                break;
            default: // rectangular
                window.fill(1);
        }
        
        return window;
    },
    
    _fft: function(samples) {
        const N = samples.length;
        
        if (N <= 1) {
            return [samples[0] || 0, 0];
        }
        
        const even = [];
        const odd = [];
        for (let i = 0; i < N; i += 2) {
            even.push(samples[i]);
            odd.push(samples[i + 1] || 0);
        }
        
        const fftEven = this._fft(even);
        const fftOdd = this._fft(odd);
        
        const result = new Array(N * 2).fill(0);
        for (let k = 0; k < N / 2; k++) {
            const angle = -2 * Math.PI * k / N;
            const wRe = Math.cos(angle);
            const wIm = Math.sin(angle);
            
            const oddRe = fftOdd[2 * k];
            const oddIm = fftOdd[2 * k + 1];
            
            const tRe = wRe * oddRe - wIm * oddIm;
            const tIm = wRe * oddIm + wIm * oddRe;
            
            result[2 * k] = fftEven[2 * k] + tRe;
            result[2 * k + 1] = fftEven[2 * k + 1] + tIm;
            result[2 * (k + N / 2)] = fftEven[2 * k] - tRe;
            result[2 * (k + N / 2) + 1] = fftEven[2 * k + 1] - tIm;
        }
        
        return result;
    },
    
    _ifft: function(spectrum) {
        const N = spectrum.length / 2;
        
        // Conjugate
        const conjugate = [];
        for (let i = 0; i < N; i++) {
            conjugate.push(spectrum[2 * i]);
            conjugate.push(-spectrum[2 * i + 1]);
        }
        
        // FFT
        const fft = this._fft(conjugate.filter((_, i) => i % 2 === 0));
        
        // Conjugate and scale
        const result = [];
        for (let i = 0; i < N; i++) {
            result.push(fft[2 * i] / N);
            result.push(-fft[2 * i + 1] / N);
        }
        
        return result;
    }
};

