    registerAll: function() {
        let registered = 0;
        let failed = 0;
        
        if (typeof PRISM_GATEWAY === 'undefined') {
            console.warn('[Phase 3] PRISM_GATEWAY not found - routes will register on build merge');
            return { registered: Object.keys(this.routes).length, failed: 0, deferred: true };
        }
        
        for (const [route, target] of Object.entries(this.routes)) {
            try {
                PRISM_GATEWAY.register(route, target);
                registered++;
            } catch (e) {
                console.warn(`[Phase 3] Failed to register route: ${route}`);
                failed++;
            }
        }
        
        console.log(`[Phase 3 Routes] Registered: ${registered}, Failed: ${failed}`);
        return { registered, failed };
    }
